insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (148,'تقارير أداء الهيئة','التقرير الأول لأداء هيئة الشراء العام (2022-2025)','2026-11-05','https://www.ppa.gov.lb/ar/pages/details/148','{"https://admin.ppa.gov.lb/storage/listing-pages/files/1795602839-Book4_PPA_Performance_Report_AR_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795602959-Book6_PPA_Executive_Summary_EN_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795603017-Book7_PPA_Executive_Summary_FR_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795602839-Book4_PPA_Performance_Report_AR_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795602959-Book6_PPA_Executive_Summary_EN_DIGITAL.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1795603017-Book7_PPA_Executive_Summary_FR_DIGITAL.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
delete from public.procurement_doc_chunk where doc_id=(select id from public.procurement_doc where page_id=148);
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=148),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "إمسح الرمز لإلطالع على النسخة اإللكترونية لهذا التقرير\n\f\f\f\f كلمة الرئيس\n حلم إلى حقيقة\n من ٍ\n في 29تموز من العام ،2022كنّ ا أمام خيار من اثنين،\n ّإما إعالن بدء نفاذ قانون الشراء العام استناداً الى ما ورد في نص"}, {"o": 1, "l": "المادة 115", "b": "المادة 115منه،\nـددي قــاس :مديــر عــام إدارة المناقصــات الســابقة فــي التفتيــش\n وإمــا اإلعــان عــن عــدم المقــدرة ،فــي ظــل واقـ ٍـع عـ ٍّ\n ّ\n المركــزي وثمانيــة موظفيــن ،فــي مقابــل مــا ال يقــل عــن 1300جهــة شــارية خاضعــة لرقابــة الهيئــة.\n مستحيال.\n ً في المعادلة الحسابية البحتة ،كان ذلك\n لكن في المعادلة الوطنية ،وأمام العزم واإلرادة واإليمان باإلصالح ،تسقط األرقام ،وتنتصر اإلرادة.\nانتظــر كثيــرون أن يطـ ّـل جــان العليــة فــي ذلــك اليــوم مــن الســراي الحكومــي ليعلــن عــدم مقــدرة إدارة المناقصــات\nـردد المقولــة المشــهورة« :ال ُيلــزم أحـ ٌـد\n علــى تطبيــق قانــون الشــراء العــام والتحـ ّـول الــى هيئــة الشــراء العــام ،وأن يـ ّ\n بأمـ ٍـر مســتحيل».\nلكــن المفاجــأة كانــت أن أطـ ّـل جــان العليــة مــن الســراي الحكومــي ،وفــي احتفــال وطنــي كبيــر رعــاه دولــة الرئيــس\nنجيــب ميقاتــي ،وبلقبــه الــذي منحــه إيــاه القانــون رئيســاً لهيئــة الشــراء العــام ،ليعلــن بــدء نفــاذ قانــون الشــراء العــام،\nويعمــل بهــا» .وقــد أعلــن دولــة الرئيــس فــي تلــك المناســبة طبــق ُ ـردد عبارتــه الشــهيرة «القوانيــن ُوضعــت لتُ َّ وهــو يـ ّ\nســيما فــي محــور الشــراء العــام ،ودعمــه للهيئــة المنشــأة بموجــب دعمــه الكامــل لمســار اإلصــاح المالــي ،وال ّ\n القانــون.\nـور وهــو مؤمــن بأنــه لــن يكــون ســراباً ،انطلق عمل\n كمــن ُيضــيء شــمعة وســط الظــام الدامــس ،وكمــن يمشــي وراء نـ ٍ\nهيئــة الشــراء العــام فــي 29تمــوز مــن العــام .2022وأدى رئيســها اليميــن القانونيــة أمــام فخامــة رئيــس الجمهوريــة"}, {"o": 2, "l": "المادة 115", "b": "العمــاد ميشــال عــون فــي 3آب مــن العــام نفســه ،فتأسســت الهيئــة بقــوة القانــون ،وتولّ ــى رئيســها مهامهــا كاملــة\n إلــى حيــن تعييــن أعضائهــا ،تطبيقــاً للفقــرة الثانيــة مــن المــادة 88مــن قانــون الشــراء العــام.\nـتدت العتمــة :جائحــة كورونــا ،االعتــداءات اإلســرائيلية ،واالنهيــار االقتصــادي ،إضافــة لــم تكــن الطريــق ســهلة ،اشـ ّ\nإلــى ضعــف المقـ ّـدرات الذاتيــة للهيئــة ،وال سـ ّـيما البشــرية منهــا .ومــع ذلــك ،كان حرصنــا علــى ممارســة مهامنــا فــي\nأصعــب الظــروف نابعــاً مــن قناعــة راســخة بــأن عمــل الجهــات الخاضعــة للقانــون مرتبــط عضويــاً بــدور هيئــة الشــراء\n العــام ،ومــن ارادة وايمــان بمهمــة ورســالة ذات بعــد وطنــي لبنــاء دولــة القانــون والمؤسســات.\nفكانــت إدارة المناقصــات الســابقة نموذجــاً لهيئــة الشــراء العــام ،نموذجــاً فــي الــوالء للوطــن واالنتمــاء الــى\n المؤسســات.\nبــدأ العمــل فــي ظــروف اســتثنائية قاســية ،وكان الهـ ّـم األول ضمــان اســتمرارية عمــل الجهــات الشــارية ،بالتــوازي مــع\nاالضطــاع بالمهــام الواســعة التــي أناطتهــا المــادة 76مــن القانــون بالهيئــة ،مــن تنظيــم الشــراء العــام ،واإلشــراف\n عليــه ،ومراقبتــه ،وتطويــر إجراءاتــه ونُ ُظمــه وأدائــه ،وتقديــم المســاندة الفنيــة واإلرشــاد.\nوتراكمــت إلــى جانــب األزمــات االســتثنائية عراقيــل بنيويــة مزمنــة ،أبرزهــا التأخيــر فــي تنفيــذ النــص القانونــي المتعلّ ــق\nـاس غيــر مبـ َّـرر حــول الطبيعــة القانونيــة\n بنقــل المــاك والموظفيــن مــن إدارة المناقصــات إلــى الهيئــة .كمــا ســاد التبـ ٌ\n وتأخــر تعييــن أعضائهــا ألســباب خارجــة عــن إرادتهــا."}, {"o": 3, "l": "المادة 115", "b": "ّ للهيئــة ،وجــرى الخلــط بيــن إنشــائها الحاصــل بقــوة القانــون،\n\fعطلــت النــص وحاولــت نــزع صالحيــات منحهــا القانــون لرئيــس الهيئــة ،فــي نهـ ٍـج يتعــارض مــع أبســطواجهنــا حججــاً ّ\nمبــادئ الحوكمــة ،ويغفــل أن األنظمــة اإلداريــة والماليــة هــي أدوات رقابــة وضبــط تشــتد الحاجــة إليهــا سـ ّـيما فــي\n مرحلــة التأســيس.\nوصــدرت بمراســيم رســمية ،مــا شــكّ ل محطــة\n َ وأخيــراً ُ ،أ ِق ّــرت أنظمــة هيئــة الشــراء العــام وفقــاً ألحــكام القانــون،\n أساســية فــي اســتكمال اإلطــار المؤسســي للهيئــة.\nمنــذ اليــوم األول النطــالق هيئــة الشــراء العــام ،كان الرهــان واضحــاً بالنســبة إلينــا :تطبيــق القانــون مهمــا بلغــت\nالصعوبــات ،وعــدم الســماح لألزمــات بــأن تتحـ ّـول إلــى ذريعــة لتعطيــل اإلصــالح .لــم تكــن اإلمكانــات متوافــرة ،ولــم\nيكــن الظــرف مؤاتيــاً ،لكــن القناعــة كانــت راســخة بــأن بنــاء الثقــة يبــدأ بالشــفافية ،وأن الشــفافية اليــوم ال تنفصــل\n عــن الرقمنــة.\nفــي ســنواتها األولــى ،تمكّ نــت الهيئــة ،بإمكانــات بشــرية محــدودة ،مــن إرســاء األســس العمليــة لنظــام شــراء\nعــام حديــث ،قائــم علــى توحيــد اإلجــراءات ،تعزيــز اإلفصــاح ،وتفعيــل الرقابــة الالحقــة .وقــد شــكّ ل تطويــر الموقــع\nاإللكترونــي للهيئــة وتحويلــه تدريجيــاً إلــى منصــة وطنيــة للشــراء العــام أحــد أبــرز أدوات هــذا التحـ ّـول ،بمــا أتــاح توســيع\n دائــرة الوصــول إلــى المعلومــات ،وتعزيــز دور الــرأي العــام والجهــات الرقابيــة ،وترســيخ مبــدأ المســاءلة.\nعبــرت عــن خيــار إصالحــي واضــح :االنتقــال مــن إدارة ورقيــة مغلقــة إلــى\n هــذه الخطــوات لــم تكــن تقنيــة بحتــة ،بــل ّ"}, {"o": 4, "l": "المادة 115", "b": "آن واحــد .أمــا مــا تحقــق مــن\n نظــام رقمــي مفتــوحُ ،يخضــع اإلنفــاق العــام للرقابــة المجتمعيــة والمؤسســية فــي ٍ\n إنجــازات ،فيعرضــه هــذا التقريــر بالتفصيــل ،بوصفــه ثمــرة عمــل جماعــي وإيمــان عميــق برســالة وطنيــة.\nقدمه شــركاء لبنان الدوليون ،وال سـ ّـيما االتحــاد األوروبي،\n لــم يكــن هــذا المســار ممكنــاً لــوال الدعــم المتواصــل الــذي ّ\nالبنــك الدولــي ،وكالــة التنميــة الفرنســية ،الوكالــة األلمانيــة للتعــاون الدولــي ،ووكاالت التنميــة الشــريكة األخــرى،\nالذيــن واكبــوا إصــالح الشــراء العــام منــذ مراحلــه التحضيريــة ،واســتمروا فــي دعــم هيئــة الشــراء العــام فــي مرحلــة\n اإلطــالق والتشــغيل.\nأن هــذا\n إننــا نقـ ّـدر هــذا الدعــم ،ال بوصفــه مســاندة ظرفيــة ،بــل كشــراكة قائمــة علــى ثقــة متبادلــة بخيــار اإلصــالح .غيــر ّ\nالدعــم ال يحقــق غايتــه الكاملــة إال إذا تُ رجــم إلــى بنــاء قــدرات مســتدامة ،ونقــل معرفــة ،وتعزيــز لألنظمــة الرقميــة،\n بمــا يمكّ ــن الهيئــة مــن االضطــالع بدورهــا بكفــاءة واســتقاللية علــى المــدى الطويــل.\nتتطلّ ــع هيئــة الشــراء العــام فــي المرحلــة المقبلــة إلــى تثبيــت مــا تحقــق والبنــاء عليــه ،مــن خــالل اســتكمال االنتســاب\nالشــامل للجهــات الشــارية إلــى نظــام الشــراء العــام ،والمضــي قدمــاً فــي تطبيــق منظومــة الشــراء اإللكترونــي بشــكل\n متكامــل ،وإصــدار األطــر التنظيميــة الالزمــة لذلــك.\nكمــا تلتــزم الهيئــة باالســتثمار فــي الرأســمال البشــري ،عبــر بنــاء القــدرات ،وتعزيــز التدريــب المتخصــص ،وتكريــس\nثقافــة الشــراء العــام الحديــث داخــل اإلدارات العامــة .ويبقــى هــذا المســار مرتبطــاً ارتباطــاً وثيقــاً باســتمرار التعــاون"}, {"o": 5, "l": "المادة 115", "b": "مــع الشــركاء المحلييــن وتعزيــز الشــراكة مــع المجتمــع الدولــي.\nإن هيئــة الشــراء العــام ،بالنســبة إلينــا ،ليســت مجــرد مؤسســة أنشــأها القانــون ،بــل هــي خيــار إصالحــي وطنــي نؤمــن\n ّ\n ـتدت التحديــات. ونتحمــل مســؤوليته ،ونلتــزم بالســير بــه قدمــاً ،مهمــا اشـ ّ\n ّ بــه،\nحزيران 2026\nد .جان العلّ ية\n\f الشكر والتقدير\n أعدتهــا هيئــة الشــراء العــامّ ،\nتوثــق مــن جهــة مســار إصــاح الشــراء العــام يأتــي هــذا التقريــر بوصفــه قــراءة مؤسســية ّ\nإن\n وتقيــم مــن جهــة أخــرى أداء الهيئــة ودورهــا خــال الســنوات األولــى مــن تطبيــق قانــون الشــراء العــامّ . ّ فــي لبنــان،\nهــذا المســار قــام علــى تضافــر الجهــود الوطنيــة فــي مرحلــة دقيقــة مــن تاريــخ اإلدارة العامــة ،وفــي ســياق إصالحــي\n ـا.\n معقــد تطلّ ــب التزامــاً سياســياً ،وتعاونــاً مؤسســياً ،وجهــداً تقنيــاً متواصـ ًّ\nوتثمــن هيئــة الشــراء العــام ،فــي هــذا اإلطــار ،الــدور الــذي اضطلعــت بــه الســلطات الدســتورية والــوزارات واإلدارات ّ\nالعامــة والجهــات الشــارية ،والتــي انخرطــت فــي تطبيــق قانــون الشــراء العــام ،رغــم التحديــات االســتثنائية التــي\nواجهتهــا الدولــة اللبنانيــة .كمــا تُ قـ ّـدر الهيئــة التفاعــل المؤسســي البنّ ــاء الــذي أســهم فــي ترســيخ منطــق اإلصــاح،\nوفــي االنتقــال التدريجــي مــن الممارســات الســابقة إلــى إطــار قانونــي ومؤسســي حديــث يقــوم علــى الشــفافية\n والمســاءلة والمهنيــة.\nكمــا ينــدرج هــذا التقريــر ضمــن مســار تعــاون وثيــق مــع المؤسســات الوطنيــة المعنيــة ببناء القــدرات وتعزيــز الحوكمة،"}, {"o": 6, "l": "المادة 115", "b": "وال سـ ّـيما الجهــات التدريبيــة والرقابيــة ،التــي ســاهمت فــي مواكبــة تطبيــق القانــون ،وفــي دعــم الجهــود الراميــة\n إلــى تطويــر الكفــاءات وتوحيــد الممارســات داخــل اإلدارة العامــة.\nوال يفــوت الهيئــة أن تُ قـ ّـر بالــدور المحــوري الــذي ّأداه الشــركاء الدوليــون فــي مرافقــة هــذا المســار اإلصالحــي ،مــن\nخــال الدعــم التقنــي ،وبنــاء القــدرات ،ونقــل المعرفــة ،وتعزيــز المعاييــر الدوليــة .وقــد شــكّ ل هــذا التعــاون عنصــراً\nداعمــاً لتثبيــت اإلصــاح فــي مراحلــه التأسيســية ،ضمــن مقاربــة قائمــة علــى الشــراكة ،واحتــرام األولويــات الوطنيــة،\n وتعزيــز االســتدامة المؤسســية.\nإن هيئــة الشــراء العــام ،إذ تضــع هــذا التقريــر بيــن أيــدي المعنييــن علــى المســتويين الوطنــي والدولــي ،تؤكّ ــد أن\n ّ\nيترســخ إال بتكامــل اإلرادة الوطنيــة\n إصــاح الشــراء العــام هــو مســؤولية مشــتركة ،ومســار طويــل األمــد ،ال يمكــن أن ّ\n مــع الشــراكات المؤسســية الفاعلــة.\n\f\fتســتند البيانــات الــواردة فــي هــذا التقريــر إلــى الســجالت الرســمية المتاحــة علــى منصــة هيئــة الشــراء العــام كمــا\nكانــت بتاريــخ 31كانــون األول .2025وقــد ُبذلــت العنايــة المهنيــة الواجبــة للتحقــق مــن دقــة البيانــات عنــد إعــداد\nالتقريــر؛ غيــر أنّ هــا تظـ ّـل محكومــة بمــدى اكتمــال وصحــة المعلومــات المسـ ّـجلة فــي مصادرهــا األصليــة ،وال تشــمل\n أي تعديــات أو تحديثــات ُأجريــت بعــد التاريــخ المرجعــي المذكــور.\n\f\f جدول المحتويات\n6 كلمة الرئيس\n8 الشكر والتقدير\n16 ّ\n الملخص التنفيذي\n16 .Iاإلطار العام والغرض االستراتيجي للتقرير\n16 .IIالرسائل االستراتيجية األساسية\n17 .IIIماذا تقول لنا البيانات؟\n20 يقيد اإلصالح؟\n .IVما الذي ال يزال ّ"}, {"o": 7, "l": "المادة 115", "b": "21 .Vأولويات الهيئة االستراتيجية للمرحلة المقبلة\n22 .VIالتعاون الدولي :من دعم اإلصالح إلى شراكة في بناء النظام\n26 الفصل األول :من إدارة المناقصات إلى هيئة الشراء العام\n26 .Iالخلفية التاريخية واإلطار القانوني السابق لقانون الشراء العام ()2022 - 1959\n26 .IIإشكاليات نظام الصفقات العمومية قبل قانون الشراء العام\n28 .IIIأداء إدارة المناقصات وإنجازاتها\n29 .IVمرحلة االنتقال المؤسسي والموارد البشرية\n32 الفصل الثاني :سياق إصالح الشراء العام في لبنان\n32 .Iمسار إصالح الشراء العام قبل العام 2021\n33 .IIقانون الشراء العام الجديد\n33 التحوالت المؤسسية والقانونية المرافقة ّ .III\n .IVالمؤشرات األولية ألثر اإلصالح 34\n34 .Vالتحديات المرتبطة بسياق اإلصالح\n34 .VIدور هيئة الشراء العام في سياق اإلصالح\n38 الفصل الثالث :اإلطار القانوني والمؤسسي للشراء العام\n38 .Iاإلطار القانوني :قانون الشراء العام 2021/244\n40 .IIاإلطار المؤسسي :هيئة الشراء العام\n41 .IIIالخالصة\n44 الفصل الرابع :اإلنجازات األولى والنتائج الرئيسة\n44 .Iمقدمة\n44 .IIاإلنجازات المؤسسية وبناء الهيكلية\n47 .IIIاإلنجازات التنظيمية والتشريعية الداعمة\n52 .IVاإلنجازات في مجال التدريب وبناء القدرات\n52 .Vالخالصة\n56 الفصل الخامس :الشفافية والرقمنة واألثر على اإلصالح\n56 .Iمقدمة\n56 .IIالشفافية كنهج عمل – من النص إلى التطبيق\n58 .IIIالرقمنة – المنصة اإللكترونية المركزية للشراء العام\n59 .IVاألثر األولي لإلصالح الرقمي :مؤشرات ونتائج مبدئية\n61 .Vالدروس المستفادة والتحديات\n62 .VIالخالصة\n\f66 الفصل السادس :البيانات واإلحصاءات\n66 مقدمة\n ّ .I\n68 تطور حجم نشاط الشراء العامّ .II\n71 .IIIتحليل طرق الشراء\n76 .IVتحليل الجهات الشارية\n81 .Vتحليل االنفاق حسب نوع العقد\n84 .VIتحليل المنافسة والمشاركة في عمليات الشراء العام"}, {"o": 8, "l": "المادة 115", "b": "88 .VIIالتحليل المالي والمؤشرات األولية للقيمة مقابل المال\n92 .VIIIالشفافية والنشر وجودة البيانات\n95 التحول في نظام الشراء العام\n ّ .IXمن البيانات إلى الرسائل :مؤشرات\n100 الفصل السابع :التعاون الدولي والشراكات االستراتيجية\n100 مقدمة :الشراكة كرافعة أساسية لإلصالح\n ّ .I\n100 .IIالتعاون الدولي\n108 .IIIالشراكات االستراتيجية على المستوى الوطني\n108 .IVالخالصة\n112 الفصل الثامن :التحديات والصعوبات\n112 .Iمقدمة\n112 .IIالسياق العام واألزمات المحيطة باإلصالح\n113 .IIIالتحديات على مستوى هيئة الشراء العام\n113 .IVالتحديات على المستوى القانوني\n114 .Vتحديات حوكمة نظام الشراء العام وإدارة التغيير\n115 .VIالتحديات على مستوى الجهات الشارية\n116 .VIIالتحديات على مستوى العالقة مع القطاع الخاص وجهوزية السوق\n116 .VIIIالتحديات على مستوى الشفافية والنزاهة والرقابة\n117 التحول الرقمي\n ّ .IXالتحديات على مستوى\n117 .Xالتحديات المتعلقة بالمستوى السياسي /اإلرادة السياسية\n118 .XIالخالصة\n122 الفصل التاسع :األولويات االستراتيجية وخارطة الطريق\n122 .Iمقدمة\n122 .IIالرؤية واألهداف االستراتيجية\n122 .IIIالمحاور االستراتيجية التنفيذية\n124 .IVعوامل النجاح والمخاطر التنفيذية\n124 .Vإطار المتابعة والحوكمة\n125 .VIالخالصة\n128 المالحق\n128 .Iملحق رقم :1إدارة المناقصات\n132 .IIملحق رقم :2المراحل التشريعية التي أدت الى صدور قانون الشراء العام في لبنان رقم 2021/244\n134 .IIIملحق رقم :3دراسة حول المحاور اإلصالحية لقانون الشراء العام في لبنان رقم 2021/244\n149 التطور التشريعي :صعوبات ومعالجات التطبيق ()2025-2022 ّ .IVملحق رقم :4\n154 المدنية\n ّ َ\n الموافق على ملئها من قبل مجلس الخدمة .Vملحق رقم :5الوظائف\n وفقا للمرسوم رقم 14632ً .VIملحق رقم :6مالك هيئة الشراء العام\n156\n ّ\n المتعلق بنظام مستخدمي هيئة الشراء العام الصادر بتاريخ 2025/1/9"}, {"o": 9, "l": "المادة 115", "b": "158 .VIIملحق رقم :7الئحة المذكرات والقرارات والتوصيات الصادرة عن الهيئة بين 2022و2025\n161 .VIIIملحق رقم :8المراسالت\n168 .IXملحق رقم :9األخطاء الشائعة المتعلقة بدفاتر الشروط\n174 المسجلة على المنصة االلكترونية المركزية\n ّ .Xملحق رقم :10الئحة الجهات الشارية\n\f ّ\nالملخص التنفيذي\n\f جدول المحتويات\n16 .Iاإلطار العام والغرض االستراتيجي للتقرير\n16 .IIالرسائل االستراتيجية األساسية\n16 مجرد التزام نظري\n ّ .1إصالح الشراء العام في لبنان هو مسار قائم ،ال\n16 التحول التشغيلي\n ّ التحول المؤسسي سبق\n ّ .2\n17 تقدم ملموس ،لكن غير مكتمل\n .3الرقمنة والشفافيةّ :\n17 ً\n أحكاما نهائية .4البيانات المتاحة تكشف اتجاهات ،ال\n17 دعم\n مهدد إذا لم ُي َ\n ّ .5اإلصالح\n17 .IIIماذا تقول لنا البيانات؟\n18 تطور حجم النشاط والنشر على المنصة\n ّ .1\n18 .2مخرجات عمليات الشراء ونسب التلزيم\n18 تطور هيكل اإلنفاق وقيمة العقود\n ّ .3\n18 .4أنماط وطرق الشراء\n19 .5مؤشرات المنافسة والمشاركة\n19 .6دالالت األداء المؤسسي لهيئة الشراء العام\n20 يقيد اإلصالح؟\n .IVما الذي ال يزال ّ\n20 .1التحديات المؤسسية\n20 .2التحديات القانونية والتنظيمية\n20 .3التحديات التقنية والرقمية\n21 .4التحديات الثقافية والسلوكية\n21 .Vأولويات الهيئة االستراتيجية للمرحلة المقبلة\n21 التحول الرقمي كنقطة ارتكاز لإلصالح\n ّ .1استكمال\n21 .2تعزيز المهنية وبناء القدرات المؤسسية\n21 .3تثبيت اإلطار التنظيمي وتوحيد الممارسات\n22 .4تعزيز التنسيق والحوكمة متعددة المستويات\n22 .5ضمان االستدامة المؤسسية للهيئة\n22 .VIالتعاون الدولي :من دعم اإلصالح إلى شراكة في بناء النظام\n22 .1مواكبة اإلصالح منذ مراحله التأسيسية\n22 .2دعم اإلطالق والتشغيل في مرحلة عالية المخاطر\n22 .3نحو شراكة استراتيجية طويلة األمد\n\f 16\n ّ\n الملخص التنفيذي\n .Iاإلطار العام والغرض االستراتيجي للتقرير"}, {"o": 10, "l": "المادة 115", "b": "لماذا هذا التقرير؟ ولماذا اآلن؟\nيصــدر هــذا التقريــر فــي لحظــة مفصليــة مــن مســار إصــاح الشــراء العــام فــي لبنــان ،بعــد مــرور الســنوات األولــى\nحيــز التنفيــذ وانشــاء هيئــة الشــراء العــام ،وفــي ظـ ّـل ســياق وطنــي يتّ ســم بتحديــات\n علــى دخــول قانــون الشــراء العــام ّ\nغيــر مســبوقة علــى المســتويات الماليــة والمؤسســية ولجهــة الحوكمــة .وهــو ال يهــدف إلــى توثيــق مرحلــة زمنيــة\nآن معــاً تقريــراً تقييميــاً ألداء هيئــة الشــراء العــام خــال فتــرة التطبيــق ،وقــراءة اســتراتيجية\n فحســب ،بــل يشــكّ ل فــي ٍ\nوتوقعــات عاليــة مــن الداخــل\n ّ معمقــة لمســار إصالحــي ناشــئ ،يتقـ ّـدم بخطــى متباينــة ،وســط ضغــوط بنيويــة كبيــرة ّ\nالملخــص التنفيــذي ليشــكّ ل فــي الوقــت نفســه أداة مســاءلة مؤسســية ّ والخــارج علــى حــد ســواء .ويأتــي هــذا\nطوعيــة ،تضــع هيئــة الشــراء العــام أداءهــا ومســار تطبيــق القانــون فــي متنــاول الســلطات الدســتورية ،والجهــات\n وتحمــل المســؤولية.\n ّ الشــارية ،والــرأي العــام ،والشــركاء الدولييــن ،فــي مقاربــة تقــوم علــى الشــفافية\nتحــو ًال نوعيــاً فــي مقاربــة الدولــة اللبنانيــة إلدارة المــال العــام ،إذ أرســى\n ّ لقــد شــكّ ل إقــرار قانــون الشــراء العــام\nإطــاراً قانونيــاً حديثــاً يقــوم علــى مبــادئ الشــفافية ،والمنافســة ،والمســاءلة ،وتكافــؤ الفــرص ،وربــط تنفيــذ عمليــات\nأن االنتقــال مــن النــص التشــريعي إلــى الممارســة الفعليــة أثبــتالشــراء بمنظومــة رقابيــة ومؤسســية متكاملــة .إال ّ\nأن اإلصــاح القانونــي ،علــى أهميتــه ،ال يكفــي وحــده إلحــداث التحـ ّـول المنشــود ،مــا لــم ُيرفــق بجهــد مؤسســي ّ"}, {"o": 11, "l": "المادة 115", "b": "مســتدام ،واســتثمارات فــي القــدرات ،وتغييــر ثقافــي تدريجــي فــي ســلوك الجهــات الشــارية.\nمــن هــذا المنطلــق ،ينــدرج هــذا التقريــر كتمريــن تقييمي-تحليلــي ( )Stocktaking Exerciseيهــدف إلــى تقييــم\nمــا تحقــق خــال الســنوات األولــى مــن تطبيــق القانــون ،ورصــد التحـ ّـوالت المؤسســية التــي رافقــت إنشــاء الهيئــة،\nوتحليــل البيانــات المتاحــة الســتخالص اتجاهــات عامــة ،وتشــخيص التحديــات القائمــة ،واقتــراح توجهــات اســتراتيجية\n واقعيــة للمرحلــة المقبلــة.\nيوجــه هــذا التقريــر إلــى الشــركاء الدولييــن بوصفــه أداة حــوار سياســاتي ،تســعى إلــى نقــل\n وعلــى الصعيــد الدولــيَّ ،\nصــورة دقيقــة ومتوازنــة عــن مســار اإلصــاح :صــورة ال تُ غفــل اإلنجــازات المحققــة ،وال تُ قلّ ــل مــن حجــم الفجــوات\n القائمــة ،بــل تضعهــا فــي إطارهــا الصحيــح ،تمهيــداً لتصميــم تدخــات دعــم أكثــر فعاليــة.\n .IIالرسائل االستراتيجية األساسية\n يتغير؟\n ّ تغير؟ ما الذي لم\n ما الذي ّ\n مجرد التزام نظري ّ .1إصالح الشراء العام في لبنان هو مسار قائم ،ال\nأن إصــاح الشــراء العــام فــي لبنــان لــم يعــد مجـ ّـرد إعــان نوايــا أو التــزام\n أولــى الرســائل التــي يبرزهــا هــذا التقريــر هــي ّ\nتشــريعي ،بــل أصبــح مســاراً مؤسســياً قائمــاً ،تُ مـ َـارس فيــه أدوار جديــدة ،وتُ ختبــر فيــه أدوات حديثــة ،وتُ بنــى فيــه\nتحــول\n ّ تدريجيــاً ثقافــة مختلفــة إلدارة المــال العــام .فقــد ّأدى إنشــاء هيئــة الشــراء العــام وتفعيلهــا إلــى إحــداث\n بنيــوي فــي موقــع الرقابــة والتنظيــم ،واالنتقــال مــن نمــوذج مشــتّ ت إلــى إطــار أكثــر توحيــداً وتنظيمــاً.\nيترســخ ،خصوصــاً فــي بيئــة إداريــة"}, {"o": 12, "l": "المادة 115", "b": "أن هــذا المســار ال يــزال فــي مراحلــه األولــى ،ويتطلّ ــب وقتــاً واســتمرارية كــي ّ\n غيــر ّ\n مثقلــة بــاإلرث الســابق ،وبقــدرات بشــرية محــدودة ،وبضغــوط تشــغيلية متزايــدة.\n التحول التشغيليّ التحول المؤسسي سبق ّ .2\nأن التحـ ّـول المؤسســي ،مــن حيــث األطــر التنظيميــة ،واألدوار ،والمفاهيــم ،قــد تقـ ّـدم بوتيــرة\n ُيظهــر التقريــر بوضــوح ّ\nأســرع مــن التحـ ّـول التشــغيلي الكامــل داخــل الجهــات الشــارية .فقــد باتــت مفاهيــم مثــل التخطيــط المســبق ،وفصل\n\f17\nالمهــام ،والتدقيــق الداخلــي ،واالمتثــال لإلجــراءات القانونيــة ،جــزءاً مــن الخطــاب المؤسســي ،لكنهــا لــم تترجــم بعــد\n بشــكل متجانــس فــي الممارســة اليوميــة لجميــع الجهــات الشــارية.\nـا بقــدر مــا تعكــس طبيعــة اإلصالحــات البنيويــة ،التــي تتطلّ ــب وقتــاً ،واســتثمارات فــي\n هــذه الفجــوة ال تعكــس فشـ ً\n التدريــب ،وأنظمــة داعمــة ،وآليــات متابعــة ،وتقييم.\n تقدم ملموس ،لكن غير مكتمل .3الرقمنة والشفافيةّ :\nتقدمــاً ملحوظــاً مــن حيــث إرســاء منصــة إلكترونيــة مركزيــة، يشــكّ ل البعــد الرقمــي أحــد أعمــدة اإلصــاح ،وقــد أحــرز ّ\nأن الرقمنــة ال تــزال فــي مرحلــة انتقاليــة،\n يبيــن ّ\n أن التقريــر ّ وتوســيع نطــاق النشــر ،وتحســين إتاحــة المعلومــات .إال ّ\nحيــث تتعايــش الممارســات الرقميــة مــع إجــراءات تقليديــة ،مــا يحـ ّـد أحيانــاً مــن األثــر التحويلــي الكامــل لألنظمــة\n اإللكترونيــة.\nتبــرز هنــا فرصــة اســتراتيجية لدعــم االنتقــال مــن رقمنــة جزئيــة إلــى حوكمــة رقميــة متكاملــة للشــراء العــام ،تربــط بيــن\n البيانــات ،والرقابــة ،واتخــاذ القرار.\n ً\n أحكاما نهائية .4البيانات المتاحة تكشف اتجاهات ،ال"}, {"o": 13, "l": "المادة 115", "b": "يعتمــد التقريــر علــى البيانــات المتاحــة عبــر المنصــة االلكترونيــة المركزيــة لــدى هيئــة الشــراء العــام ،ويســتخدمها\nال الســتخالص اســتنتاجات تفصيليــة ،بــل لرصــد اتجاهــات عامــة فــي حجــم العمليــات ،وأنــواع اإلجــراءات ،وأنمــاط\nالتفاعــل مــع هيئــة الشــراء العــام .وتُ ظهــر هــذه االتجاهــات ازديــاداً فــي حجــم المعامــات وتعقيدهــا ،مــا يعكــس مــن\n توســع نطــاق تطبيــق القانــون ،ومــن جهــة أخــرى ضغطــاً متزايــداً علــى القــدرات المؤسســية القائمــة. جهــة ّ\n دعم\n مهدد إذا لم ُي َ\n ّ .5اإلصالح\n تقدمــه ،يبقــى ّ\nهشــاً إذا لــم ُيســتكمل أن اإلصــاح ،علــى الرغــم مــن ّ\n أحــد أهــم االســتنتاجات االســتراتيجية للتقريــر هــو ّ\n عبر:\n •تعزيز القدرات البشرية؛\n •ترسيخ الهياكل المؤسسية داخل الجهات الشارية؛\n •تطوير األنظمة الرقمية؛\n منسق ومستدام. •وتوفير دعم دولي ّ\nوهنــا تبــرز المســؤولية ليــس فقــط فــي التمويــل ،بــل فــي مرافقــة اإلصــاح علــى المــدى المتوســط ،بمــا يضمــن\n اســتدامته وتحويلــه إلــى ممارســة مؤسســية راســخة.\n .IIIماذا تقول لنا البيانات؟\n المجردة\n ّ قراءة تحليلية لالتجاهات ال لألرقام\nيســتند هــذا التقريــر إلــى البيانــات المتاحــة عبــر المنصــة اإللكترونيــة المركزيــة لــدى هيئــة الشــراء العــام ،ويعتمــد\nـدال مــن إطــاق اســتنتاجات إحصائيــة شــاملة ،وذلــك مقاربــة تحليليــة حــذرة تقــوم علــى قــراءة االتجاهــات العامــة بـ ً\nانســجاماً مــع واقــع حداثــة النظــام ،وتفــاوت مســتويات االمتثــال ،والتحديــات المرتبطــة بجــودة البيانــات فــي مرحلــة\nانتقاليــة ،بمــا يهــدف إلــى تقديــم قــراءة تفســيرية تســاعد علــى فهــم ديناميــات التطبيــق وتطـ ّـور الممارســات ،دون"}, {"o": 14, "l": "المادة 115", "b": "االدعــاء باإلحاطــة الكاملــة بجميــع الحــاالت أو التفاصيــل الفرديــة.\n\f 18\n تطور حجم النشاط والنشر على المنصة ّ .1\nشــهد عــدد العمليــات المنشــورة علــى المنصــة اإللكترونيــة نمــواً متســارعاً ،إذ ارتفــع مــن 203عمليــات فــي عــام\n 2022إلــى 1,135عمليــة فــي عــام ،2023ثــم إلــى 2,347عمليــة فــي عــام ،2024ليســتقر عنــد 2,181عمليــة فــي\nتوســعاً تدريجيــاً فــي امتثــال الجهــات الشــارية لمتطلبــات النشــر والعلنيــة ،وانتقــال\n عــام .2025ويعكــس هــذا التطــور ّ\nالمنصــة مــن مرحلــة اإلطــاق التجريبــي إلــى أداة تشــغيلية مركزيــة .كمــا تُ ظهــر البيانــات أن نحــو %73مــن الجهــات\nالشــارية المسـ ّـجلة علــى المنصــة التزمــت فعليــاً بالنشــر عليهــا خــال الفتــرة المدروســة ،مقابــل %27لــم تبــدأ بعــد\n بالنشــر ،مــا يبــرز هامشــاً إضافيــاً لتحســين االمتثــال.\n .2مخرجات عمليات الشراء ونسب التلزيم\nالمســجلة علــى المنصــة بيــن 1آب 2022و 31كانــون األول 2025أن نحــو\n ّ تُ ظهــر نظــرة شــاملة إلــى العمليــات\nتوقفــت فــي مرحلــة اإلعــان ،وقرابــة %17لــم\n وأدت إلــى تلزيــم فعلــي ،مقابــل ّ %15 %68مــن العمليــات ُأنجــزت ّ\nتُ لــزَّ م .وتعكــس هــذه المؤشــرات قــدرة النظــام علــى اســتكمال الغالبيــة العظمــى مــن اإلجــراءات رغــم الظــروف\nتعطــل تســتدعي معالجــة تنظيميــة وتشــغيلية المؤسســية واالقتصاديــة الضاغطــة ،مــع اإلقــرار بوجــود نســب ّ\n الحقــة.\n تطور هيكل اإلنفاق وقيمة العقود ّ .3\nتُ بــرز البيانــات تحـ ّـو ًال واضحــاً فــي هيــكل اإلنفــاق العــام خــال الســنوات األخيــرة ،مــع انتقــال تدريجــي نحــو عقــود"}, {"o": 15, "l": "المادة 115", "b": "أعلــى قيمــة .فقــد ارتفــع متوســط قيمــة العقــد مــن نحــو 345ألــف دوالر أميركــي فــي عــام 2022إلــى مــا يقــارب\n 883ألــف دوالر فــي عــام ،2025مــا يعكــس االنتقــال مــن مرحلــة إدارة األزمــات والحــد األدنــى مــن التشــغيل إلــى\n مرحلــة إعــادة تفعيــل االســتثمارات العامــة والعقــود الكبــرى.\nوعلــى مســتوى القيمــة الماليــة ،بلــغ إجمالــي اإلنفــاق المسـ ّـجل خــال الفتــرة 2025–2022مــا يفــوق 2مليــار دوالر\n أميركــي ،تــوزّ ع أساســاً بيــن:\n •اللوازم/السلع (نحو %44من القيمة اإلجمالية)،\n •األشغال (حوالي ،)%41\n •الخدمات (نحو ،)%15\n فيما شكّ لت الخدمات االستشارية نسبة هامشية من إجمالي اإلنفاق.\n .4أنماط وطرق الشراء\nتنوعــاً متزايــداً فــي أنــواع طــرق الشــراء المســتخدمة (مناقصــات ،مزايــدات ،اتفاقــات رضائيــة ،شــراء\n تكشــف البيانــات ّ\nبالفاتــورة) ،وهــو مــا يشــير إلــى انتقــال تدريجــي ،مــن االعتمــاد علــى أنمــاط تقليديــة إلــى اســتخدام األدوات التــي\n أتاحهــا القانــون الجديــد.\n عدة ،أبرزها:\n التنوع ال يزال محكوماً بعوامل ّ ّ أن هذا غير ّ\n •القدرات التقنية والقانونية للجهات الشارية؛\n •مستوى التدريب المتاح؛\n •ومدى توافر أدوات رقمية داعمة التخاذ القرار.\nكذلــك تُ ظهــر البيانــات أن المناقصــة العموميــة ،وعلــى الرغــم مــن كونهــا الطريقــة األكثــر انســجاماً مــع مبــادئ\nتمثــل نســبة محــدودة مــن حيــث عــدد العمليــات مقارنــة بطــرق أخــرى كطلــب المنافســة والشــفافية ،إال أنهــا ّ\nعــروض األســعار أو االتفــاق الرضائــي ،وال ســيما لــدى الجهــات ذات النشــاط التشــغيلي المرتفــع .فــي المقابــل،\nتحتفــظ المناقصــة العموميــة بثقــل مالــي كبيــر ،إذ شــكّ لت مــا يزيــد عــن %54مــن إجمالــي قيمــة اإلنفــاق فــي عــام\n\f19"}, {"o": 16, "l": "المادة 115", "b": "،2025مقابــل ارتفــاع تدريجــي فــي الــوزن النســبي لالتفــاق الرضائــي وطلــب عــروض األســعار مــن حيــث القيمــة،\n ضمــن الســياقات القانونيــة المبـ ّـررة لذلــك.\nويؤكّ ــد هــذا التبايــن ضــرورة قــراءة متكاملــة تجمــع بيــن البعديــن العــددي والمالــي ،إذ ال يعكــس عــدد العمليــات\n وحــده طبيعــة المخاطــر أو مســتوى األثــر المالــي للشــراء العــام.\n .5مؤشرات المنافسة والمشاركة\nفــي ظــل محدوديــة البيانــات التفصيليــة حــول عــدد العارضيــن المشــاركين فــي كل عمليــة ،وال سـ ّـيما فــي المراحــل\nالتوجهــات اإلجرائيــة .وتُ ظهــر هــذه المؤشــرات\n ّ األولــى مــن تشــغيل المنصــة ،اعتمــد التقريــر مؤشــرات بديلــة لتحليــل\nزيــادة ملحوظــة فــي عــدد العارضيــن الفائزيــن بعقــود عامــة ،مــن 17فائــزاً فــي عــام 2022إلــى أكثــر مــن 1,000فائــز\nوتحســن فــرص النفــاذ إلــى العقــود العامــة ،مــع ّ توســع قاعــدة المشــاركة تدريجيــاً\n فــي عــام ،2025بمــا يعكــس ّ\n التأكيــد أن هــذه النتائــج تُ قــرأ كمؤشــرات اتجاهيــة ال كتقييــم نهائــي لمســتوى المنافســة الفعليــة فــي الســوق.\n .6دالالت األداء المؤسسي لهيئة الشراء العام\nتعكــس المعطيــات المتعلّ قــة بــأداء هيئــة الشــراء العــام قدرتهــا علــى إدارة حجــم متزايــد مــن العمليــات ،وتأميــن حـ ٍّـد\nأدنــى مــن االســتمرارية والفعاليــة التشــغيلية ،رغــم حداثــة التجربــة ،ومحدوديــة الموارد البشــرية والمالية ،والظروف\nالوطنيــة االســتثنائية التــي رافقــت مرحلــة اإلطــاق والتشــغيل .كمــا تُ بــرز هــذه المعطيــات الــدور المتنامــي للمنصــة\nمنظمــة وقابلــة اإللكترونيــة ،ليــس فقــط كأداة للنشــر واإلفصــاح ،بــل كرافعــة مؤسســية أساســية إلنتــاج بيانــات ّ"}, {"o": 17, "l": "المادة 115", "b": "للتحليــل ،تُ شــكّ ل قاعــدة ضروريــة للتقييــم الموضوعــي ،وتعزيــز المســاءلة ،ودعــم صنــع السياســات العامــة فــي\n مجــال الشــراء العــام.\n توسع نطاق التطبيق ّ أ .ازدياد حجم المعامالت كمؤشر على\nمطــرداً فــي عــدد المعامــات الــواردة إلــى هيئــة الشــراء العــام ،وال ســيما تلــك المتعلقــة\n تُ ظهــر البيانــات ارتفاعــاً ّ\nتوســعاً فعليــاً فــي نطــاق تطبيــق قانــون الشــراء العــام عبــر الجهــات الشــارية.\n بطلبــات إبــداء الــرأي ،مــا يعكــس ّ\n ويمكــن قــراءة هــذا االرتفــاع كمؤشــر مــزدوج الداللــة:\n يدّل على تزايد وعي الجهات الشارية بمتطلبات القانون وحاجتها إلى االلتزام باإلجراءات\n • من جهةّ ،\n المختّصة؛\n ّ القانونية واللجوء إلى المرجعية\n • ومن جهة أخرى ،يعكس اعتمادًاً متزايدًاً على الهيئة كمرجعية تنظيمية لتفسير النصوص وتوحيد\n الممارسات.\nالتطــور ال يمكــن فصلــه عــن الضغــط التشــغيلي المتزايــد الــذي يولّ ــده علــى الهيئــة ،فــي ظــل\n ّ أن هــذاغيــر ّ\nمحدوديــة المــوارد البشــرية المتاحــة ،مــا يســلّ ط الضــوء علــى ضــرورة االســتثمار فــي القــدرات المؤسســية كشــرط\n الســتدامة اإلصــاح.\nكمؤّشــر على التوازن بين الجودة والضغط التشــغيلي ّ ب .المهل الزمنية الســتجابة هيئة الشراء العام\nُتُ ظهــر معــدالت المهلــة الزمنيــة الســتجابة هيئــة الشــراء العــام لطلبــات إبــداء الــرأي قــدرة الهيئــة علــى الحفــاظ\nعلــى مســتوى مقبــول مــن الفعاليــة رغــم االرتفــاع المتواصــل فــي حجــم وتعقيــد المعــامالت .وتكتســب هــذه\n المؤشــرات أهميــة خاصــة عنــد قراءتهــا فــي ســياق وطنــي شــديد التعقيــد ،اّتّ ســم بـــ:\n •أزمات متالحقة ذات طابع مالي واقتصادي ومؤسسي؛\n •ظروف أمنية استثنائية خالل بعض الفترات؛\n مواز في الموارد البشرية."}, {"o": 18, "l": "المادة 115", "b": "ٍ •واستمرار العمل دون تعزيز\n\f 20\nوبذلــك ،ال ُيقــاس زمــن االســتجابة هنــا كمؤشــر أداء تقنــي فحســب ،بــل كدليــل علــى مرونــة مؤسســية ناشــئة،\n تحتــاج إلــى دعــم لتعزيزهــا ال إلــى تحميلهــا أعبــاء إضافيــة.\n البيانــات المتاحــة تشــير إلــى مســار إصالحــي نشــط ،لكنــه يعمــل عنــد حــدود طاقتــه القصــوى ،ما يجعل دعــم القدرات\n أولويــة ال تقــل أهميــة عــن دعم التشــريعات.\n يقيد اإلصالح؟\n .IVما الذي ال يزال ّ\n تشخيص واقعي للفجوات البنيوية\nأن إصــاح الشــراء العــام فــي لبنــان ال يــزال يواجــه مجموعــة\n يبيــن التقريــر بوضــوح ّ\n علــى الرغــم مــن التقـ ّـدم المحقــقّ ،\nمــن التحديــات المتداخلــة ،ال يمكــن معالجتهــا بإجــراءات معزولــة أو قصيــرة األمــد .ويقتــرح التقريــر مقاربــة تشــخيصية\n تُ صنّ ــف هــذه التحديــات ضمــن أربعــة مســتويات مترابطــة:\n .1التحديات المؤسسية\n ّ\n تتمثل أبرز هذه التحديات في:\n •محدودية الموارد البشرية المتخصصة داخل هيئة الشراء العام والجهات الشارية؛\n •عدم استكمال تكييف الهياكل التنظيمية في عدد كبير من اإلدارات؛\n •التفاوت الكبير في مستويات الجهوزية المؤسسية بين جهة وأخرى.\nموحــد علــى\n ّ ويــؤدي هــذا الواقــع إلــى تفــاوت فــي جــودة التطبيــق ،ويضعــف قــدرة النظــام علــى تحقيــق أثــر\n المســتوى الوطنــي.\n .2التحديات القانونية والتنظيمية\nعلــى الرغــم مــن حداثــة قانــون الشــراء العــام ،ال يــزال هنالــك حاجــة الــى بعــض النصــوص التنظيميــة التــي تهــدف\n الــى:\n •مزيد من التوضيح؛\n •التحديث المستمر استجابة للتطبيق العملي؛\n التحوالت الرقمية.\n ّ والتكيف مع\n ّ •\nكمــا يبــرز تحـ ّـدي مواءمــة القوانيــن واألنظمــة األخــرى ذات الصلــة (الماليــة ،اإلداريــة ،الرقابيــة) مــع فلســفة قانــون"}, {"o": 19, "l": "المادة 115", "b": "الشــراء العــام ،بمــا يمنــع التناقضــات أو االزدواجيــة فــي التفســير والتطبيــق.\n .3التحديات التقنية والرقمية\nالمحقــق ،ال تــزال التحديــات قائمــة علــى\n ّ ُيعـ ّـد البعــد الرقمــي أحــد أكثــر محــاور اإلصــاح حساســية .فرغــم التقـ ّـدم\n مســتوى:\n •تكامل األنظمة؛\n •جودة البيانات؛\n •استخدام التحليل الرقمي كأداة دعم للقرار؛\n •وضمان االستمرارية التقنية في ظل محدودية الموارد.\n ويحذر التقرير من االكتفاء برقمنة شكلية لإلجراءات ،دون االنتقال إلى نموذج حوكمة رقمية شاملة.\n ّ\n\f21\n .4التحديات الثقافية والسلوكية\n ربما تكون هذه التحديات هي األكثر تعقيداً ،إذ ترتبط:\n •بثقافة إدارية راسخة؛\n •بمقاومة التغيير؛\n •وبفهم محدود لمفهوم الشراء العام كأداة سياسات عامة ،ال كإجراء إداري صرف.\n أن معالجة هذا البعد تتطلّ ب استثمارات طويلة األمد في التدريب ،والتواصل ،وبناء الثقة.\n ويؤكد التقرير ّ\nاإلصــاح التشــريعي بلــغ مرحلــة متقدمــة ،لكــن اإلصــاح المؤسســي والســلوكي لــم يكتمــل بعــد ،وهــو مــا يجعــل\n الموجــه شــرطاً أساســياً لتفــادي تــآكل المكاســب المحققــة.\n ّ الدعــم الدولــي\n .Vأولويات الهيئة االستراتيجية للمرحلة المقبلة\n تثبيت اإلصالح وتوسيعه\nبعــد الســنوات األولــى مــن تطبيــق قانــون الشــراء العــام ،بــات واضحــاً أن اإلصــاح لــم يعــد مســألة تشــريعية أو\nتنظيميــة فحســب ،بــل أصبــح مســاراً مؤسســياً طويــل األمــد يتطلّ ــب رؤيــة اســتراتيجية متكاملــة ،تقــوم علــى تثبيــت\n تحقــق ،ومعالجــة مكامــن الضعــف ،واالنتقــال مــن منطــق اإلطــاق إلــى منطــق االســتدامة. مــا ّ\nوانطالقــاً مــن التجربــة العمليــة لهيئــة الشــراء العــام ،ومــن تحليــل المعطيــات والمؤشــرات الــواردة فــي هــذا التقريــر،"}, {"o": 20, "l": "المادة 115", "b": "يمكــن تحديــد خمــس أولويــات اســتراتيجية مترابطــة تشــكّ ل إطــار العمــل للمرحلــة المقبلــة.\n التحول الرقمي كنقطة ارتكاز لإلصالح ّ .1استكمال\n ّ\nوتتمثــل األولويــة فــي االنتقــال تؤكّ ــد التجربــة أن الرقمنــة ليســت أداة تقنيــة مســاندة ،بــل خيــاراً إصالحيــاً بنيويــاً.\nتغطــي كامــل دورة الشــراء\n مــن اســتخدام األدوات الرقميــة الجزئيــة إلــى إرســاء منظومــة شــراء إلكترونــي متكاملــةّ ،\n العــام ،مــن التخطيــط إلــى التلزيــم والتنفيــذ والرقابــة الالحقــة .ويشــمل ذلــك:\n •تعميم االنتساب اإللزامي للجهات الشارية إلى المنصة االلكترونية المركزية؛\n تتبع العمليات وتحليل البيانات؛\n •ضمان قابلية ّ\n •تعزيز الشفافية والمساءلة العامة.\n .2تعزيز المهنية وبناء القدرات المؤسسية\nأظهــر التطبيــق أن نجــاح القانــون مرتبــط مباشــرة بقــدرة المــوارد البشــرية علــى اســتيعابه وتطبيقــه .وعليــهُ ،يعـ ّـد بناء\nالقــدرات والتدريــب المتخصــص أولويــة اســتراتيجية ،ليــس فقــط لموظفــي هيئــة الشــراء العــام ،بــل أيضــاً للجهــات\n للمورديــن .ويقتضــي ذلــك:\n ّ الشــارية ووحــدات الشــراء والتدقيــق الداخلــي كمــا\n التوجهات الوطنية للتدريب بحسب االولويات االستراتيجية؛\n ّ •وضع\n •بناء القدرات بالتعاون مع الشركاء؛\n •ربط التدريب بالتطبيق العملي؛\n •االنتقال من المعرفة الفردية إلى المعرفة المؤسسية.\n .3تثبيت اإلطار التنظيمي وتوحيد الممارسات\nالتقــدم المحقــق علــى المســتوى التنظيمــي ،ال تــزال الحاجــة قائمــة الســتكمال إصــدار األدلــة اإلجرائيــة، ّ رغــم\nوتوضيــح بعــض المســائل التطبيقيــة ،بمــا يحـ ّـد مــن االجتهــادات المتباينــة ،ويضمــن وحــدة تفســير القانــون وتكافــؤ\n التطبيــق بيــن مختلــف الجهــات الخاضعــة لــه.\n\f 22"}, {"o": 21, "l": "المادة 115", "b": ".4تعزيز التنسيق والحوكمة متعددة المستويات\nــاال بيــن مختلــف الجهــات المعنيــة :الجهــات الشــارية ،األجهــزة\n فع ً يتطلّ ــب نظــام الشــراء العــام الحديــث تنســيقاً ّ\n ّ\nوتتمثــل األولويــة فــي ترســيخ هــذا التنســيق ضمــن أطــر مؤسســية واضحــة، الرقابيــة ،القضــاء ،والمجتمــع المدنــي.\n تحفــظ اســتقاللية األدوار وتكاملهــا وتمنــع تداخــل الصالحيــات.\n .5ضمان االستدامة المؤسسية للهيئة\nالتحــدي األبــرز هــو االنتقــال مــن هيئــة تعمــل فــي ظــروف اســتثنائية إلــى مؤسســة مســتقرة ،مــن حيــث ّ يبقــى\nالمــوارد البشــرية ،والقــدرات التقنيــة ،والتمويــل ،بمــا يتيــح لهــا االضطــاع بدورهــا الكامــل كمــا نـ ّـص عليــه القانــون.\n .VIالتعاون الدولي :من دعم اإلصالح إلى شراكة في بناء النظام\nقدمــه شــركاءلــم يكــن مســار إصــاح الشــراء العــام فــي لبنــان ليأخــذ شــكله الحالــي لــوال الدعــم المتواصــل الــذي ّ\nلبنــان الدوليــون ،وال سـ ّـيما خــال المراحــل التحضيريــة لتشــريع القانــون ،ثــم فــي مرحلــة إطــاق هيئــة الشــراء العــام\n ومواكبــة تطبيقــه.\nأن هــذا التقريــر ُيظهــر بوضــوح أن دور التعــاون الدولــي تجــاوز الدعــم الظرفــي أو المشــاريع القطاعيــة ،ليشــكّ ل\n غيــر ّ\n رافعــة أساســية لبنــاء نظــام وطنــي للشــراء العــام.\n .1مواكبة اإلصالح منذ مراحله التأسيسية\n ساهم الشركاء الدوليون في:\n •دعم التقييمات التشخيصية؛\n •مرافقة إعداد اإلطار التشريعي والتنظيمي؛\n •تعزيز المعايير الدولية في تصميم نظام الشراء العام الجديد.\nوقــد شــكّ ل هــذا الدعــم عنصــراً حاســماً فــي االنتقــال مــن إدارة المناقصــات إلــى هيئــة الشــراء العــام ،وفــي تثبيــت\n منطــق اإلصــاح المؤسســي.\n .2دعم اإلطالق والتشغيل في مرحلة عالية المخاطر"}, {"o": 22, "l": "المادة 115", "b": "تحديــات غيــر مســبوقة ،فــي ظــل االنهيــار االقتصــادي واألزمــات المتالحقــة.\n مــع بــدء نفــاذ القانــون ،واجهــت الهيئــة ّ\n وفــي هــذا الســياق ،أســهم التعــاون الدولــي فــي:\n •دعم القدرات التشغيلية؛\n التحول الرقمي؛\n ّ •مواكبة\n •تعزيز التنسيق بين الجهات المعنية.\n .3نحو شراكة استراتيجية طويلة األمد\nوأن المرحلــة المقبلــة تتطلّ ــب نقلــة نوعيــة فــي طبيعــة التعــاون الدولــي،\n تُ ظهــر التجربــة أن اإلصــاح لــم يكتمــل بعــدّ ،\n تقــوم علــى:\n •برامج دعم متعددة السنوات؛\n •استثمارات في األنظمة الرقمية؛\n •نقل معرفة وبناء قدرات مستدامة؛\n •مواءمة الدعم مع األولويات الوطنية.\n\f23\nومــن هــذا المنطلــق ،تشــكّ ل هــذه المرحلــة دعــوة صريحــة إلــى الشــركاء الدولييــن لالنتقــال مــن دعــم اإلصــاح إلــى\n الشــراكة فــي ترســيخه.\nيقــدم ســرداً إلنجــازات فحســب ،وال يكتفــي بتشــخيص ّ إن مــا يعرضــه هــذا التقريــر ،فــي فصولــه التســعة ،ال\nالتحديــات ،بــل يرســم مالمــح مســار إصالحــي قائــم علــى قناعــة راســخة بــأن بنــاء دولــة القانــون والمؤسســات يبــدأ ّ\nـا للتطويــر ،ومتالزمــاً مــع اإلرادة الوطنيــة،ً ـ وقاب ـاًـ ديناميكي ـارـ المس ـذاـ ه ـيبقىـ وس ـام.ـ الع ـاقـ اإلنف ـةـ حوكم مــن\nومــع اســتمرار الشــراكة مــع المجتمــع الدولــي .وفيمــا تؤكــد هيئــة الشــراء العــام التزامهــا الكامــل باســتكمال\nـإن ترســيخه وتأميــن اســتدامته يظــان رهنــاً بتوفيــر دعــم سياســي واضــح ،وتمكيــن هــذا المســار اإلصالحــي ،فـ ّ\nويترجــم اإلرادة المشــتركة إلــى مؤسســي فاعــل ،وشــراكة دوليــة متواصلــة ،بمــا يحــول دون انتــكاس اإلصــاحُ ،\n نتائــج ملموســة ودائمــة.\n\f الفصل األول\nمــن إدارة المناقصــات إلــى هيئــة الشــراء\n العــام\n\f جدول المحتويات"}, {"o": 23, "l": "المادة 115", "b": "26 .Iالخلفية التاريخية واإلطار القانوني السابق لقانون الشراء العام ()2022 - 1959\n26 .IIإشكاليات نظام الصفقات العمومية قبل قانون الشراء العام\n26 .1الثغرات الهيكلية والنقص في المعلومات\n27 .2التحديات اإلجرائية والقانونية\n27 .3التحديات الفنية\n28 .IIIأداء إدارة المناقصات وإنجازاتها\n28 .1التدقيق القانوني والفني\n28 .2التوحيد والتبسيط\n28 .3دمج معايير التنمية المستدامة\n28 .4اإلنجازات ضمن برنامج المساعدة التقنية ()TAF\n28 .5مكافحة الفساد المالي\n29 .IVمرحلة االنتقال المؤسسي والموارد البشرية\n\f 26\n الفصل األول :من إدارة المناقصات إلى هيئة الشراء العام\n .Iالخلفية التاريخية واإلطار القانوني السابق لقانون الشراء العام ()2022 - 1959\nتعــود الجــذور القانونيــة للنظــام الســابق للشــراء العــام فــي لبنــان أو مــا كان يعــرف بـ»الصفقــات العموميــة» إلــى\nالمرســوم رقــم 59/2460الصــادر فــي 1959/11/9المتعلــق بتنظيــم التفتيــش المركــزي والــذي أنشــئت بموجبــه\n«إدارة المناقصــات» ،باإلضافــة الــى المرســوم رقــم ( 59/2866نظــام المناقصــات) الــذي أوجــب علــى المؤسســات\nالمطبقــة علــى اإلدارات العامــة فــي موضــوع الصفقاتّ العامــة والبلديــات واتحــادات البلديــات اعتمــاد ذات األســس\nالعموميــة .اســتكمل قانــون المحاســبة العموميــة الصــادر بالمرســوم رقــم 14969فــي العــام 1963هــذا اإلطــار\nالقانونــي ،وال ســيما فــي مــا يتعلــق بعقــد النفقــات ،وآليــات الرقابــة المســبقة والمؤخــرة ،وصالحيــات الســلطات\nموحــد\n ّ المختصــة بااللتــزام والصــرف .والجديــر بالذكــر أنّ ــه قبــل العــام 1959لــم يكــن يوجــد أي إطــار قانونــي تنظيمــي\n إلجــراء الصفقــات العموميــة ولــو علــى مســتوى إدارات الدولــة المركزيــة."}, {"o": 24, "l": "المادة 115", "b": "شــكّ ل نظــام المناقصــات فــي لبنــان وقانــون المحاســبة العموميــة اإلطــار القانونــي الناظــم لعمليــات الصفقــات\nالعموميــة قبــل إقــرار قانــون الشــراء العــام رقــم 2021/244فــي العــام .2021وقــد هــدف هــذا اإلطــار إلــى تنظيــم\nكيفيــة إنفــاق المــال العــام مــن خــال تحديــد القواعــد واإلجــراءات الواجــب اتباعهــا فــي التلزيمــات الحكوميــة ،بمــا\n يضمــن مبــادئ المنافســة ،والمســاواة بيــن المتنافســين ،وحســن إدارة األمــوال العامــة.\nكمــا كـ ّـرس نظــام المناقصــات الصــادر فــي العــام 1959دور إدارة المناقصــات كجهــة مركزيــة تتولــى اإلشــراف علــى\nإجــراءات المناقصــات ،وأعطاهــا دوراً رقابيــاً تمحــور حــول التدقيــق فــي الملفــات لضمــان قانونيــة وشــفافية عمليــات\n التلزيــم ،وقــد شــمل هــذا الــدور:\n • التأكد من إدراج المناقصة في البرنامج السنوي أو وجود ترخيص بإجرائها؛\n وتوفر االعتماد المالي؛\n ّ • التحقق من استكمال الملف للمستندات اإللزامية\n خلّوه من كل ما من شأنه تقييد\n • تصديق دفتر الشروط الخاص وانطباقه على القوانين واألنظمة ،وضمان ّ\n المنافسة أو ترجيح كفة أحد المنافسين؛\n التهّرب من تطبيق األحكام القانونية؛\n ّ مبّرر فني أو مالي لضمان عدم• منع تجزئة األشغال أو اللوازم دون ّ\n • التحقق من صحة تقدير الكميات واألسعار.\nورغــم أن نظــام المناقصــات شــكّ ل لعــدة عقــود مرجعيــة أساســية للشــراء الحكومــي فــي لبنــان ،إال أن محدوديــة\nنطاقــه ،وضعــف أدوات الشــفافية والحوكمــة فيــه ،إضافــة إلــى عــدم مواكبتــه للمعاييــر الدوليــة الحديثــةّ ،أدت إلــى\nاعتبــاره إطــاراً تقليديــاً لــم يعــد قــادراً علــى االســتجابة لمتطلبــات الحوكمــة واإلدارة الحديثــة ،مــا اســتدعى الحقــاً"}, {"o": 25, "l": "المادة 115", "b": "اســتبداله بقانــون أكثــر شــمولية وتطـ ّـوراً فــي العــام ،2021وهــو قانــون الشــراء العــام رقــم .2021/244\n .IIإشكاليات نظام الصفقات العمومية قبل قانون الشراء العام\nالمرجوتيــن،\n ّ اتّ صــف نظــام الصفقــات العموميــة الســابق لقانــون الشــراء العــام فــي لبنــان بانــه دون الكفــاءة والفاعليــة\nوحــال دون بلــوغ هــذا الهــدف بشــكل كلــي مشــاكل تراوحــت بيــن النــص الســابق وتطبيقاتــه وامكانيــات اإلدارات\n العامــة الفنّ يــة والبشــرية ،يمكــن تلخيصهــا فــي مــا يلــي:\n .1الثغرات الهيكلية والنقص في المعلومات\n أ .غياب المرصد الوطني للبيانات\nلــم توجــد جهــة مركزيــة تملــك معلومــات شــاملة عــن مجمــل الصفقــات العموميــة ،ممــا حال دون تحليــل اإلنفاق\n واالســتفادة مــن البيانــات فــي إعــداد الموازنــات وفــي عمليــات الرقابــة علــى كفاءة اإلنفــاق العام.\n\f27\n ب.محدودية الجهات المشمولة بصالحية إدارة المناقصات\nالممولــة مــن المــال العــام خاضعــة إلدارة المناقصــات .تشــير التقديــرات إلــى أن نســبة\n ّ لــم تكــن جميــع الصفقــات\nاإلنفــاق مــن خــال إدارة المناقصــات لــم تتجــاوز %5مــن مجمــل اإلنفــاق العــام علــى الصفقــات ،فيمــا كانــت\nمؤسســات عامــة وبلديــات تنفــق مليــارات الليــرات خــارج هــذا اإلطــار ،دون خضــوع موازناتهــا لتصديــق الســلطة\n التشــريعية.\n .2التحديات اإلجرائية والقانونية\n أ .إساءة تطبيق القوانين\n • تخفيض مهل اإلعالن :كانت ترد طلبات متكررة الى إدارة المناقصات لتخفيض مهلة اإلعالن إلى 5\n أيام بحجة «الضرورة» .مع العلم ان التخفيض مسموح به قانونًاً لحاالت الضرورة فقط ،اال أن إساءة\n استخدام السماح بالتخفيض كان يؤدي الى إلغاء المنافسة واإلخالل بمبدأي العلنية والمساواة."}, {"o": 26, "l": "المادة 115", "b": "• تجزئة الصفقات :عمدت بعض اإلدارات إلى تجزئة الصفقات لتجنّ ب رقابة إدارة المناقصات.\n محّددة بإجراء\n ّ • القرارات المخالفة :صدرت قرارات عن السلطة التنفيذية (مجلس الوزراء) في حاالت\n صفقات بطرق غير تنافسية أو بتكليف لجان خاصة خارج األطر القانونية (مثال :صفقة شبكات الهاتف\n الخليوي لعام ،2015ومناقصة مراكز المعاينة الميكانيكية لعام 2016ومناقصة بواخر كهرباء العام\n .)٢٠١٧\n ب .الصفقات غير التنافسية\n • االتفاقات الرضائية :شاع اللجوء إلى االتفاقات الرضائية خارج إطار األسباب الموضوعية التي يجيزها\n قانون المحاسبة العمومية ،وبالرغم من تعارضها مع التزام لبنان باتفاقية األمم المتحدة لمكافحة\n الفساد وتطبيق مبدأ المنافسة في عقد الصفقات العمومية.\n عّد من دون\n • إستدراجات العروض المحصورة :اعتماد استدراجات عروض محصورة بلوائح مختصرة ُتُ ّ\n يحّد من المنافسة ويؤدي\n معايير واضحة ،وغالبًاً ما تقتصر على شركات محددة تتكرر مشاركتها ،ما ّ\n إلى ارتفاع األسعار.\n ج .غياب التخطيط\n حّول الشراء إلى إجراءات طارئة ترفع التكلفة\n تّم االلتزام بالبرنامج السنوي للصفقات ،مما ّ\n • نادرًاً ما ّ\n وتقّلّ ص المنافسة.\n •عدم إلزامية وضع سعر تقديري للصفقات ،مما سمح بالتواطؤ ورفع األسعار فوق الكلفة الفعلية.\n د .إشكالية تصنيف المتعهدين\nعانــى تطبيــق تصنيــف المتعهديــن فــي النظــام الســابق للصفقــات العموميــة مــن مشــاكل أبرزهــا الحــد مــن\nالمنافســة ،وبقيــت هــذه المســألة إحــدى أبــرز اإلشــكاليات حتــى صــدور قانــون الشــراء العــام رقــم ،2021/244\n بدال عنها.\n الذي ألغى المراسيم السابقة المتعلقة بالتصنيف واعتمد التأهيل المسبق ً\n .3التحديات الفنية\n أ .لجان التلزيم واالستالم\nصعوبــة فــي تشــكيل هــذه اللجــان بســبب نقــص العناصــر الكفــؤة ،باإلضافــة الــى مشــاكل تتعلــق بآليــة وقواعــد"}, {"o": 27, "l": "المادة 115", "b": "عملهــا وإجــراءات الرقابــة عليهــا.\n\f 28\n ب .غياب المعايير البيئية واالجتماعية\n افتقرت دفاتر الشروط الخاصة لمعايير التنمية المستدامة ،بالرغم من حرص إدارة المناقصات على التأكيد على:\n• تشــجيع المؤسســات الصغيرة والمتوســطة الحجم على المشــاركة عبر تبســيط اإلجراءات وتخفيف الشــروط\n المطلوبة لالشتراك بالمناقصة؛\n والتقيد بأحكام قوانين العمل والضمان االجتماعي؛ ّ • تحفيز استخدام اليد العاملة اللبنانية\n• دراســة االثــر البيئــي بالنســبة للمشــاريع التــي تســتوجب ذلــك ،اال أنــه غالبــًاً مــا تأخــرت دراســات األثــر البيئي لما\n يلّوث يدفع». بعد التلزيم أو التنفيذ في كثير من الحاالت ،دون تطبيق مبدأ «من ّ\n .IIIأداء إدارة المناقصات وإنجازاتها\nفــي ظــل المعطيــات الصعبــة والمــوارد المحــدودة وبالرغــم مــن محدوديــة صالحياتهــا المعطــاة لهــا قانونــاً ،\nاســتطاعت إدارة المناقصــات ،فــي المعامــات التــي عرضــت عليهــا ،الحفــاظ علــى المــال العــام وممارســة صالحياتهــا\n بحياديــة ،وذلــك عبــر المحــاور التاليــة:1\n .1التدقيق القانوني والفني\n • رفضت اإلدارة إعطاء الحجج ليحل محلها سواها ،وأبدت مالحظات موضوعية على دفاتر الشروط حتى\n تلك المقررة في مجلس الوزراء (مثال :صفقات الفيول ،بواخر الكهرباء.)... ،\n • أصدرت تقارير خاصة في الصفقات المخالفة للقانون (مثال :مراكز المعاينة الميكانيكية ،بواخر الكهرباء).\n .2التوحيد والتبسيط\nموحــدة ونمــاذج قياســية (تصريــح النزاهــة ،نمــوذج التعهــد ،نموذج األســعار) لتســهيل\n ّ عممــت شــروطاً إداريــة عامــة\n ّ\n ولــوج المؤسســات الصغيــرة والمتوســطة وتكافؤ الفرص.\n .3دمج معايير التنمية المستدامة\nحرصــت علــى تضميــن دفاتــر الشــروط اعتبــارات بيئيــة (المراســيم رقــم 2012/8213ورقــم ،)2012/8633ودعــم اليــد"}, {"o": 28, "l": "المادة 115", "b": "العاملــة اللبنانيــة ،وتفضيــل المنتجــات الوطنيــة ،وضبــط الضمانــات المصرفيــة.\n .4اإلنجازات ضمن برنامج المساعدة التقنية ()TAF\n تم إنجاز ملفات استراتيجية ،أبرزها:\n بتمويل من االتحاد األوروبي (ّ ،)2022-2017\n • ملف الكهرباء ( :)IPPاقترحت إدارة المناقصات االستغناء عن الحل المؤقت لصالح الحل الدائم (توربينات\n الزهراني) ،مما يوفر على الخزينة نحو مليار دوالر ويؤمن طاقة مستدامة بكفاءة أعلى.\n مقّيدة للمنافسة مستمدة من • مواصفات الفيول والغاز أويل :كشف تقرير الخبراء عن مواصفات ّ\n كاتالوغات شركات محددة ،وتم التوصية بتصحيحها لتتوافق مع معايير الـ .ISO\n • ملفات أخرى :مراجعة شروط مناقصات مرفأ بيروت ،عدادات الوقوف (بارك ميتر) بناء على طلب وزارة\n األشغال العامة والنقل وبلدية بيروت ،عقود سوناطراك ،ودعم الجمارك في مواصفات سكانر التفتيش\n في المرافئ والمنشآت الحدودية.\n .5مكافحة الفساد المالي\nبنــاء علــى قــرار مجلــس\n أدرجــت إدارة المناقصــات رفــع الســرية المصرفيــة لمصلحــة اإلدارة فــي دفاتــر الشــروطً ،\n الــوزراء رقــم 4تاريــخ ،2020/4/28لضمــان شــفافية التدفقــات الماليــة.\n 1يمكن االطالع على التفاصيل في الملحق رقم 1\n\f29\n .IVمرحلة االنتقال المؤسسي والموارد البشرية\nشــكّ ل االنتقــال مــن «إدارة المناقصــات» إلــى «هيئــة الشــراء العــام» بموجــب المــادة 88مــن قانــون الشــراء العــام\nنقطــة تحـ ّـول مفصليــة فــي نظــام الشــراء العــام فــي لبنــان ،إذ جــرى التحـ ّـول مــن جهــاز ذي طابــع تنفيــذي يتولــى إدارة\nالصفقــات مركزيــاً ،إلــى ســلطة ناظمــة ذات دور سياســاتي وتنظيمــي ورقابــي ،تتمتــع بصالحيــات واســعة فــي اقتــراح\n السياســات العامــة ،وإصــدار األطــر التنظيميــة ،وتعزيــز الحوكمــة والشــفافية فــي الشــراء العــام."}, {"o": 29, "l": "المادة 115", "b": "أمــا واقــع المــوارد البشــرية لهيئــة الشــراء العــام عنــد االنتقــال فهــو لــم يكــن متكافئــاً مــع المســؤوليات والمهــام\nالموكلــة الــى الهيئــة الجديــدة ،إذ انتقــل الــى الهيئــة ثمانيــة موظفيــن مــن إدارة المناقصــات ،باإلضافــة الــى الرئيــس،\n ممــا يظهــر حجــم التحــدي التشــغيلي الــذي واجهتــه (وال تــزال تواجهــه) هــذه الهيئــة منــذ انطالقتهــا...\n\f الفصل الثاني\nسياق إصالح الشراء العام في لبنان\n\f جدول المحتويات\n32 .Iمسار إصالح الشراء العام قبل العام 2021\n33 .IIقانون الشراء العام الجديد\n33 التحوالت المؤسسية والقانونية المرافقة\n ّ .III\n .IVالمؤشرات األولية ألثر اإلصالح 34\n34 .Vالتحديات المرتبطة بسياق اإلصالح\n34 .VIدور هيئة الشراء العام في سياق اإلصالح\n\f 32\n الفصل الثاني :سياق إصالح الشراء العام في لبنان\n .Iمسار إصالح الشراء العام قبل العام 2021\nلــم يكــن إصــاح نظــام الشــراء العــام أو الصفقــات العموميــة فــي لبنــان خطــوة معزولــة أو آنيــة ،بــل جــاء نتيجــة مســار\n تدريجــي امتـ ّـد علــى مــدى ســنوات طويلــةّ ،\nتأثــر بالتحديــات البنيويــة التــي واجهــت إدارة الماليــة العامــة ،وبالحاجــة\n المتزايــدة إلــى تحديــث األطــر القانونيــة والمؤسســية الناظمــة لإلنفــاق العــام.\nتنظــم الصفقــات العموميــة ضمــن قانــون المحاســبة العموميــة ونظــام المناقصــات فعلــى الرغــم مــن وجــود قواعــد ّ\nأن تعـ ّـدد هــذه األنظمــة واالســتثناءات واختــاف الممارســات بيــن اإلدارات ّأدت إلــى نشــوء وأنظمــة خاصــة أخــرى ،إال ّ\n نظــام غيــر متجانــس ،يفتقــر إلــى الشــمولية والشــفافية الكافيــة ،ويحـ ّـد مــن فعاليــة الرقابــة والمســاءلة."}, {"o": 30, "l": "المادة 115", "b": "جديــة متعـ ّـددة هدفــت إلــى تحســين حوكمــة الشــراء العــام، بــدءاً مــن العــام ،2012بــدأت تبــرز مبــادرات إصالحيــة ّ\nشــملت تطويــر بعــض اإلجــراءات ،وتعزيــز دور الهيئــات الرقابيــة ،وإدخــال مبــادئ المنافســة والعلنيــة بشــكل أوســع.\nكمــا شــكّ لت التجربــة المتراكمــة إلدارة المناقصــات عنصــراً أساســياً فــي كشــف الثغــرات القائمــة وفــي بلــورة الحاجــة\n موحــد.\n ّ إلــى إطــار قانونــي\nوتعــزّ ز هــذا المســار اإلصالحــي تدريجيــاً بفعــل التزامــات لبنــان الدوليــة وبشــكل خــاص منــذ مؤتمــر CEDREفــي العــام\n ،2018وال ســيما فــي مجــال الشــفافية ومكافحــة الفســاد ،إضافــة إلــى توصيــات الجهــات الدوليــة الداعمــة لإلصــاح\nالمالــي واإلداري ،التــي أكّ ــدت مــراراً علــى مركزيــة الشــراء العــام فــي ضبــط اإلنفــاق العــام وتحســين الحوكمــة .ترافــق\nذلــك مــع التزامــات محليــة تجلّ ــت عبــر التــزام الحكومــات المتتاليــة بإصــاح الشــراء العــام كمدخــل الــى إصــاح الماليــة\n العامة.\nمهــد هــذا المســار التراكمــي إلقــرار قانــون الشــراء العــام فــي العــام ،2021الــذي شــكّ ل نقلــة نوعيــة مــنوقــد ّ\nإصالحــات جزئيــة ومبعثــرة إلــى إصــاح تشــريعي شــامل ،كمــا أرســى أسســاً جديــدة لتنظيــم الشــراء العــام وأنشــأ هيئــة\n الشــراء العــام كســلطة رقابيــة تنظيميــة مســتقلة لتولّ ــي مواكبــة تنفيــذ هــذا اإلصــاح.2\n والبينات ()EVIDENCE-BASED POLICY REFORM\n ّ مبني على األرقام\n ّ إصالح\nاعتمــدت مقاربــة إصــاح الشــراء العــام فــي لبنــان منهجيــة قائمــة علــى األدلــة واألرقــام (Evidence-Based\n ،)Approachارتكــزت علــى تشــخيص موضوعــي للثغــرات القانونيــة والمؤسســية واإلجرائيــة ،بــدل االكتفــاء"}, {"o": 31, "l": "المادة 115", "b": "بمعالجــات ظرفيــة أو جزئيــة .وقــد اســتند هــذا النهــج إلــى تقييمــات ودراســات تحليليــة هدفــت إلــى فهــم واقــع\nنظــام الشــراء العــام ،وقيــاس مــدى توافقــه مــع المعاييــر الدوليــة ،وتحديــد أولويــات اإلصــاح بشــكل منهجــي.\n وفي هذا اإلطار ،شّكّ ل تقييم نظام الشراء العام وفق منهجية (Methodology for Assessing\n ،MAPS (Procurement Systemsالــذي ُُأنجــز خالل عامــي 2020–2019بدعــم مــن البنــك الدولــي ووكالــة\nالتنميــة الفرنســية ،محطــة أساســية فــي مســار اإلصالح .وقــد أتــاح هــذا التقييــم تحديــد مكامــن الضعــف الهيكليــة،\nوال ســيما علــى صعيــد اإلطــار القانونــي ،والحوكمــة ،والقــدرات المؤسســية ،والشــفافية ،مــا أســهم فــي بلــورة\nرؤيــة إصالحيــة متكاملــة ُتُ ّّوجــت بإقــرار قانــون الشــراء العــام عــام 2021وإنشــاء هيئــة الشــراء العــام كســلطة رقابيــة\nوتنظيميــة مســتقلة ،وهيئــة االعتراضــات كجهــة تختـ ّـّص بالنظــر فــي المراجعــات والشــكاوى فــي مرحلــة مــا قبــل\n توقيــع العقــد.\n 2لالطالع على المراحل التشريعية التي أدت الى صدور قانون الشراء العام رقم ،2021/244يرجى الرجوع الى الملحق رقم 2\n\f33\nوقــد أتــاح تقييــم MAPSاعتمــاد مجموعــة مــن المؤشــرات التشــخيصية المرجعيــة (،)Baseline Indicators\n المحقــق الحقــاً ،وال ســيما فــي المجــاالت التاليــة:\n ّ التقــدم\n ّ شــكّ لت نقطــة انطــاق لقيــاس\n •درجة توحيد اإلطار القانوني للشراء العام،\n • مستوى اعتماد اإلجراءات التنافسية،\n •وضوح األدوار المؤسسية وتوزيع الصالحيات،\n •مستوى نشر المعلومات المتعلقة بإجراءات الشراء،\n •توافر آليات الطعن والمساءلة.\n .IIقانون الشراء العام الجديد\n موحداً يهدف إلى:\n ّ أرسى قانون الشراء العام إطاراً تشريعياً"}, {"o": 32, "l": "المادة 115", "b": "• تنظيم إجراءات الشراء التي تقوم بها الجهات الشارية كافة (اإلدارات العامة ،المؤسسات العامة ،البلديات\n موّحدة ،واضحة ومعلنة،\n ّ والهيئات وغيرها من الجهات الشارية المشمولة بالقانون) ضمن قواعد\n • تنظيم عمل لجان التلزيم واالستالم،\n • تعزيز مبادئ الشفافية والمنافسة والمساواة وتكافؤ الفرص،\n • تحسين الكفاءة والفعالية في إنفاق المال العام وتحقيق أفضل قيمة مقابل الكلفة،\n • الحد من مخاطر الهدر والفساد وتعزيز آليات المساءلة.\nـاال نوعيــاً مــن نظــام قائــم علــى اســتثناءات متعـ ّـددة واجتهــادات إداريــة متباينــة ،إلــى\n وقــد شــكّ ل القانــون الجديــد انتقـ ً\nموحــدة .كمــا أرســى نهجــاً ال مركزيــاً إلجــراءات الشــراء ،إذ أصبحــت كافــة\n ّ نظــام مؤسســي حديــث يســتند إلــى إجــراءات\nـوال الــى تنفيــذ وإدارة العقــد\n مراحــل الشــراء مــن تحديــد الحاجــات والتخطيــط ،الــى إجــراءات التلزيــم وإرســاء العقــد وصـ ً\nموحــدة علــى هــذه اإلجــراءات ّ تجــري بطريقــة المركزيــة علــى مســتوى الجهــة الشــارية ،مــع إرســاء مركزيــة رقابيــة\n للتتبــع والرقابــة والمســاءلة.\n ّ قابلــة\nيتضمنهــا القانــون الجديــدُ ،يرجــى الرجــوع إلــى\n ّ لالطــاع علــى الدراســة التفصيليــة حــول المحــاور اإلصالحيــة التــي\n الملحــق رقــم ( )3المرفــق بهــذا التقريــر.\n التحوالت المؤسسية والقانونية المرافقة\n ّ .III\nلــم يقتصــر اإلصــاح علــى تحديــث اإلطــار القانونــي فحســب ،بــل شــمل أيضــاً إعــادة تنظيــم األدوار المؤسســية فــي\n مجــال الشــراء العــام ،وال ســيما مــن خــال:\n •إنشاء هيئة الشراء العام كسلطة رقابية تنظيمية مستقلة،\n تختص بالنظر في المراجعات والشكاوى في مرحلة ما قبل توقيع العقد، ّ •إنشاء هيئة االعتراضات كجهة\n •إعادة تحديد صالحيات الجهات الشارية ومسؤولياتها،"}, {"o": 33, "l": "المادة 115", "b": "•تنظيم العالقة بين هيئة الشراء العام وسائر أجهزة الرقابة اإلدارية والمالية والقضائية.\nتكيفــاً تدريجيــاً مــن قبــل اإلدارات العامــة ،ســواء علــى مســتوى اإلجــراءات أو الثقافــة\n وقــد تطلّ بــت هــذه التحـ ّـوالت ّ\n اإلداريــة ،فــي ظــل االنتقــال مــن ممارســات موروثــة إلــى قواعــد جديــدة أكثــر صرامــة وشــفافية.\n\f 34\n .IVالمؤشرات األولية ألثر اإلصالح\nمنــذ األشــهر األولــى لتطبيــق القانــون ،بــدأت تظهــر مؤشــرات أوليــة تعكــس أثــر اإلصــاح ،يمكــن رصدهــا مــن خــال\n مجموعــة مــن مؤشــرات األداء الســياقية ،مــن أبرزهــا:\n • ارتفاع نسبة اللجوء إلى اإلجراءات التنافسية مقارنة باإلجراءات االستثنائية،\n • زيادة عدد الجهات الشارية التي تطلب مواكبة وتوجيهات من هيئة الشراء العام،\n الموحدة الصادرة عن الهيئة،\n ّ • تنامي الطلب على النماذج ووثائق الشراء\n تحسن تدريجي في مستوى نشر اإلعالنات ووثائق الشراء، • ّ\n • ارتفاع عدد االستفسارات والتفاعالت المرتبطة بتطبيق القانون ،بما يعكس ازدياد الوعي بمتطلبات\n االمتثال.\n .Vالتحديات المرتبطة بسياق اإلصالح\nحيــز التنفيــذ فــي 29تمــوز 2022عــدداً مــن التحديــات\n واجــه تنفيــذ إصــاح الشــراء العــام منــذ دخــول القانــون الجديــد ّ\n البنيويــة ،أهمهــا:3\n• محدودية الموارد البشــرية لدى عدد كبير من اإلدارات والمؤسســات العامة ،وخاصة لدى البلديات واتحاداتها،\n • مقاومة التغيير الناتجة عن ممارسات إدارية راسخة،\n مّر بها لبنان خالل تلك الفترة والتي ّأّثرت على قدرة اإلدارات\n • الظروف االقتصادية والمالية الصعبة التي ّ\n التكّيف السريع.\n ّ على\nوقــد تعاملــت هيئــة الشــراء العــام مــع هــذه التحديــات مــن خــال اعتمــاد مقاربــة تدريجيــة ،ترتكــز علــى التوجيــه\nمكونــات الدولــة.\n ّ وتكامــا بيــن مختلــف"}, {"o": 34, "l": "المادة 115", "b": "ً والمواكبــة وبنــاء القــدرات ،مــع إدراك أن نجــاح اإلصــاح يتطلّ ــب وقتــاً\n والتحديــات التــي تواجــه هيئــة الشــراء العــام ومســار اصــاح الشــراء\n ّ مفصــل وشــامل لمجمــل القيــود ّ ُيعــرض تحليـ ٌـل\n العــام فــي الفصــل الثامــن مــن هــذا التقريــر.\n .VIدور هيئة الشراء العام في سياق اإلصالح\n في هذا السياق اإلصالحي ،اضطلعت هيئة الشراء العام بدور محوري يتمثل في:\n •مرافقة الجهات الشارية في فهم وتطبيق أحكام القانون،\n •توحيد الممارسات اإلجرائية والحد من التباين في التطبيق،\n •تعزيز ثقافة الشفافية والمساءلة في الشراء العام،\n •المساهمة في تحويل النص القانوني إلى ممارسة إدارية مستدامة.\nويشــكّ ل هــذا الــدور جــزءاً ال يتجــزّ أ مــن مســار إصالحــي أوســع ،يتطلّ ــب اســتمرار االلتــزام السياســي والمؤسســي،\n وتوفيــر المــوارد الالزمــة ،وتعزيــز التنســيق بيــن مختلــف الجهــات المعنيــة.\n 3لالطالع على المراحل التشريعية التي أدت الى صدور قانون الشراء العام رقم ،2021/244يرجى الرجوع الى الملحق رقم 2\n\f\f الفصل الثالث\nاإلطــار القانونــي والمؤسســي للشــراء\n العــام\n\f جدول المحتويات\n38 .Iاإلطار القانوني :قانون الشراء العام 2021/244\n38 .1المحاور اإلصالحية الرئيسية في قانون الشراء العام (قانون )2021/244\n39 التطور التشريعي ومعالجات التطبيق ()2025-2022\n ّ .2\n40 .IIاإلطار المؤسسي :هيئة الشراء العام\n40 .1هيئة الشراء العام :من التأسيس الى البناء المؤسسي\n40 .2معوقات تأسيس الهيئة والمعالجات\n41 .IIIالخالصة\n\f 38\n الفصل الثالث :اإلطار القانوني والمؤسسي للشراء العام\n .Iاإلطار القانوني :قانون الشراء العام 2021/244\n ُيعـ ّـد قانــون الشــراء العــام رقــم 2021/244حجــر الزاويــة فــي إصــاح منظومــة اإلنفــاق العــام فــي لبنــان .فقــد ّ\nمثــل"}, {"o": 35, "l": "المادة 115", "b": "ومقيــد بـــ «قانــون المحاســبة العموميــة» ونظــام المناقصــات القديــم ،إلــى قانــون\n ّ ـاال نوعيــاً مــن نظــام مجــزّ أ\n انتقـ ً\nيغطــي هــذا الفصــل أبــرز المحــاور\n موحــد يركّ ــز علــى القيمــة مقابــل المــال ،الشــفافية ،والمنافســة العادلــةّ .\n ّ عصــري\nاإلصالحيــة فــي القانــون ،التطـ ّـورات التشــريعية الالحقــة لتســهيل التطبيــق ،وبنــاء الهيــكل المؤسســي لهيئــة الشــراء\n العــام.\n .1المحاور اإلصالحية الرئيسية في قانون الشراء العام (قانون )2021/244\nمتميــزاً عــن التشــريعات الســابقة بالمبــادئ\n ّ ينظــم كافــة مراحــل الشــراء،\n شــامال ّ\n ً أرســى القانــون الجديــد إطــاراً\n واإلجــراءات التاليــة ،والتــي يمكــن تلخيصهــا فــي خمــس محــاور أساســية هــي :\n 4\n أ .توسيع نطاق التطبيق وتعريفات واضحة\n وّسع القانون مفهوم «الجهات الشارية» ليشمل الدولة ،اإلدارات العامة، • شمولية الجهات الخاضعةّ :\n المؤسسات العامة ،البلديات ،األجهزة األمنية والعسكرية ،والشركات التي تملك فيها الدولة وتعمل\n في بيئة احتكارية ،مما يغطي إنفاقًاً كان سابقًاً خارج رقابة إدارة المناقصات (التي كانت تغطي نحو %5\n فقط من اإلنفاق).\n عّرف القانون بوضوح «الشراء العام»« ،اللوازم»« ،األشغال» ،و»الخدمات» (المادة • تعريفات دقيقةّ :\n ،)2مما يقلل من التناقض في التطبيق مقارنة بقانون المحاسبة العمومية.\n • لغة المستندات :ألزم اعتماد اللغة العربية في مستندات الشراء (المادة ،)4مع جواز استخدام لغات\n مكّملة.\n ّ أجنبية\n ب .التخطيط والشفافية المسبقة\n • إلزامية التخطيط :أوجب على الجهات الشارية وضع خطط سنوية للشراء وإرسالها للهيئة (المادة ،)11\n وربطها بالموازنة.\n• القيمــة التقديريــة :ألــزم وضــع قيمــة تقديريــة للمشــروع اســتنادًاً ألســعار الســوق قبــل اإلعالن (المادة ،)13"}, {"o": 36, "l": "المادة 115", "b": "لسـ ّـّد ثغــرة التواطــؤ التــي كانــت ســائدة ســابقًاً ،وأعطــى االمكانيــة إلبقائهــا ســرية أو اإلفصــاح عنهــا ،حســب\n مقتضيات الحالة.\n • منع التجزئة :حصر تجزئة الشراء بما هو ضروري ألسباب فنية أو تشجيعًاً لتطبيق الشراء المستدام\n التهّرب من الرقابة (المادة .)14\n ّ وتشجيع المؤسسات الصغيرة والمتوسطة ،ومنع التجزئة بهدف\n • اإلعالن اإللكتروني :اعتمد المنصة اإللكترونية المركزية كقناة إلزامية للنشر ،مع تحديد مهل إعالن\n بدًال من النشر الورقي الجامد (المادة .)12 مرنة ترتبط بتعقيدات الصفقة ( 21يومًاً كقاعدة عامة) ً\n ج .إجراءات المنافسة والتقييم\n • معايير التقييم :سمح باإلرساء على «العرض األفضل» وليس فقط «السعر األدنى» ،مع إدخال\n معايير غير سعرية (كفاءة ،بيئة ،تشغيل) (المادة .)18\n • التأهيل المسبق :اعتمد نظام التأهيل المسبق للعارضين ،الذي يسمح بفتح المنافسة دوريًاً لتأهيل\n مؤّهلين\n ّ المعّينين\n ّ جدد،بدًال من نظام التصنيف المسبق ،الذي أبقى على بعض العارضين\n ً عارضين\n لسنوات طويلة دون غيرهم ،ما أساء الى المنافسة وتكافؤ الفرص بين العارضين (المادة .)19\n موردين في مشروع واحد بشكل متكافل (المادة .)23 نظم إمكانية مشاركة عدة ّ • العروض المشتركةّ :\n قّدموا عرضهم في المناقصات العمومية • حظر المفاوضات :منع المفاوضات مع العارضين الذين ّ\n لضمان النزاهة (المادة .)56\n 4لالطالع على الدراسة التفصيلية حول المحاور اإلصالحية التي يتضمنها القانون الجديدُ ،يرجى الرجوع إلى الملحق رقم ( )3المرفق بهذا التقرير.\n\f39\n د .إدارة العقد والتنفيذ\n نّص على ثبات قيمة العقد مع استثناءات محددة ومضبوطة للتعديل (المادة .)29 • ثبات القيمةّ :\n كّرس مبدأ الدفع مقابل التنفيذ ،مع مرونة في إعطاء السلفات (تصل إلى %20دون • الدفع والتنفيذّ :\n معّين) مقارنة بالقيود السابقة (المادة .)37\n كفالة ضمن سقف ّ"}, {"o": 37, "l": "المادة 115", "b": "• اإلشراف :ألزم بتعيين مشرفين متخصصين ومتابعة الكشوفات خالل التنفيذ (المادة .)31\n • التعاقد من الباطن :سمح به ضمن حدود %50وبموافقة مسبقة ،مع منع التنازل الكامل عن العقد\n (المادة .)30\n ه .الحوكمة والنزاهة\nلتنّحي الموظفين\n ألّول مرة بشكل صريح ووضع ضوابط ّ عّرف مفهوم تضارب المصالح ّ • تضارب المصالحّ :\n في حاالت القرابة أو المصلحة ("}, {"o": 38, "l": "المادة 2", "b": "المادة 2و.)10\n • هيكلية رقابية مستقلة :أنشأ هيئة الشراء العام (لتنظيم الرقابة) وهيئة االعتراضات (للنظر بالنزاعات\n قبل التعاقد) (المواد 74وما يليها).\n • العقوبات والمساءلة :فرض عقوبات على المخالفين ونظاماً للنزاهة يلزم الجميع (المادة .)112\n التطور التشريعي ومعالجات التطبيق ()2025-2022 ّ .2\nـا تشــريعياً ،تنظيميــاً ورقابيــاً لضمــان\n واجــه تطبيــق القانــون فــي مراحلــه االولــى تحديــات عمليــة اســتدعت تدخـ ً\n اســتمرارية العمــل العــام .يوضــح الجــدول أدنــاه أبــرز المحطــات التعديليــة والمعالجــات :\n 5\n الهدف الرئيسي والمعالجات اإلجراء /التشريع التاريخ\n بدء تطبيق القانون بعد عام من النشر ،وأداء رئيس الهيئة اليمين القانونية. بدء النفاذ آب 2022\n إبطــال المــادة 119مــن موازنــة ( 2022التــي حاولــت تعديــل تشــكيل اللجــان) باعتبارهــا قرار المجلس\n كانون الثاني 2023\n مــن «فرســان الموازنــة». الدستوري ()2023/1\n تنظيــم عمــل لجــان التلزيــم واالســتالم مؤقتاً لحين صــدور اللوائح الموحــدة ،ومراعاة تعميم السيد رئيس\n شباط 2023\n الظروف االستثنائية. الحكومة ()2023/5\n تعديل جوهري لتسهيل التطبيق:\n •إلغاء شرط فئة الموظفين (الثالثة) لتشكيل اللجان.\n القانون رقم\n •إلزامية التصريح عن «صاحب الحق االقتصادي». نيسان 2023\n 2023/309\n •تعديل مهل تقديم الخطط السنوية.\n •تسهيل الشراء بالفاتورة للقيم الصغيرة.\n رفــض الطعــن بالقانــون ،309مــع تحصيــن العقــود الســرية لألمــن والدفــاع مــن بعــض قرار المجلس\n أيار 2023\n اإلجــراءات العلنية. الدستوري ()2023/7\n تعديــل الســقوف الماليــة :رفــع الســقف المالــي الســتخدام طــرق الشــراء ،ولنشــر\n ـا :خطــة الشــراء مــن 1إلــى\n الخطــط ،والضمانــات والدفعــات لمواكبــة التضخــم (مثـ ً المرسوم 11339 أيار 2023\n 5مليــار ليــرة)."}, {"o": 39, "l": "المادة 2", "b": "الملحــة (أدويــة ،غــذاء،\n ّ الظــروف االســتثنائية :الســماح بالشــراء المباشــر للحاجــات\n مذكرة الهيئة رقم 8 تشرين األول 2024\n محروقــات) وتجزئــة الشــراء لضمــان اســتمرارية المرافــق.\n ـا :خطــة الشــراء إلــى\n تعديــل الســقوف الماليــة :رفــع الســقوف الماليــة مجــدداً (مثـ ً\n المرسوم 14063 تشرين األول 2024\n 10مليــار).\n توضيــح مســألة تفويــض صالحيات عقد النفقــة (الــرأي ،)2025/38مؤكــداً ضرورة نص آب - 2024تموز\n آراء ديوان المحاسبة\n قانونــي خــاص لتفويــض الصالحيات في األجهــزة األمنية. 2025\n مفصل للمعالجات والتعديالت التي دخلت على القانون 2021/244وأسبابها ،يرجى الرجوع الى الملحق رقم .4\n ّ 5لالطالع على سرد\n\f 40\n .IIاإلطار المؤسسي :هيئة الشراء العام\n .1هيئة الشراء العام :من التأسيس الى البناء المؤسسي\nكـ ّـرس قانــون الشــراء العــام الجديــد مبــدأ الفصــل بيــن األدوار والمســؤوليات ،حيــث تبقــى الجهــات الشــارية مســؤولة\nعــن التخطيــط والتنفيــذ المباشــر إلجــراءات الشــراء ،فــي حيــن تتولــى هيئــة الشــراء العــام دوراً تنظيميــاً ورقابيــاً\n يهــدف إلــى ضمــان حســن تطبيــق أحــكام القانــون.\nفــي هــذا الســياق ،ينــدرج دور الهيئــة ضمــن مســار طويــل األمــد يهــدف إلــى ترســيخ ثقافــة قانونيــة ومؤسســية\n جديــدة فــي مجــال الشــراء العــام ،قائمــة علــى االمتثــال ،والشــفافية ،والمســاءلة.\nويهــدف هــذا المبــدأ ،أي الفصــل بيــن األدوار ،إلــى تحقيــق تــوازن مؤسســي يضمــن الفعاليــة فــي التنفيــذ ،مــن دون\n المســاس باســتقاللية الجهــات الشــارية أو تحميــل الهيئــة مهــام تنفيذيــة ليســت مــن صلــب صالحياتهــا.\nمنــذ تمــوز ،2022انتقلــت الهيئــة مــن مرحلــة التأســيس القانونــي إلــى مرحلــة البنــاء المؤسســي الفعلــي ،واجهــت"}, {"o": 40, "l": "المادة 2", "b": "خاللهــا تحديــات تتعلــق بنقــل المــاك وإصــدار األنظمــة الداخليــة.\n .2معوقات تأسيس الهيئة والمعالجات\n أ .تأخير إصدار األنظمة الخاصة بالهيئة ألكثر من سنتين ما أعاق انطالقتها وتفعيلها\nنصــت المــادة 88مــن قانــون الشــراء العــام علــى نقــل مــاكات إدارة المناقصــات إلــى هيئــة الشــراء العــام وتعييــن ّ\nمديرهــا العــام رئيســاً للهيئــة .إال أن التأخيــر فــي تنفيــذ هــذا النــص لناحيــة نقــل المــاكات ّأدى إلــى غيــاب الجهــاز\n اإلداري والمالــي للهيئــة ،رغــم أداء رئيســها اليميــن القانونيــة فــي .2022/8/3\nبالرغــم مــن إعــداد الهيئــة لمشــاريع أنظمتهــا الداخليــة والماليــة ونظــام العامليــن وإيداعهــا األمانــة العامــة\nلمجلــس الــوزراء خــال عــام ،2022وورود اعتمــادات لهــا فــي الموازنــة العامــة منــذ ذلــك التاريــخ ،تعـ ّـذر عليهــا\n تنفيــذ موازنتهــا لعــدم توافــر جهــاز إداري ومالــي.\n .1إيضاحات الهيئة بشأن مالحظات الجهات الرقابية\nقّدمــت هيئــة الشــراء العــام ردودهــا علــى مالحظــات مجلــس الخدمــة المدنيــة ووزارة الماليــة ومجلــس كذلــك ّ\nشــورى الدولــة بشــأن النظاميــن الداخلــي والمالــي للهيئــة ،مؤكــدة التمييــز الــذي أقـ ّـّره قانــون الشــراء العــام\nبيــن إنشــاء الهيئــة الــذي حصــل بتاريــخ بــدء نفــاذ القانــون ،وتشــكيلها المرتبــط بتعييــن أعضائهــا ،وأن عــدم التمييــز\nبينهمــا يــؤدي إلــى تعطيــل إرادة المشـ ّـّرع .وأوضحــت الهيئــة أن المشـ ّـّرع منــح رئيــس الهيئــة صالحيــة ممارســة\nمهامهــا إلــى حيــن تعييــن األعضــاء ،بمــا يشــمل اتخــاذ التدابيــر الضروريــة لضمــان اســتمرارية عمــل الهيئــة"}, {"o": 41, "l": "المادة 2", "b": "وممارســة إشــرافها علــى حوالــي 1300جهــة شــارية ،بمــا فــي ذلــك إعــداد وإصــدار األنظمــة الداخليــة والماليــة.\nكمــا شــددت علــى أن عــدم إصــدار هــذه األنظمــة يشـ ّـل عمل الهيئة ،ويحول دون نقل موظفــي إدارة المناقصات\nالســابقة إليهــا ،ويعيــق تطبيــق القانــون علــى مشــتريات الجهات الشــارية ،بما فيها المشــاريع اإلصالحية الممولة\n دولياً.\nـاء عليــه ،رفعــت الهيئــة كتابــاً إلــى مجلــس الــوزراء مطلــع عــام 2024طالبــت فيــه بتنفيــذ المــادة 88مــن قانــون\n بنـ ً\nالشــراء العــام ،وتكليــف مراقــب عقــد نفقــات ومحاســب مؤقتيــن ،والســماح بتكليــف موظفين مؤقتيــن إلى حين\nصــدور األنظمــة .وقــد صــدر عــن مجلــس الــوزراء بتاريــخ 2024/2/28القــرار رقــم 7الــذي قضــى بتنفيــذ المــادة 88\n وبتكليــف مراقــب عقــد نفقــات ومحاســب مــن وزارة الماليــة بصــورة مؤقتــة.\n .2إصدار المراسيم\nتــأِت قبــل 17كانــون األول ،2024تاريــخ موافقــة مجلــس ااّلا ّأّن الموافقــة علــى إصــدار مراســيم الهيئــة لــم ِ\nالــوزراء علــى مشــاريع مراســيم أنظمــة العامليــن لــدى هيئــة الشــراء العــام ،بمــا يشــمل نظــام األجــراء ،ونظــام\n المــستخدمين ،وتحوــيل سالــسل رواــتب المــستخدمين.\n\f41\n المدنية.\n ّ الموافق على ملئها من قبل مجلس الخدمة\n َ يبين الملحق رقم 5الوظائف\n ّ\n وتحديات ملء الشغور ّ شح الموارد البشرية بّ .\n .1الهيكلية التنظيمية والمالك الوظيفي\nيعتمــد الــمالك الوظيفــي للهيئــة وفقــًاً للمرســوم رقــم 14632الصــادر بتاريــخ 2025/1/9والمتعّلّ ــق بنظــام\n مســتخدمي هيئــة الشــراء العــام علــى هيكليــة تــوّزّ ع المهــام بيــن عــدة مصالــح متخصصــة.\n مفصلة لمالك الهيئة وفقاً للمرسوم المذكور أعاله. ّ يبين الملحق رقم 6جداول ّ"}, {"o": 42, "l": "المادة 2", "b": ".2الشغور الحاد وتحديات ملء المالك\nـاّد فــي الــمالك المعتمــد للهيئــة ومــا يســتتبعه مــن شــلل فــي تأديــة وظائفهــا كمــا نـ ّـّص عليــه نظــرًاً للشــغور الحـ ّ\nالقانــون رقــم ( 2021/244قانــون الشــراء العــام فــي لبنــان) ،باشــرت الهيئــة منــذ انشــائها بخطــوات للحـ ّـّد مــن\n تبعــات النقــص الحــاد فــي المــوارد البشــرية ،نذكــر منهــا اإلجــراءات التاليــة:\n • نقل الخبرات :االعتماد على النواة االنتقالية من إدارة المناقصات السابقة ( 9موظفين أساسيين)\n لتسيير األعمال لحين اكتمال المالك.\n• المبــاراة المفتوحــة :تــمت الموافــقة عــلى إــجراء مــباراة لــملء المراــكز الــشاغرة بــقرار مجــلس اــلوزراء رــقم\nأّن اإلجــراءات اآليلــة الــى تنفيــذ هــذا القرار لم\n ( 20حزيــران ،)2025بالتنســيق مــع مجلــس الخدمــة المدنيــة .اال ّ\n تكتمل حتى تاريخ كتابة هذا التقرير.\n في ما يلي أبرز الخطوات التي قامت بها الهيئة للبدء بملء الشغور الحاد في مالكها:\n ً\n طالبًة المدنّية،\n ّ • في 2025/3/3أودعت هيئة الشراء العام كتابها رقم /74ه.ش.ع 2025/مجلس الخدمة\n القانونّية الالزمة والمبادرة إلى تنظيم مباراة في أقرب وقت ممكن لملء المراكز\n ّ اتخاذ اإلجراءات\n الشاغرة في مالكات الهيئة.\n المدنّية بموجب الكتاب رقم ،2025/499\n ّ تلّقت الهيئة جوابًاً من مجلس الخدمة• في ّ 2025/5/16\n متضّمنًاً عرض الموضوع على مقام مجلس الوزراء للحصول على موافقته. ّ\n • في 2025/6/16صدر قرار مجلس الوزراء رقم 20بالموافقة على طلب إجراء المباراة.\n المدنّية،\n ّ وّجهت هيئة الشراء العام الكتاب رقم /397ه.ش.ع 2025/إلى مجلس الخدمة • في ّ 2025/6/27\n تضّمن قرار مجلس الوزراء رقم 20بالموافقةّ العاّمة لمجلس الوزراء الذي\n ّ مشيرًة إلى كتاب األمانة\n ً"}, {"o": 43, "l": "المادة 2", "b": "على طلب إجراء المباراة ولملء بعض المراكز الشاغرة في مالك هيئة الشراء العام.\n المدنّية من الهيئة بموجب الكتاب رقم /397ه.ش.ع2025/ ّ • في 2025/8/7طلب مجلس الخدمة\n تسمية مندوب من قبلها للتنسيق وتنظيم المباراة المطلوبة .ويجري العمل بين مجلس الخدمة\n المدنية وهيئة الشراء العام على التوصيف الوظيفي للوظائف الملحوظة في مالكات هيئة الشراء\n العام.\n .IIIالخالصة\nُيظهــر هــذا الفصــل ّأن مســار إنشــاء هيئــة الشــراء العــام انتقــل تدريجيــاً مــن التأســيس القانونــي إلــى البنــاء المؤسســي\nالفعلــي ،وإن كان ذلــك فــي ظـ ّـل تحديــات هيكليــة وإجرائيــة حالــت دون تفعيــل دورهــا بالوتيــرة التــي قصدهــا المشـ ّـرع.\nفقــد ّأدى التأخيــر فــي إصــدار األنظمــة ونقــل المــاك ،إلــى جانــب الشــغور الحــاد في الموارد البشــرية ،إلــى إبطاء انطالقة\n الهيئــة والحـ ّـد مــن قدرتهــا علــى ممارســة كامــل صالحياتهــا التنظيميــة والرقابيــة.\nومــع صــدور المراســيم التنظيميــة واعتمــاد الهيكليــة والمــاك الوظيفــي ،بــات اإلطــار القانونــي والمؤسســي للهيئــة\nـا مــن حيــث المبــدأ ،فيمــا يبقــى تعييــن أعضــاء الهيئــة واســتكمال مــلء الشــغور وتوفيــر المــوارد البشــرية المؤهلــة\n مكتمـ ً\nالفعــال لقانــون الشــراء\n شــرطاً أساســياً لتمكينهــا مــن أداء دورهــا المحــوري فــي حوكمــة الشــراء العــام وضمــان التطبيــق ّ\n العــام.\n\f الفصل الرابع\nاإلنجازات األولى والنتائج الرئيسة\n\f جدول المحتويات\n44 .Iمقدمة\n44 .IIاإلنجازات المؤسسية وبناء الهيكلية\n44 .1استكمال الشخصية المعنوية واالستقالل اإلداري\n44 .2تطوير الموارد البشرية\n44 .3االستقالل المالي\n44 .4ترسيخ الدور المؤسسي لهيئة الشراء العام\n46 .5إرساء الرقمنة منذ اليوم األول :انجاز المنصة اإللكترونية المركزية"}, {"o": 44, "l": "المادة 2", "b": "46 .6اعتماد الهوية البصرية للهيئة منذ التأسيس\n47 .IIIاإلنجازات التنظيمية والتشريعية الداعمة\n47 .1تطوير نماذج وأدوات عمل ووضعها بمتناول الجهات الشارية\n47 .2إصدار المذكرات التفسيرية\n48 .3التوجيه عبر التقارير\n48 بعمليات الشراء العام\n ّ المهنية والمواطنة الصالحة الخاصة\n ّ .4إصدار شرعة قواعد السلوك واألخالق\n49 .5تحديد أسس تأليف لجان التلزيم واالستالم عبر إصدار القرار التنظيمي رقم /9هـ.ش.ع2023/\n49 .6المذكرة رقم /2هـ.ش.ع :2024/تعزيز المهنية والمساءلة المؤسسية\n49 .7دفاتر الشروط النموذجية (أو ملفات التلزيم النموذجية)\n50 .8األسئلة واألجوبة الشائعة\n50 .9األخطاء الشائعة المتعلقة بدفاتر الشروط\n50 .10مواكبة األزمة المالية واالقتصادية والظروف االستثنائية\n51 .11تعزيز الشفافية ومكافحة الفساد\n51 .12االنخراط في األطر الدولية ومكافحة الفساد\n52 .IVاإلنجازات في مجال التدريب وبناء القدرات\n52 .1سياسة التدريب الوطنية\n52 .2تطوير األدلة االرشادية\n52 .Vالخالصة\n\f 44\n الفصل الرابع :اإلنجازات األولى والنتائج الرئيسة\n .Iمقدمة\nيمثــل هــذا الفصــل مرحلــة االنتقــال مــن اإلطــار القانونــي والمؤسســي إلصــاح الشــراء العــام إلــى التطبيــق العملــيّ\nوالنتائــج الملموســة .ويســتعرض اإلنجــازات األساســية التــي حققتهــا هيئــة الشــراء العــام منــذ األشــهر األولــى لبــدء\nنفــاذ القانــون ،حيــث بــدأت تظهــر مؤشــرات أوليــة تعكــس أثــر اإلصــاح ،مــع التركيــز علــى بنــاء المؤسســة ،تطويــر\n األطــر التنظيميــة ،إطــاق األدوات التشــغيلية ،وبنــاء القــدرات.\n .IIاإلنجازات المؤسسية وبناء الهيكلية\n .1استكمال الشخصية المعنوية واالستقالل اإلداري\nتمكّ نــت هيئــة الشــراء العــام مــن ترســيخ شــخصيتها المعنويــة وتعزيــز اســتقاللها اإلداري ،بمــا مكّ نهــا مــن ممارســة"}, {"o": 45, "l": "المادة 2", "b": "صالحياتهــا التنظيميــة والرقابيــة بصــورة مســتقلة عــن الجهــات الشــارية .وقــد أســهم هــذا التطـ ّـور المؤسســي فــي\nتعزيــز الحوكمــة عبــر تكريــس مبــدأ الفصــل بيــن وظائــف التنظيــم والرقابــة مــن جهــة ،والتنفيــذ مــن جهــة أخــرى ،بمــا\n كرســها قانــون الشــراء العــام.\n يتماشــى مــع المبــادئ األساســية التــي ّ\nوقــد شــكّ ل هــذا االســتقالل ركيــزة أساســية لتعزيــز فعاليــة النظــام الرقابــي وترســيخ الثقــة فــي حياديــة اإلطــار\n التنظيمــي للشــراء العــام.\n .2تطوير الموارد البشرية\n على الرغم من محدودية المالك الوظيفي والتحديات المرتبطة بالشغور الحاد ،عملت الهيئة على:\n •تنظيم العمل الداخلي وتوزيع المهام،\n •االستفادة المثلى من الموارد المتاحة،\n •وتعزيز الكفاءات عبر التدريب.\nتبيــن أرقــام الجــدول رقــم ()1\n وقــد مكّ نهــا ذلــك مــن االســتجابة للطلــب المتزايــد علــى التوجيــه وإبــداء الــرأي ،كمــا ّ\n أدنــاه ،وذلــك رغــم االرتفــاع المســتمر فــي الضغــط التشــغيلي مقارنــة بعــدد الموظفيــن المتاحيــن.\n .3االستقالل المالي\nمقومــات االســتقالل المالــي الــذي يمنحهــا\n ّ تقــدم تدريجــي فــي إرســاء\n ّ عملــت هيئــة الشــراء العــام علــى إحــراز\nايــاه القانــون ،بمــا يتيــح لهــا تنفيــذ مهامهــا بصــورة أكثــر اســتدامة .ورغــم التحديــات المرتبطــة بالســياق المالــي\nالعــام ،والتحديــات المرتبطــة بغيــاب موازنــة تشــغيلية نافــذة خاصــة بهــا لعــدة ســنوات ،فقــد واصلــت اعتمــاد\nتدابيــر تشــغيلية مرنــة مكّ نتهــا مــن تأميــن اســتمرارية عملهــا واالضطــاع بمهامهــا األساســية ضمــن حــدود المــوارد\n المتاحــة ،مــع الحفــاظ علــى الحــد األدنــى مــن الجاهزيــة المؤسســية.\n .4ترسيخ الدور المؤسسي لهيئة الشراء العام"}, {"o": 46, "l": "المادة 2", "b": "منــذ تأســيس هيئــة الشــراء العــام فــي 29تمــوز 2022وبــدء نفــاذ قانــون الشــراء العــام فــي التاريــخ نفســه ،شــهدت\nســّيما طلبــات إبــداء الــرأي المرتبطــة بتطبيــق أحــكام تدّفقــًاً متزايــدًاً فــي المــراسالت الــواردة إليهــا ،وال ّ\n الهيئــة ّ\nمّطــردًاً خالل الفتــرة الممتــدة مــن عــام 2022\n القانــون وتفســير إجراءاتــه .وقــد سـ ّـّجل حجــم هــذه المــراسالت نمـ ّـّوًاً ّ\n 6\nحتــى نهايــة عــام ،2025إذ ارتفــع عددهــا مــن 130مراســلة فــي عــام 2022إلــى 700مراســلة فــي عــام ،2025وفــق\n يبّينــه الجــدول رقــم ( )1أدنــاه.\n مــا ّ\n 6لالطالع على لوائح مفصلة بالمراسالت الواردة الى الهيئة ونوعها يرجى الرجوع الى الملحق رقم 8\n\f45\nويعكــس هــذا التطـ ّـور تصاعــد أهميــة الــدور المؤسســي الــذي تضطلــع بــه الهيئــة منــذ نشــأتها ،وتكريســها كمرجعيــة\nـدل علــى اتســاع نطــاق\n تنظيميــة ورقابيــة مركزيــة ضمــن منظومــة الشــراء العــام التــي أرســاها القانــون الجديــد .كمــا يـ ّ\nتطبيــق القانــون ،وازديــاد اعتمــاد الجهــات الشــارية علــى الهيئــة فــي تفســير األحــكام ،وتوحيــد الممارســات ،وضبــط\n اإلجــراءات بمــا ينســجم مــع المبــادئ القانونيــة المعتمــدة.\n عدد المراسالت المجاب\n نسبة االستجابة عدد المراسالت الواردة السنة\n عليها\n %100 130 130 2022\n %100 354 354 2023\n %100 427 427 2024\n %90 714 719 2025\n :1المراسالت الواردة الى هيئة الشراء العام لبيان الرأي\n جدول :1\nفــي مــا يتعلــق بمســتوى االســتجابة ،تُ ظهــر البيانــات أن نســبة معالجــة المراســات بلغــت %100بشــكل ثابــت خــال\nالســنوات الثــاث األولــى ( ،)2024–2022رغــم االرتفــاع التدريجــي والكبيــر فــي حجــم الطلبــات ،وهــو مــا يعكــس"}, {"o": 47, "l": "المادة 2", "b": "قــدرة الهيئــة علــى الحفــاظ علــى فعاليــة اســتجابتها رغــم التزايــد المســتمر فــي حجــم الطلبــات ،وذلــك فــي ســياق\nالتحديــات المرتبطــة بشـ ّـح المــوارد البشــرية ،كمــا تـ ّـم التطـ ّـرق إليــه ســابقاً فــي محــور التحديــات ضمــن هــذا التقريــر.\nّأمــا فــي عــام ،2025فقــد سـ ّـجل عــدد المراســات الــواردة ارتفاعــاً حــاداً بلــغ 719مراســلة ،جــرى التعامــل مــع 714\nمنهــا خــال الســنة نفســها ،مــا أبقــى نســبة االســتجابة عنــد مســتوى مرتفــع بلــغ .%99وال يمكــن قــراءة هــذا\nالمؤشــر بمعــزل عــن الضغــط التشــغيلي المتنامــي ،وتزايــد تعقيــد الملفــات ،واســتمرار محدوديــة المــوارد البشــرية\nأن جميــع المعامــات التــي لــم تُ عالــج مــع نهايــة عــام\n مقارنــة بحجــم الطلــب .وفــي هــذا اإلطــار ،تجــدر اإلشــارة إلــى ّ\n 2025قــد اســتُ كملت معالجتهــا فــي مطلــع عــام ،2026بمــا يؤكّ ــد التــزام الهيئــة باســتكمال الملفــات وعــدم ترحيــل\n أي طلبــات دون متابعــة.\nتمــتفعــال ،قائــم علــى ســرعة المعالجــة وجــودة التوجيــه ،حيــث ّ كمــا حرصــت الهيئــة علــى اعتمــاد نهــج اســتجابة ّ\nمهــل زمنيــة معقولــة قياســاً بحجــم الضغــط التشــغيلي ومحدوديــة المــوارد اإلجابــة علــى غالبيــة المراســات ضمــن َ\nيبينــه الجــدول رقــم ( )2أدنــاه .وقــد ســاهم ذلــك فــي تعزيــز الثقــة بــدور الهيئــة ،والحــد مــن حــاالت\n البشــرية ،وفــق مــا ّ\nالتعطيــل أو االجتهــاد المتبايــن فــي تطبيــق القانــون ،وتكريســها كمرجعيــة تنظيميــة فاعلــة قــادرة علــى مواكبــة\n التطبيــق اليومــي لقانــون الشــراء العــام.\n معدل الفترة الزمنية المستغرقة لالجابة\n السنة\n (بعدد االيام)\n 7 2022\n 16 2023\n 14 2024\n 9 2025"}, {"o": 48, "l": "المادة 2", "b": "معدل الوقت المستغرق لالجابة من قبل الهيئة على بيانات الرأي الواردة\n ّ جدول :2\n :2\nُيعــزى التطـ ّـور فــي معـ ّـدل الفتــرة الزمنيــة المســتغرقة لإلجابــة إلــى االرتفــاع الملحــوظ فــي عــدد المعامــات الواردة\nإلــى هيئــة الشــراء العــام ،ســواء مــن حيــث الكـ ّـم أو مــن حيــث تنـ ّـوع طبيعتهــا وتعقيدهــا اإلجرائــي ،مــن دون أن يقابلــه\n\f 46\nأي ازديــاد فــي عــدد الموظفيــن .وقــد شــملت اإلحصــاءات المعامــالت التــي تتعلّ ــق بدفاتــر شــروط المناقصــات ّ\nأن والمزايــدات ،واالتفاقــات الرضائيــة ،والشــراء بالفاتــورة ،واالتفاقــات اإلطاريــة ،إضافــة إلــى االعتراضــات ،علمــاً ّ\nهــذه المعامــالت تَ ـ ِـرد بمعظمهــا إلــى الهيئــة تحــت عنــوان «إبــداء رأي» ،وتســتلزم فــي كثيــر مــن الحــاالت تدقيقــاً\n معمقــاً قبــل إصــدار الجــواب.\n ّ قانونيــاً وفنيــاً\nتُ ظهــر البيانــات الــواردة فــي الجــدول أعــاله تطـ ّـور معـ ّـدل الفتــرة الزمنيــة المســتغرقة لإلجابــة علــى طلبــات إبــداء\nالــرأي الــواردة إلــى هيئــة الشــراء العــام خــالل الفتــرة الممتــدة بيــن عامــي 2022و .2025فقــد ُسـ ّـجل فــي عــام 2022\nتميــزت بمــدة قصيــرة (آب معـ ّـدل اســتجابة بلــغ 7أيــام ،وهــو مــا يعكــس طبيعــة المرحلــة التأسيســية األولــى التــي ّ\nحتــى كانــون االول) وبعــدد محــدود نســبياً مــن المراســالت .وفــي عــام ،2023ارتفــع معـ ّـدل الفتــرة الزمنيــة إلــى 16\nالتوســع الملحــوظ فــي تطبيــق قانــون الشــراء العــام ،وازديــاد عــدد المعامــالت الــواردة إلــى ّ يومــاً ،بالتــوازي مــع\n الهيئــة مــن حيــث الكــم والتنـ ّـوع والتعقيــد اإلجرائــي ،دون أي زيــادة مقابلــة فــي المــوارد البشــرية المتاحــة."}, {"o": 49, "l": "المادة 2", "b": "تحســناً تدريجيــاً فــي األداء ،حيــث انخفــض معـ ّـدل الفتــرة الزمنيــة إلــى 14يومــاً\n ومــع ذلــكُ ،يظهــر المســار الالحــق ّ\nفــي عــام ،2024ثــم إلــى 9أيــام فــي عــام ،2025بمــا يعكــس قــدرة الهيئــة علــى تعزيــز كفاءتهــا التشــغيلية ،وتحســين\nتنظيــم آليــات المعالجــة الداخليــة ،واالســتفادة مــن تراكــم الخبــرة المؤسســية ،رغــم اســتمرار الضغــوط المرتبطــة\n ّ\nويؤشــر هــذا االتجــاه اإليجابــي إلــى تطـ ّـور ملحــوظ بحجــم الطلبــات والظــروف االســتثنائية المحيطــة بســير العمــل.\nفــي فعاليــة االســتجابة ،ويعــزّ ز موقــع الهيئــة كمرجعيــة تنظيميــة قــادرة علــى مواكبــة متطلبــات التطبيــق العملــي\n لقانــون الشــراء العــام ضمــن أطــر زمنيــة معقولــة.\n .5إرساء الرقمنة منذ اليوم األول :انجاز المنصة اإللكترونية المركزية\nباشــرت الهيئــة ،منــذ اليــوم األول لتأسيســها ،العمــل علــى إطــالق وتفعيــل المنصــة اإللكترونيــة المركزيــة للشــراء\nمنظــم ومركــزي.العــام ،باعتبارهــا األداة األساســية لضمــان الشــفافية ،وتوحيــد اإلجــراءات ،وإتاحــة البيانــات بشــكل ّ\nوقــد نجحــت فــي ذلــك ،مــا شــكّ ل خطــوة مفصليــة فــي مســار التحـ ّـول الرقمــي ،الــذي يتناولــه الفصــل الخامــس مــن\n هــذا التقريــر بصــورة متخصصــة.\n .6اعتماد الهوية البصرية للهيئة منذ التأسيس\nموحــدة شــملت الشــعار ( )Logoوالعناصــر\n ّ اعتمــدت هيئــة الشــراء العــام ،منــذ يــوم تأسيســها ،هويــة غرافيكيــة\nيرســخ حضورهــا المؤسســي ويعــزّ ز قابليتهــا للتعـ ّـرف والتمييــز ضمــن المنظومــة اإلداريــة\n البصريــة األساســية ،بمــا ّ\n العامــة.\nوقــد شــكّ لت هــذه الخطــوة جــزءاً مــن بنــاء الهوية المؤسســية الشــاملة للهيئة ،بما يدعم اتســاق التواصل الرســمي،"}, {"o": 50, "l": "المادة 2", "b": "الموجهــة إلــى الجهــات الشــارية والــرأي العــام ،ويســهم فــي تكريــس صــورة مؤسســية حديثــة\n ّ ويعــزز وضــوح الرســائل\n ومهنيــة تتماشــى مــع متطلبات الحوكمة والشــفافية.\n\f47\n .IIIاإلنجازات التنظيمية والتشريعية الداعمة\n .1تطوير نماذج وأدوات عمل ووضعها بمتناول الجهات الشارية\nمنــذ األيــام األولــى لتأسيســها ،أولــت هيئــة الشــراء العــام أهميــة خاصــة لتطويــر نمــاذج وأدوات عمــل عمليــة تهــدف\nإلــى تســهيل تطبيــق قانــون الشــراء العــام الجديــد ،وقــد ُوضعــت هــذه األدوات علــى المنصــة اإللكترونيــة المركزيــة\n بمتنــاول الجهــات الشــارية ،بمــا يســهم فــي:\n •تبسيط اإلجراءات،\n •تقليص هامش االجتهاد،\n •وتعزيز العدالة وتكافؤ الفرص بين المتنافسين.\nوفــي هــذا اإلطــار ،أعـ ّـدت الهيئــة عشــرات النمــاذج المســاعدة علــى تطبيــق القانــون منــذ مرحلــة اإلطــاق األولــى،\nوبلــغ عــدد النمــاذج المطـ ّـورة حتــى تاريخــه أكثــر مــن 22نموذجــاً ،شــملت مجــاالت متعــددة ،مــن بينهــا اإلعالنــات،\nاإلشــعارات ،التســجيل علــى المنصــة ،تصاريــح النزاهــة ،إجــراءات إرســاء العقــود ،وغيرهــا مــن المراحــل األساســية فــي\n دورة الشــراء العــام.\nكمــا اعتمــدت الهيئــة نهجــاً قائمــاً علــى التطويــر المســتمر لهــذه النمــاذج ،ســواء مــن خــال إعــداد نمــاذج جديــدة\nمحســنة مــن النمــاذج المعتمــدة ،بمــا يضمــن مالءمتهــا للتطــورات\n ّ اســتجابة لحاجــات التطبيــق ،أو عبــر إصــدار نســخ\n العمليــة وللمالحظــات الــواردة مــن الجهــات الشــارية.\n .2إصدار المذكرات التفسيرية\nمنــذ تأسيســها وحتــى نهايــة العــام ،2025اضطلعــت هيئــة الشــراء العــام بــدور تنظيمــي فاعــل مــن خــال إصــدار عــدد"}, {"o": 51, "l": "المادة 2", "b": "متزايــد مــن المذكــرات التفســيرية ،هدفــت إلــى معالجــة اإلشــكاليات التطبيقيــة األساســية المرتبطــة بتنفيــذ قانــون\n الشــراء العــام ،وســاهمت فــي توحيــد تفســير أحكامــه وتعزيــز االمتثــال لــه.\nالتدخــل التنظيمــي للهيئــة ،إذ انتقلــت\n ّ ويظهــر المســار الزمنــي إلصــدار هــذه المذكــرات تطـ ّـوراً تدريجيــاً فــي طبيعــة\n ُ\nتخصصــاً وتعقيــداً ناتجــة عــن التطبيــق\n مــن معالجــة متطلبــات اإلطــاق األولــي للقانــون ،إلــى تنــاول قضايــا أكثــر ّ\n فصــل الجــدول رقــم ( )3أدنــاه عــدد المذكــرات الصــادرة ســنوياً وأبــرز المحــاور التــي تناولتهــا. وي ّالعملــيُ .\n أبرز المحاور عدد المذكرات الصادرة السنة\n النشر ،دفاتر الشروط ،اللجان 17 2022\n الشفافية ،اإلفصاح ،المستفيد االقتصادي 8 2023\n التخطيط ،مهام اللجان ،الطوارئ 10 2024\n االتفاق الرضائي ،مهلة اإلعالن 5 2025\n 40 المجموع\n :3المذكرات الصادرة عن الهيئة\n جدول :3\nويعكــس هــذا التطـ ّـور انتقــال الهيئــة مــن دور إرســاء اإلطــار التطبيقــي األساســي للقانــون إلــى دور تنظيمــي أكثــر\n عمقــاً ،يركّ ــز علــى ضبــط الممارســات ،معالجــة الحــاالت الخاصــة ،وتعزيــز اســتقرار التطبيــق عبــر التوجيــه المســبق.\n\f 48\n .3التوجيه عبر التقارير\nمنــذ األشــهر األولــى لتأسيســها ،اعتمــدت هيئــة الشــراء العــام ،عنــد االقتضــاء ،آليــة التوجيــه عبــر تقاريــر تصــدر عــن\nحســاس .وقــدومعقــدة ذات طابــع اســتثنائي أو ّ ّ رئيــس الهيئــة ،وذلــك فــي ســياق معالجــة ملفــات تلزيــم أساســية\nهدفــت هــذه التقاريــر إلــى توجيــه الجهــات الشــارية نحــو التطبيــق الســليم ألحــكام قانــون الشــراء العــام ،وال ســيما\n معمقــة للســياق القانونــي أو اإلجرائــي.\n ّ فــي الحــاالت التــي تقتضــي قــراءة"}, {"o": 52, "l": "المادة 2", "b": "محددة ،من بينها:\n ّ وتناولت هذه التقارير مواضيع\n •تلزيمات ذات طابع استراتيجي أو مالي مرتفع،\n •حاالت تطبيق استثناءات أو إجراءات خاصة،\n •إشكاليات مرتبطة بتفسير بعض أحكام القانون في سياقات غير نمطية.\nموجــه\n ّ مكملــة للمذكــرات التنظيميــة ،ســمحت للهيئــة بالتدخــل بشــكل ّ وقــد شــكّ لت هــذه اآلليــة أداة توجيــه\nومحــدد ،مــع الحفــاظ علــى مبــدأ اســتقاللية الجهــات الشــارية ومســؤوليتها المباشــرة عــن إجــراءات الشــراء .كمــا\nوالحــد مــن الطعــون\n ّ أســهمت هــذه التقاريــر فــي تعزيــز الوقايــة المســبقة مــن المخاطــر القانونيــة واإلجرائيــة،\n والنزاعــات المحتملــة.\nنذكــر التقاريــر التاليــة الصــادرة عــن الهيئــة ،وجميعهــا منشــورة علــى المنصــة اإللكترونيــة المركزيــة لهيئــة الشــراء\n العــام ،بمــا يعــزّ ز مبــدأ الشــفافية ويتيــح االطــاع العــام علــى التوجيهــات الصــادرة:\n • المناقصة العمومية لشراء كمية من مادة الغاز أويل وكمية من مادة وقود الديزل تلبية لحاجات\n مؤسسة كهرباء لبنان.\n • النظام الخاص بالرسائل النصية الذي يمّكّ ن المتعاقد معه من الولوج الى الشبكة الخلوية إليصال رسائل\nمعّينة الى األشخاص المشتركين في الخطوط الخلوية علىالشبكة. نصية قصيرة دولية SMSمن تطبيقات ّ\n • المزايدة العمومية لتلزيم الخدمات والمنتجات البريدية.\n • الغرامات المالية المترتبة على الدولة اللبنانية نتيجة توقيع عقود لشراء كميات من ال Fuel oil Aوال\n Fuel Oil Bوال Gas Oilخالفًاً ألحكام قانون المحاسبة العمومية وقانون الشراء العام.\nوتُ بــرز هــذه األمثلــة طبيعــة الملفــات التــي اضطلعــت الهيئــة بتوجيههــا عبــر التقاريــر ،والتــي اتّ ســمت بحساســية"}, {"o": 53, "l": "المادة 2", "b": "عاليــة مــن حيــث القيمــة الماليــة ،األثــر االقتصــادي ،أو التعقيــد القانونــي .كمــا تعكــس الــدور الوقائــي للهيئــة فــي\n الحـ ّـد مــن المخاطــر ،وتعزيــز االمتثــال المســبق ،وتفــادي النزاعــات والطعــون المحتملــة.\n بعملّيات الشراء العام\n ّ المهنّية والمواطنة الصالحة الخاصة ّ .4إصدار شرعة قواعد السلوك واألخالق\nفــي إطــار تعزيــز النزاهــة فــي منظومــة الشــراء العــام ،أصــدرت هيئــة الشــراء العــام شــرعة قواعــد الســلوك\nواألخالق المهنيــة والمواطنــة الصالحــة الخاصــة بعمليــات الشــراء العــام ،وذلــك بموجــب القــرار التنظيمــي رقــم\n 79/هـــ.ش.ع.2025/.\nوتهــدف هــذه الشــرعة إلــى وضــع إطــار مرجعــي واضــح للســلوك المهنــي الواجــب اعتمــاده مــن قبــل جميــع\nالمتدخليــن فــي عمليــات الشــراء العــام ،بمــا فــي ذلــك الموظفيــن العمومييــن ،أعضــاء لجــان التلزيــم واالســتالم،\nترســخ مبــادئ النزاهــة ،الشــفافية ،تضــارب المصالــح ،والمســاءلة ،وتســهم فــي تعزيــز الثقــة بيــن\n والمتعاقديــن .كمــا ّ\n اإلدارة العامــة والمواطنيــن والمتعامليــن مــع الدولــة.\nويشــكّ ل اعتمــاد هــذه الشــرعة خطــوة نوعيــة فــي مســار اإلصــاح ،إذ تنقــل تنظيــم الشــراء العــام مــن مجـ ّـرد االلتــزام\nباإلجــراءات إلــى تكريــس ثقافــة مؤسســية قائمــة علــى القيــم واألخــاق المهنيــة ،بمــا يدعــم اســتدامة العمليــة\n اإلصالحيــة.\n\f49\n .5تحديد أسس تأليف لجان التلزيم واالستالم عبر إصدار القرار التنظيمي رقم /9هـ.ش.ع2023/\nبعــد تعديــل قانــون الشــراء العــام فــي تشــرين االول ،2023أصــدرت هيئــة الشــراء العــام القــرار التنظيمــي رقــم /9"}, {"o": 54, "l": "المادة 2", "b": "هـــ.ش.ع ،2023/الــذي حـ ّـدد األســس التنظيميــة لتأليــف لجــان التلزيــم واالســتالم فــي الجهــات الشــارية ،اســتناداً\nإلــى أحــكام قانــون الشــراء العــام ،وذلــك بهــدف توحيــد المعاييــر المؤسســية والعمليــة لهــذه اللجــان فــي جميــع\n الجهــات.\nيســاهم هــذا القــرار فــي تعزيــز المهنيــة والنزاهــة فــي مرحلــة تنفيــذ إجــراءات الشــراء ،مــن خــال اعتمــاد قواعــد\nواضحــة لتشــكيل اللجــان ،وضمــان تمثيــل متــوازن للكفــاءات الالزمــة إلدارة عمليــات التلزيــم واالســتالم .كمــا ُيعـ ّـد\nالقــرار خطــوة مهمــة نحــو رفــع جــودة عمليــات الشــراء داخــل الجهــات الشــارية وتجنّ ــب أي تباينــات إجرائيــة يمكــن أن\n تحـ ّـد مــن عدالــة المنافســة أو شــفافية اإلجــراءات.\n .6المذكرة رقم /2هـ.ش.ع :2024/تعزيز المهنية والمساءلة المؤسسية\nفــي إطــار ســعيها إلــى إرســاء مهنيــة مؤسســية مســتدامة وتعزيــز المســاءلة الداخليــة داخــل الجهــات الشــارية،\nأصــدرت هيئــة الشــراء العــام المذكــرة رقــم /2هـــ.ش.ع ،2024/التــي شــكّ لت محطــة تنظيميــة أساســية فــي مســار\nـكل مــن وحــدة الشــراء\n تطبيــق قانــون الشــراء العــام ،مــن خــال تحديــد األدوار والمســؤوليات الوظيفيــة المرتبطــة بـ ٍّ\n والتدقيــق الداخلــي.\nوهدفــت هــذه المذكــرة إلــى االنتقــال مــن مقاربــة فرديــة أو ظرفيــة فــي إدارة الشــراء العــام إلــى مقاربــة مؤسســية\nواضحــة المعالــم ،تقــوم علــى تخصيــص وحــدات إداريــة محــددة وتوزيــع المســؤوليات بشــكل يمنــع تداخــل\nكرســت المذكــرة مبــدأ إحــداث أو تكييــف وحــدة للشــراء الصالحيــات ويعــزّ ز قابليــة المســاءلة .وفــي هــذا اإلطــارّ ،"}, {"o": 55, "l": "المادة 2", "b": "العــام ضمــن الهيــكل التنظيمــي للجهــة الشــارية ،تتولــى حصــراً مهــام الشــراء وفقــاً ألحــكام القانــون ،بمــا يعــزّ ز\n ويحــد مــن االجتهــادات غيــر المنضبطــة.\n ّ ويوحــد الممارســات،\n ّ االحتــراف الوظيفــي،\nوبالتــوازي ،شـ ّـددت المذكــرة علــى تفعيــل وظيفــة التدقيــق الداخلــي كأداة رقابــة ذاتيــة أساســية ،تُ مـ َـارس بصــورة\nمســتقلة عــن وحــدة الشــراء ،بمــا ينســجم مــع فلســفة قانــون الشــراء العــام القائمــة علــى المركزيــة التنفيــذ ومركزية\nالرقابــة .وقــد أســهم هــذا التوجــه فــي تعزيــز الحوكمــة ،وإدخــال المســاءلة كعنصــر بنيــوي فــي دورة الشــراء العــام،\n وتحويــل أحــكام القانــون مــن نصــوص تنظيميــة إلــى أدوار وظيفيــة عمليــة تدعــم التطبيــق الســليم والمســتدام.\nوبذلــك ،أســهمت المذكــرة رقــم 2024/2فــي ترجمــة مبــادئ قانــون الشــراء العــام إلــى ممارســات مؤسســية\nملموســة ،وربطــت بصــورة منهجيــة بيــن المهنيــة ،وضــوح المســؤوليات ،والرقابــة الداخليــة ،بمــا يعــزّ ز الثقــة\n بمنظومــة الشــراء العــام ككل.\n .7دفاتر الشروط النموذجية (أو ملفات التلزيم النموذجية)\nأصــدرت هيئــة الشــراء العــام ثالثــة دفاتــر شــروط نموذجيــة ،ووضعتهــا بمتنــاول الجهــات الشــارية الســتخدامها علــى\nســبيل التجربــة قبــل اعتمادهــا إلزاميــاً بموجــب قــرار تنظيمــي الحــق ،وذلــك فــي إطــار اعتمــاد نهــج تدريجــي يراعــي\n واقــع التطبيــق ويتيــح اختبــار األدوات قبــل تعميمهــا.\n وتشمل دفاتر الشروط النموذجية الصادرة:\n • دفتر شروط خاص للخدمات االستشارية العادية\n • دفتر شروط خاص للخدمات االستشارية المعقدة\n • دفتر شروط نموذجي لشراء اللوازم بموجب مناقصة عمومية (السعر األدنى)"}, {"o": 56, "l": "المادة 2", "b": "ويجــري العمــل حاليــاً علــى تطويــر دفاتــر شــروط نموذجيــة إضافيــة ،تمهيــداً إلصدارهــا فــي المــدى القريــب ،بمــا\n يســهم فــي توســيع نطــاق التوحيــد اإلجرائــي وتعزيــز جــودة وثائــق الشــراء العــام.\n\f 50\n .8األسئلة واألجوبة الشائعة\nأعـ ّـدت هيئــة الشــراء العــام ونشــرت مجموعــة مــن األســئلة واألجوبــة الشــائعة حــول تطبيــق قانــون الشــراء العــام،\nبهــدف معالجــة اإلشــكاليات المتكـ ّـررة التــي تواجــه الجهــات الشــارية والعامليــن فــي الشــراء العــام ،وتقديــم إجابــات\n ـداوال.\n ً عمليــة ومباشــرة علــى التســاؤالت األكثــر تـ\nمكملــة للمذكــرات التنظيميــة واألدلة اإلرشــادية ،وأســهمت ّ وشــكّ لت هــذه األداة وســيلة مرنــة وســريعة للتوجيــه،\nفــي توحيــد الفهــم التطبيقــي للنصــوص القانونيــة ،والحــد مــن االستفســارات المتكـ ّـررة ،وتعزيــز االمتثــال لإلجــراءات\n المعتمدة.\n .9األخطاء الشائعة المتعلقة بدفاتر الشروط\nأظهــرت مراجعــة هيئــة الشــراء العــام لعــدد مــن دفاتــر الشــروط المتداولــة وجــود أخطــاء متكـ ّـررة وصياغــات غيــر\nمنســجمة مــع أحــكام قانــون الشــراء العــام ،مــن شــأنها التأثيــر ســلباً علــى مبــدأي المنافســة والتــوازن التعاقــدي،\nوفتــح المجــال أمــام اجتهــادات إجرائيــة وقانونيــة غيــر منضبطــة .وقــد شــملت هــذه المالحظــات ،علــى ســبيل\nالمثــال ال الحصــر ،آليــات ســحب وتعديــل العــروض ،ومعالجــة العــروض المتأخــرة ،واعتمــاد تقديــرات قديمــة للقيمــة\nقيــد إنهــاء العقــد\n خــل بتــوازن الحقــوق وااللتزامــات أو تُ ّ\n التقديريــة للمشــاريع ،إضافــة إلــى إدراج بنــود تعاقديــة تُ ّ\n خالفــاً لمــا نـ ّـص عليــه القانــون."}, {"o": 57, "l": "المادة 2", "b": "وانطالقــاً مــن دورهــا الرقابــي والتوجيهــي ،قامــت الهيئــة بتجميــع هــذه األخطــاء وتصنيـــفها ،وإعــداد تصحيحــات\nمعياريــة مدعومــة بإحــاالت صريحــة إلــى المــواد ذات الصلــة فــي قانــون الشــراء العــام .وقــد جــرى إتاحــة هــذا العمــل\nفــي الملحــق رقــم ،9بهــدف توحيــد الممارســات ،وتعزيــز الســامة القانونيــة لدفاتــر الشــروط ،وتحويلهــا إلــى أداة\n عمليــة داعمــة للتطبيــق الســليم والمســتدام لمنظومــة الشــراء العــام.\n .10مواكبة األزمة المالية واالقتصادية والظروف االستثنائية\nواجهــت هيئــة الشــراء العــام منــذ تأسيســها فــي العــام 2022ظروفــاً اســتثنائية بالغــة التعقيــد ،فرضتهــا األزمــة\nالماليــة والنقديــة واالقتصاديــة التــي شــهدها لبنــان .وقــد بــادرت منــذ المراحــل األولــى الــى التعامــل مــع هــذه\nموجهــة إلــى الجهــات الشــارية،\n ّ التحديــات عبــر اعتمــاد مقاربــة تنظيميــة مرنــة ،تمثلــت فــي إصــدار مذكــرات توجيهيــة\nبهــدف ضمــان حســن تطبيــق قانــون الشــراء العــام فــي ظــل الواقــع المســتجد ،وال ســيما فــي مــا يتعلــق بتعديــل\n األســقف الماليــة ،وتنظيــم االتفاقيــات الرضائيــة ،والشــراء فــي حــاالت الطــوارئ.\nارتبطــت أكثريــة المذكــرات الصــادرة بيــن عامــي 2023و 2025بشــكل مباشــر أو غيــر مباشــر بظــروف اســتثنائية أو\n تحديــات اقتصاديــة.\n أ .تعديل السقوف المالية لمواكبة التضخم\nبــادرت الهيئــة إلــى معالجــة أثــر التضخــم والتقلبــات االقتصاديــة الحــادة علــى تطبيــق قانــون الشــراء العــام ،مــن\nخــال مراجعــة وتعديــل األســقف الماليــة المعتمــدة .وقــد تـ ّـم ذلــك علــى مرحلتيــن ،فــي العــام 2023ثــم فــي"}, {"o": 58, "l": "المادة 2", "b": "العــام ،2024عبــر اقتــراح التعديــل الــى مجلــس الــوزراء الــذي أصــدر مرســومي تعديــل الســقوف الماليــة:\n •المرسوم رقم 11339تاريخ ،2023/5/29\n •المرسوم رقم 14063تاريخ .2024/10/3\nوقــد هــدف هــاذان التعديــان إلــى ضمــان قابليــة تطبيــق األحــكام القانونيــة واســتمرارية عمــل المرافــق العامــة\n دون تعطيــل ،مــع الحفــاظ علــى التــوازن بيــن المرونــة والضوابــط الرقابيــة.\n\f51\n ب .مواكبة الظروف االستثنائية في أواخر عام 2024\nأصــدرت الهيئــة المذكــرة رقــم /8هـــ.ش.ع 2024/.فــي 30أيلــول 2024حــول تأميــن الحاجــات األساســية والملحــة\nفــي ظــل الظــروف االســتثنائية ،والتــي هدفــت إلــى تنظيــم الشــراء العــام فــي حــاالت الطــوارئ والظــروف\nاالســتثنائية التــي مـ ّـر بهــا لبنــان فــي أيلــول ،تشــرين األول وتشــرين الثانــي مــن العــام ،2024مــع الحفــاظ علــى الحــد\n التوســع غيــر المبــرر فــي االســتثناءات.\n ّ األدنــى مــن مبــادئ الشــفافية والمنافســة ،ومنــع\n .11تعزيز الشفافية ومكافحة الفساد\n كرست الهيئة مبدأ الشفافية كأحد أعمدة اإلصالح ،من خالل: ّ\n •إلزام النشر المركزي،\n •توحيد متطلبات اإلفصاح،\n •وتعزيز آليات المساءلة.\n وقد شكّ لت هذه التدابير أساساً لمكافحة الفساد وتعزيز الثقة في منظومة الشراء العام.\n .12االنخراط في األطر الدولية ومكافحة الفساد\nفــي مــوازاة دورهــا التنظيمــي والرقابــي الداخلــي ،حرصــت هيئــة الشــراء العــام علــى االنخــراط الفاعــل فــي األطــر\nالوطنيــة والدوليــة ذات الصلــة بمكافحــة الفســاد وتعزيــز النزاهــة ،بمــا يعكــس انتقالهــا مــن دور تطبيقــي داخلــي\n إلــى فاعــل مؤسســي مســاهم فــي العمــل اإلصالحــي األوســع .نذكــر فــي هــذا االطــار:\n أ .اتفاقية األمم المتحدة لمكافحة الفساد UNCAC"}, {"o": 59, "l": "المادة 2", "b": "فــي إطــار التزامــات لبنــان بموجــب اتفاقيــة األمــم المتحــدة لمكافحــة الفســاد ( ،)UNCACانضمــت هيئــة الشــراء\nالعــام ،بموجــب القــرار رقــم ( 2024/18تعديــل القــرار رقــم )2021/140تاريــخ ،2024/3/7إلــى عضويــة اللجنــة الفنيــة\nلمســاندة اللجنــة الوزاريــة المكلّ فــة مكافحــة الفســاد ،وفريــق عمــل مواءمــة التشــريعات مــع المعاييــر الدوليــة،\n إلــى جانــب الهيئــة الوطنيــة لمكافحــة الفســاد.\nومنــذ آذار ،2024شــاركت الهيئــة فــي أعمــال التحضيــر والمراجعــة الخاصــة بتقريــر التقييــم الذاتــي للبنــان ضمــن\nالــدورة الثانيــة مــن آليــة االســتعراض – Review Cycle 2الفصــان الثانــي والخامــس المتعلقــان بالتدابيــر\nالوقائيــة واســترداد الموجــودات .وشــمل ذلــك المســاهمة فــي تقييــم المعطيــات المتعلقــة بالشــراء العــام،\nوالمشــاركة فــي االجتماعــات التقنيــة ،واالســتعراض المكتبــي ،والزيــارة القطريــة التــي جــرت بيــن 24و 26نيســان\nتضمــن الخالصــة التنفيذيــة.\n ّ ـوال إلــى إنجــاز النســخة المرجعيــة اللبنانيــة وتقديــم التقريــر النهائــي الــذي\n ،2024وصـ ً\n ب .المساهمة في االستراتيجية الوطنية لمكافحة الفساد\nيو�ث ـّق تنفيــذ االســتراتيجية الوطنيــة لمكافحــة الفســاد فــي لبنــان 7مــن خالل تقاريــر وطنيــة دوريــة تصدرهــا هيئــة\nمكتــب وزيــر الدولــة لشــؤون التنميــة اإلداريــة ( )OMSARبالتنســيق مــع اإلدارات العامــة المعنيــة وشــركاء\nالتنميــة .وتشــكل هــذه التقاريــر اإلطــار الوطنــي الرســمي للمســاءلة ومتابعــة تنفيــذ إصالحــات مكافحــة الفســاد،\n كمــا تمثــل المرجــع األساســي لألدلــة فــي إطــار اتفاقيــة األمــم المتحــدة لمكافحــة الفســاد (.)UNCAC"}, {"o": 60, "l": "المادة 2", "b": "وقــد ســاهمت هيئــة الشــراء العــام ،بصفتهــا عضــواً فــي اللجنــة الفنيــة الداعمــة لتنفيــذ االســتراتيجية الوطنيــة\nلمكافحــة الفســاد ،فــي تزويــد التقاريــر الوطنيــة الدوريــة بالمعلومــات المرتبطــة بإصــاح منظومــة الشــراء العــام،\nوال سـ ّـيما فــي إطــار المحصلــة رقــم ( )3منظومــة شــراء عــام أقــل عرضــة للفســاد .وقــد شــملت هــذه المســاهمة\n التقريــر الوطنــي الثانــي الــذي ُأطلــق فــي 13أيــار ،2024إضافــة إلــى التقريــر الثالــث.\n 7https://omsar.gov.lb/anti-corruption-ar/national-anti-corruption-strategy-2020-2025-ar/progress-reports-ar/\n\f 52\n ج .عضوية فريق عمل بشأن تعزيز نزاهة القطاع الخاص\nوفــي ســياق تعزيــز النزاهــة فــي عالقــات القطاعيــن العــام والخــاص ،انضمــت الهيئــة ،اعتبــاراً مــن آب ،2025إلــى\n فريــق العمــل المعنــي بتعزيــز نزاهــة القطــاع الخــاص ،بموجــب قــرار وزيــر الدولــة لشــؤون التنميــة اإلداريــة رقــم\n .2025/49وتشــارك الهيئــة فــي إعــداد ومناقشــة خطــة العمــل التــي تتضمــن توصيــات تشــريعية وتنظيميــة\nوتطبيقيــة ،ومقترحــات لتعزيــز االمتثــال ،وتطويــر الممارســات األخالقيــة داخــل الشــركات ،وتعزيــز التعــاون\nالمؤسســي بيــن القطاعيــن العــام والخــاص ،بمــا يتــاءم مــع المعاييــر الدوليــة وأحــكام اتفاقيــة األمــم المتحــدة\n لمكافحــة الفســاد.\nويعكــس هــذا االنخــراط تطـ ّـور دور هيئــة الشــراء العــام مــن جهــة تنظيميــة وطنيــة إلــى شــريك مؤسســي فاعــل\n فــي منظومــة النزاهــة والحوكمــة علــى المســتويين الوطنــي والدولــي.\n .IVاإلنجازات في مجال التدريب وبناء القدرات\n .1سياسة التدريب الوطنية"}, {"o": 61, "l": "المادة 2", "b": "وضعــت هيئــة الشــراء العــام سياســة وطنيــة للتدريــب فــي مجــال الشــراء العــام ،بالتعــاون مــع Expertise France\nوبمنهجيــة تشــاركية مــع مختلــف الجهــات المعنيــة علــى المســتوى الوطنــي .وتشــكّ ل هــذه السياســة إطــاراً مرجعيــاً\nنظــم أنشــطة التدريــب وبنــاء القــدرات والتخصــص فــي مجــال الشــراء العــام ،بمــا يضمــن توحيــد وي ّ\n يوجــه ُ\n ـامال ّشـ ً\n المعاييــر وتعزيــز االتســاق فــي تطويــر الكفــاءات علــى المســتوى الوطنــي.\nكمــا حرصــت الهيئــة علــى تعزيــز التعــاون المؤسســي الوثيــق مــع معهــد باســل فليحــان المالــي واالقتصــادي فــي\nالمتخصــص والمســتمر\n ّ مجــال التدريــب ،باعتبــاره الجهــة التــي أنــاط بهــا قانــون الشــراء العــام مســؤولية التدريــب\nيرســخ مقاربــة وطنيــة مســتدامة لبنــاء القــدرات وربــط التدريــب بالتطبيــق\n للمولجيــن بمهــام الشــراء العــام ،بمــا ّ\n العملــي ألحــكام القانــون.\n .2تطوير األدلة االرشادية\nأعـ ّـدت هيئــة الشــراء العــام وأصــدرت دليليــن إرشــاديين تطبيقييــن حــول عمــل لجــان التلزيــم ولجــان االســتالم ،هدفــا\nإلــى تبســيط أحــكام قانــون الشــراء العــام وترجمتهــا إلــى خطــوات عمليــة واضحــة ،بمــا يسـ ّـهل االنتقــال مــن اإلطــار\n القانونــي إلــى التطبيــق الفعلــي.\nموحــداً لعمــل لجــان التلزيــم واالســتالم وأســهما فــي توحيــد الممارســات،\n ّ وقــد شــكّ ل هــذان الدليــان مرجعــاً عمليــاً\nتقليــص هامــش التفســير المتبايــن ،وتعزيــز االمتثــال لإلجــراءات المعتمــدة .كمــا مكّ نــا أعضــاء هــذه اللجــان مــن\n تقليــص األخطــاء اإلجرائيــة.\n .Vالخالصة\nمعقــد ،فــي إرســاء"}, {"o": 62, "l": "المادة 2", "b": "ّ يبيــن هــذا الفصــل أن هيئــة الشــراء العــام نجحــت ،خــال فتــرة زمنيــة قصيــرة وفــي ســياق وطنــي ّ\nأســس مؤسســية وتنظيميــة متينــة إلصــاح الشــراء العــام .ومــع أن التحديــات ال تزال قائمة ،فإن اإلنجــازات المحققة\nتشــكّ ل نقطــة انطــاق فعليــة لتعزيــز األثــر ،وتبـ ّـرر االنتقــال فــي الفصــول الالحقــة إلــى تحليــل الشــفافية ،الرقمنــة،\n والبيانــات اإلحصائيــة.\nكميــاً ونوعيــاً فــي نشــاط هيئــة الشــراء العــام ،يتجلّ ــى\n علــى الرغــم مــن حداثــة التجربــة ،تُ ظهــر البيانــات الفعليــة تصاعــداً ّ\n فــي مؤشــرات أساســية أبرزهــا:\n • ارتفاع عدد المراسالت الواردة إلى الهيئة بما يقارب ستة أضعاف بين عامي 2022و ،2025بما يعكس\n توّسع نطاق تطبيق القانون وتعاظم دور الهيئة كمرجعية تنظيمية؛\n ّ\n\f53\n • الحفاظ على مستوى استجابة مرتفع خالل السنوات 2022الى ،2025بما يعكس قدرة تشغيلية ملحوظة\n رغم محدودية الموارد؛\n تطّور دور الهيئة تدريجيًاً من التركيز على تفسير أحكام القانون إلى االضطالع بوظائف أشمل في الرقابة\n ّ • \n الوقائية ،وتوجيه الجهات الشارية ،وبناء القدرات المؤسسية.\nويؤكــد ذلــك أن المرحلــة المقبلــة تتطلــب االنتقــال مــن إدارة الضغط التشــغيلي إلى تعزيز األثر المنهجي والمســتدام\n لإلصالح.\n\f الفصل الخامس\nالشفافية والرقمنة واألثر على اإلصالح\n\f جدول المحتويات\n56 .Iمقدمة\n56 .IIالشفافية كنهج عمل – من النص إلى التطبيق\n56 .1النشر اإللزامي والمركزي\n57 .2إتاحة البيانات المفتوحة ()Open Data\n58 .IIIالرقمنة – المنصة اإللكترونية المركزية للشراء العام\n58 .1المنصة كأداة إصالح مؤسسي\n58 .2وظائف المنصة ودورها في حوكمة الشراء\n58 .3البيانات المفتوحة والشفافية المؤسسية\n58 .4تطوير المنصة وتعزيز أدائها\n59 .IVاألثر األولي لإلصالح الرقمي :مؤشرات ونتائج مبدئية"}, {"o": 63, "l": "المادة 2", "b": "59 .1أثر على المنافسة وبيئة األعمال\n61 .2أثر على الكفاءة اإلدارية\n61 .3أثر على الرقابة ومكافحة الفساد\n61 .Vالدروس المستفادة والتحديات\n61 ً\n وقتا .1التغيير الثقافي يحتاج\n61 .2المرونة في التطبيق\n61 .3أهمية جودة البيانات\n61 .4أبرز التحديات المؤسسية والتقنية وآليات المعالجة\n62 .VIالخالصة\n\f 56\n الفصل الخامس :الشفافية والرقمنة واألثر على اإلصالح\n .Iمقدمة\nشــكّ لت الشــفافية والرقمنــة ركيزتيــن أساســيتين فــي مســار إصــاح نظــام الشــراء العــام فــي لبنــان ،ليــس باعتبارهمــا\nأدوات تقنيــة فحســب ،بــل كمدخــل إلعــادة تنظيــم اإلجــراءات ،توحيــد الممارســات ،وتعزيــز المســاءلة .وفــي هــذا\nاإلطــار ،اعتمــد قانــون الشــراء العــام الجديــد مبــدأ النشــر اإللزامــي والمركــزي ،وأنــاط بهيئــة الشــراء العــام مســؤولية\n توفيــر اإلطــار العملــي الــذي يتيــح تطبيــق هــذا المبــدأ بصــورة منتظمــة وقابلــة للتنفيــذ.\nمثلــت المنصــة اإللكترونيــة المركزيــة للشــراء العــام األداة المحوريــة لترجمــة هــذا المبــدأ إلــى ممارســة فعليــة،وقــد ّ\nإذ أضحــت منــذ إطالقهــا العمــود الفقــري لمســار الرقمنــة ،ومركــز تجميــع البيانــات ،ومنصــة إتاحــة المعلومــات\n المتعلقــة بإجــراءات الشــراء العــام.\n .IIالشفافية كنهج عمل – من النص إلى التطبيق\n .1النشر اإللزامي والمركزي\nأرســى قانــون الشــراء العــام مبــدأ النشــر اإللزامــي والمركــزي لمختلــف مراحــل إجــراءات الشــراء ،بمــا يضمــن إتاحــة\nالمعلومــات لجميــع الجهــات المعنيــة علــى قــدم المســاواة .وقــد عملــت هيئــة الشــراء العــام منــذ بــدء نفــاذ القانــون\nـا أساســياً للشــفافية والمســاءلة ،وقــد تولّ ــت تنفيــذه عمليــاً عبــر المنصــة علــى تكريــس هــذا المبــدأ باعتبــاره مدخـ ً"}, {"o": 64, "l": "المادة 2", "b": "اإللكترونيــة المركزيــة ،التــي أصبحــت المرجــع الوطنــي الوحيــد لنشــر إعالنــات الشــراء ،ملفــات التلزيــم (او دفاتــر\n الشــروط) ،قــرارات اإلرســاء ،ونتائــج التلزيــم حتــى تنفيــذ العقــود.8\nوســاهم االنتقــال مــن النشــر المتفـ ّـرق وغيــر المتجانــس إلــى النشــر المركــزي عبــر المنصــة فــي توحيــد ممارســات\nفضــا عــن تســهيل وصــول\n ً والحــد مــن االستنســابية،\n ّ اإلعــان والنشــر ،تعزيــز الشــفافية ،تعزيــز تكافــؤ الفــرص،\n المعلومــات إلــى المتنافســين ،والمجتمــع المدنــي ،والجهــات الرقابيــة.\nفــي هــذا اإلطــار ،تُ ظهــر المؤشــرات واألرقــام خــال الفتــرة التــي يغطيهــا هــذا التقريــر اتجاهــاً تصاعديــاً واضحــاً\nفــي مســتوى النشــر واســتخدام المنصــة ،ســواء علــى صعيــد الجهــات الشــارية النشــطة أو حجــم إجــراءات الشــراء\n المنشــورة.\nمؤشــر الجهــات الشــارية النشــطة تزايــداً مســتمراً فــي أعــداد الجهــات التــي تســتخدم المنصــة ّ فمــن جهــة ،يؤكّ ــد\nاإللكترونيــة المركزيــة للنشــر المتعلّ ــق بتنفيــذ إجــراءات الشــراء العــام .فقــد ارتفــع عــدد هــذه الجهــات مــن 32جهــة\n 9\nاســتخدمت المنصــة خــال األشــهر الخمســة األولــى مــن تطبيــق القانــون فــي العــام ( 2022مــن 29تمــوز 2022حتــى\nـوال إلــى 128جهــة\n 31كانــون األول ،)2022إلــى 113جهــة فــي العــام ،2023ثــم الــى 123جهــة فــي العــام ،2024وصـ ً\nفــي العــام .2025ويعكــس هــذا التطـ ّـور االنتقــال التدريجــي مــن االســتخدام المحــدود للمنصــة فــي مرحلــة اإلطــاق\nتحســن مســتوى\n ـدل علــى ّ إلــى اعتمادهــا كأداة عمــل مؤسســية مــن قبــل عــدد متزايــد مــن الجهــات الشــارية ،بمــا يـ ّ"}, {"o": 65, "l": "المادة 2", "b": "وتوســع نطــاق تطبيــق نظــام الشــراء العــام الرقمــي. ّ االمتثــال\n ّ\nمؤشــر إجــراءات الشــراء المنشــورة تزايــداً كبيــراً فــي عــدد اإلجــراءات المنشــورة علــى المنصــة مــن جهــة ثانيــةُ ،يظهــر\nاإللكترونيــة المركزيــة ،وال ســيما بيــن العــام ( 2022مــع األخــذ فــي االعتبــار أن الســنة األولــى شــملت فقــط األشــهر\n يبينــه الجــدول أدنــاه:\n الخمســة األولــى مــن تطبيــق القانــون) والعاميــن 2023و ،2024كمــا ّ\n 8علماً أن المعلومات المتعلّ قة بمرحلة تنفيذ العقود ال تزال محدودة حالياً على المنصة.\n 9علماً أنه قبل حزيران 2025كانت الجهات الشارية ترسل اعالناتها عبر البريد االلكتروني الى هيئة الشراء التي تتولى نشرها على المنصة.\n\f57\n عدد إجراءات الشراء المنشورة العام\n 203 1( 2022آب 2022حتى 31كانون األول )2022\n 1,135 2023\n 2,347 2024\n 2,181 2025\n 5,866 المجموع\n :4عدد إجراءات الشراء المنشورة على المنصة اإللكترونية المركزية\n جدول :4\n توســعاً ملموســاً فــي نطــاق النشــر المركــزي واعتمــاد المنصــة ،كمــا ّ\nتؤشــر إلــى تحـ ّـول نوعــي وتعكــس هــذه األرقــام ّ\nويعــزىفــي ممارســات اإلعــان عــن إجــراءات الشــراء العــام ،وانتقالهــا مــن ممارســة اســتثنائية إلــى قاعــدة عامــةُ .\n التراجــع الطفيــف المسـ ّـجل فــي العــام 2025إلــى عوامــل تشــغيلية وســياقية ،مــن دون أن ّ\nيؤثــر ذلــك علــى االتجــاه\n العــام التصاعــدي الســتخدام المنصــة.\nويعــرض تطـ ّـور هــذه المؤشــرات بصيغــة رســوم بيانيــة تحليليــة فــي الفصــل الســادس مــن هــذا التقريــر ،بمــا يتيــحُ\n أدق.\n قــراءة االتجاهــات الزمنيــة وتقييــم تطـ ّـور النشــر واســتخدام المنصــة علــى نحــو ّ"}, {"o": 66, "l": "المادة 2", "b": "كمــا واكبــت هيئــة الشــراء العــام هــذا التطـ ّـور عبــر مجموعــة مــن التدابيــر التنظيميــة والتشــغيلية التــي أســهمت فــي\n تمكيــن الجهــات الشــارية مــن االمتثــال لموجــب النشــر ،أبرزهــا:\nحّددت بوضوح موجبات اإلعالن ،ونشر النتائج ،ونشر العقود؛ • إصدار سلسلة من المذكرات التوجيهية التي ّ\n ّ\nالمكّثفــة لمــراسالت الجهــات الشــارية المرتبطــة بآليــات النشــر ،ال سـ ّـّيما خالل المراحــل األولــى • االســتجابة\nلتطبيــق القانــون ،مــا يعكــس انتقــال الشــفافية مــن مبــدأ نظــري إلــى ممارســة يوميــة خاضعــة للتدقيــق\n والمتابعة؛\n التدّخل لتصحيح اإلعالنات عند االقتضاء ،بما يضمن سالمة النشر وتكافؤ الفرص بين المتنافسين؛ ّ • \n • التدخل من خالل توصيات لتصحيح انحرافات جسيمة في ملفات التلزيم (دفاتر الشروط) او لمنع تقاضي\n يحّد من المنافسة.اثمان مبالغ فيها لهذه الملفات ما ّ\n مفصلة وتحليلية في الفصل الرابع من هذا التقرير.\n ّ وتُ عرض هذه المؤشرات بصورة\n .2إتاحة البيانات المفتوحة ()Open Data\nلــم يقتصــر دور المنصــة علــى نشــر الوثائــق والمســتندات ،بــل هــي شــكّ لت اإلطــار العملــي األول إلتاحــة البيانــات\nالمتعلقــة بالشــراء العــام .وعلــى الرغــم مــن أن اكتمــال البيانــات ال يــزال متفاوتــاً بيــن الجهــات ،إال أن حجــم\nتتبــع اإلجــراءات،\n موحــد يتيــح للمــرة األولــى إمكانيــة ّ\n ّ والمجمعــة ضمــن نظــام الكترونــي\n ّ المعلومــات المنشــورة\n مقارنــة الممارســات ،واســتخراج مؤشــرات كميــة حــول حجــم الشــراء ،عــدد اإلجــراءات ،وأنمــاط المنافســة.\nويعـ ّـد هــذا التطـ ّـور خطــوة أولــى نحــو اعتمــاد البيانــات المفتوحــة كأداة لدعــم السياســات العامــة ،وتعزيــز الرقابــة ُ"}, {"o": 67, "l": "المادة 2", "b": "المجتمعيــة ،واالنتقــال تدريجيــاً إلــى إدارة الشــراء العــام باالســتناد إلــى الوقائــع واألرقــام.\n\f 58\n .IIIالرقمنة – المنصة اإللكترونية المركزية للشراء العام\n .1المنصة كأداة إصا