فــي اإلجــراءات\n ّ وسـ ّـهل وصــول المهتميــن مــن القطــاع الخــاص إلــى فــرص الشــراء،\n التنافســية.\nالتحســن النســبي فــي االســتقرار النقــدي خــال العــام ،2023وال سـ ّـيما مــع اســتقرار ســعر صــرف ّ وثانيــاً ،\nـادة بيــن األعــوام 2019و .2022وقــد ســاهم هــذا االســتقرار النســبي الليــرة اللبنانيــة بعــد فتــرة مــن التقلّ بــات الحـ ّ\nفــي تحســين قــدرة القطــاع الخــاص علــى التســعير ،وتقديــر المخاطــر ،واتخــاذ قــرارات المشــاركة فــي التلزيمــات\n العامــة ،مــا انعكــس ارتفاعــاً فــي عــدد العارضيــن ،واســتمر أثــره اإليجابــي خــال العاميــن 2024و.2025\nويؤكّ ــد تزامــن هذيــن العامليــن أن أثــر المنصــة اإللكترونيــة علــى المنافســة وبيئــة األعمــال كان مضاعفــاً عندمــا\n تحســن نســبي فــي الظــروف االقتصاديــة الكلّ يــة.\n ترافقــت اإلصالحــات المؤسســية مــع ّ\n\f61\n .2أثر على الكفاءة اإلدارية\nســاهمت المذكــرات التفســيرية وتوحيــد اإلجــراءات فــي تقليــص التبايــن فــي تفســير القانــون ،مــا انعكــس تدريجيــاً\n المقدمــة وانخفــاض األخطــاء اإلجرائيــة المتكــررة.\n ّ علــى جــودة الملفــات\n .3أثر على الرقابة ومكافحة الفساد\nأرســى اإلصــاح أسســاً عمليــة لمكافحــة الفســاد ،إذ عــزّ زت الرقمنــة قــدرة الجهــات الرقابيــة والــرأي العــام علــى\nـا رادعــاً للممارســات المخالفــة ،وســاهم فــي تعزيــز وتتبــع اإلجــراءات ،مــا شــكّ ل عامـ ً\n االطــاع علــى المعلومــات ّ\n ّ\n النزاهــة مــن خــال الرقابــة الوقائيــة ،حتــى فــي ظــل محدوديــة المــوارد البشــرية والتقنيــة.\nوفــرت لهــا مصــدراً مركزيــاً"}, {"o": 73, "l": "المادة 2", "b": "كمــا انعكســت المنصــة اإللكترونيــة بشــكل مباشــر علــى عمــل الجهــات الرقابيــة ،إذ ّ\nوموحــداً للمعلومــات المتعلقــة بمختلــف مراحــل الشــراء العــام ،بمــا يســهم فــي تعزيــز فعاليــة الرقابــة المســبقة ّ\nوالمرافقــة والالحقــة .فقــد بــات بإمــكان األجهــزة الرقابيــة ،كـــالتفتيش المركــزي ،وديــوان المحاســبة ،ومراقبــي\nعقــد النفقــات فــي وزارة الماليــة ،إضافــة إلــى الهيئــة الوطنيــة لمكافحــة الفســاد وســائر الجهــات المعنيــة ،الوصــول\nبصــورة أســرع وأكثــر انتظامــاً إلــى اإلعالنــات ،ودفاتــر الشــروط ،ونتائــج التلزيــم ،والعقــود ،والتعديــات الطارئــة،\nوغيرهــا مــن المســتندات والبيانــات المرتبطــة بتنفيــذ الشــراء العــام ،األمــر الــذي عــزّ ز القــدرة علــى رصــد المخالفــات\n موثقــة وشــفافة. أو مكامــن الخلــل ،ودعــم اتخــاذ القــرارات الرقابيــة علــى أســس ّ\nومــن شــأن هــذا التكامــل بيــن الرقمنــة والرقابــة أن يســاهم فــي تعزيــز الحوكمــة الرشــيدة ،ورفــع مســتوى الثقــة\nبإجــراءات الشــراء العــام ،وتحســين كفــاءة اإلنفــاق العــام ،بمــا ينســجم مــع األهــداف اإلصالحيــة لقانــون الشــراء\n العــام الجديــد.\n .Vالدروس المستفادة والتحديات\n ً\n وقتا .1التغيير الثقافي يحتاج\nأظهــرت التجربــة أن الرقمنــة ال تقتصــر علــى توفيــر أدوات تقنيــة ،بــل تتطلــب تغييــراً تدريجيــاً فــي الثقافــة اإلداريــة،\n وبنــاء قــدرات بشــرية قــادرة علــى اســتخدام األنظمــة الجديــدة بفعاليــة.\n .2المرونة في التطبيق\nوالتوســع اعتمــاد مقاربــة مرنــة ،تســمح بالتطويــر التدريجــي للمنصــة ومعالجــة التحديــات\n ّ اســتدعت مرحلــة اإلطــاق\n التقنيــة والتنظيميــة بالتــوازي مــع االســتخدام الفعلــي.\n .3أهمية جودة البيانات"}, {"o": 74, "l": "المادة 2", "b": "بــرزت جــودة البيانــات كإحــدى التحديــات األساســية ،مــا يؤكــد الحاجــة إلــى تعزيــز اإلرشــاد ،التوحيــد ،والتدقيــق\n المســتمر لضمــان موثوقيــة المعلومــات المنشــورة وقابليتهــا للتحليــل.\n .4أبرز التحديات المؤسسية والتقنية وآليات المعالجة\nموحــد\n ّ المحقــق فــي مجــال الرقمنــة والنشــر المركــزي ،فــإن تطبيــق نظــام إلكترونــي\n ّ التقــدم\n ّ علــى الرغــم مــن\nمعقــد ،وفــي ظــل تفــاوت كبيــر فــي قــدرات الجهــات الشــارية ،أفــرز\n ّ للشــراء العــام فــي ســياق مؤسســي واقتصــادي\n مجموعــة مــن التحديــات المؤسســية والتقنيــة التــي واجهــت مراحــل التطبيــق األولــى.\nوقــد تعاملــت هيئــة الشــراء العــام مــع هــذه التحديــات وفــق مقاربــة تدريجيــة وعمليــة ،تقــوم علــى تشــخيص األثــر،\nوتطويــر آليــات معالجــة قابلــة للتنفيــذ ،تجمــع بيــن التدخــات التنظيميــة ،وبنــاء القــدرات ،والدعــم التقنــي ،بمــا\n يضمــن اســتمرارية المنصــة وتحســين جــودة البيانــات دون تعطيــل ســير إجــراءات الشــراء.\n\f 62\nويبيــن الجــدول أدنــاه أبــرز هــذه التحديــات ،آثارهــا المباشــرة على النشــر وجودة البيانــات ،وآليات المعالجــة المعتمدة\n ّ\n لمعالجتها.\n آلية المعالجة المعتمدة األثر التحدي\n برامــج تدريبيــة مســتمرة ،نشــر نمــاذج\n محدوديــة القــدرات الرقميــة لــدى بعــض تأخــر النشــر ،أخطــاء إدخــال ،عــدم اكتمــال\n معياريــة ،دعــم فنــي مركــزي ،وفتــرات\n البيانــات الجهــات الشــارية\n تجريبيــة موجهــة\n موحــدة ،تدقيــق\n ّ اعتمــاد قواعــد تحويــل\n فجــوات بيانــات تاريخيــة وعــدم توحيــد صعوبــة المقارنــة الزمنيــة ،ضعــف موثوقيــة\n عينــات مســتهدفة ،ونشــر منهجيــات ّ بعــض المؤشــرات الصيــغ\n التصحيــح تدريجيــاً"}, {"o": 75, "l": "المادة 2", "b": "نشــر مذكــرات إلزاميــة ،ربــط االعتمــادات\n الماليــة بالتــزام النشــر ،وإصــدار قوائــم امتثــال انخفاض االمتثال ،استخدام قنوات موازية مقاومة التغيير الثقافي واإلجرائي\n دوريــة\n حقــول إلزاميــة ،ربــط مــع الســجالت الرســمية\n (الرقــم المالــي ،الســجل التجــاري) ،ومراجعــة مؤشرات مضللة ،صعوبة الرقابة الالحقة ضمان جودة البيانات ودقتها\n مــا بعــد النشــر\n .VIالخالصة\nتحولتــا تدريجيــاً إلــى أدوات عمــل\n يبيــن هــذا الفصــل أن الشــفافية والرقمنــة لــم تعــودا مجــرد التزامــات قانونيــة ،بــل ّّ\n فعليــة داخــل منظومــة الشــراء العــام.\nكذلــك ،أثبتــت المنصــة اإللكترونيــة المركزيــة للشــراء العــام أنهــا ركيــزة أساســية إلصــاح النظــام ،وأداة ال غنــى عنهــا\nلترســيخ الشــفافية ،مركــزة البيانــات ،وتعزيــز الرقابــة .وعلــى الرغــم مــن أن األثــر الكامــل لإلصــاح الرقمــي يتطلــب\nمتقدمــة مــن الشــراء اإللكترونــي المتكامــل ،ورغــم التحديــات ،فــإن النتائــج األوليــة تشــكّ ل\n ّ ـتكماال لمراحــل\n ً وقتــاً واسـ\nأساســاً متينــاً لالنتقــال إلــى مرحلــة أكثــر نضجــاً ،قائمــة علــى البيانــات ،والتحليــل ،وصنــع السياســات المبنيــة علــى\n األدلــة.\n\f\fالفصل السادس\nالبيانات واإلحصاءات\n\f جدول المحتويات\n66 مقدمة ّ .I\n66 .1هدف الفصل ودوره في تقييم تطبيق قانون الشراء العام\n66 .2نطاق البيانات المعتمدة\n66 .3الفترة الزمنية للتحليل\n66 .4مصادر البيانات\n67 .5منهجية استخراج ومعالجة البيانات\n67 .6التمييز بين المشتريات والمزايدات العمومية\n67 .7حدود التحليل اإلحصائي والقيود المنهجية\n68 تطور حجم نشاط الشراء العام ّ .II\n68 المسجلة\n ّ .1نظرة عامة على العمليات\n69 .2تطور عدد العقود الملزّ مة ّ\n70 .3تطور القيمة المالية للعقود الملزّ مة ّ"}, {"o": 76, "l": "المادة 2", "b": "71 .4قراءة مقارنة بين عدد العقود والقيمة المالية\n71 .IIIتحليل طرق الشراء\n71 .1التوزّ ع العددي لطرق الشراء\n72 .2التوزّ ع المالي لإلنفاق حسب طريقة الشراء\n74 .3نِ َسب توزيع اإلنفاق حسب طريقة الشراء\n74 .4مقارنة بين التوزّ ع العددي والمالي\n74 .5الشراء عبر الفاتورة كآلية منخفضة القيمة\n75 .6قراءة في المزايدات العمومية\n76 للتوجهات العامة ّ .7قراءة أولية\n76 .IVتحليل الجهات الشارية\n76 .1الجهات األكثر نشاطا من حيث عدد العمليات\n ً\n79 تركز اإلنفاق العام ّ .2\n81 .Vتحليل االنفاق حسب نوع العقد\n82 .1التوزّ ع العددي للعقود حسب النوع\n83 .2توزّ ع االنفاق حسب النوع\n83 .3مقارنة بين التوزّ ع العددي والمالي\n84 .VIتحليل المنافسة والمشاركة في عمليات الشراء العام\n84 .1وزن المناقصة العمومية مقابل الطرق األخرى\n85 تطور اللجوء إلى االتفاق الرضائي :السياق القانوني واالستثنائي ّ .2\n87 .3دالالت أنماط االستخدام في سياق إصالح الشراء العام\n88 .4قراءة حذرة دون افتراض منافسة فعلية\n88 .VIIالتحليل المالي والمؤشرات األولية للقيمة مقابل المال\n89 .1متوسط قيمة العقد\n90 .2الفروقات المالية بين اإلجراءات\n91 تطّور هيكل اإلنفاقّ .3\n92 .4حدود االستنتاجات الممكنة\n92 .VIIIالشفافية والنشر وجودة البيانات\n93 .1النشر على المنصة :من اإللزام القانوني إلى الممارسة الفعلية\n95 .2نشر خطط الشراء :بين الطموح القانوني والواقع المؤسسي\n95 التحول في نظام الشراء العامّ .IXمن البيانات إلى الرسائل :مؤشرات\n96 .1الرسائل الرئيسية المتعلقة بحجم العمليات\n96 .2الرسائل الرئيسية المتعلقة بطرق الشراء\n96 .3الرسائل الرئيسية المتعلقة بالمنافسة\n96 .4الرسائل الرئيسية المتعلقة بالجهات الشارية\n96 .5الرسائل الرئيسية المتعلقة بالتحليل المالي\n96 .6الرسائل الرئيسية المتعلقة بالشفافية والرقمنة\n97 .7الرسالة العامة للفصل السادس\n\f 66\n الفصل السادس :البيانات واإلحصاءات"}, {"o": 77, "l": "المادة 2", "b": "مقدمة\n ّ .I\n .1هدف الفصل ودوره في تقييم تطبيق قانون الشراء العام\nوكميــاً لعمليــات الشــراء العــام المنشــورة علــى المنصــة اإللكترونيــة المركزيــة\n ّ ـا إحصائيــاً\n يقـ ّـدم هــذا الفصــل تحليـ ً\nلــدى هيئــة الشــراء العــام ،بهــدف تقييــم مســتوى تطبيــق قانــون الشــراء العــام مــن خــال مؤشــرات قابلــة للقيــاس.\nويســتند التحليــل إلــى البيانــات المتاحــة علــى المنصــة خــال الفتــرة الممتــدة مــن 1آب 2022إلــى 31كانــون\n األول.2025\nويقصــد بهــذا التحليــل رصــد أنمــاط التطبيــق واالتجاهــات العامــة فــي اســتخدام نظــام الشــراء العــام اإللكترونــي ُ\nالــذي تتيحــه المنصــة ،دون أن يشــكّ ل تدقيقــاً ماليــاً أو قانونيــاً لإلجــراءات أو تقييمــاً لســامة القــرارات المتّ خــذة.\nويعالــج الفصــل حجــم نشــاط الشــراء العــام ،وطــرق الشــراء المعتمــدة ،وأداء الجهــات الشــارية ،والتحليــل المالــي\nللعقــود ،إضافــة إلــى مؤشــرات الشــفافية وجــودة البيانــات ،وذلــك تمهيــداً لعــرض التحديــات البنيويــة والتشــغيلية\n فــي الفصــل الالحــق.\n .2نطاق البيانات المعتمدة\nيرتكــز هــذا الفصــل حصــراً علــى البيانــات المدخلــة والمنشــورة عبــر المنصــة اإللكترونيــة لهيئــة الشــراء العــام ،والتــي\nنفذتهــا الجهــات الشــارية خــال الفتــرة الزمنيــة المشــمولة بالتقريــر .ويشــمل نطــاق تعكــس عمليــات الشــراء التــي ّ\n البيانــات مــا يلــي:\n •إعالنات الشراء المنشورة على المنصة؛\n •إجراءات التلزيم ونتائجها؛\n •العقود المبرمة والقيم المالية المرتبطة بها؛\n •أنواع طرق الشراء المعتمدة؛\n والموردين المشاركين.\n ّ •الجهات الشارية\nالمنفــذة علــى المســتوى الوطنــي،\n ّ وال يفتــرض التحليــل اكتمــال أو شــمولية مطلقــة لجميــع عمليــات الشــراء العــام"}, {"o": 78, "l": "المادة 2", "b": "بــل يقتصــر علــى مــا هــو ّ\n موثــق إلكترونيــاً علــى المنصــة.\n .3الفترة الزمنية للتحليل\nحيــز التنفيــذ ،ولغايــة\n يغطــي التحليــل اإلحصائــي الفتــرة الممتــدة مــن 1آب ،2022تاريــخ دخــول قانــون الشــراء العــام ّ\n 31كانــون األول ،2025بمــا يتيــح رصــد االتجاهــات العامــة لتطبيــق القانــون خــال مرحلــة االنتقــال إلــى النظــام\n اإللكترونــي.\n .4مصادر البيانات\n تعتمد البيانات المستخدمة في هذا الفصل على:\n •المنصة اإللكترونية لدى هيئة الشراء العام\n •وقواعد البيانات المرافقة لها.\n وال تشمل هذه البيانات أي معلومات مستقاة من مصادر خارجية أو تقارير ورقية غير منشورة على المنصة.\n\f67\nأن األرقــام الــواردة فــي هــذا التقريــر تعكــس المعطيــات المتوافــرة علــى المنصــة المركزيــةمــن المهــم اإلشــارة إلــى ّ\nلــدى هيئــة الشــراء العــام بتاريــخ إعــداد اإلحصــاءات ،وقــد ال تتطابــق بشــكل كامــل مــع األرقــام التــي قــد تظهــر\nالحقــاً علــى هــذه المنصــة عنــد اســتخدام األدوات اإلحصائيــة المتاحــة عليهــا للفتــرة الزمنيــة نفســها .ويعــود ذلــك\nبشــكل أساســي إلــى قيــام بعــض الجهــات الشــارية بنشــر أو اســتكمال إدخــال المعلومــات المتعلقــة بعمليــات\n متأخــر.\n ّ الشــراء لديهــا بشــكل\n أن هــذه الفروقــات ،عنــد حصولهــا ،تبقــى محــدودة وال ّ\nتؤثر على االتجاهــات العامة والتحليالت وتجــدر اإلشــارة إلــى ّ\n االســتنتاجية المعتمــدة فــي هذا الفصل.\n .5منهجية استخراج ومعالجة البيانات\n تم اعتماد المنهجية التالية في إعداد التحليل اإلحصائي:\n • استخراج البيانات :جرى استخراج البيانات الخام مباشرة من المنصة بصيغ قابلة للمعالجة اإلحصائية.\n • تنظيف البيانات :شمل ذلك إزالة التكرار ،معالجة القيم الناقصة حيث أمكن ،وتوحيد التسميات والفئات."}, {"o": 79, "l": "المادة 2", "b": "• تصنيف البيانات :جرى تصنيف البيانات وفق محاور تحليلية تشمل نوع الجهة الشارية ،طريقة الشراء،\n القطاع ،القيمة المالية ،وحالة العملية (معلن ،ملّزّ م ،ملغى).\n مالحظة منهجية حول احتساب القيم المالية\nألغــراض هــذا الفصــل ،ونظــراً للتقلبــات الحــادة فــي ســعر صــرف الليــرة اللبنانيــة خــال الفتــرة المشــمولة بالتقريــر،\nالمبينــة فــي الجــداول والرســوم البيانيــة بالــدوالر األميركــي ،وذلــك اســتناداً\n ّ جــرى التعبيــر عــن القيــم الماليــة للعقــود\nإلــى القيمــة الفعليــة لليــرة اللبنانيــة بتاريــخ التلزيــم .وقــد اعتمــد هــذا النهــج بهــدف تأميــن إمكانيــة المقارنــة بيــن\nالتشــوهات التــي قــد تنتــج عــن تقلبــات ســعر الصــرف ،بمــا يســمح بعكــس ّ المعطيــات عبــر الســنوات ،وتفــادي\n الحجــم الحقيقــي لإلنفــاق العــام واتجاهاتــه الفعليــة خــال فتــرة تطبيــق قانــون الشــراء العــام.\n .6التمييز بين المشتريات والمزايدات العمومية\nُيراعــى فــي هــذا الفصــل التمييــز بيــن عمليــات الشــراء العــام التــي تشــكّ ل إنفاقــاً عامــاً ،وعمليــات البيــع أو اإليجــار\nعمال بمذكّ رة هيئة الشــراء العام 2022/7تاريخ 2022/08/19 ً طويــل األمــد التــي تتـ ّـم عبــر المزايــدة العموميــة ،وذلك\n ذات الصلــة .وعليــه ،تـ ّـم اعتمــاد نوعيــن مــن البيانــات:\n • بيانات اإلنفاق ،وتشمل العقود الملّزّ مة عبر المناقصات العمومية ،وطلبات عروض األسعار ،وطلبات\n االقتراحات للخدمات االستشارية ،واالتفاقات الرضائية.\n وُيشار إليها\n • بيانات المزايدات العمومية ،المرتبطة بالبيع أو اإليجار ،والتي ال ُتُ درج ضمن تحليل اإلنفاقُ ،\n بشكل منفصل حيثما اقتضى األمر.\n .7حدود التحليل اإلحصائي والقيود المنهجية"}, {"o": 80, "l": "المادة 2", "b": "يرتكــز التحليــل اإلحصائــي الــوارد فــي هــذا الفصــل علــى البيانــات المتاحــة عبــر المنصــة اإللكترونيــة خــال الفتــرة\nالزمنيــة قيــد الدراســة ،مــع مــا يرافــق ذلــك مــن قيــود منهجيــة ينبغــي أخذهــا بعيــن االعتبــار عنــد قــراءة النتائــج.\nفالمؤشــرات الــواردة ال تهــدف إلــى إصــدار أحــكام تقييميــة علــى أداء منظومــة الشــراء العــام ،بقــدر مــا تســعى\nإلــى توصيــف التوزيعــات الرقميــة والماليــة كمــا هــي متاحــة فعليــاً ،وقــراءة أنماطهــا فــي ضــوء خصائــص الجهــات\n الشــارية ،وحجــم إنفاقهــا ،وطبيعــة القطاعــات التــي تنتمــي إليهــا.\nأوال ،ال تــزال قاعــدة البيانــات فــي مرحلــة تشــكّ ل تدريجــي ،حيــث يفتقــر عــدد مــن الســجالت إلــى معلومــات أساســية، ً\nوال ســيما القيــم الماليــة أو طريقــة الشــراء ،إذ ُيسـ َّـجل نحــو 570عقــداً دون قيمــة ماليــة مكتملــة .وقــد تـ ّـم اعتمــاد\nالعقــود المكتملــة البيانــات حيثمــا أمكــن ،مــع التأكيــد علــى أن النتائــج تعكــس اتجاهــات عامــة أكثــر مــن كونهــا\n قياســات دقيقــة وشــاملة لحجــم اإلنفــاق الفعلــي.\n\f 68\nثانيــاً ُ ،يالحــظ تفــاوت فــي مســتوى الدقــة والتفصيــل بيــن الجهــات الشــارية فــي إدخــال البيانــات ،مــا ينعكــس علــى\n درجــة تجانــس المؤشــرات المســتخرجة ويحـ ّـد مــن قابليــة المقارنــة الكاملــة بيــن مختلــف الفئــات والســنوات.\nثالثــاً ،ال تتوافــر حاليــاً بيانــات تفصيليــة كافيــة حــول عناصــر تحليليــة أساســية مثــل عــدد العارضيــن أو تجزئــة العقــود\nيقيــد إمكانيــة\n إلــى مجموعــات ،وال ســيما فــي المراحــل األولــى مــن تشــغيل المنصــة قبــل حزيــران ،2025األمــر الــذي ّ"}, {"o": 81, "l": "المادة 2", "b": "تحليــل مســتوى المنافســة الفعليــة أو البنيــة التفصيليــة للعقــود.\nرابعــاً ،ينبغــي اإلشــارة إلــى أن نطــاق البيانــات المنشــورة ال يعكــس بالضــرورة كامــل حجــم الشــراء العــام ،إذ يتــم\nعــادة نشــر العقــود التــي تتجــاوز ســقوفاً ماليــة محــددة ،فــي حيــن قــد تُ ســتثنى بعــض العقــود أو تُ عــرض بصــورة غيــر\n مكتملــة ،بمــا يخلــق تفاوتــاً فــي مســتوى التغطيــة بحســب القطــاع وطبيعــة العمليــة.\nخامســاً ،كان للتعديــات القانونيــة والسياســاتية أثــر مباشــر علــى قابليــة المقارنــة الزمنيــة للبيانــات ،إذ ّأدى رفــع\nالســقوف الماليــة خــال عامــي 2023و 2024إلــى تغييــر فــي أنمــاط تصنيــف وتســجيل عــدد مــن عمليــات الشــراء،\nكمــا أســهمت التعديــات التنظيميــة ،ومنهــا إعفــاء بعــض فئــات طلبــات عــروض األســعار مــن النشــر اإللزامــي ،فــي\n تعديــل مســتوى ظهــور بعــض العمليــات فــي البيانــات المنشــورة ،وبالتالــي التأثيــر علــى المقارنــة بيــن الســنوات.\nوعليــه ،تُ قــرأ النتائــج الــواردة فــي هــذا الفصــل كمؤشــرات اتجاهيــة تعكــس مســتوى التفاعــل مــع نظــام الشــراء\nوتطــور تطبيقــه ،وليــس كخالصــات نهائيــة أو قيــاس شــامل ألداء المنظومــة .كمــا يســتدعي تفســيرها ّ العــام\nالمتغيــر ،وباالختالفــات فــي التغطيــة وجــودة البيانــات عبــر الزمــن والجهــات.\n ّ ربطهــا باإلطــار القانونــي والتنظيمــي\n تطور حجم نشاط الشراء العام\n ّ .II\n ّ\nالموثــق إلكترونيــاً علــى منصــة هيئــة الشــراء العــام خــال كميــاً لحجــم نشــاط الشــراء العــام\n يقـ ّـدم هــذا القســم عرضــاً ّ\nالفتــرة الممتــدة مــن 1آب 2022إلــى 31كانــون األول ،2025مــن حيــث عــدد العمليــات والقيمــة الماليــة للعقــود"}, {"o": 82, "l": "المادة 2", "b": "الملزّ مــة ،بمــا يتيــح تكويــن صــورة أوليــة عــن مســتوى اســتخدام المنصــة وتطـ ّـور النشــاط الشــرائي المنشــور.\n تجدر اإلشارة إلى أن:\n • البيانات المعروضة في هذا القسم تشمل كافة العقود الملّزّ مة ،إن بطريقة المزايدة العمومية او بطرق\n الشراء االخرى.\n • التحليل يقتصر على العقود الملزّ مة والمنشورة على المنصة.\n المنّفذة خارج المنصة خالل الفترة\n ّ • ال تعكس األرقام بالضرورة الحجم الكامل لجميع عمليات الشراء العام\n نفسها.\n المسجلة\n ّ .1نظرة عامة على العمليات\nخــال الفتــرة الزمنيــة التــي يغطيهــا التقريــر ،تـ ّـم تســجيل مــا مجموعــه 5،866عمليــة شــراء علــى منصــة الشــراء العــام.\nالتوقــف\n ّ ـوال إلــى التلزيــم أو\n وتشــمل مختلــف المراحــل اإلجرائيــة ،بــدءاً مــن اإلعــان ،مــروراً بســير اإلجــراءات ،وصـ ً\n دون تلزيــم.\nومــن بيــن هــذه العمليــات ،توقفــت 854عمليــة عنــد مرحلــة اإلعــان ولــم تســتكمل إجراءاتهــا ،فــي حيــن بلغــت 980\nعمليــة مرحلــة متقدمــة مــن اإلجــراءات دون أن تنتهــي بتلزيــم .أمــا العمليــات التــي ُأنجــزت وتُ ّوجــت بإرســاء عقــود،\n فتشــكّ ل قاعــدة التحليــل األساســي فــي هــذا الفصــل.\nيبيــن الرســم البيانــي أدنــاه النســب المئويــة لعمليــات الشــراء االجماليــة التــي سـ ّـجلت علــى المنصة والنســب المئوية\n ّ\n توقفــت عنــد االعــان والتــي لــم تلزّ م.\n للعمليــات التــي لزّ مــت وتلــك التــي ّ\n\f69\n جدول :6نظرة عامة على عمليات الشراء المسجلة على المنصة ()2025/12/31 – 2022/8/1\n .2تطور عدد العقود الملزّ مة\n ّ\n 12\n جدول :7عدد العقود الملزّ مة سنويا\nالتوســع التدريجــي فــي\n ّ ُيظهــر تحليــل تطـ ّـور عــدد العقــود الملزّ مــة خــال فتــرة التقريــر نمــواً تصاعديــاً واضحــاً يعكــس"}, {"o": 83, "l": "المادة 2", "b": "اســتخدام المنصــة مــن قبــل الجهــات الشــارية.\n 12بما في ذلك المزايدات\n\f 70\nحيــز التنفيــذُ ،سـ ّـجل عــدد محــدود\n ففــي عــام ،2022الــذي اقتصــر علــى األشــهر الخمســة األولــى مــن دخــول القانــون ّ\nوالتكيــف األولــي مــع النظــام الجديــد .أمــا عــام ،2023فقــد\n ّ مــن العقــود الملزّ مــة ،مــا يتماشــى مــع مرحلــة اإلطــاق\nـدل علــى بــدء االنتقــال مــن مرحلــة التجريــب إلــى مرحلــةشــهد قفــزة ملحوظــة فــي عــدد العقــود الملزّ مــة ،بمــا يـ ّ\n االســتخدام الفعلــي.\nويبــرز عــام 2024كنقطــة تحـ ّـول أساســية ،حيــث تضاعــف عــدد العقــود الملزّ مــة بشــكل كبيــر مقارنــة بالعــام الســابق،\nتوســع قاعــدة الجهــات الشــارية التــي باتــت تعتمــد المنصــة كأداة رئيســية لتنفيــذ إجــراءات الشــراء مــا يشــير إلــى ّ\nالعــام وكذلــك يتأثــر باســتقرار ســعر صــرف الليــرة اللبنانيــة ابتــداء مــن هــذا العــام .ويســتمر هــذا االتجــاه التصاعــدي\nفــي عــام ،2025مــع تســجيل زيــادة إضافيــة فــي عــدد العقــود ،وإن بوتيــرة أقــل حـ ّـدة ،مــا قــد يعكــس دخــول النظــام\n مرحلــة أكثــر اســتقراراً مــن حيــث حجــم االســتخدام.\nـدل علــى تزايــد اعتمــاد ّ\n الموثــق إلكترونيــاً ،وتـ ّ وتعكــس هــذه المعطيــات تطـ ّـوراً تدريجيــاً فــي حجــم النشــاط الشــرائي\n وتحســن مســتوى االمتثــال لمتطلبــات النشــر. ّ الجهــات الشــارية علــى المنصــة\n .3تطور القيمة المالية للعقود الملزّ مة\n ّ\n جدول : 8قيمة العقود الملزّ مة\nنمــواً متســارعاً فــي القيمــة الماليــة اإلجماليــة للعقــود\n ّ إلــى جانــب النمــو فــي عــدد العقــودُ ،يظهــر التحليــل\n الملزّ مــة 13والمنشــورة علــى المنصــة ،محســوبة بالــدوالر األميركــي."}, {"o": 84, "l": "المادة 2", "b": "ففــي عــام ،2022بقيــت القيمــة اإلجماليــة للعقــود محــدودة ،انســجاماً مــع العــدد المنخفــض للعقــود المنشــورة\nوقصــر الفتــرة الزمنيــة المشــمولة .إال أن عــام 2023سـ ّـجل ارتفاعــاً كبيــراً فــي القيمــة اإلجماليــة ،مــا يعكــس إدراج\n عقــود ذات أحجــام ماليــة أكبــر ضمــن نطــاق النشــر اإللكترونــي.\nيبــرز عــام 2024كنقطــة تحـ ّـول واضحــة مــن حيــث حجــم اإلنفــاق ،إذ شــهدت القيمــة اإلجماليــة للعقــود الملزّ مــة\n ارتفاعــاً ملحوظــاً مقارنــة بالســنوات الســابقة.\n 13بما في ذلك المزايدات\n\f71\nـداء مــن ذلــك العــام ،مــا ســاهم\n ويعــزى هــذا التطـ ّـور بشــكل أساســي إلــى اســتقرار ســعر صــرف الليــرة اللبنانيــة ابتـ ً\n ُ\nفــي إعــادة تنشــيط عمليــات الشــراء العــام وتعزيــز مشــاركة القطــاع الخــاص فــي العقــود العامــة ،بعــد فتــرة مــن\nالشــلل أصابــت المنظومــة منــذ أواخــر عــام ،2019تزامنــاً مــع االنهيــار المالــي واالقتصــادي الحــاد وتراجــع قيمــة\n العملــة الوطنيــة.\nتوســعاً نوعيــاً إضافيــاً فــي القيمــة الماليــة اإلجماليــة ،مــا يعكــس دخــول قطاعــات\n ســجل ّ\n ّ أمــا عــام ،2025فقــد\nأساســية ذات وزن مالــي مرتفــع ،ويشــير إلــى إدراج عمليــات شــراء اســتراتيجية وكبيــرة الحجــم ضمــن المنصــة.\n .4قراءة مقارنة بين عدد العقود والقيمة المالية\nيتبيــن أن وتيــرة النمــو فــي اإلنفــاق تفــوق وتيــرة النمــو\n عنــد مقارنــة تطـ ّـور عــدد العقــود بالقيمــة الماليــة اإلجماليــةّ ،\nتوســع النشــر ليشــمل عمليــات فــي عــدد العقــود .ويشــير ذلــك إلــى ارتفــاع متوســط قيمــة العقــد الواحــد ،وإلــى ّ\n أكبــر حجمــاً وأكثــر تعقيــداً."}, {"o": 85, "l": "المادة 2", "b": "وتُ ظهــر هــذه القــراءة المزدوجــة أن تطـ ّـور نظــام الشــراء العــام ال يقتصــر علــى زيــادة عــدد العمليــات المنشــورة ،بــل\nيمتـ ّـد إلــى توســيع نطــاق اإلنفــاق العــام والمزايــدات العموميــة الخاضــع للنشــر والرقابــة اإللكترونيــة ،بمــا يعكــس\n تطـ ّـوراً نوعيــاً فــي اســتخدام المنصــة.\nمطــرداً فــي اســتخدام النظــام اإللكترونــي ،مــا يعكــس ونمــو عمليــات الشــراء العــام نمــواً ّ\n ّ تطــور حجــم\n ّ ُيظهــر\nـاال فعليــاً نحــو توثيــق أوســع لعمليــات الشــراء العــام مــن حيــث العــدد والقيمــة\n توســعاً مؤسســياً تدريجيــاً وانتقـ ً\n ّ\n الماليــة.\n .IIIتحليل طرق الشراء\nتوجــه\n ـا أساســياً لفهــم طبيعــة تطبيــق قانــون الشــراء العــام ،ومــدى ّ ُيشــكّ ل تحليــل طــرق الشــراء المعتمــدة مدخـ ً\nالجهــات الشــارية نحــو اآلليــات التنافســية مقارنــة باالســتثناءات التــي يجيزهــا القانــون .ويعــرض هــذا القســم التــوزّ ع\nالعــددي والمالــي للعمليــات الملزّ مــة والمنشــورة علــى منصــة هيئــة الشــراء العــام خــال الفتــرة ،2025–2022بحســب\n طريقــة الشــراء المعتمــدة ،وذلــك باالســتناد إلــى الجــداول والرســوم البيانيــة المرفقــة.\n ّ\n التوزع العددي لطرق الشراء .1\n جدول :9عدد العقود الملزّ مة بحسب طريقة الشراء\n\f 72\nنمــواً تدريجيــاً وثابتــاً فــي\n ّ ُيظهــر الرســم البيانــي الخــاص بتــوزّ ع عــدد العمليــات الملزّ مــة حســب طريقــة الشــراء\nاســتخدام المناقصــات العموميــة علــى امتــداد الفتــرة المدروســة ،إذ ارتفــع عددهــا مــن 6عمليــات فقــط فــي عــام\nتوســعاً ملحوظــاً فــي اعتمــاد هــذه 2022إلــى أكثــر مــن 430عمليــة ســنوياً فــي عامــي 2024و ،2025مــا يعكــس ّ\n اآلليــة التنافســية."}, {"o": 86, "l": "المادة 2", "b": "توســعاً عدديــاً ملحوظــاً ،ال سـ ّـيما فــي عامــي 2024و ،2025وهــو مــا\n فــي المقابــل ،سـ ّـجل طلــب عــروض األســعار ّ\nيعكــس اســتخداماً متزايــداً لهــذه الطريقــة مــن طــرق الشــراء فــي العمليــات ذات القيــم المنخفضــة أو المتوســطة،\n ضمــن الســقوف القانونيــة المعتمــدة ،وال سـ ّـيما بعــد تعديــل هــذه الســقوف فــي عامــي 2023و.2024\nفيظهــر الرســم ارتفاعــاً ملحوظــاً فــي عــدد العمليــات ،خصوصــاً فــي عــام ،2025حيــث اقتــرب أمــا االتفــاق الرضائــيُ ،\nويعــزى هــذا االرتفــاع جزئيــاً إلــى الظروف\n المنفــذة بهــذه الطريقــة مــن عــدد المناقصــات العموميــةُ .\n ّ عــدد العمليــات\nاألمنيــة االســتثنائية التــي شــهدها لبنــان فــي أواخــر عــام ،2024والتــي دفعــت بعــض الجهــات الشــارية إلــى اللجــوء\nبنــاء لمذكــرة هيئــة الشــراء العــام رقــم /٨ه.ش.ع ٢٠٢٤/تاريــخ 30ايلــول 2024وضمــن إلــى االتفاقــات الرضائيــة ً\nأن هــذه االتفاقــات الرضائيــة التــي ّلبــت حاجــات اســتثنائية واغاثيــة\n اإلطــار القانونــي المســموح بــه .الجديــر بالذكــر ّ\n خــال الربــع االخيــر مــن العــام 2024قــد تـ ّـم نشــرها علــى المنصــة فــي الربــع االول مــن العــام .2025\nوتبقــى طلبــات االقتراحــات للخدمــات االستشــارية محــدودة جــداً مــن حيــث العــدد ،مــا يشــير إلــى اســتخدام انتقائــي\n لهــذه الطريقــة خــال الفتــرة التــي يغطيهــا التقريــر.\n ّ\n التوزع المالي لإلنفاق حسب طريقة الشراء .2\n جدول :10اإلنفاق بحسب طريقة الشراء بآالف الدوالر االميركي (باستثناء المزايدات)\n\f73\nعلــى المســتوى المالــيُ ،يظهــر توزيــع اإلنفــاق 14حســب طريقــة الشــراء تباينــاً واضحــاً بيــن الــوزن العــددي والــوزن"}, {"o": 87, "l": "المادة 2", "b": "المالــي للطــرق المختلفــة .إذ تســتحوذ المناقصــات العموميــة علــى الحصــة األكبــر مــن إجمالــي قيمــة العقــود\nالملزّ مــة فــي جميــع الســنوات ،مــع تســجيل ارتفــاع حــاد فــي عــام ،2025حيــث تجــاوزت قيمتهــا 800مليــون دوالر\n أميركــي ،مــا يؤكّ ــد دورهــا كاألداة األساســية لتلزيــم العقــود ذات القيــم المرتفعــة.\nفــي المقابــل ،ورغــم االرتفــاع العــددي لعمليــات االتفــاق الرضائــي ،تبقــى مســاهمتها فــي إجمالــي اإلنفــاق أدنــى\nمــن المناقصــات العموميــة ،وإن كانــت قــد شــهدت نمــواً ملحوظــاً فــي عامــي 2024و .2025ويعــود هــذا االرتفــاع\nفــي قيمــة العقــود الملزّ مــة بطريقــة االتفــاق الرضائــي بشــكل أساســي إلــى عمليــات شــراء ذات طابــع اســتراتيجي،\nســيما عقــود متعلّ قــة بتوريــد البنزيــن والمــازوت األخضــر أبرمتهــا وزارة الدفــاع الوطنــي مــع وزارة الطاقــة وال ّ\nوالميــاه فــي عامــي 2024و 2025لصالــح الجيــش اللبنانــي والمديريــة العامــة لألمــن العــام ،وذلــك اســتناداً إلــى\nأحــكام الفقــرة الخامســة مــن المــادة 46مــن قانــون الشــراء العــام التــي تجيــز التعاقــد الرضائــي بيــن أشــخاص القانــون\nالعــام ،باإلضافــة الــى عقــود متعلّ قــة بتوريــد الغــاز أويــل أبرمتهــا وزارة الطاقــة والميــاه لصالــح مؤسســة كهربــاء\n لبنــان فــي العــام .2025\nّأمــا طلبــات عــروض األســعار ،فتُ ظهــر مســاهمة ماليــة محــدودة فــي إجمالــي اإلنفــاق مقارنــة بعددهــا المرتفــع\nمــن العمليــات ،مــا يعكــس اســتخدامها أساســاً فــي تلزيــم العقــود ذات القيــم المنخفضــة أو المتوســطة .ويأتــي\nمرتيــن متتاليتيــن ،األولــى خــال عــام 2023ليصــل\n ذلــك فــي ســياق رفــع الســقف المالــي المعتمــد لهــذه الطريقــة ّ"}, {"o": 88, "l": "المادة 2", "b": "إلــى نحــو 55ألــف دوالر أميركــي (المرســوم رقــم 11339تاريــخ ،)2023/5/29والثانيــة خــال عــام 2024ليبلــغ نحــو 165\n ألــف دوالر أميركــي (المرســوم رقــم 14063تاريــخ .)2024/10/3\nأن متوســط قيمــة العقــد ضمــن هــذه المنصــة ّ\n ّ وعلــى الرغــم مــن هــذه التعديــات ،تُ ظهــر البيانــات المسـ ّـجلة علــى\nالفئــة بلــغ نحــو 75ألــف دوالر أميركــي فــي عــام ،2024وارتفــع إلــى حوالــي 282ألــف دوالر أميركــي فــي عــام .2025\n ّ\nالمؤشــر ،مــن زاويــة إحصائيــة بحتــة ،إلــى تجــاوز المتوســط المسـ ّـجل فــي عــام 2025للســقف المالــي ويشــير هــذا\nالمنصــوص عليــه الســتخدام هــذه الطريقــة ،مــن دون أن يســمح ذلــك ،فــي غيــاب تحليــل تفصيلــي لــكل عمليــة،\n بالجــزم بوجــود مخالفــات نظاميــة.\nالتوجــه العــام،\n ّ أن طلبــات عــروض األســعار تبقــى ،مــن حيــث\n وفــي جميــع األحــوال ،تؤكّ ــد القــراءة العامــة للبيانــات ّ\nأداة معتمــدة أساســاً لتلبيــة احتياجــات ذات قيــم أدنــى نســبياً مقارنــة بالمناقصــات العموميــة ،وذلــك بمــا ينســجم\n مــع الغايــة التشــريعية مــن اعتمــاد هــذه اآلليــة.\n وتبقى طلبات االقتراحات للخدمات االستشارية ذات وزن هامشي من حيث القيمة خالل الفترة المدروسة.\n 14ال تشمل أرقام االنفاق قيم العقود الملزّ مة بطريقة المزايدة العمومية\n\f 74\n ِ .3ن َسب توزيع اإلنفاق حسب طريقة الشراء\n جدول :11نسب توزّ ع االنفاق حسب طريقة الشراء (باستثناء المزايدات)\nيبيــن الرســم الخــاص بنِ َســب توزيــع اإلنفــاق حســب طريقــة الشــراء (باســتثناء المزايــدات) الــوزن النســبي لــكل آليــة مــن\n ّ\n ّ\n الموثــق إلكترونيــاً خالل الفتــرة .2025–2022 آليــات التلزيــم فــي إجمالــي اإلنفــاق العــام"}, {"o": 89, "l": "المادة 2", "b": "أن المناقصــات العموميــة تســتحوذ علــى الحصــة األكبــر مــن اإلنفــاق فــي مختلــف الســنوات، وتُ ظهــر البيانــات ّ\nمــا يؤكّ ــد اســتمرارها كاألداة األساســية لتنفيــذ العقــود ذات القيــم المرتفعــة .وفــي المقابــل ،تُ سـ ّـجل االتفاقــات\n الرضائيــة وطلبــات عــروض األســعار نســباً متفاوتــةّ ،\nتتأثــر بشــكل ملحــوظ بوجــود عمليــات اســتراتيجية عاليــة القيمــة\n فــي قطاعــات محـ ّـددة ،وال سـ ّـيما الطاقــة واألمــن.\nوعليــه ،تُ قــرأ هــذه النِّ ســب كمؤشــرات بنيويــة علــى توزيــع أدوات الشــراء ،وليــس كمؤشــر مباشــر علــى مســتوى\nـا إضافيــاً نعالجــه فــي القســم الســادس أدنــاه مــن هــذا الفصــل.\n المنافســة الفعليــة ،التــي تتطلّ ــب بيانــات وتحليـ ً\n التوزع العددي والمالي ّ .4مقارنة بين\nتُ بــرز المقارنــة بيــن التــوزّ ع العــددي والتــوزّ ع المالــي لطــرق الشــراء وجــود فجــوة بنيويــة بيــن عــدد العمليــات وقيمتها،\nبحســب الطريقــة المعتمــدة .ففــي حيــن تهيمــن المناقصــات العموميــة علــى إجمالــي اإلنفــاق ،تتــوزّ ع األعــداد\n بشــكل أكثــر توازنــاً بيــن المناقصــات العموميــة ،وطلبــات عــروض األســعار ،واالتفاقــات الرضائيــة.\nأن اختيــار طريقــة الشــراء يرتبــط بقيمــة العقــد وطبيعــة االحتياجــات ،مــع بقــاء الطــرق ويشــير هــذا التبايــن إلــى ّ\nالتنافســية فــي موقــع الصــدارة مــن حيــث الــوزن المالــي ،بمــا ينســجم مــع أهــداف قانــون الشــراء العــام فــي تعزيــز\n المنافســة والشــفافية.\n .5الشراء عبر الفاتورة كآلية منخفضة القيمة\nإلــى جانــب الطــرق التنافســية واالســتثنائية المشــار إليهــا أعــاه ،تُ سـ َّـجل طريقــة الشــراء عبــر الفاتــورة كإحــدى طــرق"}, {"o": 90, "l": "المادة 2", "b": "والمخصصــة للعمليــات ذات القيمــة المنخفضــة ،بمــا يتيــح للجهــات ّ الشــراء المعتمــدة فــي منظومــة الشــراء العــام،\n\f75\nوتتميــز هــذه\n ّ الشــارية تأميــن احتياجاتهــا التشــغيلية اليوميــة بســرعة ومرونــة ضمــن ســقوف ماليــة محــددة مســبقا\n ً15\nنفــذ بشــكل مباشــر وفــقالطريقــة بكونهــا ال تخضــع إلجــراءات تنافســية مســبقة لــكل عمليــة علــى حــدة ،وإنمــا تُ ّ\n احتياجــات تشــغيلية فوريــة ،مــا يجعلهــا مــن أكثــر أدوات الشــراء مرونــة مــن حيــث التطبيــق.\nومــن الناحيــة التنظيميــة ،يخضــع هــذا النمــط مــن المشــتريات آلليــة شــفافية الحقــة بموجــب المــادة 26مــن قانــون\nالشــراء العــام رقــم ،2021/244التــي تُ لــزم الجهــات الشــارية بنشــر إعــان جامــع دوري يتضمــن جميــع العمليــات\nالمنفــذة عبــر الفاتــورة .وقــد تــم تعزيــز هــذا اإلطــار بموجــب المذكــرة رقــم 2022/6الصــادرة عــن هيئــة الشــراء العــام،\n ّ\nوالتــي حـ ّـددت وتيــرة اإلبــاغ علــى األقــل مرتيــن ســنوياً ،مــع إحالــة هــذه البيانــات إلــى المنصــة اإللكترونيــة المركزيــة،\n بمــا يتيــح تجميعهــا وتحليلهــا علــى مســتوى كلــي.\nوتُ ظهــر البيانــات المتاحــة للفتــرة 2025–2022أن هــذا المســار يبقــى محــدود التغطيــة مــن الناحيــة اإلحصائيــة ،إذ\nبلــغ عــدد الجهــات الشــارية التــي التزمــت باإلبــاغ عــن عمليــات الشــراء عبــر الفاتــورة 47جهــة شــارية فقــط خــال\nالفتــرة المذكــورة ،مــع تســجيل تفــاوت فــي انتظــام اإلبــاغ بيــن الجهــات ،ســواء مــن حيــث تواتــر التقاريــر أو اكتمــال\nالبيانــات .كمــا تعكــس المعطيــات وجــود فجــوات فــي التغطيــة اإلحصائيــة ناجمــة عــن عــدم التــزام بعــض الجهــات"}, {"o": 91, "l": "المادة 2", "b": "باإلفصــاح الــدوري ،إضافــة إلــى تحديــات تقنيــة مرتبطــة بعمليــة رفــع البيانــات علــى المنصــة اإللكترونيــة المركزيــة\n خــال مرحلــة االنتقــال الرقمــي.\nوبالتالــي ،تُ ســتخدم بيانــات الشــراء عبــر الفاتــورة فــي هــذا التقريــر كمؤشــر علــى الحــد األدنــى المبلّ ــغ عنــه مــن\nاإلنفــاق منخفــض القيمــة ،وليــس كتمثيــل شــامل لحجــم هــذه العمليــات الفعليــة ،مــا يســتدعي قراءتهــا ضمــن\nـا لحجــم اإلنفــاق.ســياقها المنهجــي كأداة لقيــاس مســتوى االمتثــال لإلفصــاح الالحــق أكثــر مــن كونهــا مؤشــراً كامـ ً\n .6قراءة في المزايدات العمومية\n جدول :12قيمة المزايدات العمومية (بالدوالر االميركي)\nتُ ظهــر البيانــات المتعلقــة بالمزايــدات العموميــة نمطــاً غيــر مســتقر فــي حجــم هــذا اإلجراء عبر الســنوات المشــمولة\nبالتحليــل .2025-2022فقــد ُسـ ِّـجلت قيمــة إجماليــة للمزايــدات بلغــت نحــو 30مليــون دوالر أميركــي فــي عــام ،2022\nلترتفــع بشــكل ملحــوظ فــي عــام 2023إلــى حوالــي 83مليــون دوالر ،قبــل أن تشــهد تراجعــاً حــاداً فــي عــام 2024\n لتصــل إلــى نحــو 12مليــون دوالر اميركــي ،ثــم تنخفــض أكثــر فــي عــام 2025إلــى حوالــي 7مالييــن دوالر.\n (عدل هذا السقف بالمرسوم رقم 14063تاريخ )2024/10/3\n 15السقف المالي الحالي هو مليار وخمسمائة مليون ليرة لبنانية ّ\n\f 76\nويســتخدم ويعكــس هــذا المســار المتقلّ ــب أن اللجــوء إلــى المزايــدات العموميــة ال يــزال محــدوداً وغيــر منتظــمُ ،\nبشــكل أساســي مــن قبــل وزارة األشــغال العامــة والنقــل (فــي العقــود الكبيــرة) لتلزيــم تأجيــر مســاحات أو خدمــات\nمتعلّ قــة بمطــار رفيــق الحريــري الدولــي (كموقــف الســيارات ،والســوق الحــرة ،واســتثمار مســاحات مخصصــة للبيــع"}, {"o": 92, "l": "المادة 2", "b": "بالمفـ ّـرق) .وقــد ُيعــزى هــذا التفــاوت فــي األرقــام إلــى عوامــل متعــددة ،منهــا:\n المتغيرة لألصول القابلة لالستثمار؛\n ّ •طبيعة االحتياجات\n •الظروف السوقية واالقتصادية المؤثرة على جاذبية المزاد؛\n •مستوى الجهوزية المؤسسية لتفعيل هذا النوع من اإلجراءات ونشر بياناته.\nـراء» بمفهــوم اإلنفــاق العــام ،إال أنهــا ،ولغيــاب النــص التشــريعي الخــاص\n وعلــى الرغــم مــن أن المزايــدات ال تُ عـ ّـد «شـ ً\nـا بمذكــرات هيئــة الشــراء العــام ذات الصلــة ،لمبــادئ القانــون ذاتــه وإجراءاتــه ،لضمــان الشــفافية بهــا ،تخضــع ،عمـ ً\n والمنافســة فــي عمليــات بيــع أو إيجــار األصــول العامــة.\n مالحظة منهجية\n تُ قــرأ مؤشــرات المزايــدات فــي هــذا القســم كوصــف التجاهــات عامــة ،مــع اإلشــارة إلــى أن بعــض العقــود قــد ال\n تتضمــن قيمــاً نهائيــة معلنــة ،ممــا يســتدعي حــذراً فــي تعميــم االســتنتاجات .وبوجــه عــام ،تشــير هــذه المؤشــرات\n إلــى أن المزايــدات العموميــة تشــكّ ل أداة قائمــة ضمــن منظومــة الشــراء العــام ،لكنهــا ال تــزال تُ ســتخدم بشــكل\n انتقائــي ،مــا قــد يســتدعي فــي المراحــل الالحقــة مــن اإلصــاح مراجعــة اإلطــار الناظــم لضمــان اتســاق إجرائــي أكبــر\n مــع طبيعــة هــذه العمليــات وخصوصيتهــا.\n للتوجهات العامة ّ .7قراءة أولية\nتوجهــاً واضحــاً نحــو تكريــس الطــرق التنافســية ،وال سـ ّـيما المناقصــات العموميــة،بصــورة عامــة ،تُ ظهــر البيانــات ّ\nكأداة رئيســية للشــراء العــام مــن حيــث القيمــة ،وهــو مــا ينســجم مــع أهــداف قانــون الشــراء العــام الراميــة إلــى\nتعزيــز المنافســة والشــفافية .وفــي الوقــت نفســه ،يعكــس االرتفــاع العــددي لطلبــات عــروض األســعار واالتفاقــات"}, {"o": 93, "l": "المادة 2", "b": "تنوعــاً فــي أدوات الشــراء المســتخدمة ،يرتبــط بطبيعــة االحتياجــات ،وحجــم المشــاريع ،والظــروف الرضائيــة ّ\n التشــغيلية التــي تواجههــا الجهــات الشــارية.\n ال ينبغــي قــراءة ارتفــاع نســبة أو قيمــة االتفاقيــات الرضائيــة فــي البيانــات المنشــورة بمعــزل عــن الســياق القانونــي\n والطبيعــة القطاعيــة للمشــتريات .فوجــود صفقــات اســتراتيجية عاليــة القيمــة بيــن جهــات عامــة ،أو مرتبطــة بقطــاع\n يفســر جــزءاً كبيــراً مــن التوزيــع المالــي غيــر المتجانــس ،ويؤكــد أن هــذه األرقــام تعكــس\n حيــوي كالطاقــة واألمــنّ ،\n واقعــاً مؤسســياً وقانونيــاً محــدداً أكثــر مــن كونهــا مؤشــراً علــى ضعــف المنافســة النظاميــة.\n .IVتحليل الجهات الشارية\nيهــدف هــذا القســم إلــى تحليــل دور الجهــات الشــارية فــي منظومــة الشــراء العــام ،مــن حيــث مســتوى النشــاط،\nالمنفــذة ،وذلــك اســتناداً إلــى البيانــات المنشــورة علــى منصــة هيئــة الشــراء\n ّ وحجــم اإلنفــاق ،وطبيعــة العمليــات\nويســهم هــذا التحليــل فــي إبــراز مــدى تفاعــل الجهــات المختلفــة مــع متطلبــات العــام خــال الفتــرة ُ .2025–2022\n النشــر والتلزيــم ،ورصــد مســتوى االندمــاج فــي النظــام.\n نشاطا من حيث عدد العمليات ً .1الجهات األكثر\nيعــرض هــذا القســم الجهــات الشــارية األكثــر نشــاطاً علــى منصــة هيئــة الشــراء العــام مــن حيــث عــدد العقــود\nالمنصــة وانتشــارها بيــن مختلــف اإلدارات\n ّ الملزّ مــة خــال الفتــرة ،2025–2022بمــا يتيــح تقييــم مســتوى اســتخدام\n والمؤسســات العامــة ،بغـ ّـض النظــر عــن القيمــة الماليــة للعقــود.\n\f77\n جدول :13توزّ ع أعداد العقود الملزّ مة بحسب فئات الجهات الشارية بين 2025 - 2022"}, {"o": 94, "l": "المادة 2", "b": "يظهــر الرســم البيانــي أعــاه ان فئــات واســعة مــن الجهــات الشــارية تســتخدم المنصــة االلكترونيــة لــدى هيئــة\nالشــراء العــام لنشــر المعلومــات حــول عملياتهــا الشــرائية .وتشــمل هــذه الفئــات البلديــات واتحاداتهــا ،اإلدارات\nوالمؤسســات العامــة ،شــركتي الخليــوي ،المجالــس ،المستشــفيات الحكوميــة ،مصــرف لبنــان ،الجامعــة اللبنانيــة،\n المصالــح المســتقلة ،وغيرهــا مــن الجهــات.\nكمــا تُ بــرز البيانــات تفاوتــاً ملحوظــاً فــي عــدد العقــود الملزّ مــة بيــن هــذه الجهــات ،حيــث تسـ ّـجل بعــض الجهــات عــدداً\n مرتفعــاً مــن العمليــات مقارنــة بغيرهــا.\n جدول :14الجهات الشارية األكثر نشاطاً من حيث عدد العقود الملزّ مة 2025 - 2022\n\f 78\n جدول :15نسبة عقود الجهات الشارية األكثر نشاطاً من اجمالي العقود الملزّ مة\nتعكــس هــذه النتائــج تفاوتــاً واضحــاً فــي مســتوى النشــاط العــددي بيــن الجهــات الشــارية ،حيــث يتركّ ــز عــدد كبيــر\nمــن العمليــات لــدى عــدد محــدود مــن الجهــات ،فــي حيــن يظــل حضــور عــدد كبيــر مــن الجهــات األخــرى محــدوداً أو\n فســر هــذا التفــاوت بعــدة عوامــل ،أبرزهــا:\n وي َّ\n متقطعــاًُ .\n ّ\n المنّفذة للمشاريع\n ّ سّيما الجهات\n • اختالف حجم المهام التشغيلية الموكلة إلى الجهات الشارية ،وال ّ\n والبنى التحتية أو الجهات ذات الطابع الخدماتي المستمر؛\n تخّول بعض الجهات تنفيذ عدد كبير من اإلجراءات• طبيعة الصالحيات القانونية والمؤسسية ،التي ّ\n متكّررة؛\n ّ الشرائية بصورة\n • الموازنات واختالف حجمها بين الجهات الشارية؛\n المنّصة اإللكترونية وإدخال البيانات.\n ّ • تفاوت درجات الجهوزية المؤسسية والقدرات اإلدارية في استخدام"}, {"o": 95, "l": "المادة 2", "b": "أّن الجهــات ذات الطابــع التشــغيلي أو االســتثماري (كاألشــغال العامــة ،االتصــاالت ،البنــى التحتيــة، كمــا ُُيالحــظ ّ\nواألمــن) تسـ ّـّجل عــددًاً مرتفعــًاً مــن العمليــات ،وهــو مــا يعكــس كثافــة نشــاطها اإلجرائــي أكثــر مما يعكــس بالضرورة\n حجــم اإلنفــاق المرتبــط بهــا.\n مالحظة منهجية\n معينــة ال ُيعـ ّـد بحـ ّـد ذاتــه مؤشــراً علــى حجــم\n أن ارتفــاع عــدد العمليــات لــدى جهــة شــارية ّ\n مــن المهــم اإلشــارة إلــى ّ\n اإلنفــاق أو علــى مســتوى المخاطــر أو األداء المالــي ،بــل يعكــس فــي المقــام األول كثافــة االســتخدام اإلجرائــي\n ألدوات الشــراء العــام .وعليــه ،ينبغــي قــراءة هــذا المؤشــر بالتكامــل مــع التحليــل المالــي الــوارد فــي القســم الالحــق،\n وال سـ ّـيما تــوزّ ع اإلنفــاق حســب الجهــات الشــارية.\n يظــل متركّ ــزاً\n ّ منصــة الشــراء العــام\n أن اســتخدام ّ\n ُيظهــر تحليــل الجهــات األكثــر نشــاطاً مــن حيــث عــدد العمليــات ّ\n لــدى عــدد محــدود مــن الجهــات ذات األدوار التشــغيلية المركزيــة ،مــا يعكــس تفاوتــاً مؤسســياً طبيعيــاً فــي حجــم\n النشــاط ،ويؤكّ ــد فــي الوقــت نفســه الحاجــة إلــى توســيع قاعــدة االســتخدام وتعزيــز قــدرات الجهــات األقــل حضــوراً\n المنصــة.\n ّ علــى\n\f79\n تركز اإلنفاق العام ّ .2\nينتقــل التحليــل فــي هــذا القســم مــن البعــد العــددي إلــى البعــد المالــي ،عبــر دراســة توزيــع اإلنفــاق العــام 16بيــن\nالجهــات الشــارية ،وتحديــد الجهــات والقطاعــات التــي تســتحوذ علــى الحصــة األكبــر مــن إجمالــي قيمــة العقــود\n الملزّ مــة والمنشــورة علــى المنصــة.\n جدول :16أكبر 5جهات شارية من حيث االنفاق (بالدوالر االميركي) 2022/12/31-2022/8/1"}, {"o": 96, "l": "المادة 2", "b": "جدول :17أكبر 5جهات شارية من حيث االنفاق (بالدوالر االميركي) 2023\n 16باستثناء عمليات المزايدات العمومية\n\f 80\nجدول :18أكبر 5جهات شارية من حيث االنفاق (بالدوالر االميركي) 2024\nجدول :19أكبر 5جهات شارية من حيث االنفاق (بالدوالر االميركي) 2025\n جدول :20تركّ ز االنفاق في قطاعات خمس أساسية\n\f81\n جدول :21توزّ ع االنفاق على القطاعات الخمس الكبرى (تفصيل نسبة ال )%75\nأن توزيــع اإلنفــاق أكثــر تركّ ــزاً مــن توزيــع عــدد العمليــات ،إذ تســتحوذ جهــات محـ ّـددة علــى نســبة\n تُ ظهــر البيانــات ّ\nمرتفعــة مــن إجمالــي القيمــة الماليــة للعقــود .ويعــود ذلــك إلــى طبيعــة المهــام الموكلــة إلــى هــذه الجهــات ،وال\n نفــذ عقــود اســتراتيجية وكبيــرة الحجــم.\n سـ ّـيما فــي القطاعــات ذات الكلفــة العاليــة ،حيــث تُ ّ\n وعلى المستوى القطاعي ،يتركّ ز اإلنفاق بصورة أساسية في القطاعات التالية:\n •الطاقة؛\n •األمن والدفاع؛\n •الصحة؛\n •االتصاالت؛\n •األشغال العامة.\nويعكــس هــذا التوزيــع البنيــة الوظيفيــة للدولــة وأولوياتهــا التشــغيلية واالســتراتيجية ،أكثــر ممــا يعكــس خيــارات\n إجرائيــة للجهــات الشــارية.\nيعكــس تفــاوت نشــاط الجهــات الشــارية ،ســواء مــن حيــث عــدد العمليــات أو حجــم اإلنفــاق ،اختــاف األدوار\n بحــد ذاتــه مؤشــراً علــى اختــال فــي منظومــة الشــراء العــام.\n ّ عــد\n والقــدرات المؤسســية والوظيفيــة ،وال ُي ّ\n .Vتحليل االنفاق حسب نوع العقد\n ّ\nالموثــق إلكترونيــاً بحســب الفئــات األساســية ألنــواع العقــود، يركّ ــز هــذا القســم علــى تحليــل توزيــع اإلنفــاق العــام\nبهــدف فهــم البنيــة الهيكليــة لإلنفــاق كمــا تعكســها بيانــات منصــة هيئــة الشــراء العــام خــال الفتــرة .2025–2022"}, {"o": 97, "l": "المادة 2", "b": "ـا أساســياً لفهــم أولويــات اإلنفــاق العــام ،وطبيعــة الحاجــات التــي تُ ّلبــى عبــر منظومــة\n ويشــكّ ل هــذا التحليــل مدخـ ً ُ\n معينــة مــن العقــود.\n الشــراء العــام ،ومــدى تنـ ّـوع أو تركّ ــز النشــاط الشــرائي فــي فئــات ّ\n\f 82\nويســتند التحليــل إلــى التصنيــف المعيــاري ألنــواع العقــود المعتمــد فــي قانــون الشــراء العــام والمنصــة اإللكترونيــة،\nوالــذي يشــمل أربــع فئــات رئيســية :عقــود األشــغال ،عقــود اللــوازم ،عقــود الخدمــات غيــر االستشــارية ،وعقــود\n الخدمــات االستشــارية.\n مالحظة منهجية\n المدخلــة فــي حقــل «نــوع العقــد» علــى المنصــة اإللكترونيــة .وفــي الحــاالت\n يعتمــد هــذا التصنيــف علــى المعطيــات ُ\n دقــة ،جــرى االســتناد إلــى وصــف موضــوع العقــد الســتنباط الفئــة\n التــي يغيــب فيهــا هــذا الحقــل أو تظهــر فيــه عــدم ّ\n دقــة أقــل ،مــن دون أن ّ\n يؤثــر ذلــك األقــرب .وعليــهُ ،يحتمــل أن تكــون نســبة محــدودة مــن العقــود مصنّ فــة بدرجــة ّ\n علــى االتجاهــات العامــة المســتخلصة.\n ّ\n التوزع العددي للعقود حسب النوع .1\n جدول :22توزّ ع العقود الملزّ مة بين 2025 - 2022\nُيظهــر الرســم البيانــي الخــاص بتــوزّ ع عــدد العقــود الملزّ مــة حســب نــوع العقــد خــال الفتــرة 2025–2022هيمنــة\n عقــود األشــغال مــن حيــث العــدد ،إذ ّ\nتمثــل نحــو %45مــن مجمــل العقــود الملزّ مــة .وتأتــي بعدهــا عقــود الخدمــات\n غيــر االستشــارية بنســبة تقــارب %34مــن إجمالــي عــدد العقــود.\nفــي المقابــل ،تبقــى عقــود الخدمــات االستشــارية محــدودة جــداً مــن حيــث العــدد ،إذ ال تتجــاوز نســبتها نحــو %2"}, {"o": 98, "l": "المادة 2", "b": "مــن مجمــل العقــود ،مــا يعكــس اســتخداماً انتقائيــاً ومحــدوداً لهــذا النــوع مــن العقــود خــال الفتــرة التــي يغطيهــا\n التقريــر ،ويرتبــط بطبيعــة الحاجــات االستشــارية المحـ ّـددة.\nأمــا عقــود اللــوازم ،فتسـ ّـجل حضــوراً متوســطاً مــن حيــث العــدد مقارنـ ًـة باألشــغال والخدمــات غيــر االستشــارية ،مــا\n يعكــس توازنــاً نســبياً بيــن الطابــع المتكــرر لهــذه العقــود وحجمهــا المالــي المتفــاوت.\n\f83\n ّ .2\n توزع االنفاق حسب النوع\n جدول :23توزّ ع االنفاق بالدوالر االميركي بين 2025-2022\nعلــى المســتوى المالــيُ ،يظهــر توزيــع اإلنفــاق حســب نــوع العقــد تباينــاً واضحــاً بيــن الــوزن العــددي والــوزن المالــي\n لبعــض فئــات العقــود ،وال سـ ّـيما بيــن اللــوازم واألشــغال والخدمــات.\n الحصــة األكبــر مــن إجمالــي اإلنفــاق العــام المنشــور ،إذ ّ\nتمثــل نحــو %44مــن القيمــة ّ تســتحوذ عقــود اللــوازم علــى\n مــة علــى عقــود األشــغال التــي ّ\nتمثــل نحــو %41مــن إجمالــي متقد ً\n ّ اإلجماليــة للعقــود خــال الفتــرة المدروســة،\nاإلنفــاق .ويعكــس هــذا التوزيــع الطبيعــة الماليــة المرتفعــة لعقــود اللــوازم ،وال سـ ّـيما فــي القطاعــات الحيويــة التــي\n تتطلّ ــب تجهيــزات ومســتلزمات ذات كلفــة عاليــة.\nفــي المقابــل ،وعلــى الرغــم مــن العــدد المرتفــع لعقــود الخدمــات غيــر االستشــارية ،فــإن وزنهــا المالــي يبقــى أقــل\nأن هــذا النــوع مــن العقــود يتّ ســم ،فــي المتوســط ،بقيــم ماليــة أدنــى مقارنـ ًـة بعقــود اللــوازم\n نســبياً ،مــا يشــير إلــى ّ\n واألشــغال.\nأمــا عقــود الخدمــات االستشــارية ،فتبقــى ذات وزن هامشــي مــن حيــث القيمــة الماليــة خــال الفتــرة المدروســة،"}, {"o": 99, "l": "المادة 2", "b": "متخصصــة ومحـ ّـددة.ّ بمــا يعكــس محدوديــة اللجــوء إليهــا وحصــر اســتخدامها فــي مجــاالت\n التوزع العددي والمالي ّ .3مقارنة بين\nتُ بــرز المقارنــة بيــن التــوزّ ع العــددي والتــوزّ ع المالــي ألنــواع العقــود وجــود فجــوة بنيويــة واضحــة بيــن عــدد العمليــات\nوقيمتهــا الماليــة ،تبعــاً لنــوع العقــد .ففــي حيــن تتصـ ّـدر عقــود األشــغال مــن حيــث عــدد العقــود الملزّ مــة ،تســتحوذ\n الحصــة األكبــر مــن إجمالــي اإلنفــاق.\n ّ عقــود اللــوازم علــى\nأن كثافــة االســتخدام اإلجرائــي لبعــض أنــواع العقــود (كاألشــغال والخدمــات غيــر ويشــير هــذا التبايــن إلــى ّ\nاالستشــارية) ال تترافــق بالضــرورة مــع الــوزن المالــي األكبــر ،فــي حيــن ترتبــط عقــود أخــرى بعــدد أقــل مــن العمليــات\nلكــن بقيــم ماليــة مرتفعــة .ويعكــس ذلــك اختالفــاً جوهريــاً فــي طبيعــة الحاجــات التــي تُ ّلبــى عبــر كل نــوع مــن\n العقــود ،وفــي دور كل فئــة ضمــن هيــكل اإلنفــاق العــام.\nوتُ ظهــر هــذه المعطيــات ّأن تحليــل اإلنفــاق العــام ال يمكــن أن يقتصــر علــى عــدد العمليــات وحــده ،بــل يتطلّ ــب قــراءة\nوتوجهاتــه الفعليــة.\n ّ أدق لطبيعــة النشــاط الشــرائي\n متكاملــة تجمــع بيــن البعديــن العــددي والمالــي ،بمــا يســمح بفهــم ّ\n\f 84\n .VIتحليل المنافسة والمشاركة في عمليات الشراء العام\nيهــدف هــذا القســم إلــى تقديــم قــراءة تحليليــة لمســتوى المنافســة فــي منظومــة الشــراء العــام ،اســتناداً إلــى\nالبيانــات المتاحــة علــى المنصــة االلكترونيــة لــدى هيئــة الشــراء العــام خــال الفتــرة .2025–2022وبســبب عــدم توافــر"}, {"o": 100, "l": "المادة 2", "b": "ســيما فــي المراحــل األولــى مــن تشــغيل بيانــات تفصيليــة حــول عــدد العارضيــن المشــاركين فــي كل عمليــة (ال ّ\nالتوجــه اإلجرائــي نحو اآلليات التنافســية أو االســتثنائية،\n ّ المنصــة) ،يعتمــد هــذا التحليــل علــى مؤشــرات بديلــة تعكــس\n وذلــك عبــر:\n •وزن المناقصات العمومية مقارنة بطرق الشراء األخرى؛\n المبرر له؛\n ّ تطور اللجوء إلى االتفاق الرضائي والسياق القانوني\n • ّ\n •دالالت هذه األنماط في مسار إصالح الشراء العام.\nوتُ قــرأ النتائــج الــواردة فــي هــذا القســم كمؤشــرات اتجاهيــة تعكــس هيكليــة اإلجــراءات المعتمــدة ،وليــس كتقييــم\n ـا نوعيــاً.\n ـا وتحليـ ً\n لمســتوى المنافســة الفعليــة فــي الســوق ،الــذي يتطلّ ــب بيانــات أكثــر تفصيـ ً\n .1وزن المناقصة العمومية مقابل الطرق األخرى\n جدول :24التوزّ ع العددي لطرق الشراء\n\f85\n جدول :25نسب توزّ ع االنفاق حسب طريقة الشراء (باستثناء المزايدات)\nأن المناقصــة العموميــة ،رغــم كونهــا الطريقــة األكثــر التزامــاً بمبــادئ المنافســة والشــفافية ،ال تــزال\n تُ ظهــر البيانــات ّ\nتشــكّ ل نســبة محــدودة مــن حيــث العــدد مقارنـ ًـة بطــرق أخــرى كطلــب عــروض األســعار أو االتفــاق الرضائــي ،وال\nسـ ّـيما لــدى الجهــات ذات النشــاط التشــغيلي المرتفــع .فــي المقابــل ،ترتفــع مســاهمة المناقصــة العموميــة بشــكل\nملحــوظ مــن حيــث القيمــة الماليــة ،مــا يعكــس اســتخدامها أساســاً فــي العقــود ذات القيــم المرتفعــة ،وال سـ ّـيما\n فــي القطاعــات االســتراتيجية كالطاقــة ،واألشــغال العامــة ،والدفــاع.\nمبســطة للعقــود ذات القيــم\n ويفهــم هــذا التبايــن فــي ضــوء طبيعــة العمليــات ،إذ تميــل الجهــات إلــى اعتمــاد طــرق ّ ُ"}, {"o": 101, "l": "المادة 2", "b": "المنخفضــة أو الطابــع المتكــرر ،فــي حيــن ُيلجــأ إلــى المناقصــة العموميــة عنــد تنفيــذ مشــاريع كبــرى أو عقــود ذات\n أثــر مالــي وتنفيــذي مرتفــع.\n تطور اللجوء إلى االتفاق الرضائي :السياق القانوني واالستثنائي ّ .2\nالمنفــذة بطريقــة االتفــاق الرضائــي\n ّ تبيــن الرســوم البيانيــة فــي الفقــرة الســابقة ،فقــد سـ ّـجل عــدد العمليــات\n كمــا ّ\nارتفاعــاً ملحوظــاً فــي عــام ،2025حيــث اقتــرب مــن عــدد المناقصــات العموميــة مــن حيــث العــدد .كذلــك سـ ّـجل\nأن القــراءة الســياقية للبيانــات تكشــف\n االنفــاق عــن طريــق االتفاقــات الرضائيــة ارتفاعــاً فــي عامــي 2024و .2025إال ّ\n أن هــذا االرتفــاع يعكــس عوامــل محــددة ،أبرزهــا: ّ\n أ .اإلطار القانوني المسموح به\n محددة ،منها:\n ّ يجيز قانون الشراء العام النافذ اللجوء إلى االتفاق الرضائي في حاالت استثنائية\n •الشراء بين أشخاص القانون العام (المادة ،46الفقرة )5؛\n المبررة (المادة ،46الفقرة )2؛\n ّ •الظروف الطارئة\n\f 86\n ب .الحاالت االستراتيجية عالية القيمة\nيعــود جــزء كبيــر مــن االرتفــاع المالــي لالتفاقــات الرضائيــة فــي 2025–2024إلــى عمليــات شــراء ذات طابــع\n اســتراتيجي ،منهــا:\n • عقود توريد البنزين والمازوت األخضر بين وزارة الدفاع الوطني ووزارة الطاقة والمياه ،لصالح الجيش\n اللبناني والمديرية العامة لألمن العام (تشرين األول 2024وتشرين األول )2025؛\n • عقود توريد الغاز أويل من قبل وزارة الطاقة والمياه لصالح مؤسسة كهرباء لبنان (.)2025\n وتندرج هذه العمليات ضمن اإلطار القانوني المسموح به قانوناً.\nأمــا إذا مــا اســتثنينا ،ألهــداف احصائيــة بحتــة ،عقــود توريــد الطاقــة االســتراتيجية مــن العــام 2024و ،2025فتصبــح\n نســب تــوزّ ع االنفــاق كالتالــي:"}, {"o": 102, "l": "المادة 2", "b": "جدول :26نسب توزّ ع االنفاق حسب طريقة الشراء (باستثناء المزايدات وعقود توريد الطاقة االستراتيجية)\n ج .الظروف االستثنائية في أواخر 2024\nّأدت التطــورات األمنيــة واإلنســانية التــي شــهدها لبنــان فــي الربــع األخيــر مــن عــام 2024إلــى لجــوء بعــض\nالجهــات الشــارية إلــى االتفاقــات الرضائيــة لتلبيــة حاجــات إغاثيــة وعاجلــة ،وذلــك اســتناداً إلــى مذكــرة هيئــة\nالشــراء العــام رقــم /٨ه.ش.ع ٢٠٢٤/تاريــخ 30ايلــول .2024وقــد تـ ّـم نشــر هــذه العقــود علــى المنصــة فــي الربــع\n يفســر جزئيــاً االرتفــاع العــددي المسـ ّـجل فــي هــذا العــام.\n األول مــن عــام ،2025مــا ّ\n جدول :27العقود الملزّ مة بين 2025-2022\n\f87\nأمــا نســب العقــود الملزّ مــة بطــرق تنافســية مقارنــة مــع العقــود الملزّ مــة رضائيــاً علــى كامــل الفتــرة الزمنيــة التــي\n يغطيهــا التقريــر ،فهــي تتــوزّ ع علــى الشــكل االتــي %70 :بطــرق تنافســية %30بطــرق غيــر تنافســية.\n ً\nـتجابة لظــروف اســتثنائية توجهــاً هيكليــاً بعيــداً عــن المنافســة ،بــل اسـ\n ال يعكــس ارتفــاع عــدد االتفاقــات الرضائيــة ّ\nوإطــار قانونــي مــرن .وتُ قــرأ هــذه البيانــات فــي ســياقها المؤسســي ،وليــس كمؤشــر علــى تراجــع مبــدأ المنافســة.\n .3دالالت أنماط االستخدام في سياق إصالح الشراء العام\n ّ\nمؤشــرات أوليــة علــى مســار تطبيــق قانــون الشــراء العــام، تشــكّ ل األنمــاط اإلجرائيــة المرصــودة فــي هــذا القســم\n ويمكــن اســتخالص الــدالالت التاليــة:\n أ .اتجاه إيجابي نحو تكريس المنافسة في العقود الكبرى\n • هيمنة المناقصة العمومية على القيمة المالية لإلنفاق تعكس التزامًاً نسبيًاً بمبدأ المنافسة في\n المشتريات ذات األثر المالي المرتفع؛"}, {"o": 103, "l": "المادة 2", "b": "توّسع قاعدة الجهات الشارية التي تعتمد • النمو التصاعدي في عدد المناقصات المنشورة يشير إلى ّ\n اآلليات التنافسية.\n ب .مرونة النظام في االستجابة للظروف االستثنائية\n التكّيف مع الحاجات الطارئة،\n ّ • استخدام االتفاق الرضائي في حاالت محددة يعكس قدرة النظام على\n دون الخروج عن اإلطار القانوني؛\n • نشر هذه العقود على المنصة ،حتى لو كانت رضائية ،يعزّ ز مبدأ الشفافية والتوثيق اإللكتروني.\n ج .فجوة بين اإلجراءات التنافسية والمنافسة الفعلية\n • ال تسمح البيانات المتاحة حالياً بقياس مستوى المنافسة الفعلية (عدد العارضين ،جودة العروض ،إلخ)؛\n نفذ مناقصة عمومية إجرائياً دون ضمان منافسة فعلية في السوق ،والعكس صحيح. • قد تُ َّ\n د.حاجة إلى مؤشرات أكثر دقة لقياس المنافسة\n الموّردين ،معدالت إعادة النشر،\n ّ تنّوع\n • يتطّلّ ب التقييم النوعي للمنافسة بيانات حول :عدد العارضينّ ،\n ومستوى المشاركة القطاعية؛\n توقع أن يسهم تحديث المنصة اإللكترونية الذي جرى في منتصف العام 2025في تحسين جودة • ُي ّ\n مستقبال.\n ً هذه المؤشرات\nالمحقــق فــي مســار إصــاح الشــراء العــام ،كمــا تكشــف فــي\n ّ تعكــس أنمــاط توزيــع طــرق الشــراء مســتوى التقـ ّـدم\nالمنصــة اإللكترونيــة\n ّ توســع فعلــي فــي اســتخدامالوقــت نفســه عــن التحديــات المتبقيــة .فمــن جهــةُ ،يسـ َّـجل ّ\n المنظــم.\n ّ ـدل علــى انتقــال تدريجــي مــن منطــق االســتثناء إلــى منطــق اإلجــراء\n وتنـ ّـوع فــي أدوات الشــراء ،بمــا يـ ّ\nأن اإلصــاح\n ومــن جهــة أخــرىُ ،يظهــر اســتمرار االعتمــاد النســبي علــى الطــرق غيــر التنافســية أو شــبه التنافســية ّ\n ال يــزال فــي مرحلــة ترســيخ ،ويتأثــر بعوامــل مؤسســية وبشــرية وتنظيميــة ،مــن أبرزهــا:\n •تفاوت القدرات بين الجهات الشارية؛\n •محدودية الخبرة التطبيقية في إعداد دفاتر شروط تنافسية؛"}, {"o": 104, "l": "المادة 2", "b": "•االعتبارات الزمنية والضغوط التشغيلية.\nوعليــه ،فــإن قــراءة هــذه األنمــاط يجــب أن تتــم فــي إطــار ديناميكــي ،يربــط بيــن تطـ ّـور الســلوك اإلجرائــي للجهــات\n وبيــن مســار بنــاء القــدرات وتعزيــز الحوكمــة.\n\f 88\n .4قراءة حذرة دون افتراض منافسة فعلية\nأن تصنيــف طريقــة الشــراء بحـ ّـد ذاتــه ال يكفــي الســتنتاج مســتوى المنافســة الفعليــة.\n مــن المهــم التأكيــد علــى ّ\nفالمناقصــة العموميــة ،رغــم طابعهــا التنافســي نظريــاً ،قــد تشــهد فــي الممارســة مشــاركة محــدودة أو عرضــاً\n واحــداً فقــط ،فــي حيــن قــد تتيــح بعــض اإلجــراءات األخــرى درجــة مــن المنافســة الفعليــة ضمــن نطــاق أضيــق.\nوعليــه ،ينبغــي التمييــز بيــن اإلجــراء التنافســي (مثــل المناقصــة العموميــة) والمنافســة الفعليــة فــي الســوق،\n وذلــك لألســباب المنهجيــة التاليــة:\n • عدم توافر بيانات عدد العارضين :ال تسمح المنصة حاليًاً باستخراج عدد العارضين المشاركين في كل\n سّيما في العقود المنشورة قبل حزيران ،2025ما يحول دون قياس مستوى المشاركة الفعلية. عملية ،وال ّ\n يتقّدم لها سوى\n ّ • احتمال «العرض الوحيد» في المناقصات :قد ُتُ علن مناقصة عمومية إجرائيًاً ،لكن ال\n عارض واحد ،ما يقّلّ ل من أثر المنافسة على السعر والجودة.\n معّينة :في قطاعات مثل الطاقة أو االتصاالت ،قد يكون عدد ّ • تأثير ترّكّ ز السوق في قطاعات\n يحّد من المنافسة الفعلية حتى في إطار مناقصة عمومية. الموّردين المؤهلين محدودًاً هيكليًاً ،ما ّ\n ّ\n • جودة البيانات وتجانسها :تفاوت مستوى إدخال البيانات بين الجهات الشارية قد ّ\n يؤّثر على دقة\n المؤشرات المستخلصة.\nويبــرز هــذا األمــر الحاجــة ،فــي المراحــل الالحقــة مــن اإلصــاح ،إلــى تطويــر مؤشــرات نوعيــة إضافيــة لقيــاس"}, {"o": 105, "l": "المادة 2", "b": "المنافســة ،تتجــاوز مجــرد تصنيــف طريقــة الشــراء ،وتســتند إلــى بيانــات أعمــق حــول المشــاركة وســلوك الســوق.\n ـاال تدريجيــاً نحــو إجــراءات\n أن منظومــة الشــراء العــام فــي لبنــان تشــهد انتقـ ً\n تُ ظهــر أنمــاط اســتخدام طــرق الشــراء ّ\n أن ترســيخ المنافســة الفعليــة ال يــزال يتطلّ ــب تعزيــز القــدرات المؤسســية، أكثــر تنظيمــاً وشــفافية ،غيــر ّ\n الفعالــة لمبــادئ القانــون.ّ وتحســين جــودة اإلعــداد ،واالنتقــال مــن االمتثــال الشــكلي إلــى الممارســة\n .VIIالتحليل المالي والمؤشرات األولية للقيمة مقابل المال\nيهــدف هــذا القســم إلــى تقديــم قــراءة ماليــة أوليــة لعمليــات الشــراء العــام المنشــورة علــى منصــة هيئــة الشــراء\nالعــام ،مــن خــال تحليــل متوســطات القيــم الماليــة للعقــود ،والفروقــات بيــن طــرق الشــراء ،وتطـ ّـور هيــكل اإلنفــاق\n خــال الفتــرة .2025–2022\nوال يســعى هــذا التحليــل إلــى تقييــم شــامل لمســتوى «القيمــة مقابــل المــال» ،بقــدر مــا يهــدف إلــى اســتخالص\nمؤشــرات كميــة أوليــة تســاعد علــى فهــم االتجاهــات العامــة فــي اإلنفــاق العــام ،مــع اإلقــرار الصريــح بالقيــود\n ســيما غيــاب مؤشــرات المنافســة والتنفيــذ الفعلــي. المرتبطــة بطبيعــة البيانــات المتاحــة ،وال ّ\n\f89\n .1متوسط قيمة العقد\n أ .المعدالت العامة\n جدول :28متوسط قيمة العقد (بالدوالر االميركي)\nُيظهــر تحليــل متوســط قيمــة العقــد تطـ ّـوراً ملحوظــاً خــال الفتــرة التــي يغطيهــا التقريــر ،حيــث ارتفــع المعـ ّـدل\nيتبيــن مــن الرســم البيانــي\n ـداء مــن عــام ،2024كمــا ّ العــام لقيمــة العقــود الملزّ مــة بشــكل واضــح ،وال سـ ّـيما ابتـ ً\n ويعــزى هــذا االرتفــاع إلــى مجموعــة عوامــل متداخلــة ،أبرزهــا: أعــاهُ ."}, {"o": 106, "l": "المادة 2", "b": "• استقرار سعر صرف الليرة اللبنانية وما رافقه من إعادة إطالق تدريجية لعمليات الشراء العام؛\n • عودة تنفيذ عقود ذات طابع استثماري أو استراتيجي بعد مرحلة طويلة من االنكماش الحاد؛\n ً\n مقارنًة بالسنوات األولى التي طغت عليها عقود • إدراج عمليات شراء ذات قيم أعلى ضمن المنصة،\n تشغيلية صغيرة أو متوسطة الحجم.\n ب .الفروقات بين طرق الشراء\n جدول :29متوسط قيمة العقد (بالدوالر االميركي)\n\f 90\n تُ ظهر البيانات تفاوتاً واضحاً في متوسط قيمة العقد بين طرق الشراء المختلفة ،حيث:\n تسّجل المناقصة العمومية أعلى متوسطات من حيث القيمة ،نظرًاً الرتباطها بعقود كبيرة الحجم أو ّ • \n ذات طابع استراتيجي؛\n المحّددة\n ّ • تأتي طلبات عروض األسعار بمتوسطات أدنى نسبيًاً ،بما ينسجم مع السقوف المالية\n معّينة؛\n قانونًاً ،رغم تسجيل بعض االنحرافات في سنوات ّ\n يسّجل االتفاق الرضائي تباينًاً ملحوظًاً في متوسطات القيم ،ما يعكس اختالف السياقات القانونية ّ • \n والتشغيلية التي ُُيلجأ فيها إلى هذه الطريقة.\nأن اختيــار طريقــة الشــراء يرتبــط ،فــي جــزء كبيــر منــه ،بحجــم العقــد وطبيعتــه ،أكثــر ممــاويؤكّ ــد هــذا التفــاوت ّ\n يرتبــط بعوامــل إجرائيــة بحتــة.\n .2الفروقات المالية بين اإلجراءات\n أ .اإلجراءات التنافسية مقابل غير التنافسية\nأن اإلجــراءات التنافســية ،وال سـ ّـيما المناقصــة العموميــة ،ترتبــط فــي المتوســط بعقــود ذات يبيــن التحليــل ّ\n ّ\nأن هــذا الفــارق ال يمكــن تفســيره\n ّ ـرـ غي ـس. ـ التناف ـدودةـ المح أو ـيةـ التنافس ـرـ غي ـراءاتـ باإلج ـةـ مقارن ـىـ أعل ـمـ قي\n حصــراً مــن زاويــة الكفــاءة أو مســتوى المنافســة ،بــل يرتبــط أساســاً بـــ:\n الممولة؛\n ّ •طبيعة المشاريع\n •حجم االلتزامات التقنية والمالية؛\n •مستوى المخاطر المرتبطة بالتنفيذ."}, {"o": 107, "l": "المادة 2", "b": "وعليــه ،ال يمكــن اعتبــار ارتفــاع القيــم الماليــة فــي اإلجــراءات التنافســية مؤشــراً تلقائيــاً علــى قيمــة أفضــل مقابــل\n المــال ،دون توافــر معطيــات إضافيــة تتعلّ ــق بنتائــج المنافســة والتنفيــذ.\n ب .حدود القيم المالية واالنحرافات\nتكشــف البيانــات عــن وجــود حــدود واســعة للقيــم الماليــة داخــل اإلجــراء الواحــد ،وال سـ ّـيما فــي االتفــاق\n ـدل علــى:\n الرضائــي وطلبــات عــروض األســعار ،مــا يـ ّ\n • تباين كبير في طبيعة العقود المشمولة ضمن اإلجراء نفسه؛\n • احتمال وجود حاالت استثنائية أو تطبيقات مرنة للسقوف المالية؛\n • الحاجة إلى قراءة هذه المؤشرات ضمن سياقها القانوني والمؤسسي ،دون تعميم أو استنتاجات\n متسّرعة.\n ّ\n\f91\n تطور هيكل اإلنفاق\n ّ .3\n أ .انتقال اإلنفاق نحو عقود أكبر\n 17\n جدول :30متوسط قيمة العقد (بالدوالر االميركي)\n تُ ظهر المعطيات توجهاً تدريجياً نحو عقود أعلى قيمة خالل السنوات األخيرة من فترة الرصد ،ما يعكس:\n والحد األدنى من التشغيل،\n ّ انتقاال من مرحلة إدارة األزمات\n ً •\n •إلى مرحلة إعادة تفعيل االستثمارات العامة والعقود الكبرى.\n تغير توزيع القيم بين طرق الشراء\n بّ .\n جدول :31نسبة توزّ ع االنفاق حسب طريقة الشراء\n 17باستثناء المزايدات\n\f 92\n تغير نسبي في توزيع القيم المالية بين طرق الشراء ،حيث:\n التحول ّ\n ّ يرافق هذا\n • ترتفع مساهمة المناقصة العمومية في إجمالي اإلنفاق؛\n • فيما تتراجع نسبيًاً مساهمة الطرق ذات القيم المنخفضة ،من حيث الوزن المالي وإن بقي حضورها\n العددي مرتفعًاً.\n ج .قراءة حذرة في ضوء السياق العام\n سيما:\n التطور في ضوء السياق االقتصادي والمؤسسي العام ،وال ّ\n ّ ينبغي قراءة هذا\n •تقلبات المالية العامة؛\n •أولويات اإلنفاق الحكومي؛\n •تفاوت جهوزية الجهات الشارية.\nتحســناً فــي األداء ،بقــدر مــا يعكــس تحـ ّـو ًال تدريجيــاً فــي"}, {"o": 108, "l": "المادة 2", "b": "تغيــر هيــكل اإلنفــاق ال يعكــس بالضــرورة ّ\n وعليــه ،فــإن ّ\n المنفــذة.\n ّ طبيعــة العمليــات\n .4حدود االستنتاجات الممكنة\n أ .غياب بيانات المنافسة الفعلية\n تظل القدرة على تقييم «القيمة مقابل المال» محدودة ،في ظل غياب بيانات تفصيلية حول:\n ّ\n •عدد العارضين؛\n •مستويات التنافس السعري؛\n •الفروقات بين الكلفة التقديرية والكلفة النهائية.\n ب .المؤشرات كإشارات أولية ال أحكام نهائية\nـاء عليــه ،يجــب التعامــل مــع المؤشــرات الماليــة الــواردة فــي هــذا القســم بوصفهــا إشــارات أوليــة تســاعد علــى بنـ ً\n فهــم االتجاهــات العامــة ،ال بوصفهــا أحكامــاً نهائيــة علــى كفــاءة اإلنفــاق أو فعاليــة النظــام.\n وتبرز الحاجة ،في المراحل الالحقة من اإلصالح ،إلى:\n شموال؛\n ً •تطوير منظومة بيانات أكثر\n •وربط التحليل المالي بمؤشرات األداء والمنافسة والتنفيذ؛\n •تطوير أدوات رقابة قائمة على المخاطر.\n أن تقييــم\n توفــر البيانــات المتاحــة قــراءة أوليــة لتطـ ّـور القيــم الماليــة وهيــكل اإلنفــاق فــي الشــراء العــام ،غيــر ّ\n ّ\n القيمــة مقابــل المــال يبقــى رهنــاً باســتكمال منظومــة المؤشــرات ،واالنتقــال مــن التحليــل الكمــي إلــى التقييــم\n المتكامــل لــأداء والمخرجــات.\n .VIIIالشفافية والنشر وجودة البيانات\nُيعـ ّـد النشــر أحــد الركائــز األساســية التــي يقــوم عليهــا نظــام الشــراء العــام الحديــث ،وأداة محوريــة لتعزيــز الشــفافية\nوالمســاءلة وتمكيــن الرقابــة المجتمعيــة والمؤسســية .ويهــدف هــذا القســم إلــى تحليــل واقــع النشــر علــى منصــة\nوتنــوع المعلومــات\n ّ هيئــة الشــراء العــام خــال الفتــرة ،2025–2022مــن حيــث مــدى االلتــزام ،وانتظــام النشــر،\n المنشــورة ،وجودتهــا ،دون الدخــول فــي تقييــم قانونــي فــردي للجهــات الشــارية.\n\f93"}, {"o": 109, "l": "المادة 2", "b": "ويستند التحليل إلى المبادئ التالية:\n • الشفافية كشرط للمساءلة :ال تكتمل فائدة المنصة دون نشر كامل ومنتظم ودقيق للبيانات؛\n • جودة البيانات كأساس للتحليل :المؤشرات الكمية تفقد مصداقيتها إذا اعتمدت على بيانات ناقصة أو\n غير متجانسة؛\n • النضج التدريجيُ :يقرأ مستوى االلتزام بالنشر ضمن سياق المرحلة االنتقالية التي يمر بها النظام.\n مالحظة منهجية\nُيقصــد بـــ «جــودة البيانــات» فــي هــذا القســم مــدى اكتمــال الحقــول اإللزاميــة (القيمــة ،طريقــة الشــراء ،تاريــخ\n المــورد) ،وليــس تقييمــاً ألداء جهــة شــارية بعينهــا.\n ّ اإلرســاء ،اســم\n .1النشر على المنصة :من اإللزام القانوني إلى الممارسة الفعلية\n يشكّ ل النشر العلني للمعلومات المتعلّ قة بالشراء العام شرطاً أساسياً لتحقيق:\n المشغلين االقتصاديين؛\n ّ •تكافؤ الفرص بين\n تتبع مسار العملية الشرائية من مرحلة اإلعالن إلى التلزيم؛\n •إمكانية ّ\n •تعزيز ثقة القطاع الخاص والرأي العام بمنظومة الشراء العام.\nـراء شــكلياً أو التزامــاً إجرائيــاً فحســب ،بــل كأداة حوكمــة تمكّ ــن مــن\n وفــي هــذا اإلطــار ،ال ُيفهــم النشــر بوصفــه إجـ ً\n مراقبــة الســلوك الشــرائي وتحليــل االتجاهــات العامــة لإلنفــاق العــام.\n جدول :32عدد العمليات المنشورة على المنصة سنوياً\nُيلــزم قانــون الشــراء العــام الجهــات الشــارية بنشــر إعالنــات الشــراء ،ونتائــج التلزيــم ،والعقــود المبرمــة علــى المنصــة\nاإللكترونيــة المركزيــة .وتُ ظهــر البيانــات المنشــورة تطـ ّـوراً ملحوظــاً فــي مســتوى اســتخدام المنصــة ،وال سـ ّـيما خالل\nـدل علــى تراجــع العوائــق التقنيــة والتنظيميــة التــي واجهــت الجهــات الشــارية فــي المراحــل عامــي 2023و ،2024مــا يـ ّ"}, {"o": 110, "l": "المادة 2", "b": "أن هــذا التقـ ّـدم الكمــي ال يلغــي اســتمرار بعــض الفجــوات فــي ممارســات النشــر، األولــى مــن تشــغيل المنصــة .غيــر ّ\n ومــن أبرزهــا:\n •إدراج عقود دون قيمة مالية معلنة؛\n •عمليات ال تُ نشر نتائجها النهائية؛\n تأخر النشر عن المهل القانونية؛• ّ\n الموردين.\n ّ •عدم توحيد تسميات المتعاقدين أو\n\f 94\n جدول :33عدد الجهات الشارية التي تلتزم بالنشر على المنصة\nكمــا تُ ظهــر البيانــات تفاوتــاً واضحــاً فــي مســتوى تفاعــل الجهــات الشــارية مــع المنصــة .18فمــن أصــل 282جهــة\nشــارية مسـ ّـجلة علــى المنصــة 207 ،جهــات قامــت بالنشــر بدرجــات متفاوتــة ،فــي حيــن لــم تقــم 75جهــة بــأي عمليــة\n نشــر علــى المنصــة خــال فتــرة التقريــر ،مــا يعكــس فجــوة مؤسســية فــي االندمــاج الرقمــي ال تــزال قائمــة.\n جدول :34نظرة عامة على عمليات الشراء المسجلة على المنصة 2025/12/31-2022/8/1\n المسجلة على المنصة في الملحق رقم 10\n ّ 18الالئحة الكاملة للجهات الشارية\n\f95\n أن:\n وفي السياق نفسهُ ،ي ّبين توزيع العمليات المنشورة ّ\n تتوقف عند مرحلة اإلعالن؛\n ّ •نحو %15من العمليات\n تتوقف في مراحل الحقة من اإلجراء دون الوصول إلى التلزيم ،ألسباب قانونية أو إجرائية؛\n ّ •ونحو %17\n أن %68فقط من العمليات المنشورة تصل إلى مرحلة التلزيم. •في حين ّ\nويعكــس هــذا التوزيــع واقعــاً إجرائيــاً طبيعيــاً فــي منظومــة الشــراء العــام ،حيــث ال تــؤدي جميــع اإلعالنــات بالضرورة\nإلــى تلزيــم ،إال أنّ ــه فــي الوقــت نفســه يبــرز أهميــة اســتكمال نشــر نتائــج العمليــات غيــر المكتملــة لتعزيــز الشــفافية\n اإلجرائية.\n .2نشر خطط الشراء :بين الطموح القانوني والواقع المؤسسي\nُيلزم قانون الشــراء العام الجهات الشــارية بإعداد ونشــر خطط شــراء ســنوية أو متعددة الســنوات ،كأداة للتخطيط"}, {"o": 111, "l": "المادة 2", "b": "المســبق وتعزيــز الشــفافية ،وال سـ ّـيما للعمليــات التــي تتجــاوز ســقوفاً ماليــة محـ ّـددة ،وضمن مهــل زمنية واضحة.\nأن نشــر خطــط الشــراء ال يــزال محــدود االنتشــار مقارنــة بباقــي مراحــل النشــر ،ويتركّ ــز\n أن البيانــات المتاحــة تُ ظهــر ّ\n غيــر ّ\n لــدى عــدد ضيــق مــن الجهــات ذات الجهوزيــة المؤسســية األعلــى.\nوال يعكــس هــذا الواقــع بالضــرورة ضعــف االلتــزام بالقانــون أو مقاومــة للنظــام ،بــل يمكــن تفســيره بجملــة عوامــل\n متداخلــة ،مــن أبرزهــا:\n سّيما البلديات الصغيرة ،عمليات شراء\n تنّفذ العديد من الجهات الشارية ،وال ّ\n • السقوف المالية للنشر :إذ ّ\n دون السقف الملزم بنشر خطة شراء؛\n المدربة على إعداد خطط شراء منهجية؛\n ّ • القدرات الفنية المحدودة :نقص الكوادر\n يحد من القدرة على التخطيط السنوي المسبق؛ • عدم استقرار الموازنات العامة ما ّ\n • التفاوت في الجهوزية التقنية واختالف مستويات اإللمام باستخدام المنصة اإللكترونية.\n أن نشــر خطــط الشــراء ّ\nيمثــل أحــد مؤشــرات النضــج المتقـ ّـدم للنظــام ،ويحتــاج إلــى وقــت ودعــم ويظهــر هــذا الواقــع ّ\n ُ\n مؤسســي إضافــي قبــل أن يتحـ ّـول إلــى ممارســة عامــة ومنتظمــة.\nأن منصــة هيئــة الشــراء العــام باتــت تشــكّ ل مرجعــاً مركزيــاً للمعلومــات المتعلقــة بالشــراء العــام،\n ُيظهــر تحليــل النشــر ّ\nأن االنتقــال مــن النشــر الشــكلي إلــى الشــفافية الفعليــة يبقــى مــع تقـ ّـدم ملحــوظ فــي حجــم النشــر وانتشــاره .غيــر ّ\n رهنــاً بتحســين جــودة البيانــات ،وتعميــم نشــر خطــط الشــراء ،وتعزيــز القــدرات المؤسســية للجهــات الشــارية.\n التحول في نظام الشراء العام\n ّ .IXمن البيانات إلى الرسائل :مؤشرات"}, {"o": 112, "l": "المادة 2", "b": "يهــدف هــذا القســم إلــى تقديــم خالصــة مركّ ــزة ألهــم النتائــج اإلحصائيــة الــواردة فــي الفصــل الســادس ،مــن خــال\nتجميــع المؤشــرات الرئيســية وتحويلهــا إلــى رســائل تحليليــة عامــة تعكــس اتجاهــات تطبيــق نظــام الشــراء العــام كمــا\n تظهــر فــي البيانــات المنشــورة علــى المنصــة االلكترونيــة لــدى هيئــة الشــراء العــام.\nتميــز\n وال يهــدف هــذا القســم إلــى إعــادة عــرض التفاصيــل ،بــل إلــى إبــراز األنمــاط العامــة واالتجاهــات الكبــرى التــي ّ\n أداء النظــام خــال الفتــرة المدروســة ،أي مــن 1آب 2022الــى 31كانــون االول .2025\n\f 96\n .1الرسائل الرئيسية المتعلقة بحجم العمليات\nتشــير البيانــات إلــى أن نظــام الشــراء العــام يشــهد نشــاطاً متزايــداً مــن حيــث عــدد العمليــات والقيمــة الماليــة\nتوســعاً تدريجيــاً فــي اســتخدام المنصــة اإللكترونيــة واعتمادهــا كأداة مركزيــة لتوثيــقاإلجماليــة ،مــا يعكــس ّ\n عمليــات الشــراء العــام.\nوالتكيــف المؤسســي\n ّ كمــا ُيالحــظ تفــاوت زمنــي فــي وتيــرة هــذا النشــاط ،يعكــس مراحــل مختلفــة مــن االســتقرار\n مــع النظــام الجديــد.\n .2الرسائل الرئيسية المتعلقة بطرق الشراء\nتُ ظهــر النتائــج أن طــرق الشــراء التنافســية تشــكّ ل الحصــة األكبــر مــن العمليــات ،وال سـ ّـيما مــن حيــث القيمــة الماليــة،\nمــع اســتمرار اســتخدام بعــض اإلجــراءات غيــر التنافســية ضمــن اإلطــار القانونــي المســموح بــه .ويعكــس هــذا التوزيع\nاتجاهــاً عامــاً نحــو تعزيــز المنافســة ،بالتــوازي مــع الحفــاظ علــى قــدر مــن المرونــة اإلجرائيــة فــي حــاالت محـ ّـددة ،مــا\n ـدل علــى نظــام فــي مرحلــة انتقــال تدريجــي نحــو التطبيــق الكامــل لمبــادئ الشــراء التنافســي. يـ ّ"}, {"o": 113, "l": "المادة 2", "b": ".3الرسائل الرئيسية المتعلقة بالمنافسة\nتبيــن المؤشــرات المتاحــة أن الطابــع اإلجرائــي لعمليــات الشــراء العــام يختلــف باختــاف نــوع اإلجــراء وطبيعــة الجهــة ّ\n الشــارية .وبصــورة عامــة ،تُ ظهــر البيانــات:\n •تفاوتاً في االعتماد على اإلجراءات التنافسية بين الجهات؛\n •واختالفاً في أنماط االستخدام يعكس عوامل مؤسسية وتشغيلية وعوامل متعلقة بالسوق.\nوفــي ظــل غيــاب بيانــات تفصيليــة حــول عــدد العارضيــن ،تُ قــرأ هــذه المؤشــرات كدالئــل علــى هيكليــة اإلجــراءات\n المعتمــدة ،ال كمقيــاس مباشــر لمســتوى المنافســة الفعليــة فــي الســوق.\n .4الرسائل الرئيسية المتعلقة بالجهات الشارية\nتُ ظهــر البيانــات تفاوتــاً ملحوظــاً بيــن الجهــات الشــارية مــن حيــث حجــم اســتخدام المنصــة ومســتوى التفاعــل مــع\n النظــام الرقمــي .ويعكــس هــذا التفــاوت اختالفــاً فــي:\n •القدرات المؤسسية؛\n •الجهوزية التشغيلية؛\n التكيف مع متطلبات النظام الجديد؛\n ّ •وتيرة\n دون أن يشكّ ل ذلك تقييماً ألداء جهة بعينها ،بل توصيفاً التجاهات عامة في التطبيق المؤسسي.\n .5الرسائل الرئيسية المتعلقة بالتحليل المالي\nتشــير المؤشــرات الماليــة إلــى تبايــن واضــح فــي قيــم العقــود ومتوســطاتها بحســب نــوع العقــد وطريقــة الشــراء،\n مــع تركّ ــز نســبي لإلنفــاق فــي قطاعــات محـ ّـددة ذات طابــع اســتراتيجي .ويعكــس هــذا التوزيــع:\n •طبيعة أولويات اإلنفاق العام؛\n •وهيكل الطلب في القطاعات األساسية؛\n •واختالف طبيعة العقود من حيث الحجم واألثر المالي.\n .6الرسائل الرئيسية المتعلقة بالشفافية والرقمنة\nأن مســتوى اكتمــال\n تُ ظهــر النتائــج أن اســتخدام المنصــة االكترونيــة فــي الشــراء العــام فــي تزايــد مســتمر ،غيــر ّ\n البيانــات وتجانســها ال يــزال متفاوتــاً بيــن الجهــات الشــارية."}, {"o": 114, "l": "المادة 2", "b": "97\nتقدمــاً ملموســاً ،لكنــه ال يــزال فــي مرحلــة تعزيــز وتثبيــت الممارســات،\n ويشــير ذلــك إلــى أن التحــول الرقمــي يشــهد ّ\n مــع حاجــة واضحــة إلــى تحســين جــودة البيانــات واتســاقها لضمــان فعاليــة التحليــل والرقابــة.\n .7الرسالة العامة للفصل السادس\nتحول مؤسســي تدريجي،\n بشــكل عــام ،تعكــس المؤشــرات اإلحصائيــة أن نظــام الشــراء العــام فــي لبنــان يمـ ّـر بمرحلــة ّ\n يتميز بـ:\n ّ\n توسع في حجم العمليات المنشورة؛ • ّ\n تحسن نسبي في اعتماد اإلجراءات التنافسية؛\n • ّ\n •تفاوت في مستويات التطبيق بين الجهات الشارية؛\n وتقدم في مسار الرقمنة ،يقابله استمرار فجوات في جودة البيانات.\n ّ •\nـاء عليــه ،يشــكّ ل هــذا الفصــل قاعــدة كميــة أساســية لفهــم التحديــات البنيويــة والتشــغيلية التــي يتناولهــا الفصل\n وبنـ ً\n الالحق.\n مالحظة ختامية منهجية\nتُ عــد النتائــج الــواردة فــي هــذا الفصــل وصفيــة واتجاهيــة بطبيعتهــا ،وتهــدف إلــى تقديــم قــراءة كميــة لألنمــاط\nمعمقــة ،والتــي تُ تــرك\n ّ العامــة فــي تطبيــق نظــام الشــراء العــام ،دون الخــوض فــي تقييمــات ســببية أو أحــكام نوعيــة\n للفصــول التحليليــة الالحقــة.\n\f الفصل السابع\nالتعاون الدولي والشراكات االستراتيجية\n\f جدول المحتويات\n100 مقدمة :الشراكة كرافعة أساسية لإلصالح\n ّ .I\n100 .IIالتعاون الدولي\n100 .1دعم الوكالة الفرنسية للتنمية AFDعبر برنامج FEXTE Commande Publiqueللشراء العام\n101 .2برنامج دعم إصالح اإلدارة العامة في لبنان ()RAP\n103 .3التعاون مع البنك الدولي ()World Bank\n104 .4التعاون مع الوكالة األلمانية للتعاون الدولي ()GIZ\n105 .5التعاون مع مبادرة SIGMA\n105 .6التكامل بين الشركاء الدوليين واألثر التراكمي لإلصالح\n105 .7التعاون الدولي ومؤشرات النتائج"}, {"o": 115, "l": "المادة 2", "b": "108 .IIIالشراكات االستراتيجية على المستوى الوطني\n108 .1الشراكة مع وزارة المالية -معهد باسل فليحان المالي واالقتصادي\n108 .2العالقة مع مؤسسات المجتمع المدني\n108 .IVالخالصة\n\f 100\n الفصل السابع :التعاون الدولي والشراكات االستراتيجية\n مقدمة :الشراكة كرافعة أساسية لإلصالح\n ّ .I\nشــكّ لت الشــراكات ركيــزة أساســية لدفــع مســار إصــاح نظــام الشــراء العــام فــي لبنــان قدمــاً ،وال ســيما فــي ظــل\nحيــز التنفيــذ .وقــد\n الســياق االقتصــادي والمؤسســي الصعــب الــذي رافــق إقــرار قانــون الشــراء العــام ودخولــه ّ\nفعالــة ومســتدامة أدركــت هيئــة الشــراء العــام منــذ انطالقتهــا أن ترجمــة اإلصــاح التشــريعي إلــى ممارســات ّ\nتتطلــب شــراكات اســتراتيجية ،تجمــع بيــن الدعــم الفنــي ،بنــاء القــدرات ،تطويــر األدوات ،وتعزيــز التنســيق مــع مختلــف\n الفاعليــن الوطنييــن والدولييــن.\nفــي هــذا اإلطــار ،اســتفادت الهيئــة مــن برامــج تعــاون دولــي متكاملــة مــع الحكومــة اللبنانيــة ،واعتمــدت شــراكات\nوطنيــة أساســية ،ســاهمت فــي ربــط األهــداف اإلصالحيــة بالنتائــج العمليــة ودعــم االنتقــال مــن مرحلــة التأســيس\n إلــى التشــغيل والتعزيــز المؤسســي.\n .IIالتعاون الدولي\n .1دعم الوكالة الفرنسية للتنمية AFDعبر برنامج FEXTE Commande Publiqueللشراء العام\nوالمنفــذ مــن قبــل Expertise\n ّ شــكّ ل برنامــج FEXTEللشــراء العــام ،الممـ ّـول مــن الوكالــة الفرنســية للتنميــة ،AFD\n Franceبيــن العاميــن 2021و ،2024أحــد أطــر الدعــم الدولــي األساســية التــي واكبــت المراحــل التأسيســية إلصــاح\nوفــر هــذا البرنامــج دعمــاً تقنيــاً ومؤسســياً متعـ ّـدد األبعــاد لهيئــة الشــراء العــام ،تمحــور\n الشــراء العــام فــي لبنــانّ ."}, {"o": 116, "l": "المادة 2", "b": "حــول إرســاء األســس التنظيميــة والمؤسســية لتفعيــل القانــون ،وبنــاء القــدرات ،وتطويــر أدوات الشــراء العــام،\n ودعــم التحـ ّـول الرقمــي.\nحيــز التنفيــذ ،مــا مكّ ــن\n وجــاء هــذا الدعــم فــي مرحلــة مفصليــة ســبقت وتزامنــت مــع دخــول قانــون الشــراء العــام ّ\nهيئــة الشــراء العــام مــن االضطــاع بدورهــا الرقابــي والناظــم وفقــاً لمتطلبــات القانــون ،ومــن االنتقــال التدريجــي\n مــن اإلطــار التشــريعي إلــى التطبيــق العملــي.\n أ .الدعم القانوني والتنظيمي والمؤسسي\nركّ ــز برنامــج FEXTEعلــى اســتكمال اإلطــار التنظيمــي لقانــون الشــراء العــام وتعزيــز الحوكمــة المؤسســية لهيئــة\n الشــراء العــام ،مــن خــال:\n سيما:\n • إعداد مشاريع التشريعات الثانوية المنصوص عليها في قانون الشراء العام ،وال ّ\n -مشروع مرسوم تعيين رئيس وأعضاء هيئة الشراء العام وتحديد شروط تعويضاتهم؛\n -مشروع النظام اإلداري والمالي لهيئة الشراء العام؛\n -مشروع النظام الوظيفي لموظفي الهيئة؛\n -مشروع النظام الداخلي لهيئة الشراء العام.\n • وضع إطار متابعة وتقييم إلصالح الشراء العام ،وتطوير آليات جمع البيانات المرتبطة به؛\n• دعــم تحديــد إجــراءات التدقيــق والرقابــة الداخليــة داخــل الجهــات الشــارية ،بمــا في ذلك رســم خرائط المخاطر\n وإعداد مشاريع تنظيمية للتدقيق الداخلي؛\n • توفير مساندة تقنية مباشرة للهيئة عبر تأمين خبير في الشراء العام بدوام كامل ،مما ساهم في\n مواكبة الهيئة في تنفيذ مهامها وتعزيز قدراتها المؤسسية.\n\f101\n ب .تطوير أدوات الشراء العام وبناء القدرات\nســاهم البرنامــج فــي تزويــد هيئــة الشــراء العــام بــاألدوات العمليــة الالزمــة لتطبيــق القانــون وبنــاء القــدرات\n الوطنيــة فــي هــذا المجــال ،عبــر:"}, {"o": 117, "l": "المادة 2", "b": "• إنشاء «صندوق أدوات» ( )Toolboxلالستخدام من قبل الجهات الشارية وتسهيل التطبيق؛\n موحدة لملفات التلزيم؛\n ّ • تصميم نماذج\n مسودة سياسة وطنية للتدريب في مجال الشراء العام ،مرفقة بأدلة تشغيلية؛ّ • إعداد\n • توفير خبرات وطنية لفترات قصيرة لدعم الهيئة في مهامها اليومية ونقل المعرفة؛\n • توفير خبير فرنسي متخصص لدعم الهيئة في وضع منهجيات التدقيق الجنائي ()Forensic Audit\n والتدقيق المحاسبي-القانوني ،ورسم خرائط المخاطر المرتبطة بالشراء العام.\n والتحول الرقمي\n ّ ج .دعم الشراء العام المستدام\n أولى برنامج FEXTEاهتماماً خاصاً بإدماج مفاهيم االستدامة والرقمنة في نظام الشراء العام ،من خالل:\n •إعداد تقارير تشخيصية حول واقع الشراء العام المستدام في لبنان؛\n •تصميم مسودة سياسة وطنية للشراء العام المستدام؛\n •إعداد أدوات تطبيقية لترجمة هذه السياسة إلى ممارسات عملية؛\n •تنظيم دورات تدريبية متخصصة لصالح هيئة الشراء العام حول التطبيق العملي للشراء العام المستدام؛\n • دعم إنشاء أول موقع إلكتروني لهيئة الشراء العام ،شّكّ ل النواة األولى لمنظومة النشر والعلنية،\n تطبيقًاً لمبدأ الشفافية وإتاحة المعلومات.\n د .المخرجات الرئيسية للبرنامج\n أسفر تنفيذ برنامج FEXTEعن مجموعة من المخرجات المرجعية ،من أبرزها:\n •دليل التدقيق الجنائي ( )Forensic Auditفي مجال الشراء العام؛\n •خرائط مخاطر التدقيق الداخلي ومعايير األداء ذات الصلة؛\n •دليل التدقيق الداخلي لوظيفة الشراء؛\n مسودة السياسة الوطنية للتدريب على الشراء العام في لبنان ،مرفقة بأدلة تشغيلية؛ّ •\n •تقارير وسياسات وأدوات تنفيذية في مجال الشراء العام المستدام؛\n •الموقع اإللكتروني األولي لهيئة الشراء العام.\n .2برنامج دعم إصالح اإلدارة العامة في لبنان ()RAP\nوالمنفــذ مــن قبــل"}, {"o": 118, "l": "المادة 2", "b": "َّ ُيعـ ّـد برنامــج «دعــم إصــاح اإلدارة العامــة فــي لبنــان» ،19RAPالممـ ّـول مــن االتحــاد األوروبــي\n Expertise Franceمنــذ تشــرين الثانــي ،2023أحــد أبــرز أطــر التعــاون الدولــي الداعمــة إلصــاح نظــام الشــراء العــام\nفــي لبنــان .وقــد اكتســب هــذا البرنامــج أهميــة خاصــة نظــراً لتزامــن إطالقــه مــع مرحلــة دقيقــة مــن تطبيــق قانــون\n الشــراء العــام ،وفــي ظـ ّـل تحديــات اقتصاديــة ومؤسســية غيــر مســبوقة.\nـا (المكـ ّـون الثانــي مــن المشــروع) لدعــم إصــاح الشــراء العام ،ركّ ز بشــكل أساســي مكونــاً كامـ ً\n ّ خصــص البرنامــج\n وقــد ّ\nعلــى تفعيــل دور هيئــة الشــراء العــام ،ومواكبــة تطبيــق قانــون الشــراء العــام ،وتســريع التحـ ّـول الرقمــي عبــر تطويــر\nنظــام الشــراء اإللكترونــي ،إلــى جانــب بنــاء القــدرات المؤسســية والبشــرية لــدى الهيئــة والجهــات الشــارية ،وتعزيــز\n التنســيق مــع مختلــف الجهــات المعنيــة.\n 19https://www.expertisefrance.fr/en/projects/support-public-administration-reform-lebanon\n\f 102\n أ .دعم تمكين هيئة الشراء العام وضمان استمرارية عملها\nركّ ــز الدعــم فــي هــذا المحــور علــى تمكيــن هيئــة الشــراء العــام مــن االنطــاق الفعلــي واالضطــاع بمهامهــا فــي\n ظــروف اســتثنائية ،وشــمل علــى وجــه الخصــوص:\n مجّهزة ،وتأمين\n ّ مقّر الهيئة وتجهيزه ،بما في ذلك قاعات االجتماعات وإنشاء غرفة ترجمة • تأهيل ّ\n ومحّوالت كهربائية عالية القدرة لضمان استمرارية العمل وحماية برامج وداتا المعلومات ّ بطاريات\n الخاصة بالموقع االلكتروني للهيئة في ظل االنقطاعات المزمنة للتيار الكهربائي؛\n • تطوير قدرات موظفي الهيئة من خالل برامج تدريبية متخصصة ،شملت تدريبات على القانون الجديد"}, {"o": 119, "l": "المادة 2", "b": "بشكل عام واتفاقات اإلطار بشكل خاص ،كما شملت تدريبات في مجال تكنولوجيا المعلومات\n وتدريبات مؤسسية بالتعاون مع المعهد الوطني للخدمة العامة في فرنسا ( )INSPومعهد باسل\n فليحان المالي واالقتصادي في لبنان؛\n • تطوير وحماية البنية التحتية الرقمية للهيئة ،عبر تأمين التجهيزات المعلوماتية ،البرمجيات ،التراخيص،\n وإنشاء غرفة خوادم ()Server Room؛\n • إنشاء برنامج تدريب داخلي ( )Internship Programلدى هيئة الشراء العام؛\n وكتيب تعريفي بالهيئة؛\n ّ • إعداد استراتيجية تواصل مؤسسية\n • المساعدة في إعداد تقرير األداء لهيئة الشراء العام؛\n • دعم التنظيم الداخلي للهيئة ،بما في ذلك إعداد مالحظات تنظيمية واقتراح هيكلية تنظيمية؛\n • إعداد أوصاف وظيفية مرجعية لوظائف الشراء العام ،بالتنسيق مع مجلس الخدمة المدنية ،إضافة\n مسوّدات األوصاف الوظيفية لموظفي الهيئة (قيد المصادقة). ّ إلى إعداد\n ب .دعم تنفيذ إصالح الشراء العام ومساندة الجهات الشارية\nبالتــوازي مــع الدعــم المؤسســي ،واكــب برنامــج RAPهيئــة الشــراء العــام فــي تنفيــذ اإلصــاح علــى المســتوى\n العملــي ،مــن خــال:\n •تطوير وتحديث المنصة اإللكترونية المركزية لدى الهيئة؛\n • إعداد دفتر شروط نموذجي لشراء اللوازم عبر المناقصة العمومية على أساس السعر األدنى؛\n • تقديم مساعدة فنية متخصصة عبر خبراء وطنيين ودوليين لدعم الهيئة في:\n -الرد على استفسارات الجهات الشارية؛\n بناء على طلب الجهات الشارية؛ -مراجعة وتنقيح دفاتر الشروط ً\n -إبداء الرأي في مناقصات حساسة بطلب من مجلس الوزراء أو الجهات المختصة؛\n • تنظيم ورش عمل ولجان فنية مع الجهات الشارية لمعالجة التحديات التطبيقية واقتراح الحلول\n المناسبة؛\n كتيب ( )Q&A-FAQ20لدعم التطبيق العملي للقانون؛ • إعداد وتجميع أسئلة وأجوبة شائعة وإصدار ّ"}, {"o": 120, "l": "المادة 2", "b": "• تنظيم دورات تدريبية للجهات الشارية على استخدام المنصة اإللكترونية المركزية؛\n سّيما منظمات المجتمع المدني والمنظمات الدولية ،عبر • تعزيز التنسيق مع أصحاب المصلحة ،وال ّ\n إشراكهم في اللجان الفنية والتوجيهية للمشروع ،وضمان التكامل مع المبادرات والبرامج األخرى ذات\n الصلة.\n 20Frequently Asked Questions\n\f103\n ج .المخرجات الرئيسية المحققة في إطار برنامج RAP\n أسفر تنفيذ هذا البرنامج حتى تاريخه عن مجموعة من المخرجات العملية الداعمة لإلصالح ،أبرزها:\n •تقرير أداء هيئة الشراء العام؛\n كتيب؛\n •تجميع ونشر أسئلة وأجوبة شائعة ( )Q&A-FAQوإصدارها في ّ\n •دفتر شروط نموذجي لشراء اللوازم على أساس السعر األدنى؛\n •إصدار ملحق حول األخطاء األكثر شيوعاً في إعداد دفاتر الشروط؛\n مقر هيئة الشراء العام؛\n •تأهيل وتجهيز ّ\n •تطوير البنية التحتية لتكنولوجيا المعلومات وغرفة الخوادم؛\n وكتيب تعريفي بالهيئة؛\n ّ •استراتيجية تواصل مؤسسية\n •تحديث المنصة اإللكترونية لهيئة الشراء العام؛\n يوضح أدوار هيئات الرقابة المختلفة ضمن دورة الشراء العام؛ مخطط ّ ّ • إعداد\n مسوّدات األوصاف الوظيفية المرجعية لوظيفة الشراء العام بالتنسيق مع مجلس الخدمة ّ • إعداد\n المدنية؛\n مسودات األوصاف الوظيفية لموظفي هيئة الشراء العام؛ ّ •إعداد\n •مذكرة حول التنظيم الداخلي لهيئة الشراء العام.\n .3التعاون مع البنك الدولي ()World Bank\nيعـ ّـد البنــك الدولــي مــن أبــرز الشــركاء الدولييــن الذيــن واكبــوا مســار إصــاح الشــراء العــام فــي لبنــان علــى مــدى\nســنوات وقــد لعــب دوراً محوريــاً فــي دعــم مســار إصــاح نظــام الشــراء العــام فــي لبنــان منــذ المراحــل األولــى .وقــد\nأســهمت تدخالتــه التحليليــة واالستشــارية ،وال ســيما علــى مســتوى التشــخيص ووضــع السياســات ،فــي ترســيخ"}, {"o": 121, "l": "المادة 2", "b": "أســس إصــاح شــامل لنظــام الشــراء العــام ،ومكّ نــت الجهــات الوطنيــة مــن االنتقــال التدريجــي مــن مرحلــة إعــداد\n اإلطــار التشــريعي إلــى مرحلــة التطبيــق العملــي.\nكمــا شــكّ ل البنــك الدولــي مرجعيــة أساســية فــي إدراج إصــاح الشــراء العــام ضمــن األجنــدة األوســع إلصــاح\nالماليــة العامــة وتعزيــز الحوكمــة ،مــع إبــراز دور هــذا اإلصــاح كرافعــة لتعزيــز الشــفافية ،تحســين كفــاءة اإلنفــاق\nالعــام ،ومكافحــة الفســاد .وقــد ســاهم هــذا المســار التراكمــي فــي تهيئــة األرضيــة المؤسســية والتقنيــة التــي\nأفضــت الحقــاً إلــى إقــرار قانــون الشــراء العــام وإنشــاء هيئــة الشــراء العــام ،مــا وضــع لبنــان علــى مســار إصالحــي\n جديــد علــى المســتويين التنظيمــي والمؤسســي.\nكمــل أطــر التعــاون\n وي ّ\n ويأتــي هــذا الــدور فــي إطــار مقاربــة البنــك الدولــي الشــاملة لدعــم اإلصالحــات الهيكليــةُ ،\n الدولــي الالحقــة التــي ركّ ــزت علــى مرحلــة التطبيــق وتفعيــل القانــون وبنــاء القــدرات المؤسســية.\nوعلــى مســتوى الدعــم التقنــي المباشــر لهيئــة الشــراء العــام خــال مرحلــة االنتقــال نحو التطبيق ،شــملت مســاهمة\nتمثلــت فــي إعــداد وتطويــر مســودات دفاتــر شــروط نموذجيــة لشــراء البنــك الدولــي توفيــر أدوات مرجعيــة أوليــةّ ،\nاللــوازم والخدمــات واألشــغال ،شــكّ لت أساســاً اســتندت إليــه الهيئــة فــي اســتكمال وتطويــر النمــاذج الوطنيــة\nمتخصصــة لمراجعــة واســتكمال إعــداد دفتــر الشــروط الخــاص ّ وفــر البنــك الدولــي خبــرات دوليــة\n الحقــاً .كمــا ّ\nـا مــع الدعــم المقـ ّـدم مــن قبــل مشــروع RAP بالمناقصــة العموميــة علــى أســاس العــرض األدنــى مــا شــكّ ل تكامـ ً"}, {"o": 122, "l": "المادة 2", "b": "وأدى الــى تمكيــن الهيئــة مــن إصــدار هــذا الدفتــر النموذجــي ،كمــا ســاهم فــي مواءمــة الوثائــق مــع أحــكام قانــون ّ\n الشــراء العــام والمعاييــر الدوليــة المعتمــدة.\nويكمل الدور التأسيسي للبنك الدولي (التشخيص ،صياغة السياسات ،وتوفير النماذج األولية لدفاتر الشروط) المرحلة ُ\nـاال سلســاً مــن اإلطــار التحليلــي إلــى\n يتواّلهــا حاليــاً االتحــاد األوروبــي عبــر مشــروع ،RAPبمــا يضمــن انتقـ ً\n التنفيذيــة التــي ّ\n التطبيق التشغيلي.\n\f 104\n .4التعاون مع الوكالة األلمانية للتعاون الدولي ()GIZ\nشــكّ ل التعــاون مــع الوكالــة األلمانيــة للتعــاون الدولــي ( )GIZركيــزة أساســية فــي دعــم هيئــة الشــراء العــام علــى\nالمســتوى التطبيقــي والتقنــي ،وال سـ ّـيما فــي مــا يتعلّ ــق بتطويــر أدوات الشــراء العــام وتوحيــد الممارســات .وقــد\nاتّ ســم هــذا التعــاون بطابــع عملــي مباشــر ،اســتهدف ترجمــة أحــكام قانــون الشــراء العــام إلــى إجــراءات وأدوات\n تشــغيلية قابلــة لالســتخدام اليومــي.\n أ .تطوير األدوات المرجعية والنماذج التطبيقية\nســاهم دعــم GIZفــي إعــداد ونشــر مجموعــة متكاملــة مــن األدوات العمليــة التــي ُوضعــت بمتنــاول الجهــات\n الشــارية ونُ شــرت علــى المنصــة اإللكترونيــة المركزيــة لهيئــة الشــراء العــام ،مــن أبرزهــا:\n •إعداد دفتر شروط نموذجي للخدمات االستشارية؛\n •إعداد شرعة قواعد السلوك واألخالقيات في الشراء العام؛\n •إعداد دليل عمل لجان التلزيم؛\n •إعداد دليل عمل لجان االستالم؛\n •إعداد مسودة دفتر شروط نموذجي التفاقيات اإلطار ،ودليل خاص بها؛\n •إعداد مسودة دفاتر شروط وإرشادات للمناقصة على مرحلتين؛\n •إعداد وثائق متخصصة حول إدارة العقود والشراء العام المستدام."}, {"o": 123, "l": "المادة 2", "b": "وقــد أســهمت هــذه األدوات فــي توحيــد الممارســات ،تقليــص هامــش االجتهــاد ،وتعزيــز االمتثــال لإلجــراءات\n القانونيــة والتنظيميــة.\n ب.بناء القدرات والتدريب المتخصص\nواكــب تطويــر األدوات تنفيــذ برامــج تدريبيــة تطبيقيــة هدفــت إلــى تعزيــز القــدرات المؤسســية والبشــرية ،ومــن\n أبرزهــا:\n •تنظيم ورش عمل حول دليل لجان التلزيم ،استفاد منها 245موظفاً من 42جهة شارية مختلفة؛\n •تنفيذ تدريبات متخصصة في مجال إدارة العقود والشراء العام المستدام ،بإشراف خبراء دوليين.\n ج.تعزيز الشفافية من خالل الكشف عن معلومات صاحب الحق االقتصادي ()Beneficial Ownership\nأولــى التعــاون‌مــع الوكالــة األلمانيــة للتعــاون الدولــي ( )GIZاهتمامــاً خاصــاً بملــف الشــفافية ومكافحــة الفســاد،\nعبــر تطويــر أدوات ومعرفــة متقدمــة فــي مجــال صاحــب الحــق االقتصــادي .وفــي هــذا اإلطــار ،شــمل دعــم\n الهيئــة مــن قبــل الوكالــة:\n • إعداد دراسة متخصصة حول صاحب الحق االقتصادي (المستفيد الحقيقي) في الشراء العام وأهمية\n تجميع المعلومات على المستوى الوطني؛\n موحد لجمع معلومات صاحب الحق االقتصادي (المستفيد الحقيقي)؛\n ّ • تطوير نموذج\n • تطوير مقاربات عملية إلدماج معلومات صاحب الحق االقتصادي ضمن دورة الشراء العام؛\n • إطالق جلسات تشاركية متعددة األطراف لتفسير النموذج وضمان توحيد آليات جمع وتدقيق البيانات\n (ابتداء من كانون األول .)2025\n\f105\n .5التعاون مع مبادرة SIGMA\nمتخصــص ،ركّ ــز علــى\n ّ ـيـ ومعرف ـيـ تقن ـمـ دع ـنـ م 21\n SIGMA ـادرة ـ مب ـعـ م ـاـ تعاونه ـناســتفادت هيئــة الشــراء العــام مـ\nإدخــال أفضــل الممارســات الدوليــة وتعزيــز القــدرات التحليليــة والتطبيقيــة لموظفي الهيئة فــي مجاالت مفصلية من"}, {"o": 124, "l": "المادة 2", "b": "إصــاح الشــراء العــام .وقــد اتّ خــذ هــذا التعــاون طابعــاً مرنــاً وقائمــاً علــى نقــل المعرفــة والخبــرة ،مــن خــال ورش عمــل\nمتخصصــة ،جلســات تدريبيــة عــن ُبعــد ،ومســاندة تقنيــة مباشــرة .وشــمل الدعــم المقــدم مــن SIGMAالمحــاور التاليــة: ّ\n •تنظيم ورشة عمل حول اتفاقيات اإلطار؛\n • تنفيذ ثالث جلسات تدريبية عن بعد لموظفي الهيئة حول اتفاقيات اإلطار ،المناقصات على مرحلتين،\n وتحديد الحاجات الشرائية؛\n متخّصصة عبر اإلنترنت حول دراسة السوق ،المتابعة وإعداد التقارير ،وتأهيل المتعاملين ّ • تنظيم جلسات\n االقتصاديين ()economic operators؛\n• دعــم مشــاركة الهيئــة فــي ورشــة إقليميــة حــول الوقايــة مــن الفســاد في الشــراء العــام ُُعقدت فــي األردن (أيار\n ،)2025بما أتاح تبادل الخبرات اإلقليمية وتعزيز المقاربة الوقائية في منظومة الشراء العام؛\n • تقديم عرض تقني حول إعداد التقارير السنوية؛\n متخّصصة تتعّلّ ق بتطبيق أحكام قانون الشراء ّ موّجهة عبر اإلجابة على استفسارات ّ • توفير مساندة تقنية\n العام وإجراءاته.\n وقد أسهم هذا التعاون في:\n •تعزيز القدرات لدى هيئة الشراء العام؛\n •اإلضاءة على مقاربات حديثة في دراسة السوق ،المتابعة ،وإعداد التقارير؛\n •تعزيز البعد الوقائي في مكافحة الفساد في الشراء العام؛\n •دعم بناء قدرات الكادر الفني للهيئة بما يتالءم مع المعايير الدولية.\n .6التكامل بين الشركاء الدوليين واألثر التراكمي لإلصالح\nـا أســهم تدخــات منفصلــة ،بــل شــكّ لت نســيجاً متكامـ ً\n لــم تكــن الشــراكات الدوليــة مــع هيئــة الشــراء العــام مجــرد ّ\nوفــرت الوكالــة\n فــي نقــل الهيئــة مــن مرحلــة التأســيس التشــريعي إلــى مرحلــة التشــغيل المؤسســي الفعلــي .فقــد ّ"}, {"o": 125, "l": "المادة 2", "b": "الفرنســية للتنميــة األســس التنظيميــة واألدوات المرجعيــة األولــى ،وأســهم البنــك الدولــي فــي بلــورة الزخــم\nاإلصالحــي والتشــخيصي وتهيئــة األرضيــة العامــة لإلصــاح ،فيمــا تولّ ــى االتحــاد األوروبــي ،مــن خــال مشــروع\n ،RAPالترجمــة التشــغيلية عبــر الرقمنــة ،وبنــاء القــدرات ،وتمكيــن الجهــات الشــارية .وفــي مــوازاة ذلــك ،ســاهمت\nالوكالــة األلمانيــة للتعــاون الدولــي ( )GIZومبــادرة SIGMAفــي االرتقــاء بالممارســة المهنيــة عبــر أدوات ومعاييــر\nويظهــر هــذا التكامــل أن إصــاح الشــراء العــام فــي لبنــان ،رغــم تعقيــد ســياقه ،يســتند إلــى هيــكل تعــاون\n متقدمــةُ .\n دولــي متماســك وقابــل لالســتمرار ،قائــم علــى نقــل المعرفــة وتمكيــن الكــوادر الوطنيــة.\n .7التعاون الدولي ومؤشرات النتائج\n أ .أثر التعاون الدولي\nأدى التعــاون الدولــي دوراً محوريــاً فــي دعــم إصــاح نظــام الشــراء العــام فــي لبنــان ،مــن خــال مقاربــة تراكميــة\nومتكاملــة ســاهمت فــي تحويــل اإلطــار التشــريعي إلــى منظومــة تشــغيلية قابلــة للتطبيــق .وقــد أتــاح هــذا\nالتعــاون لهيئــة الشــراء العــام االســتفادة مــن خبــرات دوليــة متخصصــة ،وأدوات عمليــة ،ونمــاذج تنظيميــة\nمتقدمــة ،أســهمت فــي تعزيــز القــدرة المؤسســية ،تحســين جــودة اإلجــراءات ،وتوحيــد الممارســات علــى مســتوى ّ\nالجهــات الشــارية .كمــا ســاعد فــي تســريع التحـ ّـول الرقمــي ،إرســاء مبــادئ الشــفافية والعلنيــة ،وإدمــاج مفاهيــم\nاالســتدامة والنزاهــة ضمــن دورة الشــراء العــام .وبفضــل هــذا الدعــم ،تمكّ نــت الهيئــة مــن االنتقــال التدريجــي"}, {"o": 126, "l": "المادة 2", "b": "مــن مرحلــة التأســيس إلــى مرحلــة التشــغيل الفعلــي ،بمــا عــزّ ز قابليــة تطبيــق القانــون ،ورفــع مســتوى االمتثــال،\n ووضــع أســس مســتدامة إلصــاح الشــراء العــام علــى المدييــن المتوســط والطويــل.\n21مبادرة ( SIGMAدعم تحســين الحوكمة واإلدارة) هي ثمرة تعاون مشــترك بين منظمة التعاون االقتصادي والتنمية واالتحاد األوروبي\nتهــدف الــى تعزيــز أســس الحوكمــة العامــة وتحســين إدارة القطــاع العــام فــي الــدول الشــريكة ،بمــا يســاهم فــي تحقيــق التنميــة االجتماعيــة\nواالقتصاديــة مــن خــال تعزيــز قــدرات اإلدارة العامــة وإصــاح نظمهــا المؤسســية .تأسســت فــي العــام ،1992وتمتلــك خبــرة طويلــة فــي\nدعــم اإلدارات العامــة علــى المســتويات المختلفــة ،وتعمــل مــع شــركاء فــي مناطــق متعــددة تشــمل أوروبــا الشــرقية ،دول الجــوار األوروبي،\nوشــمال إفريقيــا ،مــن بينهــا لبنــان .تركّ ــز SIGMAدعمهــا فــي ســت مجــاالت رئيســية تتضمــن تطويــر السياســات ،تحســين األداء المؤسســي،\nاإلدارة الماليــة العامــة ،الرقابــة والمســاءلة ،وتقديــم الخدمــات والرقمنــة ،وذلــك بمــا يتماشــى مــع أفضــل الممارســات والمعاييــر الدوليــة.\nوتُ عنــى المبــادرة بشــكل خــاص بنظــم الشــراء العــام باعتبارهــا مــن الركائــز األساســية لفعاليــة اإلنفــاق العــام ورفــع مســتوى النزاهــة والكفــاءة.\n\f 106\n ب .مؤشرات أثر التعاون الدولي ()2025 - 2022\n المؤشرات الكمية اإلطار/المشروع الشريك الدولي\n • إعداد 4مشاريع مراسيم تنظيمية أساسية (النظام اإلداري\n والمالــي ،النظــام الوظيفــي ،النظــام الداخلــي ،ومشــروع مرســوم\n تعييــن رئيــس وأعضــاء الهيئــة).\n • وضع إطار متابعة وتقييم إلصالح الشراء العام ،وتطوير آليات\n جمع البيانات المرتبطة به."}, {"o": 127, "l": "المادة 2", "b": "• دعم تطوير إجراءات التدقيق والرقابة الداخلية لدى الجهات\n الشــارية ،بمــا فــي ذلــك رســم خرائــط المخاطــر وإعــداد أطــر تنظيميــة\n للتدقيــق الداخلــي.\n • توفير مساندة تقنية مباشرة لهيئة الشراء العام عبر خبير بدوام\n كامل لمواكبة التنفيذ وبناء القدرات المؤسسية.\n FEXTE Commande الوكالة الفرنسية للتنمية\n • تطوير أدوات الشراء العام ،بما في ذلك إنشاء صندوق أدوات\n Publique )AFD( /أكسبرتيز فرانس\n موّحدة لملفات التلزيم.ّ ( )Toolboxوتصميم نماذج\n ()2024 – 2021 Expertise France /\n • إعداد مسودة السياسة الوطنية للتدريب في مجال الشراء\n العام ،مرفقة بأدلة تشغيلية.\n • دعم تطوير منهجيات التدقيق الجنائي والتدقيق المحاسبي\n القانوني ورسم خرائط المخاطر المرتبطة بالشراء العام.\n • إعداد سياسات وأدوات تنفيذية في مجال الشراء العام\n المســتدام وتنظيــم دورات تدريبيــة متخصصــة حــول تطبيقهــا\n العملــي.\n التحّول الرقمي والشفافية من خالل إنشاء أول موقع ّ • دعم\n إلكترونــي لهيئــة الشــراء العــام ،شــّكّ ل النــواة األولــى لمنظومــة\n النشــر و العلنيــة.\nمقّر هيئة الشــراء العــام بالكامل (قاعات اجتماعات، ّ • تأهيــل وتجهيــز\nغرفــة ترجمــة ،تجهيــزات كهربائيــة احتياطيــة) بمــا يضمــن اســتمرارية\nالعمــل المؤسســي فــي ظــل االنقطاعــات المزمنــة للتيــار الكهربائــي\n (.)2024\n• تطوير وتأمين البنية التحتية الرقمية لهيئة الشراء العام (تجهيزات\nمعلوماتية ،برمجيات ،تراخيص ،وإنشاء غرفة خوادم ()Server Room\nمؤّمنــة لحمايــة البيانــات واســت