nكمحـ ّـرك أساســي لمســار إصــاح الشــراء العــام ،وســاهم فــي تهيئــة األرضيــة المؤسســية والتقنيــة لإلصــاح قبــل\nـودات إنشــاء الهيئــة .وقــد تجلّ ــى هــذا الــدور مــن خــال تطويــر األدوات األولــى ،كالنمــاذج وأول مجموعــة مــن مسـ ّ\nـودات أنظمــة الهيئــة، دفاتــر الشــروط ،ووضعهــا بمتنــاول هيئــة الشــراء العــام ،كذلــك المســاهمة فــي إعــداد مسـ ّ\nإضافــة إلــى مســاندة رئيــس الهيئــة عبــر توفيــر آليــات دعــم وتفســير لتســهيل تطبيــق القانــون فــي المراحــل األولــى\nكــرس القانــون مســتقبال بتشــغيل الهيئــة .وقــد ّ\n ً حيــز التنفيــذ ،وبنــاء قــدرات الكــوادر البشــرية المكلّ فــة\n لدخولــه ّ\nرقــم 2021/244دور المعهــد كجهــة وطنيــة مكلّ فــة بالتدريــب علــى أحكامــه ،مــا أضفــى علــى هــذه الشــراكة بعــداً\nمؤسســياً مســتداماً .ومــع إنشــاء هيئــة الشــراء العــام ،انتقلــت الشــراكة إلــى مرحلــة اإلطــاق والتشــغيل ،حيــث\nجــرى توقيــع مذكــرة تفاهــم بيــن الهيئــة والمعهــد يــوم إنشــائها ،أرســت إطــاراً مؤسســياً واضحــاً لتكامــل األدوار ،وال\nسـ ّـيما فــي مجــاالت التدريــب اإللزامــي ،والمســاندة التقنيــة ،ومواكبــة التطبيــق العملــي لقانــون الشــراء العــام ،بمــا"}, {"o": 131, "l": "المادة 2", "b": "يضمــن اســتمرارية الدعــم الفنــي وتكامــل الجهــود الوطنيــة مــع أطــر التعــاون الدولــي المســاندة لإلصــاح.\n .2العالقة مع مؤسسات المجتمع المدني\nشــكّ لت الشــراكة مــع منظمــات المجتمــع المدنــي إحــدى ركائــز مقاربــة هيئــة الشــراء العــام لتعزيــز الشــفافية\nوالمســاءلة فــي تطبيــق قانــون الشــراء العــام .وقــد حرصــت الهيئــة علــى إشــراك هــذه المنظمــات فــي مســار\nاإلصــاح باعتبارهــا شــريكاً رقابيــاً ومســانداً ،مــن خــال تبــادل المعلومــات ،والمشــاركة فــي النقاشــات التقنيــة،\nوإتاحــة الوصــول إلــى البيانــات المنشــورة علــى المنصــة اإللكترونيــة المركزيــة .وأســهم هــذا التعــاون فــي تعزيــز\nالرقابــة المجتمعيــة علــى عمليــات الشــراء العــام ،وترســيخ مبــادئ العلنيــة وإتاحــة المعلومــات ،ودعــم بنــاء الثقــة\n بيــن اإلدارة العامــة والمواطنيــن.\n .IVالخالصة\nـا فحســب ،بــل شــكّ ل رافعــة أساســية إلطــاق وتثبيــتمكمـ ً\n ّ ـايبيــن هــذا الفصــل أن التعــاون الدولــي لــم يكــن عامـ ً\n ّ\nإصــاح الشــراء العــام فــي لبنــان .وقــد ســاهم هــذا التعــاون فــي تحويــل النــص القانونــي إلــى منظومــة عمــل متكاملة،\nيمهــد لالنتقــال فــي المرحلــة المقبلــة مــن الدعــم الخارجــي إلــى التمكيــن المؤسســي واالســتدامة الوطنيــة. مــا ّ\n ويشــكّ ل هــذا التراكــم أساســاً مباشــراً لصياغــة األولويــات االســتراتيجية وخارطــة الطريــق المســتقبلية. ُ\n\f\f الفصل الثامن\nالتحديات والصعوبات\n\f جدول المحتويات\n112 .Iمقدمة\n112 .IIالسياق العام واألزمات المحيطة باإلصالح\n113 .IIIالتحديات على مستوى هيئة الشراء العام\n113 .IVالتحديات على المستوى القانوني\n114 .Vتحديات حوكمة نظام الشراء العام وإدارة التغيير\n115 .VIالتحديات على مستوى الجهات الشارية"}, {"o": 132, "l": "المادة 2", "b": "116 .VIIالتحديات على مستوى العالقة مع القطاع الخاص وجهوزية السوق\n116 .VIIIالتحديات على مستوى الشفافية والنزاهة والرقابة\n117 التحول الرقمي\n ّ .IXالتحديات على مستوى\n117 .Xالتحديات المتعلقة بالمستوى السياسي /اإلرادة السياسية\n118 .XIالخالصة\n\f 112\n الفصل الثامن :التحديات والصعوبات\n .Iمقدمة\nيمثــل مــا ســبق عرضــه مــن تطـ ّـور فــي مســار إصــاح منظومــة الشــراء العــام ومــا رافقــه مــن إنجــازات مؤسســية ّ\nأن هــذا\n وتشــغيلية ،اإلطــار اإليجابــي الــذي أتــاح االنتقــال التدريجــي نحــو التطبيــق العملــي للقانــون الجديــد .غيــر ّ\nتقدمــه ،اصطــدم بجملــة مــن التحديــات البنيويــة والســياقية التــي ّأثــرت علــى وتيــرة التنفيــذ\n المســار ،وعلــى الرغــم مــن ّ\nودرجــة تجانــس الممارســات .وانطالقــاً مــن ذلــك ،يتنــاول هــذا الفصــل أبــرز هــذه التحديــات علــى مختلــف المســتويات،\n تؤثــر علــى اســتكمال مســار اإلصــاح. بهــدف تقديــم قــراءة تحليليــة شــاملة للعوامــل التــي مــا زالــت ّ\n .IIالسياق العام واألزمات المحيطة باإلصالح\nينــدرج تحليــل التحديــات التــي واجهــت منظومــة الشــراء العــام وهيئــة الشــراء العــام ضمــن ســياق وطنــي اســتثنائي\nطبــع مســار اإلصالحــات العامــة فــي لبنــان منــذ العــام .2019فمنــذ خريــف ذلــك العــام ،شــهد لبنــان انهيــاراً اقتصاديــاً\nوماليــاً ونقديــاً غيــر مســبوق ،ترافــق مــع تفــكّ ك فــي أداء القطــاع المصرفــي وفــرض قيــود غيــر قانونيــة علــى\nالســحوبات والتحويــات ،مــا ّأدى إلــى فقــدان الثقــة بالنظــام المالــي وانعكــس مباشــرة علــى الــدورة االقتصاديــة\nوقــدرة الدولــة علــى الوفــاء بالتزاماتهــا .وفــي هــذا الســياق المتــأزّ مُ ،أقـ ّـر قانــون الشــراء العــام رقــم 2021/244ودخــل"}, {"o": 133, "l": "المادة 2", "b": "حيــز التنفيــذ فــي 29تمــوز ،2022أي فــي ذروة أزمــة متعـ ّـددة األبعــاد ،األمــر الــذي جعــل تطبيقــه أكثــر تعقيــداً مقارنــة ّ\n بالظــروف االعتياديــة.\nـادة علــى اإلنفــاق ،شــملت علــى المســتوى المالــيّ ،أدت األزمــة النقديــة وتقلّ ــص الموازنــات العامــة إلــى قيــود حـ ّ\nتأخيــر فتــح االعتمــادات ،ضعــف القــدرة علــى االلتــزام التعاقــدي طويل األمــد ،وتراجع جاذبية العقود العامة بالنســبة\nللقطــاع الخــاص ،مــا حـ ّـد مــن قــدرة الجهــات الشــارية علــى التخطيــط المســبق وتنفيــذ عمليــات شــراء متكاملــة وفــق\n األطــر الزمنيــة التــي يفترضهــا القانــون.\nعلــى المســتوى النقــدي ،أدى االنهيــار المتســارع فــي قيمــة العملــة الوطنيــة الــى إحجــام الشــركات الخاصــة عــن\n المشــاركة فــي المناقصــات.\nأما على المســتوى اإلداري ،فقد ســاهمت هجرة الكفاءات وتآكل الموارد البشــرية في إضعاف القدرة المؤسســية\nلــإدارات العامــة ،وال ســيما فــي الوظائــف التقنيــة والقانونيــة المرتبطــة بالشــراء العــام .كمــا ّأدت محدوديــة الحوافــز\nالوظيفيــة وتدنّ ــي االســتقرار الوظيفــي إلــى صعوبــة االســتثمار المســتدام فــي بنــاء القــدرات ،مــا انعكــس تفاوتــاً\n كبيــراً فــي مســتويات الجهوزيــة بيــن الجهات الشــارية.\nوفــي الســياق السياســي والمؤسســاتيّ ،أثــرت حــاالت الشــغور والتعطيــل المؤسســي وعــدم انتظــام العمــل\nوســمح فــي بعــض الحــاالت باســتمرار\n الحكومــي علــى القــدرة علــى فــرض االلتــزام المتجانــس بالقانــون الجديــدُ ،\n ممارســات اســتثنائية بعامــل الضــرورة.\nإضافــة إلــى ذلــك ،فرضــت األزمــات المتعــددة واقعــاً عمليــاً تناقــض فــي بعــض األحيــان مــع منطــق اإلصــاح القائــم"}, {"o": 134, "l": "المادة 2", "b": "علــى التخطيــط ،التنافســية ،والحوكمــة الرشــيدة ،إذ وجــدت اإلدارات نفســها أمــام ضغــوط آنيــة لتأميــن اســتمرارية\nالمرافــق العامــة فــي ظـ ّـل شـ ّـح المــوارد ،مــا ولّ ــد توتــراً دائمــاً بيــن متطلبــات االمتثــال القانونــي وحاجــات التشــغيل\n الفــوري.\nومــع ذلــكُ ،يظهــر هــذا الســياق الصعــب أن إصــاح الشــراء العــام لــم يكــن مجـ ّـرد مســار تقنــي معــزول ،بــل تجربــة\nإصــاح مؤسســي جــرت فــي قلــب األزمــة ،واختبــرت قــدرة الدولــة علــى إعــادة بنــاء أدواتهــا التنظيميــة فــي ظــروف\n بالغــة التعقيــد والهشاشــة ،مــا يضفــي علــى التحديــات المسـ ّـجلة بعــداً بنيويــاً يتجــاوز حــدود القانــون ذاتــه.\n\f113\n .IIIالتحديات على مستوى هيئة الشراء العام\nواجهــت هيئــة الشــراء العــام ،منــذ انطــاق عملهــا ،مجموعــة مــن التحديــات البنيويــة التــي ارتبطــت بطبيعة تأسيســها\n التوقعــات الملقــاة علــى عاتقهــا مقارنــة باإلمكانــات المتاحــة لهــا.\n ّ معقــد ،وبحجــم\n ّ فــي ســياق إصالحــي\nأوال ،شــكّ ل شــح المــوارد البشــرية أحــد أبــرز التحديــات التــي ّأثــرت علــى القــدرة التشــغيلية للهيئــة .فقــد باشــرت\n ً\nالهيئــة مهامهــا بتســعة موظفيــن بمــن فيهــم الرئيــس مــن أصــل 11كانــوا فــي ادارة المناقصــات الســابقة ،فــي\nوقــت كانــت فيــه مكلّ فــة بــأدوار تنظيميــة ورقابيــة وإرشــادية واســعة النطــاق ،شــملت إصــدار التوجيهــات ،تقديــم\nاآلراء ،مواكبــة الجهــات الشــارية ،وتطويــر المنصــة اإللكترونيــة .وقــد أدى هــذا االختــال بيــن حجــم المهــام والمــوارد\n المتاحــة إلــى ضغــط تشــغيلي مرتفــع وإلــى صعوبــة فــي توزيــع األعبــاء بشــكل مســتدام."}, {"o": 135, "l": "المادة 2", "b": "مؤثــر فــي قدرتهــا علــى االســتجابة ثانيــاً ،بــرز عــدم اســتكمال تعيينــات المراكــز القياديــة فــي الهيئــة كعامــل ّ\nوالقيــام بمهامهــا بالســرعة المطلوبــة ،إذ إن غيــاب تعييــن األعضــاء وفــق مــا نــص عليــه القانــون حـ ّـد مــن قــدرة الهيئــة\nـت فــي بعــض علــى العمــل بكامــل طاقتهــا المؤسســية ،وألقــى العــبء علــى رئيســها ،مــا انعكــس علــى ســرعة البـ ّ\n الملفــات.\nقيــد قدرتهــا علــىثالثــاً ،واجهــت الهيئــة غيــاب موازنــة تشــغيلية مســتقلة وشـ ّـح المــوارد الماليــة ،األمــر الــذي ّ\nالتخطيــط متوســط وطويــل األمــد ،وعلــى االســتثمار فــي تطويــر القــدرات البشــرية ،والبنيــة التحتيــة التقنيــة .وقــد\nفــرض هــذا الواقــع اعتمــاداً كبيــراً علــى الدعــم الخارجــي وعلــى إدارة المــوارد المتاحــة بأقصــى درجــات التقشــف ،فــي\n ســياق يتطلــب بطبيعتــه مــوارد مرنــة واســتجابة ســريعة.\nوأخيــراً ،وضعــت هــذه التحديــات الهيئــة أمــام معادلــة دقيقــة تقــوم علــى الموازنــة بيــن بنــاء المؤسســة مــن الداخــل\nوممارســة دورهــا اإلصالحــي علــى مســتوى المنظومــة ككل .وعلــى الرغــم مــن ذلــك ،واصلــت الهيئــة أداء مهامهــا\nمتقدمــاً مــن االلتــزام المؤسســي ،لكنــه فــي الوقــت نفســه يبــرز الحاجــة إلــى معالجــة\n ّ األساســية ،مــا يعكــس مســتوى\nهــذه التحديــات البنيويــة لضمــان اســتدامة الــدور المنــاط بهــا وتعزيــز فعاليــة اإلصــاح علــى المــدى المتوســط\n والطويــل.\n .IVالتحديات على المستوى القانوني\nشــكّ ل اإلطــار القانونــي الجديــد للشــراء العــام نقلــة نوعيــة مقارنــة بالنظــام الســابق ،إال أن عمليــة االنتقــال مــن"}, {"o": 136, "l": "المادة 2", "b": "منظومــة قانونيــة تقليديــة إلــى إطــار حديــث ومتقـ ّـدم كشــفت عــن جملــة مــن التحديــات القانونيــة التــي ّأثــرت علــى\n ســرعة التطبيــق وفاعليتــه خــال المرحلــة األولــى مــن اإلصــاح.\nتضمــن\n ّ مقدمــة هــذه التحديــات ،بــرزت الفجــوة بيــن النــص القانونــي ومتطلبــات التطبيــق العملــي .فقــد ّ فــي\nقانــون الشــراء العــام مفاهيــم وآليــات متقدمــة تســتند إلــى أفضــل الممارســات الدوليــة ،غيــر أن بعــض هــذه األحــكام\nـا ،ســواء عبــر المراســيم أو التعاميــم أو األدلــة اإلرشــادية.\n تطلّ ــب اســتكماله بنصــوص تطبيقيــة وتفســيرية أكثــر تفصيـ ً\nوقــد أدى التأخيــر النســبي فــي اســتكمال هــذه المنظومــة إلــى تــردد بعــض الجهــات الشــارية فــي اعتمــاد اإلجــراءات\nتعــرض\n الجديــدة بشــكل كامــل ،إن كان لســبب فجــوات فــي المعرفــة أو خشــية الوقــوع فــي أخطــاء قانونيــة أو ّ\n قراراتهــا للطعــن.\nكمــا واجــه التطبيــق تحديــاً مرتبطــاً باســتمرار نفــاذ نصــوص قانونيــة وتنظيميــة ســابقة فــي بعــض القطاعــات أو\nالمؤسســات العامــة ،مــا أوجــد حــاالت مــن التداخــل أو االلتبــاس فــي تحديــد القواعــد الواجبــة التطبيــق .وقــد تطلّ ــب\nتعــدد\n ّ متواصــا لتوضيــح أولويــة قانــون الشــراء العــام ونطــاق ســريانه ،وال ســيما فــي ظــل\n ً ذلــك جهــداً تفســيرياً\n القوانيــن الخاصــة واألنظمــة الداخليــة التــي اعتــادت الجهــات العامــة الرجــوع إليهــا.\nومــن التحديــات القانونيــة البــارزة أيضــاً تبـ ّـدل األدوار والمســؤوليات القانونيــة داخــل اإلدارة .فقــد نقــل القانــون\nوحدد بوضوح مســؤوليات ّ الجديــد جــزءاً مــن الســلطة التقديريــة مــن المرجعيــات التقليديــة إلــى آليات أكثر مؤسســية،\n\f 114\nللتكيــف ،ســواء علــى"}, {"o": 137, "l": "المادة 2", "b": "ّ الجهــات الشــارية وهيئــة الشــراء العــام واللجــان المختصــة .غيــر أن هــذا التحـ ّـول اســتلزم وقتــاً\n مســتوى الثقافــة القانونيــة الســائدة أو علــى مســتوى ممارســات االستشــارة القانونيــة داخــل اإلدارات.\nإضافــة إلــى ذلــك ،أظهــرت الممارســة الحاجــة إلــى تعزيــز القــدرات القانونيــة المتخصصــة فــي مجــال الشــراء العــام،\nمعمقــاً لمبــادئ\n ّ إذ لــم يعــد كافيــاً االعتمــاد علــى مقاربــات قانونيــة عامــة ،بــل بــات تطبيــق القانــون يتطلــب فهمــاً\nالمنافســة ،الشــفافية ،إدارة المخاطــر ،وتســوية النزاعــات التعاقديــة .وقــد شــكّ ل تفــاوت هــذه القــدرات بيــن الجهــات\n تحديــاً إضافيــاً أمــام التطبيــق المتجانــس للقانــون.\nوتعكــس هــذه التحديــات واقــع أن نجــاح اإلصــاح القانونــي ال يرتبــط بجــودة النــص وحدهــا ،بــل بمــدى تكامــل اإلطــار\nالتحــول القانونــي وتطبيقــه بثقــة\n ّ التشــريعي والتنظيمــي ،ووضــوح التفســيرات ،وقــدرة اإلدارة علــى اســتيعاب\n واســتقرار.\n .Vتحديات حوكمة نظام الشراء العام وإدارة التغيير\nشــكّ لت حوكمــة نظــام الشــراء العــام وإدارة التغييــر أحــد أكثــر المحــاور تعقيــداً فــي مســار اإلصــاح ،نظــراً الرتباطهــا\nالمباشــر بتــوازن الصالحيــات المؤسســية ،وبالتحـ ّـول الثقافــي المطلــوب لالنتقــال مــن ممارســات تقليديــة إلــى نظــام\n حديــث قائــم علــى الشــفافية والمســاءلة.\nأوال ،واجــه النظــام مقاومــة متفاوتــة للتغييــر ،وهــي ظاهــرة طبيعيــة فــي ســياق أي إصالح هيكلي واســع النطاق. ً\nالتمســك ببعــض الممارســات الســابقة ،أو فــي بحــث بعــض الجهــات الشــارية عــن ّ وقــد تجلّ ــت هــذه المقاومــة فــي\nالموحــد .وتعكــس هــذه"}, {"o": 138, "l": "المادة 2", "b": "ّ اســتثناء نفســها مــن تطبيــق القانــون ،أو فــي اللجــوء إلــى قنــوات موازيــة خــارج النظــام\nتحديــاً ثقافيــاً عميقــاً يتجــاوز الجوانــب التقنيــة أو القانونيــة ،ويتطلــب وقتــاً ومقاربــة تراكميــة لترســيخ\n الســلوكيات ّ\n الثقــة فــي النظــام الجديــد.\n ّ\nالمؤثرة، ثانيــاً ،بــرز تشــابك الصالحيــات وتداخــل األدوار بيــن الجهــات المعنيــة بالحوكمــة والرقابــة كأحــد التحديــات\nحيــث إن تعــدد المتدخليــن فــي منظومــة الشــراء العــام تطلّ ــب جهــداً مســتمراً لتوضيــح الحــدود الوظيفيــة وتعزيــز\nالتنســيق المؤسســي .وقــد ّأدى هــذا التشــابك ،فــي بعــض الحــاالت ،إلــى إبطــاء اتخــاذ القــرار أو إلــى تفســيرات\n متباينــة لــأدوار ،مــا انعكــس علــى فعاليــة الحوكمــة الشــاملة للنظــام.\n ثالثــاً ،شــكّ ل غيــاب هيئــة االعتراضــات المنصــوص عليهــا فــي القانــون ثغــرة مؤسســية ّ\nمؤثــرة ،إذ أدى عــدم تفعيــل\nوفعالــة للنظــر فــي االعتراضــات فــي مرحلــة مــا قبــل توقيــع العقــد إلــى كثافــة ملفــات امــام قضــاء\n ّ آليــة مســتقلة\nرد علــى مراجعــات مــا ادى الــى ضغــط تدخــل لهيئــة الشــراء العــام وطلبــات ّ\n العجلــة االداري تزامنــت مــع طلبــات ّ\nمتزايــد عليهــا ،وإلــى االعتمــاد علــى قنــوات بديلــة لمعالجــة الخالفــات ،مــا حـ ّـد مــن اكتمــال منظومــة الضمانــات\n القانونيــة المرافقــة لإلصــاح.\n ّ\nيتمثــل فــي غيــاب مأسســة مهنــة الشــراء العــام ،فعلــى الرغــم مــن النــص الصريــح فــي المــادة رابعــاً ،بــرز تحـ ٍّـد بنيــوي\n 73مــن القانــون ،لــم يتـ ّـم بعــد إقــرار نظــام اعتمــاد وطنــي ،أو وضــع أوصــاف وظيفيــة موحــدة ،أو تحديــد مســارات"}, {"o": 139, "l": "المادة 2", "b": "واضحــة للتطـ ّـور المهنــي .وقــد انعكــس هــذا الغيــاب علــى اســتدامة القــدرات داخــل اإلدارة العامــة ،وعلــى القــدرة\n فعالــة للنظــام.23\n علــى بنــاء جســم مهنــي متخصــص يشــكّ ل ركيــزة أساســية لحوكمــة ّ\nوتُ ظهــر هــذه التحديــات مجتمعــة أن نجــاح إصــاح الشــراء العــام ال يتوقــف علــى جــودة اإلطــار القانونــي فحســب،\nبــل يرتبــط بشــكل وثيــق بقــدرة المنظومــة علــى ترســيخ حوكمــة واضحــة ،وتعزيــز إدارة التغييــر ،وبنــاء هيــاكل\n مؤسســية داعمــة تضمــن االنتقــال مــن االلتــزام الشــكلي إلــى التطبيــق الفعلــي والمســتدام.\n تم بالفعل الشروع في تنفيذ األعمال ذات الصلة.\n فعال في إطار مشروع ،RAPوقد ّ\n ً 23مع العلم ّأن العمل على مأسسة الشراء قد بدأ\n\f115\n .VIالتحديات على مستوى الجهات الشارية\nشــكّ لت الجهــات الشــارية الحلقــة التنفيذيــة األساســية فــي منظومــة الشــراء العــام ،وبالتالــي بــرزت علــى هــذا\nالمســتوى مجموعــة مــن التحديــات التــي ّأثــرت بشــكل مباشــر علــى جــودة التطبيــق ووتيرتــه ،وعلــى درجــة االمتثــال\n لإلطــار القانونــي الجديــد.\nأوال ،أظهــرت التقييمــات وجــود فجــوات واضحــة فــي القــدرات والمعرفــة بيــن الجهــات الشــارية ،ســواء لناحيــة ً\nاإللمــام بأحــكام قانــون الشــراء العــام وإجراءاتــه ،أو مــن حيــث القــدرة علــى التخطيــط المســبق ،إعــداد دفاتــر الشــروط،\nإدارة اإلجــراءات التنافســية ،ومتابعــة تنفيــذ العقــود ،مــا أدى إلــى تفــاوت ملمــوس فــي مســتوى االمتثــال ألحكام\n القانــون الجديــد.\nالمحقــق ،ال تــزال مؤشــرات عــدم االلتــزام قائمــة فــي بعــض الحــاالت ،ســواء لجهــة\n ّ ثانيــاً ،وعلــى الرغــم مــن التقـ ّـدم\nوينظــر إلــى هــذه"}, {"o": 140, "l": "المادة 2", "b": "النشــر الكامــل ،أو احتــرام المهــل القانونيــة ،أو اختيــار طريقــة الشــراء األنســب لطبيعــة الشــراءُ .\nالمؤشــرات بوصفهــا عناصــر إنــذار مبكــر تســتوجب المعالجــة الوقائيــة والتصحيحيــة ،وليــس العقابيــة فقــط ،مــع\nالموحــد لإلجــراءات علــى مختلــف المســتويات.\n ّ التركيــز علــى ترســيخ ثقافــة االمتثــال المؤسســي وضمــان التطبيــق\nثالثــاً ،بــرز ضعــف التخطيــط المســبق للشــراء كإحــدى اإلشــكاليات البنيويــة ،حيــث غالبــاً مــا يتــم اللجــوء إلــى إجــراءات\nمحدثة ومبنية على تقدير واقعي لالحتياجات واالعتمادات ّ متسـ ّـرعة أو اســتثنائية نتيجة غياب خطط شــراء ســنوية\n الماليــة .ويــؤدي هــذا الضعــف إلــى تقليــص هامــش المنافســة ،وزيــادة مخاطــر اللجــوء إلــى إجــراءات غيــر تنافســية.\nرابعــاً ،واجهــت الجهــات الشــارية تحديــات متعلقــة بالجهوزيــة الرقميــة واالســتخدام غيــر المتكامــل للمنصــة\nالتكيــف مــع البيئــة الرقميــة الجديــدة .وقــد ّ اإللكترونيــة ،إذ تفاوتــت مســتويات االســتعداد التقنــي والقــدرة علــى\nترافــق ذلــك مــع فجــوات فــي األرشــفة اإللكترونيــة وفــي انتظــام إدخــال البيانــات ،مــا ّأثــر علــى االســتفادة الكاملــة\n مــن وظائــف المنصــة وعلــى جــودة المعلومــات المتاحــة.\nمؤثــراً فــي مســتوى التطبيــق ،ويعــودـا ّ خامســاً ،شــكّ لت محدوديــة التدريــب ،خاصــة فــي مرحلــة االنطالقــة ،عامـ ً\nذلــك إلــى مجموعــة مــن األســباب المتداخلــة ،أبرزهــا نقــص المــوارد البشــرية المتخصصــة فــي التدريب ،حجــم الحاجات\nالكبيــرة علــى مســتوى مختلــف الجهــات الشــارية ،القيــود التــي فرضتهــا جائحــة كورونــا ومــا رافقهــا مــن انتقــال"}, {"o": 141, "l": "المادة 2", "b": "قســري إلــى التدريــب عــن ُبعــد ،إضافــة إلــى شـ ّـح الموازنــات المخصصــة للتدريــب وبنــاء القــدرات.\nسادســاً ،برزت إشــكاليات مرتبطة بـــوحدات الشــراء العام داخل الجهات الشــارية ،حيث لم تُ ســتكمل في العديد من\nالحــاالت عمليــة إنشــاء هــذه الوحــدات أو تفعيلهــا بالشــكل المنشــود ،كمــا ُسـ ّـجل نقــص فــي الكفــاءات المتخصصــة\n القــادرة علــى تولــي مهــام الشــراء بشــكل احترافــي ومســتدام.\nأخيــراً ّ ،أثــرت األزمــة االقتصاديــة والماليــة باإلضافــة الــى تدنّ ــي الحوافــز بشــكل مباشــر علــى أداء الجهــات الشــارية ،إذ\nســاهمت الرواتــب المنخفضــة فــي القطــاع العــام ،إلــى جانــب الخــوف مــن المســاءلة القانونيــة أو اإلداريــة ،وغيــاب\nحوافــز األداء ،فــي إحجــام عــدد مــن الكفــاءات عــن االنخــراط فــي لجــان التلزيــم أو تولّ ــي أدوار متقدمــة فــي\n الشــراء العــام ،مــا انعكــس علــى اســتدامة القــدرات داخــل اإلدارة.\n وتُ ظهــر هــذه التحديــات أن الجهــات الشــارية ّ\nتمثــل نقطــة االرتــكاز األساســية لنجــاح اإلصــاح ،وفــي الوقــت نفســه\n الحلقــة األكثــر تأثــراً بتراكــم التحديــات المؤسســية والســياقية.\n\f 116\n .VIIالتحديات على مستوى العالقة مع القطاع الخاص وجهوزية السوق\nشــكّ لت العالقــة مــع القطــاع الخــاص أحــد المحــاور الحاســمة فــي نجــاح إصــاح منظومــة الشــراء العــام ،إذ ال يقتصــر\nهــذا اإلصــاح علــى تطويــر اإلطــار القانونــي واإلداري فحســب ،بــل يفتــرض أيضــاً وجــود «ســوق» قــادرة علــى التفاعل\n مــع القواعــد الجديــدة واالســتجابة لمتطلباتهــا.\nفــي هــذا الســياق ،بــرزت تحديــات مرتبطــة بجهوزيــة الســوق والمشـ ّـغلين االقتصادييــن ،حيــث لــم تكــن جميــع\nللتكيــف مــع نظــام شــراء يقــوم علــى"}, {"o": 142, "l": "المادة 2", "b": "ّ مهيــأة بالكامــل\n ّ الشــركات ،وال ســيما المؤسســات الصغيــرة والمتوســطة،\nالمنافســة المفتوحــة ،والشــفافية ،واســتخدام المنصــات الرقميــة .وقــد تجلّ ــى ذلــك فــي محدوديــة معرفــة بعــض\nالمشـ ّـغلين االقتصادييــن باإلجــراءات الجديــدة ،وفــي تفــاوت قدرتهــم علــى إعــداد عــروض مســتوفية للمعاييــر الفنيــة\n واإلداريــة المطلوبــة.\nكمــا انعكــس هــذا الواقــع علــى مســتوى المنافســة فــي عــدد مــن القطاعــات ،حيــث ُسـ ّـجلت حــاالت ضعــف فــي\nاإلقبــال علــى المشــاركة أو اقتصــار المنافســة علــى عــدد محــدود مــن العارضيــن ،األمــر الــذي تطلّ ــب جهــوداً إضافيــة\n لتعزيــز التوعيــة وبنــاء قــدرات القطــاع الخــاص ،وتشــجيع مشــاركة أوســع وأكثــر تنوعــاً.\nإضافــة إلــى ذلــك ،بــرز تحـ ٍّـد أساســي يتمثــل فــي إعــادة بنــاء الثقــة بيــن القطــاع العــام والمشـ ّـغلين االقتصادييــن،\nظــل تراكــم تجــارب ســابقة ســلبية مرتبطــة بتأخــر الدفعــات ،وعــدم انتظــام االلتزامــات الماليــة ،وتعقيــدات ّ فــي\nاإلجــراءات .وقــد ســاهم هــذا العامــل فــي زيــادة حــذر بعــض شــركات القطــاع الخــاص أو إحجامهمــا عــن المشــاركة،\n وال ســيما فــي العقــود طويلــة األمــد أو تلــك المسـ ّـعرة بالعملــة الوطنيــة.\nـا مؤثــراً فــي ســلوك الســوق ،إذ أدى عــدم انتظــام تســديد\n تأخــر الدفــع وقيــود النظــام المصرفــي عامـ ً\n كمــا شــكّ ل ّ\nالمســتحقات إلــى رفــع كلفــة المخاطــر التــي يتحملهــا الملتزمــون ،وانعكــس فــي بعــض الحــاالت علــى األســعار\n المقدمــة أو علــى قــرار المشــاركة مــن األســاس.\n ّ\nوتُ ظهــر هــذه التحديــات أن تعزيــز فعاليــة نظــام الشــراء العــام يتطلــب مقاربــة متوازنــة ال تقتصــر علــى رفــع مســتوى"}, {"o": 143, "l": "المادة 2", "b": "امتثــال الجهــات الشــارية ،بــل تمتــد إلــى تمكيــن الســوق ،وتعزيــز الثقة المتبادلــة ،وتوفير بيئة تعاقدية مســتقرة\n تشـ ّـجع المشــاركة والمنافســة وتدعــم تحقيــق القيمــة الفضلــى مــن إنفــاق المــال العــام.\n .VIIIالتحديات على مستوى الشفافية والنزاهة والرقابة\nُيعـ ّـد تعزيــز الشــفافية والنزاهــة أحــد األهــداف الجوهريــة إلصــاح نظــام الشــراء العــام ،غيــر أن ترجمــة هــذه المبــادئ\nفعالــة واجهــت عــدداً مــن التحديــات العمليــة التــي بــرزت بشــكل خــاص خــال مرحلــة إلــى ممارســات مؤسســية ّ\n االنتقــال إلــى اإلطــار القانونــي الجديــد.\nـب التركيــز\n فــي هــذا الســياق ،كشــفت الممارســة عــن ضعــف نســبي فــي أنظمــة متابعــة تنفيــذ العقــود ،حيــث انصـ ّ\nتاريخيــاً فــي العديــد مــن الجهــات الشــارية علــى مراحــل التلزيــم واإلرســاء ،مقابــل اهتمــام أقـ ّـل بمرحلــة التنفيــذ وإدارة\nاألداء التعاقــدي .وقــد أدى هــذا الخلــل إلــى محدوديــة القــدرة علــى رصــد االنحرافــات أثنــاء التنفيــذ ،ومعالجــة التأخيــر\nأو عــدم االلتــزام بالمواصفــات فــي الوقــت المناســب ،مــا أضعــف األثــر الكامــل إلجــراءات الشــفافية المعتمــدة فــي\n المراحــل الســابقة للتعاقــد.\nملحــة إلــى تعزيــز نضــج أنظمــة الرقابــة والتدقيــق داخــل إضافــة إلــى ذلــك ،أظهــرت المرحلــة االنتقاليــة حاجــة ّ\nالجهــات الشــارية .فاالنتقــال إلــى نظــام شــراء أكثــر شــفافية ورقمنــة يتطلّ ــب مقاربــات رقابــة وتدقيــق قائمــة علــى\n المخاطــر ،وأدوات قــادرة علــى تحليــل البيانــات ،وليــس االكتفــاء بالرقابــة الشــكلية أو اإلجرائيــة.\nوتبيــن هــذه التحديــات أن ترســيخ الشــفافية والنزاهــة فــي منظومــة الشــراء العــام ال يتحقــق فقــط مــن خــال ّ\n\f117"}, {"o": 144, "l": "المادة 2", "b": "فعالــة للعقــود ،وتكامــل النصــوص القانونيــة أو آليــات النشــر ،بــل يســتلزم منظومــة رقابيــة متكاملــة تشــمل إدارة ّ\nالمعلومــات ،وقــدرات رقابــة وتدقيــق قــادرة علــى مواكبــة التعقيــد المتزايــد للنظــام ،بمــا يعــزّ ز الثقــة العامــة ويحـ ّـد\n مــن مخاطــر ســوء اإلدارة والفســاد.\n التحول الرقمي\n ّ .IXالتحديات على مستوى\nشــكّ ل التحـ ّـول الرقمــي أحــد الركائــز األساســية إلصــاح منظومــة الشــراء العــام ،وال ســيما مــن خــال إطــاق المنصــة\nموحــدة كشــف عــنّ اإللكترونيــة المركزيــة .غيــر أن االنتقــال مــن بيئــة إداريــة ورقيــة ومجــزّ أة إلــى منظومــة رقميــة\nمجموعــة مــن التحديــات التقنيــة والتنظيميــة التــي ّأثــرت علــى ســرعة االســتفادة الكاملــة مــن اإلمكانــات المتاحــة.\nفــي هــذا اإلطــار ،بــرزت تحديــات متعلقــة بجــودة البيانــات وتوحيدهــا ،ســواء علــى مســتوى إدخــال المعلومــات أو\nتصنيفهــا أو اكتمالهــا ،مــا انعكــس مباشــرة علــى القــدرة علــى إنتــاج مؤشــرات دقيقــة وموثوقــة بشــكل فــوري .فقــد\nالموحــدة إلدخــال البيانــات فــي المراحــل األولــى ،إلــى\n ّ ّأدى تفــاوت ممارســات الجهــات الشــارية ،وضعــف المعاييــر\n الحـ ّـد مــن قابليــة اســتخدام البيانــات ألغــراض التحليــل ،المتابعــة ،وصنــع القــرار .\n 24\nكمــا واجهــت عمليــة الرقمنــة مشــاكل تقنيــة وتحديــات مرتبطــة بالبنيــة التحتيــة الرقميــة ،شــملت محدوديــة\nاالتصــال باإلنترنــت فــي بعــض اإلدارات ،تفــاوت جهوزيــة األنظمــة الداخليــة لــدى الجهــات الشــارية ،والضغــط\nالتشــغيلي المتزايــد علــى المنصــة .وقــد فــرض ذلــك اعتمــاد حلــول مرحليــة ،خاصــة فــي المرحلــة األولــى لتطبيــق\n اإلصــاح."}, {"o": 145, "l": "المادة 2", "b": "أمــا علــى مســتوى جهوزيــة المنصــة نفســها ،فقــد أظهــرت مرحلــة التشــغيل الحاجــة إلــى تطويــر مســتمر لبعــض\nالوظائــف ،واســتكمال وحــدات أساســية ،وتحســين واجهــة االســتخدام بمــا يتــاءم مــع تنـ ّـوع المســتخدمين وتعقيــد\nويعـ ّـد ذلــك تحديــاً طبيعيــاً فــي مســار بنــاء أنظمــة وطنيــة جديــدة ،إال أنــه شــكّ ل فــي المراحــل األولــى\n اإلجــراءاتُ .\n ـردد بعــض المســتخدمين أو لجوئهــم إلــى حلــول موازيــة. ـا إضافيــاً فــي تـ ّ\n عامـ ً\nويؤكــد مجمــوع هــذه التحديــات أن التحـ ّـول الرقمــي فــي الشــراء العــام ليــس مســألة تقنيــة بحتــة ،بل مســار مؤسســي\nمتكامــل ،يتطلّ ــب تالزمــاً بيــن تطويــر األنظمــة ،تحســين جــودة البيانــات ،بنــاء القــدرات البشــرية ،وتوحيــد الممارســات،\n لضمــان تحقيــق األثــر المنشــود مــن الرقمنــة علــى مســتوى الشــفافية والكفــاءة والمســاءلة.\n .Xالتحديات المتعلقة بالمستوى السياسي /اإلرادة السياسية\nعلــى الرغــم مــن إقــرار قانــون الشــراء العــام ومــا يحملــه مــن توجــه إصالحــي واضــح ،واجــه التطبيــق العملــي تحديــات\nان عدم انتظام عمل الســلطة التنفيذية ومحدودية الدعم السياســي مرتبطة بمســتوى االلتزام السياســي ،إذ ّ\nالمســتمر والمنتظــم ّأثــرا ســلباً علــى توفيــر الغطــاء السياســي واإلداري الــازم لدعــم اإلصــاح ،وعلــى تعزيــز االلتــزام\n المتجانــس بــه علــى مختلف المســتويات.\nوفــي هــذا الســياق ،شــكّ ل عــدم اســتكمال التعيينــات المنصــوص عليهــا فــي القانــون مــن قبــل مجلــس الــوزراء،\nمقيــداً لمســار اإلصــاح إذ أبقــى بعــض\n عامــا ّ\n ً وال ســيما علــى مســتوى هيئــة الشــراء العــام وهيئــة االعتراضــات،"}, {"o": 146, "l": "المادة 2", "b": "المكونــات األساســية للمنظومــة فــي إطــار غيــر مكتمــل ،مــا حـ ّـد مــن قدرتهــا علــى العمــل بكامــل طاقتهــا القانونيــة\n ّ\n والتنظيميــة.\nالمنصــة قــد عالجــت بالفعــل جــزءاً مــن هــذه اإلشــكالية ،مــن خــال تحســين جــودة البيانــات\n ّ حدثــة مــن\n الم َّ\n 24تجــدر اإلشــارة إلــى ّأن النســخة ُ\n ـكل ملحــوظ.\n واتســاقها بشـ ٍ\n\f 118\nكمــا ُيعـ ّـد عــدم إنشــاء هيئــة االعتراضــات حتــى تاريخــه مؤشــراً إضافيــاً علــى محدوديــة الدفــع السياســي الســتكمال\nعناصــر اإلصــاح ،إذ إن غيــاب هــذه الهيئــة حــرم النظــام من آلية مســتقلة ومؤسســية لمعالجــة االعتراضات والنزاعات\n وفعــال فــي مرحلــة مــا قبــل توقيــع العقــدّ ،\nوأثــر علــى اكتمــال منظومــة الضمانــات القانونيــة ،وعلــى ّ بشــكل ســريع\n ثقــة القطــاع الخــاص بفعاليــة النظــام وعدالتــه.\nوتُ ظهــر هــذه التحديــات أن إصــاح الشــراء العــام ،رغــم متانتــه القانونيــة والتقنيــة ،يبقــى رهنــاً بتوافــر إرادة سياســية\nواضحــة ومســتمرة ،قــادرة علــى تحويــل االلتزامــات التشــريعية إلــى قــرارات تنفيذيــة ،واســتكمال التعيينــات والهيــاكل\nالمنصــوص عليهــا ،وتوفيــر الغطــاء السياســي الــازم لحمايــة اإلصــاح مــن التعطيــل أو التــآكل ،وضمــان انتقالــه مــن\n مرحلــة التأســيس إلــى مرحلــة االســتقرار المؤسســي.\n .XIالخالصة\nأن إصــاح منظومــة الشــراء العــام فــي لبنــان لــم يكــن تُ ظهــر التحديــات التــي تـ ّـم اســتعراضها فــي هــذا الفصــل ّ\nبتعــدد\n ّ معــزوال ،بــل عمليــة إصــاح مؤسســي عميقــة نُ ّفــذت فــي ظــل ظــروف اســتثنائية اتّ ســمت ً مســاراً تقنيــاً\n األزمــات وتداخلهــا .فقــد تفاعلــت التحديــات الســياقية ،والمؤسســية ،والتشــغيلية ،والتقنيــة ،والسياســية ّ"}, {"o": 147, "l": "المادة 2", "b": "لتؤثــر علــى\nويبــرز هــذا\n وتيــرة التطبيــق ودرجــة تجانســه ،دون أن تُ لغــي فــي المقابــل المســار اإلصالحــي الــذي أطلقــه القانــونُ .\nتعبــر عــن فجــوة بيــن الطمــوح\n الواقــع أن العوائــق القائمــة ال تعكــس بالضــرورة قصــوراً فــي اإلطــار القانونــي بقــدر مــا ّ\nهشــة .وعليــه ،فــإن تجــاوز هــذه التحديــات يســتدعي مقاربــة شــاملة تقــوم التشــريعي ومتطلبــات التنفيــذ فــي بيئــة ّ\nعلــى اســتكمال البنــى المؤسســية ،تعزيــز المــوارد والقــدرات ،وترســيخ إرادة سياســية واضحــة ومســتدامة ،بمــا\nيســمح باالنتقــال مــن مرحلــة إدارة اإلصــاح فــي ظــل األزمــة إلــى مرحلــة ترســيخه كسياســة عامــة مســتقرة وقابلــة\n لالســتدامة.\n\f\f الفصل التاسع\nاألولويات االستراتيجية وخارطة الطريق\n\f جدول المحتويات\n122 .Iمقدمة\n122 .IIالرؤية واألهداف االستراتيجية\n122 .1الرؤية االستراتيجية\n122 .2األهداف االستراتيجية المتوسطة المدى\n122 .IIIالمحاور االستراتيجية التنفيذية\n122 .1التعزيز المؤسسي واستكمال مالك الهيئة\n123 التحول الرقمي والشراء اإللكتروني المتكامل\n ّ .2\n123 .3التطوير التشريعي المستمر وتحسين حوكمة اإلجراءات\n123 .4تعزيز النزاهة وإدارة المخاطر والرقابة المتكاملة\n124 .5حوكمة الشراء العام في حاالت األزمات والطوارئ\n124 .6التخصص وبناء القدرات والثقافة المؤسسية\n124 .7تعزيز الشراكات االستراتيجية والتعاون متعدد القطاعات\n124 .IVعوامل النجاح والمخاطر التنفيذية\n124 .Vإطار المتابعة والحوكمة\n125 .VIالخالصة\n\f 122\n الفصل التاسع :األولويات االستراتيجية وخارطة الطريق\n .Iمقدمة\nشــكّ ل إقــرار قانــون الشــراء العــام وإنشــاء هيئــة الشــراء العــام نقطــة تحـ ّـول أساســية فــي مســار إصــاح منظومــة"}, {"o": 148, "l": "المادة 2", "b": "الشــراء العــام فــي لبنــان ،وانتقــل باإلصــاح مــن مرحلــة التشــريع إلــى مرحلــة التفعيــل التدريجــي فــي ســياق وطنــي\nشــديد التعقيــد .وقــد أظهــرت الفصــول الســابقة مــن هــذا التقريــر أن الهيئــة ،وعلــى الرغــم مــن محدوديــة المــوارد\nوالتحديــات االقتصاديــة والمؤسســية المتراكمــة ،اســتطاعت أن تضــع األســس التنظيميــة والتشــغيلية األولــى ،وأن\n تطلــق أدوات مركزيــة للشــفافية والرقمنــة وبنــاء القــدرات المؤسســية.\n ّ\nيتمثــل فــي ترســيخه وضمــان وانطالقــاً مــن هــذا الواقــع ،لــم يعــد التحـ ّـدي محصــوراً فــي إطــاق اإلصــاح ،بــل بــات\nتوجهــات اســتراتيجية وخارطــة طريــق متوســطة اســتدامته وتعميــق أثــره .مــن هنــا ،يهــدف هــذا الفصــل إلــى رســم ّ\nالمحصلــة الثالثــة مــن االســتراتيجية\n ّ المــدى ،تســتند إلــى أحــكام القانــون رقــم ،2021/244وتتــواءم مــع أهــداف\nالتوجهــات\n ّ الوطنيــة لمكافحــة الفســاد ،الراميــة إلــى إرســاء «منظومــة شــراء عــام أقــل عرضــة للفســاد» .وتُ صــاغ هــذه\nانطالقــاً مــن اإلنجــازات المحققــة ،لتحـ ّـدد أولويــات العمــل للمرحلــة المقبلــة ،بمــا يراعــي الســياق اللبنانــي ومتطلبــات\n الواقعيــة التنفيذيــة.\n .IIالرؤية واألهداف االستراتيجية\n .1الرؤية االستراتيجية\n ّ\nتتمثــل الرؤيــة االســتراتيجية لهيئــة الشــراء العــام فــي الوصــول ،علــى المــدى المتوســط ،إلــى منظومــة شــراء عــام\nشــفافة رقميــة ،متخصصــة مهنيــاً ،تعمــل ضمــن إطــار تشــريعي مــرن وقابــل للتطويــر ،وتعــزّ ز النزاهــة والمســاءلة،\nوتدعــم التنميــة المســتدامة ،وتُ ســهم فــي تقليــص الهــدر واالنحــراف فــي اإلنفــاق العــام ،تماشــياً مــع أحــكام\n القانــون 2021/244والمعاييــر الدوليــة المعتمــدة."}, {"o": 149, "l": "المادة 2", "b": ".2األهداف االستراتيجية المتوسطة المدى\n ترتكز التوجهات االستراتيجية على مجموعة من األهداف المتوسطة المدى ،أبرزها:\n • استكمال البنية المؤسسية الناظمة والرقابية المنصوص عليها قانوناً ؛\n موحدة ومعتمدة عبر جميع الجهات الشارية؛ ّ • ترسيخ الشراء اإللكتروني كقاعدة تشغيلية\n • تحويل الرقابة من نمط شكلي إلى رقابة استباقية قائمة على إدارة المخاطر وتحليل البيانات؛\n • إرساء الشراء العام كمهنة متخصصة ومعتمدة ضمن الهيكل الوظيفي للدولة؛\n • ضمان مرونة إجرائية واضحة ومنضبطة للتعامل مع حاالت الطوارئ دون المساس بمبادئ الشفافية\n والمنافسة.\n .IIIالمحاور االستراتيجية التنفيذية\n .1التعزيز المؤسسي واستكمال مالك الهيئة\nُيعـ ّـد اســتكمال البنــاء المؤسســي لهيئــة الشــراء العــام شــرطاً أساســياً الســتدامة اإلصــاح ،كمــا ّبينــه الفصــل الثامــن.\n وتشــمل األولويــات فــي هــذا المحور:\n • استكمال المالك الوظيفي وفق الهيكلية المعتمدة ،واستكمال التعيينات المنصوص عليها قانونًاً ؛\n • تعزيز االستقاللية التشغيلية واإلدارية للهيئة عبر تأمين الموارد البشرية المتخصصة والموازنات التشغيلية\n المالئمة؛\n\f123\n • ترسيخ أنظمة العمل الداخلية واإلجراءات القياسية ،وتطوير آليات التخطيط والمتابعة والتقييم؛\nالمقّر وتجهيزه بالبنى التقنية الالزمة ،واستقطاب المساعدة\n ّ • تحسين الجهوزية المؤسسية من خالل تأهيل\n الفنية المتخصصة.\nويهــدف هــذا المحــور إلــى االنتقــال مــن هيئــة ناشــئة تعتمــد جزئيــاً علــى الدعــم الخارجــي ،إلــى مؤسســة تعتمــد علــى\n قدراتهــا ومواردهــا الذاتيــة مــا يمكّ نهــا مــن اداء مهامهــا بكفــاءة واســتقاللية.\n التحول الرقمي والشراء اإللكتروني المتكامل ّ .2\nأظهــر الفصــان الخامــس والســادس أن المنصــة اإللكترونيــة المركزيــة شــكّ لت ركيــزة أساســية لتعزيــز الشــفافية"}, {"o": 150, "l": "المادة 2", "b": "برمتهــا .وتشــمل\n والنشــر ،غيــر أن األثــر الكامــل للتحـ ّـول الرقمــي يبقــى مرتبطــاً باســتكمال رقمنــة دورة الشــراء العــام ّ\n األولويــات:\n• اســتكمال اإلطــار القانونــي والتنظيمــي الناظــم للشــراء اإللكترونــي ،وتطويــر المنصــة االكترونيــة المركزيــة لدى\n الهيئة لتشمل مراحل الشراء كافة بما فيها التلزيم والتقييم اإللكتروني؛\n • تحسين جودة البيانات وتكاملها ،وتعزيز قابليتها للتحليل واالستخدام الرقابي؛\n • تطوير أدوات دعم المستخدمين ،بما في ذلك االرشادات وأدلّ ة االستخدام؛\n • تعزيز البنى التحتية التقنية ،وأنظمة إدارة سير العمل والمستندات ،ونظم األرشفة الرقمية وتمكين\n والموّردين من استخدام المنصة االلكترونية للشراء العام. ّ الجهات الشارية\nويهــدف هــذا المحــور إلــى االنتقــال مــن رقمنــة جزئيــة تقتصــر علــى النشــر ،إلــى منظومــة رقميــة متكاملــة تديــر دورة\n الشــراء الكترونيــاً بكفاءة وشــفافية.\n .3التطوير التشريعي المستمر وتحسين حوكمة اإلجراءات\nّبيــن التطبيــق العملــي للقانــون الحاجــة إلــى اســتكمال اإلطــار التنظيمــي وتوحيــد الممارســات بيــن الجهــات الشــارية.\n وتشــمل األولويات:\n •إصدار المراسيم التطبيقية المتعلّ قة بالشراء المشترك واتفاقيات اإلطار؛\n •توسيع استخدام النماذج ودفاتر الشروط النموذجية؛\n •إصدار إرشادات تفسيرية معيارية تُ سهم في تقليص التباين في تطبيق القانون؛\n •دعم إنشاء وحدات شراء متخصصة لدى الجهات الشارية ضمن أطر تنظيمية واضحة.\nـتقر يضمــن توحيــد\n ويهــدف هــذا المحــور إلــى االنتقــال مــن االجتهــادات الفرديــة إلــى إطــار تشــريعي وتنفيــذي مسـ ّ\n المعاييــر وتحســين وتســريع االجــراءات.\n .4تعزيز النزاهة وإدارة المخاطر والرقابة المتكاملة"}, {"o": 151, "l": "المادة 2", "b": "انســجاماً مــع مــا ورد فــي الفصــل الســادس حــول أهميــة البيانــات ،يركّ ــز هــذا المحــور علــى تطويــر رقابــة اســتباقية\n قائمــة علــى تحليــل المخاطــر .وتشــمل األولويــات:\n •تطوير مقاربة وطنية إلدارة مخاطر الشراء العام وربطها بالمنصة اإللكترونية؛\n •تعزيز التنسيق المؤسسي بين أجهزة الرقابة والقضاء لتوحيد آليات المتابعة وتبادل البيانات؛\n •بناء قدرات الجهات الرقابية في مجال الرقابة الرقمية وتحليل األنماط غير الطبيعية؛\n •دعم ممارسات التدقيق الداخلي الوقائي لدى الجهات الشارية.\n ويهدف هذا المحور إلى االنتقال من رقابة مجزّ أة إلى منظومة رقابية متكاملة قائمة على البيانات والمخاطر.\n\f 124\n .5حوكمة الشراء العام في حاالت األزمات والطوارئ\n أظهرت التجربة اللبنانية الحاجة إلى أطر واضحة للشراء في حاالت الطوارئ .وتشمل األولويات:\n ينص عليه قانون الشراء العام؛\n •تحديد مبادئ وإجراءات شراء الطوارئ ضمن اإلطار القانوني الذي ّ\n •توضيح األدوار المؤسسية للجهات المعنية ،بما يضمن المساءلة؛\n •بناء قدرات الجهات الشارية على إدارة المشتريات االستثنائية؛\n •تطوير آليات مراجعة ورقابة الحقة تضمن التوازن بين السرعة والنزاهة.\n ويهدف هذا المحور إلى تنظيم المرونة اإلجرائية في الحاالت الطارئة دون تحويلها إلى استثناء دائم.\n .6التخصص وبناء القدرات والثقافة المؤسسية\n عد العامل البشري ركيزة أساسية لنجاح اإلصالح .وتشمل األولويات:\n ُي ّ\n •استكمال اإلطار المرجعي لوظائف الشراء العام واعتماده رسمياً ؛\n •تطوير سياسة التدريب الوطنية؛\n •دعم التدريب وبناء القدرات بالتعاون مع الشركاء؛\n •تعزيز ثقافة االمتثال والنزاهة والمساءلة؛\n •دعم التدريب وتبادل الخبرات بين الجهات الشارية.\n ويهدف هذا المحور إلى تحويل أحكام القانون من نصوص إلى ممارسات مهنية راسخة.\n .7تعزيز الشراكات االستراتيجية والتعاون متعدد القطاعات"}, {"o": 152, "l": "المادة 2", "b": "يشــكّ ل التعــاون مــع الشــركاء الدولييــن ،والقطــاع الخــاص ،والمجتمــع المدنــي ،رافعــة أساســية الســتدامة اإلصــاح.\n وتشــمل األولويات:\n •ترسيخ الشراكات مع شركاء التنمية لدعم نقل الخبرات وبناء القدرات؛\n •تعزيز الحوار مع القطاع الخاص لتوسيع قاعدة المنافسة؛\n •إشراك منظمات المجتمع المدني في الرصد والتغذية الراجعة ()feedback؛\n •تطوير التعاون األكاديمي لدعم البحث والتعليم األكاديمي المتخصص ذات الصلة.\n .IVعوامل النجاح والمخاطر التنفيذية\nالتوجهــات توافــر عوامــل أساســية ،أبرزهــا االســتقرار التشــغيلي للهيئــة ،واالســتقرار األمنــي ّ يتطلّ ــب تنفيــذ هــذه\nوتوفــر اإلرادة السياســية الداعمــة ،واعتمــاد مقاربــة تشــاركية .فــي المقابــل، ّ والنقــدي علــى المســتوى الوطنــي،\nوتأخــر إصــدار األطــر التنظيميــة ،ومقاومــة التغييــر .وتُ عالَ ــج هــذه\n ّ تشــمل المخاطــر المحتملــة محدوديــة المــوارد،\n المخاطــر عبــر مقاربــة تدريجيــة مرنــة ،وبنــاء شــراكات فاعلــة ،وربــط الدعــم الخارجــي بمؤشــرات أداء واضحــة.\n .Vإطار المتابعة والحوكمة\n التوجهات إلى نتائج قابلة للقياس ،تعتمد الهيئة إطار متابعة إرشادياً يقوم على:\n ّ لضمان ترجمة\n •مؤشرات أداء مرتبطة بكل محور استراتيجي؛\n •آليات تنسيق مؤسسية ولجان توجيهية مشتركة؛\n •تعزيز الشفافية والتغذية الراجعة ()feedback؛\n المتغيرات.\n ّ •مراجعة استراتيجية دورية تسمح بتكييف المسارات التنفيذية وفق\n\f125\n .VIالخالصة\nالتوجهــات االســتراتيجية لهيئــة الشــراء العــام خارطــة طريــق عمليــة تســتند إلــى الــدروس المســتفادة ّ ختامــاً ّ ،\n تمثــل\nجســدمــن مرحلــة التأســيس ،وتســتجيب مباشــرة للفجــوات المؤسســية والتشــغيلية التــي ُرصــدت فــي هذا التقرير .وتُ ّ"}, {"o": 153, "l": "المادة 2", "b": "التوجهــات التزامــاً مؤسســياً بتحويــل أحــكام القانــون رقــم 2021/244إلــى واقــع تشــغيلي ملمــوس ،يقــوم علــى ّ هــذه\nالرقمنــة المتكاملــة ،والنزاهــة االســتباقية ،والتأهيــل المهنــي المســتدام .إن ترجمــة هــذه الرؤيــة إلــى إجــراءات فعليــة\nموجهــاً وشــراكة فاعلــة مــع الشــركاء المحلييــن والقطــاع الخــاص والمجتمــع المدنــي .ومــع ّ ســتتطلب دعمــاً دوليــاً\nتحــول نوعــي فــي منظومــة الشــراء العــام، ّ التنفيــذ المنضبــط والمتابعــة الدقيقــة ،ســتتمكن الهيئــة مــن قيــادة\nليكــون الشــراء العــام ليــس فقــط أداة إنفــاق ،بــل محـ ّـركاً للتنميــة المســتدامة ،ودرعــاً للنزاهــة ،وضامنــاً للثقــة فــي\n اإلدارة العامــة اللبنانيــة.\n\fالمالحق\n\f جدول المحتويات\n128 .Iملحق رقم :1إدارة المناقصات\n128 .1مقدرات إدارة المناقصات\n128 .2أداء إدارة المناقصات بالرغم من التحديات\n132 .IIملحق رقم :2المراحل التشريعية التي أدت الى صدور قانون الشراء العام في لبنان رقم 2021/244\n132 .1المراحل التشريعية\n132 .2صدور قانون الشراء العام (القانون رقم 244تاريخ 19تموز )2021\n133 .3بدء نفاذ قانون الشراء العام في 2022/07/29\n134 .IIIملحق رقم :3دراسة حول المحاور اإلصالحية لقانون الشراء العام في لبنان رقم 2021/244\n134 .1توسيع قاعدة الجهات الخاضعة للقانون\n134 .2االستدامة ،تحديد الحاجات ،ووضع الخطط ،وضبط التجزئة\n135 .3تعريف صفقات اللوازم واألشغال والخدمات\n136 .4اللغة المعتمدة في مستندات الشراء\n136 .5األنظمة التفضيلية\n136 .6الغاء الشراء او اجراءاته\n137 .7التنازل عن العقد أو التعاقد من الباطن\n138 .8قواعد السلوك وتضارب المصالح\n139 .9العروض المشتركة\n139 .10القيمة التقديرية لمشروع الشراء\n141 .11موضوع الشراء\n142 .12معايير التقييم واإلرساء\n143 .13اإلشراف على التنفيذ\n144 .14وضع اليد"}, {"o": 154, "l": "المادة 2", "b": "144 .15اإلعالن عن الصفقات العمومية\n145 .16مبدأ التنفيذ قبل الدفع\n147 .17ثبات قيمة العقد\n147 .18األشغال باألمانة\n148 .19الغاء المواد المتعلقة بالمرجع الصالح لعقد النفقة\n149 التطور التشريعي :صعوبات ومعالجات التطبيق ()2025-2022\n ّ .IVملحق رقم :4\n154 المدنية\n ّ َ\n الموافق على ملئها من قبل مجلس الخدمة .Vملحق رقم :5الوظائف\n ً\n وفقا للمرسوم رقم 14632 .VIملحق رقم :6مالك هيئة الشراء العام\n156\n ّ\n المتعلق بنظام مستخدمي هيئة الشراء العام الصادر بتاريخ 2025/1/9\n158 .VIIملحق رقم :7الئحة المذكرات والقرارات والتوصيات الصادرة عن الهيئة بين 2022و2025\n158 .1المذكرات\n160 .2قرارات رئيس الهيئة\n161 .VIIIملحق رقم :8المراسالت\n168 .IXملحق رقم :9األخطاء الشائعة المتعلقة بدفاتر الشروط\n168 ً\n شيوعًا في دفاتر الشروط .1األخطاء األكثر\n172 .2اهم المالحظات على دفاتر الشروط الخاصة التي ُعرضت على الهيئة\n174 المسجلة على المنصة االلكترونية المركزية\n ّ .Xملحق رقم :10الئحة الجهات الشارية\n\f 128\n المالحق\n .Iملحق رقم :1إدارة المناقصات\n .1مقدرات إدارة المناقصات\n كان عدد العاملين في إدارة المناقصات في نهاية العام ،13 ،2020وذلك على الشكل اآلتي:\n •مدير عام إدارة المناقصات (فئة أولى).\n معلوماتية (فئة ثالثة -مالك).\n ّ •مهندس رئيس دائرة فنّ ي /اختصاص\n •مهندس رئيس دائرة فنّ ي /اختصاص كيمياء (فئة ثالثة -مالك).\n معلوماتية (مبرمج محـلل أو محـلل) (فئة ثالثة -متعاقد).\n ّ •أخصائي\n •موظف عدد ( )2في المالك (بصفة محرر) من أصل خمسة (الفئة الرابعة).\n •متعاقد عدد (( )2بصفة محرر) (الفئة الرابعة).\n •مستكتب أول (( )1فئة رابعة – مالك).\n •مدخل معلومات عدد (( )2فئة رابعة -متعاقد).\n •أجراء عدد (.)2\nســنداً لمــاك إدارة المناقصــات ،فــان العــدد اإلجمالــي هــو ،18بينمــا العــدد الــذي كان موجــود فعليــا كان ،6مــن"}, {"o": 155, "l": "المادة 2", "b": "هنــا كان الشــغور فــي مــاك إدارة المناقصــات 12مركــزا بمعــدل .%66\nان عــدد العامليــن المنتقليــن مــن إدارة المناقصــات الســابقة الــى هيئــة الشــراء العــام عمــا بأحــكام المــادة 88مــن\n قانــون الشــراء العــام قــد تناقــص الــى 9وأصبــح موزعــاً كمــا يلــي:\n • مدير عام إدارة المناقصات (فئة أولى) ،رئيس هيئة الشراء العام عمال بأحكام الفقرة األولى من"}, {"o": 156, "l": "المادة 88", "b": "المادة\n 88من قانون الشراء العام.\n معلوماتية (فئة ثالثة -مالك).ّ • مهندس رئيس دائرة فنّ ي /اختصاص\n • مهندس رئيس دائرة فنّ ي /اختصاص كيمياء (فئة ثالثة -مالك).\n • محرر (فئة رابعة – مالك).\n • مستكتب أول (( )1فئة رابعة – مالك).\n • مدخل معلومات عدد (( )2فئة رابعة -متعاقد).\n • أجراء عدد (.)2\n .2أداء إدارة المناقصات بالرغم من التحديات\nفــي ظــل المعطيــات القانونيــة والواقعيــة التــي كانــت قائمــة قبــل بــدء نفــاذ قانــون الشــراء العــام فــي ،2022-7-29\nاســتطاعت إدارة المناقصــات مــن خــال ممارســة الصالحيــات المعطــاة لهــا الحــد مــن الصفقــات المخالفــة للقانــون،\nوكان اهــم مــا قامــت بــه فــي إطــار تنفيــذ موجباتهــا المنصــوص عليهــا فــي المرســوم رقــم (1959/2866نظــام\n المناقصــات):\n أ .اقتراح التعديالت على دفاتر الشروط الخاصة\nالقانونيــة كاملــة ،بهــدف الحفــاظ علــى المــال العــام ،وحمايتــه\n ّ حرصــت ادارة المناقصــات علــى القيــام بموجباتهــا\nوحســن اســتخدامه ،رافضـ ًـة إعطــاء الحجــج ليحـ ّـل محلهــا ســواها ،إن فــي مــا يتعلــق بالفراغــات فــي مالكاتهــا أو\nـاوزة كل العقبــات ،مــن محدوديــة االمكانيــات والمــوارد التقنيــة والبشــرية، لعــدم وجــود موازنــة خاصــة بهــا ،متجـ ً\nمصـ ّـرة علــى أن تقــول رأيهــا فــي كل معاملــة تعــرض عليهــا انطالقــاً مــن إيمانهــا بمبــدأ ســيادة القانــون وتجلّ ــى\nذلــك بشــكل خــاص فــي مناقصــات مراكــز المعاينــة الميكانيكيــة لعــام 2016وتلزيــم شــبكتي الهاتــف الخليــوي\nلعــام 2015وصفقــات الفيــول وصفقــة بواخــر الكهربــاء لعــام 2017وتلزيمــات وزارة الطاقــة والميــاه ووزارة\n االشــغال العامــة والنقــل ومنهــا مزايــدة الســوق الحــرة.\n\f129"}, {"o": 157, "l": "المادة 88", "b": "التزمــت إدارة المناقصــات بموجباتهــا القانونيــة المنصــوص عليهــا فــي المــادة 17مــن المرســوم رقــم 59/2866\nيصدقهــا علمــاً أن هــذا المرجــع وفقــا ألحــكام ّ لناحيــة تدقيــق دفاتــر الشــروط الخاصــة أيــا كان المرجــع الــذي\nقانــون المحاســبة العموميــة هــو الوزيــر المختــص فوضعــت مالحظاتهــا بموضوعيــة وحياديــة علــى دفاتــر\nالشــروط الخاصــة ،بمــا فيهــا تلــك التــي أقــرت فــي مجلــس الــوزراء ،وعندمــا أصـ ّـر مجلــس الــوزراء علــى عــدم األخــذ\n بمالحظاتهــا قامــت اإلدارة بتنفيــذ مقــررات مجلــس الــوزراء انطالقــاً مــن التزامهــا قواعــد االختصــاص.\n ب .إصدار التقارير الخاصة\n قامــت إدارة المناقصــات بوضــع تقاريــر خاصــة فــي صفقــات مخالفــة لقانــون المحاســبة العموميــة ونظــام\n المناقصــات والمبــادئ والقواعــد ذات الصلــة المنصــوص عليهــا فــي االتفاقيــة األمميــة لمكافحــة الفســاد.\nوتناولــت هــذه التقاريــر بشــكل خــاص مناقصــة مراكــز المعاينــة الميكانيكيــة وصفقــة بواخــر كهربــاء العــرض الوحيــد.\n ج .التعهد برفع السرية المصرفية لمصلحة اإلدارة\nوجهــت إدارة المناقصــات الكتــاب رقــم 10/143إلــى كافــة اإلدارات العامــة والــوزاراتّ ،بينــت بتاريــخ ّ 2020/5/11\nفيــه التالــي «بمــا أن مجلــس الــوزراء فــي قــراره رقــم 4تاريــخ ( 2020/4/28التدبير الثالث) ،ألــزم جميع اإلدارات ،عند\nإجــراء أي عقــد أو تلزيــم أو نفقــة ،تطبيــق المــادة الخامســة مــن قانــون الســرية المصرفيــة التــي تجيــز للمتعاقديــن\nاالتفــاق مســبقاً علــى رفــع الســرية المصرفيــة» لذلــك «يتوجــب إضافــة النــص الــوارد فــي قــرار مجلــس الــوزراء"}, {"o": 158, "l": "المادة 88", "b": "إلــى دفتــر الشــروط الخــاص بــكل صفقــة ،ضمــن مســتندات الغــاف األول ،تحــت طائلــة عــدم الســير بالتلزيــم».\nـاء عليــه ،وافــق مجلــس الــوزراء بقــراره رقــم 10تاريــخ 2020/5/29علــى اقتــراح إدارة المناقصــات (الكتــاب رقــموبنـ ً\n 10/143تاريــخ )2020/5/11بإضافــة نــص التدبيــر الثالــث الــوارد ضمــن «التدابيــر اآلنيــة والفوريــة لمكافحــة الفســاد\nواســتعادة األمــوال المتأتيــة عنــه» موضــوع قــرار مجلــس الــوزراء رقــم 17تاريــخ 2020/5/12إلــى دفتــر الشــروط\n الخاصــة بــكل صفقــة ضمــن مســتندات الغــاف األول ،تحــت طائلــة عــدم الســير بالتلزيــم.\n د .إصدار النماذج والوثائق الموحدة\nوعممتهــا علــى مختلــف اإلدارات\n ّ العامــة ،وتبســيطها\n ّ اإلداريــة\n ّ ســعت إدارة المناقصــات ،الــى توحيــد الشــروط\nتبيــن لهــا وجــود تفــاوت\n العامــة ،حرصــاً علــى اعتبــارات العدالــة والمســاواة وتكافــؤ الفــرص ،وذلــك بعــد أن ّ\nالعامــة ،بيــن صفقــة وأخــرى ضمــن اإلدارة الواحــدة وبيــن إدارة وأخــرى ،ســاهم التوحيــد\n ّ اإلداريــة\n ّ فــي الشــروط\n والتبســيط فــي تســهيل بــاب ولــوج الصفقــات العموميــة أمــام المؤسســات الصغيــرة والمتوســطة الحجــم.\nباإلضافــة إلــى تحضيــر وثيقــة تدقيــق لدفاتــر الشــروط خاصــة بــاإلدارة وتحديثهــا ،ســعت إدارة المناقصــات إلــى\nتعميــم وثائــق ونمــاذج موحــدة للصفقــات العموميــة باإلضافــة إلــى الشــروط اإلداريــة الموحــدة ،مــن بيــن هــذه\n النمــاذج:\n •تصريح النزاهة\n •نموذج التعهد\n •نموذج األسعار\n •الشروط اإلدارية النموذجية\n\f 130\n ه .أخذ مقتضيات التنمية المستدامة بعين االعتبار\nحرصــت إدارة المناقصــات ،عنــد دراســة دفاتــر الشــروط الخاصــة وإبــداء مالحظاتهــا بشــأنها واقتــراح التصحيحــات"}, {"o": 159, "l": "المادة 88", "b": "المناســبة ،علــى مراعــاة مبــادئ التنميــة المســتدامة ،مــع التركيــز علــى:\n • االعتبارات البيئية :حماية البيئة وضمان االلتزام بالتقييم البيئي للمشاريع وفق المراسيم رقم\n 2012/8213ورقم ،2012/8633كما ورد في تعميم السيد رئيس مجلس الوزراء رقم .2012/28\n • دعم المؤسسات الصغيرة والمتوسطة واليد العاملة اللبنانية :ضمان عدم التمييز أو وضع شروط\n تحّد من المنافسة ،وعدم استخدام األحداث ،وحماية العمال المحليين. ّ\n • االلتزام بالمعايير والمواصفات الوطنية :وفق تعاميم السيد رئيس مجلس الوزراء رقم ،2013/28\n وتطبيق قانون إنشاء مؤسسة المقاييس والمواصفات اللبنانية (.)LIBNOR\n • إدارة الضمانات المصرفية :وفق تعميم السيد رئيس مجلس الوزراء رقم ،2013/21مع األخذ بعين\n االعتبار الوضعية القانونية للمصارف األجنبية عند الضرورة.\n • تفضيل المنتجات الوطنية :بناء على تعاميم السيد رئيس مجلس الوزراء ذات األرقام ،2012/14\n 97/2 ،2019/7و"}, {"o": 160, "l": "المادة 131", "b": "المادة 131من قانون المحاسبة العمومية ،لضمان استفادة السلع المصّنّ عة في لبنان.\n • ضبط اإلنفاق العام وترشيده :وفق تعميم السيد رئيس مجلس الوزراء رقم ،2020/5مع التركيز على\n حصر النفقات الضرورية وتطبيق إجراءات ترشيدية في جميع اإلدارات العامة.\nكمــا قامــت إدارة المناقصــات بتدقيــق جميــع بنــود دفاتــر الشــروط ،بمــا فــي ذلــك :قيمــة التأميــن المؤقــت،\nوغرامــات التأخيــر ،وكفالــة حســن التنفيــذ ،وغيرهــا مــن الشــروط الماليــة والفنيــة لضمــان حمايــة المصلحــة الماليــة\nللدولــة .وقــد جــرى ذلــك باســتخدام نمــوذج تدقيــق داخلــي معتمــد ،يحقــق التــوازن بيــن متطلبــات المشــروع\n وحجمــه وتعقيداتــه ،ويضمــن الشــفافية والكفــاءة فــي إجــراءات الشــراء العــام.\n و.الملفات المنجزة ضمن برنامج TAF\nفــي إطــار برنامــج المســاعدة التقنيــة ( )Technical Assistance Facility – TAFالممـ ّـول مــن االتحــاد األوروبي\nوالمنفــذ مــن قبــل شــركة كــراون إيجنتــس ( )Crown Agentsبالتعــاون مــع مكتــب وزيــر الدولــة لشــؤون التنميــة ّ\nوفــر البرنامــج ،خــال\n اإلداريــة ،جــرى االلتــزام بتأميــن خبــراء فنييــن لدعــم إدارة المناقصــات عنــد الحاجــة .وقــد ّ\nمتخصصــاً عــزّ ز قــدرات اإلدارة وأســهم فــي ضمــان\n ّ الفتــرة الممتــدة مــن عــام 2017حتــى عــام ،2022دعمــاً فنيــاً\n المنافســة العادلــة وتعزيــز الشــفافية فــي إجــراءات الشــراء العــام.\nوفــي هــذا اإلطــارُ ،أنجــزت مجموعــة مــن الملفــات بالتعــاون مــع خبــراء االتحــاد األوروبــي ضمــن برنامــج ،TAFمــن\n أبرزها:\n .1ملف مناقصة الكهرباء (منتج طاقة مستقل ( )IPPتاريخ .)2019/11/8\nاقترحــت إدارة المناقصــات علــى وزارة الطاقــة والميــاه ،اســتنادًاً إلــى تقاريــر الخبــراء ،االســتغناء عــن الحــل"}, {"o": 161, "l": "المادة 131", "b": "المؤقــت نظــرًاً الرتفــاع كلفتــه ومحدوديــة جــدواه ،إذ ان كلفــة الميغــاوات الواحــد فيــه تفــوق كلفتــه فــي الحــل\nيوّفــر علــى الخزينــة نحــو مليــون\n الدائــم .وقـ ّـّدر الخبــراء أن كل ميغــاوات يتــم االســتغناء عنــه مــن الحــل المؤقــت ّ\nدوالر ،مــا يعنــي وفــرًاً ال يقــل عــن مليــار دوالر فــي حــال إلغــاء كامــل الحــل المؤقــت .أوصــت اإلدارة بتســريع\nتنفيــذ الحــل الدائــم عبــر إضافــة توربي�ن ـَي غــاز فــي موقــع الزهرانــي ،حيــث األرض متوافــرة ،بمــا يتيــح إنتــاج طاقــة\nمســتدامة قدرهــا 675ميغــاوات بعــد 15شــهرًاً مــن توقيــع اتفاقيــة الطاقــة ،مقابــل 1050ميغــاوات مــن الحــل\n المؤقــت بعــد 12شــهرًاً.\nيــؤدي الحــل المقتــرح إلــى تأميــن طاقــة مســتدامة إجماليــة تبلــغ 1850ميغــاوات خــال 30إلــى 36شــهراً مــن\nتوقيــع االتفاقيــة ،مــا يغنــي نهائيــاً عــن الحلــول المؤقتــة ،ويتــاءم مــع حاجــات لبنــان المســتقبلية ،وبكلفــة\n\f131\nتؤمــن 1500ميغــاوات فقــط خــال المــدة ذاتهــا .كمــا يســتجيب هــذا الحــل بصــورة\n أدنــى مــن خطــة الــوزارة التــي ّ\nويوفــر علــى\n ّ أفضــل لمفاهيــم الشــراكة بيــن القطاعيــن العــام والخــاص ،ولالعتبــارات البيئيــة واالجتماعيــة،\n الخزينــة اللبنانيــة مــا ال يقــل عــن 1050مليــون دوالر.\nخلــص الخبــراء إلــى أن الفائــدة الزمنيــة المحــدودة للحــل المؤقــت تــزول بعــد فتــرة قصيــرة ،إذ إن مســاهمته\nـا خــال فتــرة تأخيــر ال تتجــاوز\n فــي اإلنتــاج تنتهــي بعــد 36شــهراً ،فــي حيــن أن الحــل الدائــم يحقــق إنتاجــاً مماثـ ً\n 8أشــهر ،وهــو تأخيــر ال يبــرر االســتثمار فــي معامــل مؤقتــة مرتفعــة الكلفــة وأقــل كفــاءة ،علمــاً أن معامــل"}, {"o": 162, "l": "المادة 131", "b": "تؤمــن وفــراً وكفــاءة أعلــى بكثيــر مــن الحــل المؤقــت ويؤكــد المقتــرح أن الملتــزم هــو الــذي الــدورة المركبــة ّ\nيؤمــن الفيــول فــي حيــن أصـ ّـرت وزارة الطاقــة ومؤسســة كهربــاء لبنــان علــى شــراء الفيــول وتزويــد الملتــزم بــه. ّ\n .2المواصفات الفنية لمناقصات الفيول أويل /الغاز أويل\nبتاريــخ ،2018/10/10ورد إدارة المناقصــات فــي التفتيــش المركــزي كتــاب مــن المديريــة العامــة للنفط في وزارة\nالطاقــة والميــاه مرفقــًاً بمشــروعي دفتــري شــروط إلجــراء مناقصــة عموميــة لتوريــد مادتي الغاز أويــل والفيول\nأويــل لمؤسســة كهربــاء لبنــان ،تنفيــذًاً لقــرار مجلــس الــوزراء رقــ