نافســة. العارضيــن ممــا يحــد مــن المنافســة.\nعنــد الدعــوة إلــى التأهيــل المســبق ،يجــب ذكــر نــوع المناقصــة\nالتــي ســتعتمد فــي الخطــوة التاليــة (مناقصــة عموميــة\nأم مناقصــة علــى مرحلتيــن أم طلــب اقتراحــات للخدمــات عنــد الدعــوة إلــى التأهيــل المســبق ،ال يتــم ذكــر نــوع"}, {"o": 229, "l": "المادة 12", "b": "االستشــارية) كــي يكــون العارضــون المحتملــون علــى درايــة المناقصــة التــي ســتعتمد فــي الخطــوة التاليــة.\nتامــة بكافــة اإلجــراءات والخطــوات التــي ســيتم إعتمادهــا الحقــاً\n والتــي علــى أساســها يقــررون المشــاركة مــن عدمهــا.\nالتقيــد بنــص الفقــرة 1مــن المــادة 22مــن قانــون الشــراء العــام\n ّ\nوالتــي نصــت علــى مــا يلــي\" :تحــدد ملفــات التلزيــم مــدة صالحيــة تحديــد مــدة صالحيــة العــرض خالفــاً لمــا نصــت عليــه الفقــرة\nالعــرض علــى أن تكــون متناســبة مــع طبيعــة الشــراء ،علــى أال 1مــن المــادة 22مــن قانــون الشــراء العــام.\n تقــل عــن ثالثيــن يومــاً مــن التاريــخ النهائــي لتقديــم العــروض\".\nالتقيــد بنــص الفقــرة 4مــن المــادة 34مــن قانــون الشــراء العــام\n ّ\n تحديــد مــدة صالحيــة ضمــان العــرض خالفــاً لمــا نصــت عليــه\nوالتــي نصــت علــى مــا يلــي\" :تُ حــدد صالحيــة ضمــان العــرض\n الفقــرة 4مــن المــادة 34مــن قانــون الشــراء العــام.\nبإضافــة /28/ثمانيــة وعشــرين يومــاً علــى صالحيــة العــرض\".\nالتقيــد بنــص الفقــرة 3مــن المــادة 35مــن قانــون الشــراء العــام\n ّ\nوالتــي نصــت علــى مــا يلــي\" :يجــب تقديــم ضمــان حســن التنفيــذ تحديــد مهلــة تقديــم ضمــان حســن التنفيــذ خالفــاً لمــا نصــت\nخــال الفتــرة المحــددة فــي شــروط العقــد علــى أال تتجــاوز عليــه الفقــرة 3مــن المــادة 35مــن قانــون الشــراء العــام.\n //15//خمســة عشــر يومــاً مــن تاريــخ نفــاذ العقــد\".\nالتقيــد بمــا ورد فــي الفقــرة 1مــن المــادة 34مــن قانــون الشــراء\n ّ\nالعــام والتــي نصــت علــى مــا يلــي\"ُ :يحــدد ضمــان العــرض بمقــدار\n تحديــد قيمــة ضمــان العــرض بأكثــر مــن ثالثــة بالمائــة مــن"}, {"o": 230, "l": "المادة 12", "b": "يضمــن جديــة العــارض ويأخــذ باإلعتبــار قيمــة مشــروع الشــراء\n القيمــة التقديريــة لمشــروع الشــراء بخــاف مــا نصــت عليــه\nوأهميتــه دون أن يحــد مــن المنافســة ،علــى أن يكــون مقطوعــاً\n الفقــرة 1مــن المــادة 34مــن قانــون الشــراء العــام.\nوأال يتعــدى الثالثــة بالمئــة مــن القيمــة التقديريــة لمشــروع\n الشــراء\".\n إســتخدام بعــض التعابيــر التــي كانــت معتمــدة قبــل دخــول\nاســتخدام التعابيــر التــي نــص عليهــا قانــون الشــراء العــام مثــل حيــز التنفيــذ مثــل \"التأميــن المؤقــت\"\n قانــون الشــراء العــام ّ\n \"ضمــان العــرض\" و \"ضمــان حســن التنفيــذ\". أو \"الكفالــة المؤقتــة\" و \" التأميــن النهائــي\" أو \"الكفالــة\n النهائيــة\".\n\f169\n المالحظات او التوصيات ً\n شيوعا في دفاتر الشروط األخطاء األكثر\n التقيــد بمــا ورد فــي الفقــرة 1مــن المــادة 35مــن قانــون الشــراء\n ّ\n العــام والتــي نصــت علــى مــا يلــي\"ُ :يحــدد ضمــان حســن التنفيــذ تحديــد قيمــة ضمــان حســن التنفيــذ كمبلــغ مقطــوع وليــس\n بنســبة مئويــة ال تزيــد عــن عشــرة بالمائــة مــن قيمــة العقــد\" كنســبة مئويــة خالفــاً لمــا نصــت عليــه الفقــرة 1مــن المــادة\n وبالتالــي فإنــه يتوجــب تحديــد ضمــان حســن التنفيــذ كنســبة 35مــن قانــون الشــراء العــام.\n مئويــة وليــس كمبلــغ مقطــوع.\n التقيــد بنــص المــادة 36مــن قانــون الشــراء العــام والتــي نصــت ّ\n علــى مــا يلــي \" :يكــون ضمــان العــرض كمــا ضمــان حســن التنفيــذ\n إمــا نقديــاً ُيدفــع إلــى صنــدوق الخزينــة أو إلــى صنــدوق ســلطة تحديــد طريقــة دفــع الضمانــات بموجــب شــيك مصرفــي"}, {"o": 231, "l": "المادة 12", "b": "التعاقــد ،وإمــا بموجــب كتــاب ضمــان مصرفــي غيــر قابــل للرجــوع بخــاف مــا نصــت عليــه المــادة 36مــن قانــون الشــراء العــام.\n عنــه ،صــادر عــن مصــرف مقبــول مــن مصــرف لبنــان ُي ِّبيــن أنــه قابــل\n للدفــع غــب الطلــب\".\n التقيــد بنــص الفقــرة 4مــن المــادة 22مــن قانــون الشــراء العــام\n ّ\n والتــي تنــص علــى مــا يلــي\" :يمكــن للعــارض أن يعـ ّـدل عرضــه أو\n تنظيــم دفاتــر شــروط ال تســمح بإســترجاع العــرض أو تعديلــه\n أن يســحبه قبــل الموعــد النهائــي لتقديــم العــروض دون مصــادرة\n بعــد تقديمــه بخــاف مــا نصــت عليــه الفقــرة 4مــن المــادة\n ضمــان عرضــه .ويكــون التعديــل أو طلــب ســحب العــرض ســاري\n 22مــن قانــون الشــراء العــام.\n المفعــول عندمــا تتســلمه الجهــة الشــارية قبــل الموعــد النهائــي\n لتقديــم العــروض\".\n إلصــاق طوابــع ماليــة علــى التصريح/التعهــد بقيمــة مليــون ليــرة تنــص بعــض دفاتــر شــروط علــى إلصــاق طوابــع ماليــة علــى\n ـدال مــن خمســين ألــف ليــرة لبنانيــة.\n لبنانيــة بـ ً التصريح/التعهــد بقيمــة خمســين ألــف ليــرة لبنانيــة.\n تنــص بعــض دفاتــر الشــروط علــى فســخ العقــد أو إنهائــه أو\n التقيــد بنــص المــادة 33مــن قانــون الشــراء العــام فيمــا خــص\n ّ\n التقيــد بمــا نصــت عليــه المــادة\n ّ ـاكال مــن دون\n اعتبــار الملتــزم نـ ً\n النكــول واإلنهــاء والفســخ ونتائــج إنتهــاء العقــد.\n 33مــن قانــون الشــراء العــام.\n التقيــد بنــص المــادة 40مــن قانــون الشــراء العــام فيمــا خــص\n ّ نصــت بعــض دفاتــر الشــروط علــى إقصــاء الملتــزم دون\n اقصــاء الملتــزم. التقيــد بمــا نصــت عليــه المــادة 40مــن قانــون الشــراء العــام.\n ّ\n أوال مــن المــادة 33مــن قانــون الشــراء"}, {"o": 232, "l": "المادة 12", "b": "التقيــد بمــا ورد فــي البنــد ً\n ّ\n العــام والتــي نصــت علــى مــا يلــي:\n ناكًال إذا خاَلَ ف شروط تنفيذ العقد أو أحكامً الملتِزم\n ِ «ُيعتبر\n ُ .1\n بكاّفة\n ّ دفتر الشروط ،وبعد إنذاره رسميًاً بوجوب التقُّيّ د نــاكال دون\n ً تســمح بعــض دفاتــر شــروط باعتبــار الملتــزم\n الحصــول علــى موافقــة هيئــة الشــراء العــام علــى ذلــك\n موجباته من قبل سلطة التعاقد ،وذلك ضمن مهلة تتراوح\n وذلــك بخــاف مــا نــص عليــه البنــد 1مــن المــادة 33مــن\n بين خمسة أيام كحٍّدّ أدنى وخمسة عشر يومًاً كحٍّدّ أقصى،\n قانــون الشــراء العــام.\n الُملتزم بما ُُطلبوانقضاء المهلة هذه دون أن ََيقوم ُ\n إليه.\n إّال بموجب قرار معَّلّ ل ََيصدر عن\n ناكًال ّ\n ً الُملتزم\n .2ال يجوز اعتبار ُ\n بناًء على موافقة هيئة الشراء العام». سلطة التعاقد ً\n\f 170\n المالحظات او التوصيات ً\n شيوعا في دفاتر الشروط األخطاء األكثر\nالتقيــد بمــا ورد فــي الفقــرة 1مــن المــادة 12مــن قانــون الشــراء\n ّ\n تضمنــت بعــض دفاتــر الشــروط أنــه تتــم الدعــوة الــى التلزيــم\nالعــام والتــي نصــت علــى مــا يلــي« :تتــم الدعــوة إلــى التنافــس\n عبــر اإلعــان علــى المنصــة االلكترونيــة المركزيــة لــدى هيئــة\nالمركزيــة فــي\n ّ اإللكترونيــة\n ّ عبــر االعــان عــن الشــراء علــى المنصــة\n الشــراء العــام مــن دون ذكــر الموقــع اإللكترونــي لــدى تلــك\nهيئــة الشــراء العــام وعلــى الموقــع اإللكترونــي الخــاص بالجهــة\n الجهــات الشــارية وذلــك بخــاف مــا نصــت عليــه الفقــرة 1\nالشــارية إن ُو ِجــد .كمــا يعــود للجهــة الشــارية أن تُ ــق ِّرر نشــر\n مــن المــادة 12مــن قانــون الشــراء العــام.\n اإلعــان فــي أ ّي وســيلة إضافيــة أخــرى».\nالتقيــد بنــص المــادة 7مــن قانــون الشــراء العــام فيمــا خــص"}, {"o": 233, "l": "المادة 12", "b": "ّ وجــود الكثيــر مــن النواقــص عنــد تحديــد شــروط مشــاركة\nشــروط مشــاركة العارضيــن ومذكــرات هيئــة الشــراء العــام ذات العارضيــن وذلــك بخــاف مــا نصــت عليــه المــادة 7مــن\n الصلــة . قانــون الشــراء العــام.\nالتقيــد بمــا ورد فــي الفقــرة 2مــن المــادة 30مــن قانــون الشــراء\n ّ\nالعــام والتــي نصــت علــى مــا يلــي« :فــي عقــود األشــغال\nوالخدمــات ،وفــي حــال َأجــاز دفتــر الشــروط الخــاص ذلــكُ ،يمكــن\n إجــازة بعــض دفاتــر الشــروط بالتعاقــد الثانــوي دون تحديــد\nأن َيعهــد الملتــزم إلــى ُمتعاقــد ثانــوي تنفيــذ جــز ٍء مــن العقــد\n سيســمح للمتعاقــد الثانــوي نســبة الجــزء مــن العقــد التــي ُ\nضمــن النســبة المســموح بهــا والمنصــوص عليهــا فــي دفتــر\n بتنفيذهــا .كمــا أن بعــض دفاتــر الشــروط أجــازت التعاقــد\nأال تتــخ ّطــى % 50مــن قيمــة الشــروط الخــاص والتــي يجــب ّ\n الثانــوي بالرغــم مــن ان التلزيــم يهــدف لتحقيــق لــوازم لصالــح\nالعقــد .علــى الملتــزم َأخــذ الموافقــة ال ُمســبقة علــى التعاقــد\n الجهــة الشــارية .وذلــك بخــاف مــا نصــت عليــه الفقــرة 2مــن\nالثانــوي مــن ســلطة التعاقــد التــي يجــب عليهــا اتّ خــاذ قرارهــا\n المــادة 30مــن قانــون الشــراء العــام.\nبالموافقــة أو الرفــض المعلَّ ــل خــال مهلــة زمنيــة تُ ــح َّدد فــي\nوي َع ّد ســكوتها عنــد انقضــاء هــذه المهلــة قــراراً\n شــروط العقــدُ ،\n ضمنيــاً بالقبــول».\nالتقيــد بمــا ورد فــي المذكــرة رقــم /8ه.ش.ع 2023/.الصــادرة ّ\nعــن هيئــة الشــراء العــام والمــو ّجهــة إلــى كافــة الجهــات الخاضعة\nألحــكام قانــون الشــراء العــام حــول اإلفــادات والمســتندات التــي\nيجــب أن تتضمنهــا دفاتــر الشــروط الخاصــة مــن ضمــن الشــروط"}, {"o": 234, "l": "المادة 12", "b": "أوال – ب علــى مــا يلــي:\n اإلداريــة ،حيــث نصــت فــي الفقــرة ً\nفــي حــال إشــتراك عــارض أجنبــي يتوجــب علــى هــذا العــارض\nأن ُيراعــي أحــد الشــروط التاليــة - :أن يكــون مــن ضمــن إئتــاف\nيضــم شــركة لبنانيــة علــى األقــل تتوفــر فيهــا الشــروط المطلوبــة\nبموجــب دفتــر الشــروط الخــاص بالصفقــة - .الحضــور الشــخصي\nللممثــل القانونــي عــن الشــركة للمشــاركة فــي إجــراءات الشــراء. عــدم درايــة بالموجبــات المفروضــة علــى العــارض األجنبــي\n -أن يكــون لهــا وكيــل أو ممثــل فــي لبنــان مكلــف توقيــع العقــد التقيــد بمــا\n ّ الــذي يرغــب باإلشــتراك فــي المنافســة وعــدم\nعنهــا .إضافــة إلــى الشــروط أعــاه ،يتوجــب علــى العــارض األجنبي ورد فــي المذكــرة رقــم /8ه.ش.ع 2023/.الصــادرة عــن هيئــة\n تقديــم مــا يلــي: الشــراء العــام.\n • شهادة تسجيل الشركة أو المؤسسة لدى المراجع\n المختصة في بلده.\n • إفادة من وزارة اإلقتصاد والتجارة اللبنانية ُتُ ثبت انطباق\n أحكام قانون مقاطعة العدو اإلسرائيلي على العارض.\n (أوًال-أ) أعاله بحسب\n ً • اإلفادات المطلوبة بموجب الفقرة\n قوانين البلد الذي يوجد فيه العارض ،على أن تكون\n هذه اإلفادات مصدقة وفقًاً لألصول من المراجع\n المختصة.\nعــدم المبالغــة فــي تحديــد ثمــن دفتــر الشــروط وتأمينــه مــن المبالغــة فــي تحديــد ثمــن دفتــر الشــروط ممــا يحــد مــن\n حيــث المبــدأ مجانــاً واال فمقابــل بــدل توفيــره. المشــاركة وبالتالــي المنافســة.\n\f171\n المالحظات او التوصيات ً\n شيوعا في دفاتر الشروط األخطاء األكثر\n تحديــد معاييــر تقييــم العــروض تحديــداً واضحــاً وكيفيــة تطبيــق\n تتضمــن بعــض دفاتــر شــروط معاييــر تقييــم غيــر واضحــة\n تلــك المعاييــر دون أن يكــون للجنــة التلزيــم أي إستنســابية فــي"}, {"o": 235, "l": "المادة 12", "b": "وغيــر مفصلــة.\n التقييــم.\n تتضمــن بعــض دفاتــر شــروط مهــل ال تتوافــق مــع تلــك\n التقيد بالمهل الواردة في"}, {"o": 236, "l": "المادة 24", "b": "المادة 24من قانون الشراء العام.\n ّ\n الــواردة فــي المــادة 24مــن قانــون الشــراء العــام.\n عــدم توافــق المهــل المحــددة للموعــد النهائــي لتقديــم\n التقيــد بالمهــل المحــددة فــي المــادة 21مــن قانــون الشــراء\n ّ طلبــات اإلســتيضاح وللموعــد النهائــي للــرد علــى طلبــات\n العــام. اإلســتيضاح الــواردة فــي بعــض دفاتــر الشــروط مــع المهــل\n المحــددة فــي المــادة 21مــن قانــون الشــراء العــام.\n تنــص بعــض دفاتــر الشــروط علــى ضــم المســتند التالــي\n عــدم طلــب هــذا المســتند تطبيقــاً لمــا ورد فــي المذكــرة مــن ضمــن المســتندات اإلداريــة« :إفــادة صــادرة عــن وزارة\n الصــادرة عــن هيئــة الشــراء العــام رقــم /9ه.ش.ع 2024/.تاريــخ الماليــة تثبــت إيفــاء العــارض باإللتزامــات الضريبيــة المتوجبــة\n 23/10/2024والتــي قضــت بحــذف هــذه الفقــرة. عليــه» .بخــاف مــا ورد فــي المذكــرة الصــادرة عــن هيئــة\n الشــراء العــام رقــم /9ه.ش.ع 2024/.تاريــخ .23/10/2024\n التقيــد بمــا ورد فــي الفقــرة 8مــن المــادة 13مــن قانــون الشــراء\n ّ\n العــام والتــي نصــت علــى مــا يلــي« :يجــب أن تبقــى القيمــة\n التقديريــة لمشــروع الشــراء ســرية قبــل التلزيــم وبعــده ،إال إذا كشــفت بعــض دفاتــر الشــروط القيمــة التقديريــة لمشــروع\n رأت الجهــة الشــارية عكــس ذلــك لغايــات تتعلــق بالمنافســة التقيــد بمــا ورد فــي الفقــرة 8مــن المــادة 13\n ّ الشــراء دون\n والحــرص علــى نجــاح التلزيــم ،أو فــي الصفقــات المعلومــة مــن قانــون الشــراء العــام.\n أســعارها بشــكل جلــي وواضــح ،وعندهــا ُيعلــن عــن القيمــة\n التقديريــة وفــق األصــول».\n التقيــد بمــا ورد فــي المــادة 4مــن قانــون الشــراء العــام والتــي\n ّ"}, {"o": 237, "l": "المادة 24", "b": "نصــت علــى مــا يلــي« :تُ عتمــد اللغــة العربيــة فــي مســتندات تّ ــم إعــداُ د بعــض دفاتــر الشــروط باللغــة اإلنكليزيــة فقــط\n الشــراء وفــي قــرارات الجهــة الشــارية .إال أنــه يمكــن إعتمــاد اللغــة وذكــر فيهــا أن تقديــم المســتندات يجــب أن يتّ ــم باللغــة\n اإلنكليزيــة و/أو الفرنســية مــع العربيــة للمراســات كافــة ووضــع اإلنكليزيــة وذلــك بخــاف مــا ورد فــي المــادة\n المواصفــات الفنيــة أو الشــروط المرجعيــة .عنــد التعــارض بيــن 4من قانون الشراء العام.\n النصيــن العربــي واألجنبــي يســود األول علــى الثانــي».\n التقيــد بمــا ورد فــي الفقــرة 6مــن المــادة 55مــن قانــون الشــراء\n ّ\n «يعتبــر العــرض فائــزاً فــيالعــام والتــي نصــت علــى مــا يلــيُ :\n بعــض دفاتــر الشــروط لــم تُ حــدد كيفيــة إرســاء التلزيــم،\n إحــدى الحالتيــن التاليتيــن :أ .العــرض األدنــى ســعراً ،عندمــا يكــون\n العــرض األدنــى ســعرا أم العــرض األفضــل؟ وذلــك بخــاف\n الســعر هــو المعيــار الوحيــد إلرســاء التلزيــم؛ ب .العــرض األفضــل\n مــا ورد فــي الفقــرة 6مــن المــادة 55\n باإلســتناد إلــى معاييــر وإجــراءات التقييــم المحــددة فــي وثائــق\n من قانون الشراء العام.\n التلزيــم وفقــاً للمــادة 18مــن هــذا القانــون ،عندمــا تكــون هنــاك\n معاييــر ماليــة ومعاييــر أخــرى غيــر الســعر».\n اعــداد دفاتــر شــروط ال تتقيــد بدفاتــر الشــروط النموذجيــة\n التقيــد بالنمــاذج الصــادرة عــن هيئــة الشــراء العــام وإســتخدامها ّ التــي أعدتهــا هيئــة الشــراء العــام ونشــرتها علــى المنصــة\n إلزاميــاً ســنداً للفقــرة 16مــن المــادة 76مــن قانــون الشــراء العــام. اإللكترونيــة المركزيــة بخــاف مــا نصــت عليــه الفقــرة 16مــن"}, {"o": 238, "l": "المادة 24", "b": "المــادة 76مــن قانــون الشــراء العــام.\n\f 172\n المالحظات او التوصيات ً\n شيوعا في دفاتر الشروط األخطاء األكثر\nالتقيــد بمــا ورد فــي الفقــرة 5مــن المــادة 13مــن قانــون الشــراءّ\nالعــام والتــي نصــت علــى مــا يلــي« :يجــب أن تكــون قيمــة مشــروع\nمحــددة لــدى الجهــة الشــارية عنــد اإلعــان عنهــا الشــراء التقديريــة َّ\nأو عنــد البــدء بإجــراءات التلزيــم» مــع لفــت النظر إلــى ما نصت عليه\n تضمنــت بعــض دفاتــر الشــروط وضمــن خانــة «القيمــة\nالفقــرة 8مــن المــادة نفســها« :يجــب أن تبقــى القيمــة التقديريــة\n التقديريــة للمشــروع» مــا يلــي« :لــم يتــم وضــع قيمــة\nلمشــروع الشــراء ّســرية قبــل التلزيــم وبعــده ،إال إذا رأت الجهــة\n التقيــد بمــا نصــت عليــه\n ّ تقديريــة لمشــروع الشــراء» دون\nالشــارية عكــس ذلــك لغايــات تتعلَّ ــق بالمنافســة والحــرص علــى\n الفقــرة 5مــن المــادة 13مــن قانــون الشــراء العــام\nنجــاح التلزيــم ،أو فــي الصفقــات المعلومــة أســعارها بشــكل جلّ ــي\nوواضــح ،وعندهــا ُيعلَ ــن عــن القيمــة التقديريــة وفــق األصــول .فــي\nجميــع األحــوال ال ُيحتَّ ــج بالســرية أمــام ديــوان المحاســبة والهيئــات\n الرقابيــة».\nالتقيــد بمــا ورد فــي الفقــرة 5مــن المــادة 24مــن قانــون الشــراءّ\n«يوقــع المرجــع الصالــح لــدى الجهــة ّ العــام التــي أوجبــت أن\nالشــارية العقــد خــال //15//خمســة عشــر يومــاً مــن تاريــخ توقيــع تضمنــت بعــض دفاتــر الشــروط أنــه للمرجــع الصالــح الحــق\nالعقــد مــن قبــل الملتــزم المؤقــت .يمكــن أن تمــدد هــذه المهلــة بعــدم تصديــق التلزيــم المؤقــت دون أن يكــون للعــارض\nمعينــة تحــدد مــن قبــل ّ إلــى //30//ثالثيــن يومــاً فــي حــاالت التقيــد بمــا نصــت عليــه"}, {"o": 239, "l": "المادة 24", "b": "ّ أي حــق بالمطالبــة بالتعويــض دون\nالمرجــع الصالــح» .أضــف إلــى ذلــك أنــه ال يمكــن إلغــاء الشــراء و/أو الفقــرة 5مــن المــادة 24مــن قانــون الشــراء العــام.\nأي مــن اجراءاتــه إال وفقــاً لمــا نصــت عليــه المــادة 25مــن قانــون\n الشــراء العــام.\nالتقيــد بمــا ورد فــي الفقــرة 1مــن المــادة 54مــن قانــون الشــراء\n ّ\nالعــام والتــي نصــت علــى مــا يلــي« :تَ فتَ ــح العــروض لجنــة التلزيــم\n اشــارت بعــض دفاتــر الشــروط إلــى إنعقــاد لجنــة فــض\nالمنصــوص عليهــا فــي المــادة 100مــن هــذا القانــون ،وذلــك\n العــروض فــي تاريــخ يختلــف عــن تاريــخ إنتهــاء موعــد تقديــم\nفــي جلســة علنيــة بحضــور األشــخاص ال َمــأذون لهــم فــي ملــف\n العــروض وذلــك بخــاف مــا نصــت عليــه الفقــرة 1مــن\nالتلزيــم ،فــي الوقــت والمــكان ووفقــاً للطريقــة المــح َّددة فــي\n المــادة 54مــن قانــون الشــراء العــام.\nعقــد هــذه الجلســة فــور انتهــاء مهلــة هــذا الملــف ،علــى أن تُ َ\n تقديــم العــروض».\nتــم التوضيــح بــأن هيئــة الشــراء العــام ال تُ عطــي إيصــال للعــارض\nعنــد حصولــه علــى دفتــر الشــروط الخــاص بالصفقــة ،فاإليصــال تضمنــت بعــض دفاتــر الشــروط إعطــاء إيصــال للعــارض مــن\nُيعطــى عــادة مــن قبــل الجهــة الشــارية لقــاء بــدل الحصــول علــى قبــل هيئــة الشــراء العــام عنــد حصولــه علــى دفتــر الشــروط\nدفتــر الشــروط فــي الحــاالت التــي يتــم فيهــا الحصــول علــى دفتــر الخــاص بالصفقــة.\n الشــروط لقــاء بــدل.\nالتقيــد بمــا نصــت عليــه المــواد 63و 64و 65مــن قانــون الشــراء ّ عــدم تحديــد مــدة اإلتفــاق اإلطــاري وعــدد العارضيــن"}, {"o": 240, "l": "المادة 24", "b": "العــام لجهــة كيفيــة إرســاء اإلتفــاق اإلطــاري وعــدد المورديــن أو الذيــن ترغــب الجهــة الشــارية بالتعاقــد معهــم فــي اإلتفــاق\nالمقاوليــن أو اإلستشــاريين أو مقدمــي الخدمــات الذيــن ســوف اإلطــاري ،وفــي حــال تعــدد العارضيــن هــل ســينطوي\nيكونــون أطرافــاً فــي اإلتفــاق واإلطــاري ،ومــا إذا كان اإلتفــاق اإلتفــاق اإلطــاري علــى تنافــس فــي المرحلــة الثانيــة أو\nاإلطــاري ينطــوي علــى تنافــس فــي مرحلــة ثانيــة ،ومــدة هــذا دون تنافــس وذلــك بخــاف مــا نصــت عليــه المــواد 63و\nاإلتفــاق التــي يجــب أن ال تقــل عــن ســنة وال تزيــد عــن أربــع ســنوات. 64و 65مــن قانــون الشــراء العــام.\n تحتــوي بعــض دفاتــر الشــروط علــى عبــارات غامضــة غيــر\nالطلــب مــن الجهــات الشــارية المعنيــة إيضــاح وتفصيــل المقصــود مفهومــة ،تحتمــل التأويــل وتســبب إشــكاليات للعارضيــن\nوتوصيتهــا بعــدم إســتخدام عبــارات أو فقــرات مبهمــة غيــر واضحــة. عنــد تحضيــر عروضهــم ،كمــا تســبب إشــكاليات للجنــة\n التلزيــم عنــد تقييــم العــروض.\n .2اهم المالحظات على دفاتر الشروط الخاصة التي ُعرضت على الهيئة\n • في االتفاقات االطارية التي ال تحدد فيها الكميات بدقة ،يستحسن ان يذكر « تجري محاسبة الملتزم\n على اساس االشغال المنفذة فعليًاً ،في مواقع العمل التي تحددها االدارة الحقًاً ».\n\f173\n• مــن األخطــاء الشــائعة ،تأتــي بعــض دفاتــر الشــروط خاليــة مــن تحديــد مــؤهالت العارضيــن المقبوليــن لالشــتراك\nفــي التلزيــم ،او انهــا ال تتضمــن وضــع وحــدات قيــاس لبعــض الشــروط ،لتمكيــن لجان التلزيم مــن تقييم العروض\n(كأن يشــترط ان يكــون العــارض ذات مصداقيــة ،او لديــه ســجل حافــل ،او معرفــة معمقــة .) ....لذلــك يرجــى"}, {"o": 241, "l": "المادة 24", "b": "التقّيد بأحكام القانون لجهة تضمين دفاتر الشروط معايير تأهيلية واضحة وقابلة للقياس والتقييم. ّ\n • عدم تضمين معظم الدفاتر النص التالي «إذا تساوت األسعار بين العارضين أعيدت الصفقة بطريقة\n الظرف المختوم بين أصحابها دون سواهم في الجلسة نفسها ،فإذا رفضوا تقديم عروض أسعار جديدة\n عّين الملتزم المؤقت بطريقة القرعة بين أصحاب العروض المتساوية». أو إذا ظلت أسعارهم متساوية ّ\n لذلك تذّكّ ر الهيئة بضرورة تضمين دفتر الشروط النص أعاله.\n • تحديد قيمة ضمان حسن التنفيذ بنسب منخفضة (كنسبة %3المالحظ اعتمادها في بعض دفاتر\n يتّم اعتمادها فقط في الحاالت التي تتطّلّ ب موازنة بين أهمية الشروط) ال يجب ان تكون القاعدة ،انما ّ\n تنفيذ الشراء والمخاطر المحيطة به.\n • التذكير بوجوب اجراء دراسة مسبقة اقتصادية تحليلية لإليرادات والنفقات للقطاعات المنوي تلزيمها،\n ومن ثم تحديد سعر الطرح في المزايدات العمومية.\n مؤّهالت العارضين وفقًاً لمعايير وإجراءات التأهيل المبَّيَ نة بشكل واضح ّ • التذكير بان ُتُ ََقِّيِ م لجان التلزيم\n ودقيق في دفتر شروط التلزيم.\n • عدم السماح بأن تدفع قيمة الضمانات بموجب شك مصرفي.\n • وجود العديد من االخطاء االمالئية واللغوية في صياغة بعض مواد دفاتر الشروط.\n • التوصية بإجراء التلزيم على أساس المجموعات كلما كان ذلك ممكنًاً ،تحقيقًاً لألهداف المتوخاة من\n المادة /15/من قانون الشراء العام.\n • بالنسبة لدفاتر الشروط الخاصة بتلزيم االدوية ،يجب التأكيد ان المنافسة بين العارضين بالنسبة للصنف\n الواحد تجري على أساس:\n -المادة الفعالة في الدواء وليس على أساس اسمه التجاري.\n يتكّون منها (حبة ،أنبوب ،تحميلة ،الخ )...من العيار عينه ،وبصرف النظر عن عدد ّ الجزئّية التي\n ّ -الوحدة\n الجزئّية التي تحتويها العلبة المخصصة للتوضيب. ّ الوحدات"}, {"o": 242, "l": "المادة 24", "b": "تبّين ان دراسة القيمة التقديرية في بعض التلزيمات تعود الى أكثر من سنة ونصف .لذلك ذّكّ رت هيئة • ّ\n الشراء العام بأحكام المادة /13/من قانون الشراء العام ،التي أوجبت على كل جهة شارية تحديث\n تقديراتها لقيمة مشروع الشراء قبل اإلعالن عنه إال في الحاالت االستثنائية التي يتعَّذَ ر فيها ذلك ،على\n أن ُتُ بِّيِ ن األسباب بشكل معَّلَ ل وواضح.\n المنّظمة لبعض التلزيمات ،هنالك مادة شائعة أدى تطبيقها الى العديد من ّ • في دفاتر الشروط\n المشكالت مع المتعهدين ،وهي تنص على:\n «ال يمكن للمستثمر بأي وجه أن يعتد بأية قوانين لجهة تخفيض أو تمديد مدة االستثمار ,لكن إذا حالت\n ظروف قاهرة أو استثنائية خارجة عن إرادة المستثمر من ممارسة عمله (إقفال المطار كليًاً أو جزئيًاً ،\n أعمال عدوانية ).....يتوجب على المستثمر أن يعرضها فورًاً ،وبصورة خطية على المالك الذي يعود له\n الحق باالنفراد في تقدير هذه الظروف وقبولها أو رفضها وعلى المستثمر الرضوخ لقرار المالك المشار\n إليه في هذا الشأن (تخفيض أو تمديد مدة االستثمار ،اإلعفاء من بدل االستثمار السنوي دون العالوات\n خالل فترة الظروف القاهرة.»).....\n • وقد اقترحت الهيئة الغاءها ،واإلحالة على أحكام المادة /33/من قانون الشراء العام التي ترعى حالة\n تعَّذَ ر الملتزم القيام بالتزاماته التعاقدية بنتيجة القوة القاهرة.\n مّدته ،اال • ورد في أحد مواد دفتر شروط «ال يمكن الغاء العقد خالل فترة االلتزام ،او انهائه قبل انتهاء ّ\n يستمّر الملتزم بمهامه ،بصورة متواصلة ،لحين تأمين بديل ّ بقرار من البلدية أو من ،............وعلى ان\n موافق عليه من قبل البلدية».\n • وقد اعتبرت الهيئة ،ان انهاء العقد بإرادة اإلدارة المنفردة من شأنه ان يرتب تعويضًاً عليها لصالح الملتزم،\n ويخلق ال توازن بين فريقي العقد .ويستحسن كبديل عن هذا النص ،اإلحالة الى"}, {"o": 243, "l": "المادة 33", "b": "المادة 33من قانون\n تنّظم أسباب انتهاء العقد ونتائجه. الشراء العام التي ّ\n\f 174\nالمسجلة على المنصة االلكترونية المركزية\n ّ .Xملحق رقم :10الئحة الجهات الشارية\nالرقم التسلسلي الجهة الشارية\n 1 وزارة األشغال العامة والنقل\n 2 وزارة اإلعالم\n 3 وزارة التربية والتعليم العالي\n 4 وزارة ا